  { t:"1386-01-01", k:"fetih", etiket:["siyaset","toprak-kazanc","konu-askeri","konu-siyasi"], kapsam:"dis", onem:4, b:"Timur'un 'üç yıllık sefer'i: Azerbaycan ve Kuzey İran'ın alınması", gun:"788 / 1386", yer:"Tebriz", yer_id:"Tebriz", kisiler:"Timur, Toktamış Han", d:"Horasan seferleri sırasında İran'ın dağınık hâlini yakından gören Timur 788'de (1386) batıya yürüdü. 'Üç yıllık sefer' diye anılan 1386-1388 harekâtında Mâzenderan, Luristan ve Gürcistan üzerinden Azerbaycan'a geçip Karabağ'a ulaştı; Tebriz, Erdebil, Urmiye ve Nahçıvan Timurlu idaresine girdi. Kuzey İran ile Azerbaycan'ı ele geçirmesi, vaktiyle Cuci ulusu ile İlhanlılar arasında olduğu gibi, Altın Orda ile uzun bir çekişmenin de başlangıcı oldu.", kaynak:"timur", duygu:["⚔️","🏛"] },
  { t:"1393-01-01", k:"kayip", etiket:["siyaset","toprak-kayip","konu-askeri","konu-siyasi","konu-hanedan"], kapsam:"dis", onem:3, b:"Muzafferî hânedanının sonu: Şah Mansûr'un Şîraz önünde yenilmesi", gun:"795 / 1393", yer:"Şiraz", yer_id:"Şiraz", kisiler:"Timur, Şah Mansûr, Şah Yahyâ, İmâdüddin Ahmed", d:"1318'den beri Yezd, Fars, Isfahan ve Kirman'da hüküm süren Muzafferîler'in son güçlü hükümdarı Şah Mansûr, akrabalarıyla birlik olup Timur'a karşı harekete geçti. Şîraz yakınlarındaki savaşta emîrlerinden birinin karşı tarafa geçmesiyle kuvvetlerinin çoğunu kaybetti, yenilerek öldürüldü. Timur'un ardından bütün hânedan üyelerini de öldürtmesiyle Muzafferî hâkimiyeti sona erdi ve Fars ile Kirman Timurlu idaresine katıldı.", kaynak:"muzafferiler", duygu:["😔","⚔️"] },

{ t:"1671-01-01", k:"siyaset", etiket:["idari","konu-siyasi","konu-idari"], b:"Cezayir'de dayı idaresinin başlaması", gun:"1671", yer:"Cezayir", yer_id:"Cezayir", kisiler:"Hacı Mehmed Dayı, IV. Mehmed", d:"Cezayir ocağı ile taife-i reîs (korsan kaptanları) son ağayı azledip Hacı Mehmed'i kayd-ı hayat şartıyla dayı seçti. Bu tarihten sonra Cezayir'i İstanbul'un atadığı beylerbeyi değil, yerel ocağın kendi içinden seçtiği dayı yönetti; Osmanlı bağı hutbede padişahın adının okunması, sancak ve sefer yükümlülüğüyle sınırlı kaldı. Cezayir böylece eyaletten OCAKLIĞA dönüştü — aynı dönüşümü Tunus 1705'te Hüseynîler, Trablusgarp 1711'de Karamanlılar ile yaşadı.", statu_vasal:["Cezayir","Konstantin","Tilimsan","Annaba","Bicâye","Şerşel (Cherchell)","Medea (Titteri)","Setif","Biskra","Tuggurt"], kaynak:"cezayir", duygu:["🏛"] },

// ---------- 00) KURULUŞ ÖNCESİ VE OSMAN BEY DEVRİ (1281-1324) ----------
// Atlasın başlangıcı 1299'dan 1281'e çekildi. TDV'ye göre Osman Bey babasından
// fethedilmiş tek bir kale bile devralmadı; elinde yalnız Söğüt kışlağı ile
// Domaniç yaylağı vardı. İlk askerî harekât 1285, ilk şehir fethi 1288'dir.
{ t:"1281-01-01", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler"], b:"Ertuğrul Gazi'nin ölümü ve Osman Bey'in beyliğe geçişi — Söğüt ve Domaniç mirası", gun:"680 (1281-82)", yer:"Söğüt, Domaniç", kisiler:"Ertuğrul Gazi, Osman Bey", d:"TDV'ye göre Ertuğrul Gazi 680 (1281-82) yılında vefat etti; madde 1288 ve 1289 tarihlerinin de verildiğini kaydeder. Osman Bey babasından fethedilmiş bir şehir değil, Selçuklu sultanının uç bölgesinin en ileri hattına yerleştirdiği Ertuğrul'a verdiği iki tahsisi devraldı: Söğüt'te yurtluk (kışlak) ve Domaniç'te yaylak. Yani beylik bir fetih mirasıyla değil, iki otlak tahsisiyle işe başlamıştır; haritada bu iki yer 'fetih' değil 'miras' olarak gösterilir.", kaynak:"ertugrul-gazi", duygu:["🏛"], yer_id:"Söğüt" },
{ t:"1285-01-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Kulacahisar baskını — Osman Bey'in ilk askerî harekâtı", gun:"684 (1285)", yer:"Kulacahisar (İnegöl yakını)", kisiler:"Osman Bey", d:"TDV OSMAN I maddesi: 'İnegöl yakınında küçük Kulaca Hisarı'nı yağmalayıp ateşe vermiştir (684/1285).' Bu, Osman Bey'in kaynaklarda tarihlenebilen ilk askerî hareketidir. Kalıcı bir yerleşim ele geçirilmemiş, hisar yağmalanıp yakılmıştır; dolayısıyla bir fetihten çok klasik bir uç akınıdır. Beyliğin askerî faaliyetinin başlangıç noktası sayılır.", kaynak:"osman-i", duygu:["⚔️","😔"], yer_id:"Kulacahisar" },
{ t:"1288-01-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Karacahisar'ın fethi — ilk şehir kazanımı ve Eskişehir'e hâkimiyet", fethedilen:["Karacahisar","Eskişehir"], gun:"687 (1288)", yer:"Karacahisar, Eskişehir", kisiler:"Osman Bey", d:"TDV OSMAN I maddesi: Osman Bey 687 (1288) yılında 'Karacahisar'ı fethedip Eskişehir'e mâlik oldu'. Bu, beyliğin ilk gerçek şehir kazanımıdır ve rivayete göre Osman Bey bu başarıyla uçta sancak beyliğine yükselmiştir; adına ilk cuma hutbesinin Karacahisar'da okunduğu ve buraya ilk kadının tayin edildiği nakledilir. TDV ESKİŞEHİR maddesi Osmanlı geleneğinin 1291 tarihini verdiğini, ancak bunun doğruluğunun şüpheli olduğunu belirtir.", kaynak:"osman-i", duygu:["🎉"], yer_id:"Karacahisar" },
{ t:"1299-01-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Bilecik ve Yarhisar'ın gece baskınıyla fethi", fethedilen:["Bilecik","Yarhisar"], gun:"1299", yer:"Bilecik, Yarhisar", kisiler:"Osman Bey, Bilecik tekfuru", d:"TDV BİLECİK maddesi: 'Bilecik tekfurunun da aralarında bulunduğu bölgedeki diğer tekfurlar Osman Gazi'ye bir suikast hazırladılarsa da bu tertibin haber alınması üzerine Osmanlı kuvvetleri âni bir baskınla Yarhisar ve Bilecik'i fethettiler (1299).' İki kale tek harekâtta, aynı gece baskınında alınmıştır. Bu tarih Osmanlı Devleti'nin kuruluş yılı olarak kabul edilen dönüm noktasıdır. Aynı tarihte katılan öteki yerler: İnegöl.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"bilecik", duygu:["🎉"], yer_id:"Bilecik" },
{ t:"1302-07-27", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Koyunhisar (Bapheus) Savaşı — Bizans ordusuna karşı ilk büyük zafer", gun:"27 Temmuz 1302", yer:"Koyunhisar / Bapheus (Yalova yakını)", yer_id:"Yalova", kisiler:"Osman Bey, Bizans komutanı Mouzalon", d:"TDV OSMAN I maddesi: Osman Bey 27 Temmuz 1302'de Bapheus'ta (Koyunhisar) Bizans ordusuyla savaşıp onu yendi. Bu zafer, Osman Bey'i bölgesel bir uç beyi olmaktan çıkarıp hanedan kurucusu statüsüne yükselten dönüm noktasıdır. Savaşın ardından Bursa ovası Osmanlı denetimine girmiş, İznik'in ablukası başlamıştır.", kaynak:"osman-i", duygu:["⚔️"] },
{ t:"1303-01-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Dimbos zaferi ve ardından Kite ile Ulubat'ın alınması", fethedilen:["Kite"], gun:"702 (1303)", yer:"Dimbos Boğazı (Bursa-İnegöl arası), Kite, Ulubat", yer_id:"Dimbos", kisiler:"Osman Bey, Orhan Bey, Kestel tekfuru", d:"TDV OSMAN I maddesi: 702 (1303) yılında Bursa, Kestel, Kite ve Adranos tekfurlarının kurduğu ittifak Dimbos Boğazı'nda bozguna uğratıldı; düşman savaşa savaşa dar boğaza kadar çekildi ve Kestel tekfuru savaş meydanında öldü. Zaferin hemen ardından Kite ve Ulubat kaleleri ele geçirilerek Bursa'nın kara bağlantısı kesildi ve ablukası sıkılaştırıldı. Genç Orhan da bu savaşa katılmıştır.", kaynak:"osman-i", duygu:["⚔️"] },
{ t:"1304-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Sakarya seferi: Leblebicihisar, Lefke, Mekece ve Geyve'nin alınması", fethedilen:["Leblebicihisar","Lefke","Mekece","Geyve"], gun:"704 (1304)", yer:"Lefke (Osmaneli), Mekece, Geyve, Akhisar", yer_id:"Leblebicihisar", kisiler:"Osman Bey", d:"TDV OSMAN I maddesi 704 (1304) Sakarya seferinin sırasını verir: 'Leblebüci Hisarı'na geldiğinde tekfur itaat etti... Lefke'ye vardı... Mekece'ye ulaştı... Geyve'ye gidip boş bulduğu hisarı aldı.' Lefke, Sakarya vadisinin Bilecik'e açılan kapısıdır. Bu tek sefer, vadi boyunca uzanan kale zincirini Osmanlı denetimine geçirerek İznik havzasının doğu kanadını kapatmıştır.", kaynak:"osman-i", duygu:["🎉"] },
{ t:"1305-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Geyve Boğazı kalelerinin fethi: Karaçepüş, Karatigin ve Absu", fethedilen:["Karaçepüş","Karatigin","Absu"], gun:"705 (1305)", yer:"Geyve Boğazı ve İznik çevresi", yer_id:"Karaçepüş", kisiler:"Orhan Bey, Gazi Abdurrahman", d:"TDV ORHAN maddesi: Orhan 705 (1305) Sakarya seferinde 'Karaçepüş (Katoikia), İznik önünde Karatigin, Absu (Hypsu: Geyve Boğazı'nda) kalelerini fethetti'. Bu üç kale, Sakarya vadisi ile İznik havzası arasındaki geçişi kapatarak İznik'in kara yardımını tamamen kesmiştir. Geyve boğazındaki Karaçepüş ve Absu'ya Gazi Abdurrahman yerleştirilmiştir; şehir artık yalnızca açlıkla düşürülebilecekti.", kaynak:"orhan", duygu:["🎉"] },
{ t:"1323-09-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Adranos (Orhaneli) seferi — Osman Bey'in son seferi", gun:"1323 sonbaharı", yer:"Adranos / Atranos (Orhaneli, Bursa)", yer_id:"Adranos (Orhaneli)", kisiler:"Osman Bey, Orhan Bey", d:"TDV ORHAN maddesi 1323 sonbaharındaki Adranos Kalesi seferini Osman Bey'in son seferi olarak kaydeder. Adranos tekfuru, yirmi yıl önce Dimbos'ta Osmanlılara karşı kurulan tekfurlar ittifakının üyesiydi; bu sefer o hesabın kapatılması anlamına geliyordu. Kalenin kesin fetih günü bilinmez; harekât Orhan Bey tarafından sürdürülmüştür.", ic_not_d:"eski: TDV kalenin kesin fetih gününü vermez", kaynak:"orhan", duygu:["⚔️"] },
{ t:"1329-06-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Pelekanon (Maltepe) Savaşı ve Kocaeli'nin tamamının alınması", fethedilen:["Hereke","Gebze","Üsküdar"], gun:"1 Haziran 1329", yer:"Pelekanon (Eskihisar-Darıca), Gebze, Hereke, Samandıra, Aydos Kalesi", yer_id:"Gebze", kisiler:"Orhan Bey, kardeşi Pazarlu, İmparator III. Andronikos", d:"TDV ORHAN maddesi: savaşın ilk günü Orhan Gazi, Bizans ordusunu kendine çekmek için üç yüz kişilik bir kuvvet gönderdi; ikinci gün Pazarlu kumandasındaki birliklerin düzlüğe inmesiyle savaş büyüdü ve imparator okla yaralanınca Bizans ordusunda panik çıktı. Sonuç kesindir: 'Orhan bütün Kocaeli'yi ele geçirdi; zaferden sonra İznikliler'in hiçbir ümidi kalmadı.' Hereke'den Üsküdar'a kadar sahil kasabaları Osmanlı hükmüne girdi, Gebze bölgenin merkezi yapıldı. Bu, İstanbul'u kurtarmak için gelen son Bizans imparatorluk ordusuydu.", kaynak:"orhan", duygu:["⚔️"] },
{ t:"1333-08-01", k:"antlasma", etiket:["antlasma","diplomasi","ekonomi","konu-diplomasi","konu-ekonomi"], b:"Bizans'ın haraca bağlanması — İzmit kuşatması ve antlaşma", gun:"Zilhicce 733 / Ağustos 1333", yer:"İzmit (Nikomedia)", yer_id:"İzmit", kisiler:"Orhan Bey, İmparator III. Andronikos", d:"TDV ORHAN maddesi: Orhan 733 (1333) yazında İzmit'i büyük bir ordu ve mancınıklarla kuşattı, imparator antlaşmaya razı oldu. Kuşatmadan vazgeçmesi karşılığında Bizans, Orhan'a yılda 12.000 altın (hyperper) ödemeyi kabul etti; 'böylece Osmanlı emîri gözünde Bizans haraçgüzâr bir ülke durumuna düşmüştür'. Karşılığında Orhan imparatorun dostu olacak ve Bizans'a tâbi şehirlere saldırmayacaktı. Bir uç beyliğinin Doğu Roma'yı vergiye bağlaması, güç dengesinin ne kadar döndüğünün ilanıydı.", kaynak:"orhan", duygu:["🤝"] },
{ t:"1345-01-01", k:"fetih", etiket:["toprak-kazanc","siyaset","konu-askeri","konu-siyasi"], b:"Karesi Beyliği'nin ilhakı: Balıkesir, Bergama, Biga, Edremit ve Erdek", fethedilen:["Balıkesir","Bergama","Biga","Edremit","Erdek"], gun:"735 (1334-35)", yer:"Balıkesir, Bergama, Biga, Çanakkale, Edremit, Erdek, Ayvalık, Behramkale (Assos), Karabiga, Kirmasti, Mihaliç", yer_id:"Balıkesir", kisiler:"Orhan Bey, Süleyman Paşa, Dursun Bey, Demirhan Bey, Hacı İlbey", d:"TDV ORHAN maddesi (İnalcık) ilhakı 735 (1334-35) tarihine koyar: Demirhan Bey'in ölümü üzerine Karesi gazileri ve Hacı İlbey, Dursun Bey'i tahta davet edip Orhan'dan yardım istediler. Orhan önce Balıkesir üzerine yürüdü; barış görüşmesine giden Dursun Bey Bergama kalesinden atılan bir okla ölünce beylik bütünüyle Osmanlı ülkesine katıldı. Aynı harekâtta Kirmasti ve Mihaliç itaat etti, Gölyazı alındı ve daha önce emanla bırakılmış Ulubat kesin olarak zaptedildi. Orhan, Karesi sancağına Süleyman Paşa'yı tayin edip Biga'yı uç merkezi yaptı — Rumeli'ye geçişin denizci kadrosu böylece kazanıldı. Not: TDV'nin KARESİOĞULLARI maddesi aynı olay için 746 (1345) tarihini verir; ansiklopedi kendi içinde çelişmektedir. Aynı tarihte katılan öteki yerler: Çanakkale.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"orhan", duygu:["🎉"] },

// ---------- 0a) ANKARA SAVAŞI'NA GİDEN SÜREÇ VE FETRET DEVRİ ----------
// Kullanıcı talebi: Timur-Bayezid restleşmesi ayrı madde, Ankara Savaşı ayrı
// madde, beyliklerin yeniden müstakilleşmesi haritada ve maddede, şehzade
// paylarının ayrı ayrı gösterilmesi. Haritada 1402-1413 arasında yerleşimler
// "Osmanlı" yerine o an tutan şehzadenin rengiyle çizilir.
{ t:"1393-08-29", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Timur Bağdat'ı zaptetti — Celâyirliler Anadolu'ya kaçtı", gun:"29 Ağustos 1393", yer:"Bağdat", yer_id:"Bağdat", kisiler:"Timur, Celâyirli Sultan Ahmed", d:"Timur, uzun bir kuşatmanın ardından Bağdat'ı ele geçirdi; şehrin hâkimi Celâyirli Sultan Ahmed batıya kaçarak önce Memlükler'e, sonra Osmanlı sarayına sığındı. Timur'un batıya doğru genişlemesi böylece ilk kez Osmanlı nüfuz alanıyla doğrudan temas etti. İki hükümdar arasındaki husumetin ilk halkası buradan başlar.", kaynak:"timur", duygu:["⚔️"] },
{ t:"1399-11-01", k:"siyaset", etiket:["diplomasi","ittifak","konu-siyasi","konu-diplomasi"], b:"Timur'un restleşmesi: kaçakların iadesi reddedildi", gun:"1399", yer:"Bursa", yer_id:"Bursa", kisiler:"Yıldırım Bayezid, Sultan Ahmed Celâyirî, Karakoyunlu Kara Yûsuf", d:"Timur'un baskısı üzerine Celâyirli Sultan Ahmed ile Karakoyunlu lideri Kara Yûsuf Osmanlı topraklarına sığındı; Timur bu iki firarinin iadesini istedi, Yıldırım Bayezid reddetti. Bunun üzerine iki hükümdar arasında karşılıklı ağır hakaretler içeren mektuplar teâti edilmeye başlandı. Savaşın ideolojik zemini, henüz tek bir asker hareket etmeden bu yazışmalarla kuruldu.", kaynak:"ankara-savasi", duygu:["🏛"] },
{ t:"1400-08-01", k:"kayip", etiket:["savas","konu-askeri"], b:"Timur Sivas'ı yerle bir etti", gun:"Ağustos 1400", yer:"Sivas", yer_id:"Sivas", kisiler:"Timur, Şehzade Süleyman, Mutahharten", d:"Akkoyunlu Karayülük Osman Bey ile Erzincan emîri Mutahharten'in kılavuzluğunda Sivas'a yürüyen Timur, şehri on sekiz gün kuşattı ve kimsenin kanının dökülmeyeceği vaadiyle teslim aldıktan sonra büyük bir katliam yaptı; müdafileri hendeklere doldurup canlı canlı üzerlerini örttürdü. Surlar başta olmak üzere şehrin önemli eserleri tahrip edildi, Sivas demografik olarak çöktü. Bu, Ankara Savaşı'ndan iki yıl önce Timur'un Osmanlı topraklarına indirdiği ilk büyük darbedir.", kaynak:"sivas", duygu:["😔"] },
{ t:"1401-02-01", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Yıldırım Bayezid Erzincan ve Kemah'ı geri aldı", gun:"1400-1401 kışı", yer:"Erzincan, Kemah", yer_id:"Erzincan", kisiler:"Yıldırım Bayezid, Mutahharten", d:"Timur'un Suriye seferine çıkmasını fırsat bilen Yıldırım Bayezid, Timur'a tâbi olan Erzincan emîri Mutahharten'in elinden Erzincan ve Kemah'ı aldı. Sivas'ın yıkımına müdahale etmemiş olmasına rağmen bu hamle, Timur'un Doğu Anadolu'daki nüfuz alanına doğrudan meydan okumak anlamına geliyordu. İki hükümdarın arası bundan sonra onarılamaz hâle geldi.", kaynak:"ankara-savasi", duygu:["🎉"] },
{ t:"1402-03-13", k:"siyaset", etiket:["diplomasi","savas","konu-askeri","konu-siyasi","konu-diplomasi"], b:"Timur'un Tebriz'den gönderdiği ültimatom — dört şart", gun:"13 Mart 1402", yer:"Tebriz – Osmanlı sarayı", yer_id:"Tebriz", kisiler:"Timur, Yıldırım Bayezid, Mutahharten", d:"Timur, Tebriz'den yolladığı elçiyle dört şart bildirdi: Kemah'ın Mutahharten'e iadesi, Anadolu beylerinden alınan toprakların sahiplerine geri verilmesi, bir Osmanlı şehzadesinin rehin gönderilip külâh ve kemerin tâbiiyet alâmeti olarak kabul edilmesi ve Kara Yûsuf'un teslimi. Bayezid bunların hiçbirini kabul etmedi; devlet adamlarının ısrarına ve Mutahharten'in aracılığına rağmen görüşmeler çöktü. Timur, Çin seferine çıkmadan önce Anadolu meselesini kesin biçimde kapatmaya kararlıydı.", kaynak:"ankara-savasi", duygu:["🏛"] },
{ t:"1402-08-17", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Saruhanoğulları yeniden kuruldu — Manisa Osmanlı'dan çıktı", gun:"17 Ağustos 1402", yer:"Manisa", yer_id:"Manisa", kisiler:"Timur, Saruhanoğlu Orhan Bey", d:"Ankara bozgunundan üç hafta sonra Timur'un desteğiyle Orhan Bey beyliğin başına geçti ve Saruhan ili yeniden bağımsız oldu. Manisa merkezli bölge, 1390'daki Osmanlı ilhakından on iki yıl sonra haritadan çıktı. Bu, Timur'un beylikleri diriltme siyasetinin tarihi kesin olarak bilinen ilk uygulamalarındandır.", kaynak:"saruhanogullari", duygu:["😔"] },
{ t:"1402-08-20", k:"siyaset", etiket:["siyaset","ekonomi","konu-siyasi","konu-ekonomi"], b:"Emîr Süleyman devlet hazinesiyle Rumeli'ye kaçtı", gun:"Ağustos 1402", yer:"Bursa – Gemlik – Güzelcehisar – Gelibolu", yer_id:"Bursa", kisiler:"Emîr Süleyman Çelebi, Şehzade Kasım, Çandarlı Ali Paşa", d:"Bursa'daki devlet hazinesini, arşivleri, ailesini ve kardeşlerini yanına alan Emîr Süleyman, Gemlik'ten gemiyle Güzelcehisar'a (Anadoluhisarı) geçti, oradan Gelibolu'ya ulaşarak Edirne'de hükümdarlığını ilân etti. Devlet arşivinin ve hazinenin Rumeli'ye taşınması, Osmanlı ağırlık merkezinin bir nesil boyunca Balkanlar'a kaymasının başlangıcıdır. Haritada Rumeli bu tarihten itibaren Emîr Süleyman'ın kendi rengiyle çizilir.", kaynak:"suleyman-celebi-emir", duygu:["🏛"] },
{ t:"1402-09-15", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Timur Anadolu beyliklerini yeniden kurdu — Türk birliği dağıldı", gun:"1402 sonbaharı", yer:"Karaman, Germiyan, Aydın, Menteşe, Teke, Candar toprakları", yer_id:"Karaman", kisiler:"Timur, Karamanoğlu II. Mehmed Bey, Germiyanoğlu II. Yâkub Bey, İsfendiyar Bey", d:"Timur, Ankara zaferinin ardından yanında bulunan beyleri eski topraklarına iade etti. Karamanoğlu Mehmed ve Ali beylere Karaman ili ile Kayseri, Kırşehir, Sivrihisar ve Beyşehir; Germiyanoğlu II. Yâkub Bey'e Kütahya ve Germiyan ili; Candaroğlu İsfendiyar Bey'e Kastamonu-Sinop hattına ek olarak Çankırı ve Kalecik verildi. Aydın, Menteşe ve Teke illeri de eski hânedanlarına döndü. Yıldırım Bayezid'in on yılda kurduğu Anadolu Türk birliği tek bir yaz içinde dağıldı; haritada bu beylikler yeniden kendi renklerinde belirir.", kaynak:"ankara-savasi", duygu:["😔"] },
{ t:"1402-12-14", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Timur İzmir'i Saint Jean şövalyelerinden aldı", gun:"Aralık 1402", yer:"İzmir", yer_id:"İzmir", kisiler:"Timur, Saint Jean şövalyeleri", d:"Kütahya, Denizli, Aydın, Ayasuluk ve Tire üzerinden batıya inen Timur, 1344'ten beri Hıristiyanların elinde bulunan sahil İzmir'i kuşatarak aldı. Yıldırım Bayezid'in yıllarca alamadığı bu kaleyi kısa sürede zapteden Timur, çevredeki kaleleri de ele geçirdikten sonra Aydın ilini eski sahiplerine bırakarak doğuya döndü. Şehir bundan sonra Aydınoğlu Cüneyd Bey'in idaresine girdi.", kaynak:"izmir", duygu:["⚔️"] },
{ t:"1402-12-20", k:"siyaset", etiket:["siyaset","toprak-kazanc","konu-askeri","konu-siyasi","konu-kisiler"], b:"Îsâ Çelebi Bursa'yı ele geçirdi — Anadolu payı doğdu", gun:"1402 sonu", yer:"Bursa, Balıkesir (Karesi)", yer_id:"Bursa", kisiler:"Îsâ Çelebi", d:"Ankara bozgunundan sonra Karesi taraflarına çekilen Îsâ Çelebi, Timur İzmir'deyken Bursa'yı ele geçirdi. Timur'un askerlerince yağmalanıp yakılmış eski başkentte hükümdarlığını ilân etti ve kendi adına sikke kestirdi; Ocak 1403'te Anadolu'da 'Türkler'in hükümdarı' sıfatıyla tanınıyordu. Haritada Marmara'nın Asya kıyısı boyunca uzanan bu pay, Îsâ Çelebi'nin kendi rengiyle görünür.", kaynak:"isa-celebi", duygu:["🏛","😔"] },
{ t:"1403-03-15", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"Timur'un Anadolu'dan çekilmesi", gun:"Mart 1403 sonrası", yer:"Akşehir – Doğu Anadolu", yer_id:"Akşehir", kisiler:"Timur", d:"Yıldırım Bayezid'in Akşehir'de vefat ettiği haberini alan Timur, Anadolu'daki işini bitmiş sayarak doğuya yöneldi. Geride kendisine bağlılık bildiren beylikler ile birbirine düşmüş Osmanlı şehzadeleri kaldı; Sivas gibi bazı şehirler Timur'a tâbi Mezid Bey benzeri emîrlerin elinde bırakıldı. Timur bir daha Anadolu'ya dönmedi, ancak kurduğu bu parçalı düzen on yıl sürdü.", kaynak:"timur", duygu:["🏛"] },
{ t:"1404-03-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Emîr Süleyman Anadolu'ya geçti: Bursa ve Ankara onun eline geçti", gun:"Mart 1404", yer:"Bursa, Ankara, Karadeniz Ereğlisi", yer_id:"Bursa", kisiler:"Emîr Süleyman Çelebi, Çandarlı Ali Paşa, Çelebi Mehmed", d:"Îsâ Çelebi'nin yenilgisini duyan Emîr Süleyman, Çandarlı Ali Paşa ile birlikte güçlü bir orduyla Anadolu'ya geçerek Bursa'yı, ardından Ankara'yı ele geçirdi; Mart 1404 kayıtları Karadeniz Ereğlisi'nin de onun yönetiminde olduğunu gösterir. Kısa sürede hem Rumeli'ye hem Anadolu'nun büyük bölümüne hâkim olan Süleyman karşısında Çelebi Mehmed direnemedi. Haritada bu tarihten 1411'e kadar iki yaka tek renkte, Emîr Süleyman'ın payında görünür.", kaynak:"suleyman-celebi-emir", duygu:["⚔️"] },
{ t:"1405-01-01", k:"savas", etiket:["savas","toprak-kayip","konu-askeri"], b:"Yenişehir Ovası savaşı — Çelebi Mehmed Amasya'ya çekildi", gun:"1404-1405", yer:"Yenişehir Ovası, Bursa", yer_id:"Yenişehir (Bursa)", kisiler:"Emîr Süleyman Çelebi, Çelebi Mehmed", d:"Bursa ve Ankara'yı kaybeden Çelebi Mehmed, Yenişehir ovasında Emîr Süleyman'a yenilerek Batı Anadolu'daki bütün kazanımlarını yitirdi ve Tokat-Amasya üssüne çekildi. Bu yenilgiden sonra doğrudan çatışmadan kaçınıp Anadolu'nun içlerinde otoritesini pekiştirmeye yöneldi. Fetret'in en uzun sessiz safhası böyle başladı.", kaynak:"mehmed-i", duygu:["⚔️"] },
{ t:"1408-06-01", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Çelebi Mehmed Sivas'ı Timurlu Mezid Bey'den geri aldı", gun:"810 (1407-1408)", yer:"Sivas", yer_id:"Sivas", kisiler:"Çelebi Mehmed, Bayezid Paşa, Mezid Bey", d:"Timur istilasından sonra Sivas'ın idaresi Timur'a tâbi Mezid Bey'e bırakılmıştı. Amasya'daki Çelebi Mehmed, kumandanı Bayezid Paşa'yı şehri almak üzere gönderdi ve şiddetli bir direnişin ardından Sivas ikinci kez Osmanlı hânedanının eline geçti. Böylece Mehmed'in payı, Ankara Savaşı'ndan altı yıl sonra doğuda eski sınırına ulaştı.", kaynak:"sivas", duygu:["🎉"] },
{ t:"1410-02-13", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Yanbolu Savaşı — Mûsâ Çelebi Edirne'ye girdi", gun:"8 Şevval 812 / 13 Şubat 1410", yer:"Yanbolu (Yambol), Trakya", kisiler:"Mûsâ Çelebi, Emîr Süleyman Çelebi, Eflak Voyvodası Mircea", d:"Eflak üzerinden Rumeli'ye geçen Mûsâ Çelebi, Eflak ve Sırp desteğiyle Yanbolu'da Emîr Süleyman'ın kuvvetlerini bozguna uğrattı ve Edirne'ye girdi. Fetret Devri'nde Rumeli ilk kez Emîr Süleyman'ın elinden çıkmış oldu. Ancak hâkimiyeti kalıcı olmadı; dört ay sonra Kosmidion'da yenilerek Balkan içlerine çekilecekti.", kaynak:"musa-celebi", duygu:["⚔️"], yer_kon:[42.4833,26.5] },
{ t:"1412-10-01", k:"savas", etiket:["savas","konu-askeri"], b:"İnceğiz Savaşı — Çelebi Mehmed'in ilk Rumeli yenilgisi", gun:"Ekim 1412", yer:"İnceğiz, Trakya", kisiler:"Çelebi Mehmed, Mûsâ Çelebi", d:"Bizans'ın gemileriyle Rumeli'ye geçen Çelebi Mehmed, İnceğiz'de Mûsâ Çelebi ile savaşa girişti; Mûsâ emrindeki yedi bin yeniçeriyle Mehmed'i mağlup etti ve Mehmed Anadolu'ya dönmek zorunda kaldı. Bu yenilgi Mehmed'i doğrudan savaş yerine Rumeli uç beylerini ve Sırp despotluğunu kendi tarafına çekme stratejisine yöneltti. Dokuz ay sonraki Çamurlu zaferinin zemini bu diplomasiyle hazırlandı.", kaynak:"fetret-devri", duygu:["⚔️","😔"], yer_kon:[41.22,28.42] },
{ t:"1415-06-01", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"İzmir'in Aydınoğlu Cüneyd Bey'den alınışı", gun:"1415", yer:"İzmir", yer_id:"İzmir", kisiler:"Çelebi Mehmed, Aydınoğlu Cüneyd Bey", d:"Fetret boyunca şehzadeler arasında sürekli taraf değiştiren Aydınoğlu Cüneyd Bey'in merkezi İzmir, on günlük bir kuşatmanın ardından Çelebi Mehmed tarafından alındı; Cüneyd affedilerek Niğbolu sancak beyliğine gönderildi. Timur'un 1402'de Aydınoğulları'na iade ettiği şehir böylece on üç yıl sonra Osmanlı'ya döndü. Cüneyd 1422'de şehri yeniden ele geçirecek, mesele ancak 1424-1426'da II. Murad tarafından kapatılacaktır.", kaynak:"izmir", duygu:["🎉"] },
{ t:"1416-01-01", k:"isyan", etiket:["isyan","konu-askeri","konu-kisiler","konu-isyan"], b:"Torlak Kemal'in idamı — Saruhan kesin olarak Osmanlı'nın", gun:"819 (1416)", ic_not_etiket:"GEMINI-DOGRULA 0919: t 1416-09-01 → 1416-01-01 (TDV yalnız '819 (1416)' veriyor; ay-gün kaynaksızdı) · toprak-kazanc KALDIRILDI: TDV saruhanogullari Saruhan ülkesinin 1411'den sonra ve 1415'ten önce Çelebi Mehmed'in idaresi altına girdiği — Manisa zaten 1415-01-01'den beri d:; 1416 kesin idarenin tarihi, toprak değişimi değil.", yer:"Manisa", yer_id:"Manisa", kisiler:"Çelebi Mehmed, Torlak Kemal", d:"Şeyh Bedreddin hareketinin Batı Anadolu ayağını yürüten Torlak Kemal, Manisa yöresinde yenilgiye uğratılarak idam edildi. Bu tarihten sonra Saruhan bölgesi kesin olarak Osmanlı kontrolüne girdi ve 1402'de Timur'un dirilttiği beylik tarihe karıştı. Fetret Devri'nin Batı Anadolu'daki son siyasî kalıntıları böylece temizlendi.", kaynak:"saruhanogullari", duygu:["✊","😔"] },

// ---------- 0b) MADDESİZ KALAN TOPRAK DEĞİŞİMLERİ ----------
// Kullanıcı tespiti: "Gelibolu'nun geri alınışında Rumeli'de kocaman bir toprak
// parçası ekleniyor ama Gelibolu ile alakalı değil" / "Savcı Bey isyanında
// Filibe ötesinde ele geçirilen toprakların ne olduğu belli değil".
// Sebep: bu şehirler haritada el değiştiriyordu ama o tarihte hiç madde yoktu,
// dolayısıyla değişim bir sonraki alakasız maddede görünüyordu.
{ t:"1363-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Batı Trakya'ya iniş: Gümülcine'nin fethi", fethedilen:["Gümülcine"], gun:"1363 dolayı", yer:"Gümülcine (Komotini)", yer_id:"Gümülcine", kisiler:"Gazi Evrenos Bey, Lala Şâhin Paşa", d:"Edirne'nin alınmasının ardından Meriç'in batısına yönelen uç kuvvetleri, Gazi Evrenos Bey kumandasında Batı Trakya'nın merkezi Gümülcine'yi ele geçirdi. Şehir, Evrenos Bey'in akınlarını Makedonya'ya taşıyacağı ileri karargâh hâline geldi. Böylece Trakya'nın Ege kıyısına uzanan bölümü Osmanlı denetimine girdi ve Selanik yolu açıldı.", kaynak:"gumulcine", duygu:["🎉"] },
{ t:"1373-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Filibe'nin batısı: Tatarpazarcığı ve İhtiman'ın katılışı", gun:"1373 dolayı", yer:"Tatarpazarcığı (Pazarcık), İhtiman", yer_id:"Tatarpazarcığı", kisiler:"Lala Şâhin Paşa", d:"Filibe'nin 1372'de alınmasının ardından Meriç vadisinin yukarı ucundaki Tatarpazarcığı ile Sofya'ya açılan geçidi tutan İhtiman Osmanlı idaresine bağlandı. Çirmen Savaşı sonrası vasallaşan yerel beylerin elindeki bu hat, doğrudan yönetime geçirilerek Filibe-Sofya güzergâhı kesintisiz hâle getirildi. Bu ilerleyiş, on iki yıl sonra Sofya'nın fethine giden yolun hazırlığıdır.", kaynak:"filibe", duygu:["🎉"] },
{ t:"1374-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Struma ve Mesta vadileri: Köstendil, Petriç, Nevrokop ve Drama'nın katılışı", gun:"1374 dolayı", yer:"Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama", yer_id:"Köstendil", kisiler:"Gazi Evrenos Bey, Çandarlı Hayreddin Paşa", d:"Çirmen zaferinden sonra Osmanlı'ya haraç ödemeye başlayan Sırp ve Bulgar yerel beylerinin elindeki Struma ve Mesta vadileri, uç beylerinin ilerleyişiyle doğrudan Osmanlı yönetimine alındı. Köstendil, Petriç, Nevrokop ve Drama'nın katılmasıyla Makedonya'nın doğu yarısı açıldı ve Selanik ile Serez kuşatma çemberine girdi. Haritada Rumeli'nin güneybatıya doğru genişlemesi bu harekâtın sonucudur.", kaynak:"serez", duygu:["🎉"] },
{ t:"1385-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Makedonya'nın içine ilerleyiş: Manastır ve Ohri'nin fethi", gun:"1385 dolayı", yer:"Manastır (Bitola), Ohri, Makedonya", yer_id:"Manastır", kisiler:"Çandarlı Hayreddin Paşa, Gazi Evrenos Bey", d:"Via Egnatia üzerindeki Manastır ile göl kıyısındaki Ohri, Arnavutluk yönündeki akınlar sırasında Osmanlı idaresine girdi. İkisi de Adriyatik'e uzanan yolun kilit noktalarıydı; Ohri ayrıca Balkanlar'ın en eski Ortodoks başpiskoposluk merkeziydi. TDV, Ohri'nin fetih tarihi için kesin bilgi bulunmadığını, 787 (1385) ile Kraliyeviç Marko'nun ölümünden sonraki 797 (1395) tarihlerinin öne sürüldüğünü kaydeder; burada 1385 esas alınmıştır. Manastır ilerleyen yüzyıllarda Rumeli'nin en önemli askerî merkezlerinden biri olacaktı.", kaynak:"ohri", duygu:["🎉"] },
{ t:"1391-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Karadeniz kıyısında Varna'nın alınışı", gun:"1391 dolayı", yer:"Varna", yer_id:"Varna", kisiler:"Yıldırım Bayezid", d:"Bulgar Çarlığı'nın Tuna ile Karadeniz arasındaki topraklarının sıkıştırılması sırasında, kıyıdaki en büyük liman olan Varna Osmanlı idaresine geçti. Limanın alınması Dobruca yönündeki ilerleyişin önünü açtı ve Karadeniz'in batı kıyısında Osmanlı'ya ilk büyük iskeleyi kazandırdı. Varna, elli üç yıl sonra Haçlı ordusunun imha edileceği 1444 zaferinin de sahnesi olacaktı.", kaynak:"varna", duygu:["🎉"] },
{ t:"1419-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Orta Anadolu'nun geri alınışı: Kayseri ve Kırşehir", gun:"1419 dolayı", yer:"Kayseri, Kırşehir", yer_id:"Kayseri", kisiler:"Çelebi Mehmed", d:"Fetret Devri'nde Karamanoğulları'nın eline geçen Orta Anadolu şehirleri, Çelebi Mehmed'in devleti yeniden toparlama seferleri sırasında Osmanlı idaresine döndü. Kayseri ve Kırşehir'in katılmasıyla Ankara Savaşı'nda kaybedilen Kızılırmak havzası büyük ölçüde geri alındı. Bu ilerleyiş, dört yıl önceki Konya kuşatmasıyla başlayan doğuya yönelme siyasetinin devamıdır.", kaynak:"mehmed-i", duygu:["🎉"] },


// ---------- 0c) 1415-1520 ARASI MADDESİZ TOPRAK DEĞİŞİMLERİ ----------
// Kullanıcı tespiti: "Germiyan'ın vasiyetle ilhakında Tâceddinoğulları da
// katılmış görünüyor", "II. Murad'ın ölümünde Preveze ekleniyor",
// "Sırbistan'ın ilhakında Patras da alınıyor", "Mora'nın fethiyle
// Candaroğlu kıyısından toprak geçiyor" — hepsi o tarihte madde olmadığı için
// bir sonraki alakasız maddede görünen değişimlerdi.
{ t:"1423-01-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Tekeoğulları'nın kesin tasfiyesi: Antalya'nın alınışı", gun:"Ocak 1423", yer:"Antalya, Teke ili", yer_id:"Antalya", kisiler:"II. Murad, Hamza Bey, Osman Çelebi", d:"Ankara Savaşı'ndan sonra Timur'un diriltmesiyle yeniden kurulan Tekeoğulları Beyliği, Hamza Bey kumandasındaki Osmanlı kuvvetlerinin Antalya'yı kuşatmasıyla son buldu; beyliğin son önemli adamı Osman Çelebi ortadan kaldırıldı. Böylece Akdeniz kıyısındaki Teke ili yirmi bir yıllık ayrılıktan sonra kesin olarak Osmanlı'ya katıldı. Beylik, Hamîdoğulları'ndan ayrılan kol olarak 1321'den beri Antalya'da hüküm sürüyordu.", kaynak:"tekeogullari", duygu:["🎉"] },
{ t:"1424-01-01", k:"fetih", etiket:["toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Aynaroz (Athos) manastırlarının Osmanlı himayesine girişi", gun:"1424", yer:"Aynaroz (Athos) yarımadası", yer_id:"Aynaroz (Athos)", kisiler:"II. Murad", d:"Selanik'in kuşatma altına alındığı yıllarda, Halkidiki'nin doğu parmağındaki Aynaroz manastır cumhuriyeti II. Murad'a başvurarak himaye istedi ve Osmanlı hâkimiyetini kabul etti. Keşişlerin mülkiyet ve ibadet hakları güvence altına alındı; manastırlar vergi karşılığında iç işlerinde serbest bırakıldı. Bu düzen, Osmanlı'nın Ortodoks kurumlarıyla kurduğu himaye ilişkisinin en uzun ömürlü örneği oldu ve beş asır sürdü.", kaynak:"aynaroz", duygu:["🎉"] },
{ t:"1427-01-01", k:"fetih", etiket:["toprak-kazanc","siyaset","konu-askeri","konu-siyasi"], b:"Tâceddinoğulları Beyliği'nin ilhakı: Niksar", gun:"830 (1427)", yer:"Niksar, Canik", yer_id:"Niksar", kisiler:"II. Murad, Yörgüç Paşa, Hüsâmeddin Hasan Bey", d:"Amasya beylerbeyi Yörgüç Paşa'nın baskısı üzerine Tâceddinoğlu Hüsâmeddin Hasan Bey, merkezi Niksar olan ülkesinin anahtarlarını 830 (1427) yılında teslim etti; kendisine Rumeli'de bir sancak verildi. XIV. yüzyılın ikinci yarısında kurulan ve sınırları zaman zaman Kelkit, Amasya, Samsun, Ordu ve Giresun'a kadar uzanan beylik böylece sona erdi. Aynı yıl Hacıemiroğulları'na ait topraklar da tahrir edilerek Canik sancağına bağlandı; Orta Karadeniz'deki beylikler dönemi kapandı.", kaynak:"taceddinogullari", duygu:["🎉"] },
{ t:"1449-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Epir kıyısının katılışı: Arta ve Preveze", gun:"1449", yer:"Arta, Preveze, Epir", yer_id:"Arta", kisiler:"II. Murad", d:"Yanya'nın 1430'da teslim olmasından on dokuz yıl sonra, Epir despotluğunun kıyı kesimindeki Arta ve Preveze de Osmanlı idaresine girdi. Böylece İyon Denizi'ne açılan Ambrakia körfezi denetim altına alındı ve Yanya'nın deniz bağlantısı tamamlandı. Preveze, doksan yıl sonra Barbaros'un tarihe geçecek zaferine adını verecek olan koyun kilit noktasıdır.", kaynak:"osmanlilar", duygu:["🎉"] },
{ t:"1458-05-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Kuzey Mora'nın fethi: Balyabadra (Patras)", gun:"Mayıs 1458", yer:"Balyabadra (Patras), Mora", yer_id:"Balyabadra (Patras)", kisiler:"Fatih Sultan Mehmed", d:"Sırbistan'ın ilhakıyla aynı yıllarda Mora despotluğuna yönelen Fatih Sultan Mehmed'in kuvvetleri, yarımadanın kuzeybatısındaki Balyabadra'yı ele geçirdi. Korint körfezinin ağzını tutan bu liman, Mora'ya karadan girişin kilididir; alınması iki yıl sonraki nihaî fethin zeminini hazırladı. Şehir, Bizans despotlarının Latin dünyasıyla bağlantı kurduğu son büyük iskeleydi.", kaynak:"balyabadra", duygu:["🎉"] },
{ t:"1460-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Batı Karadeniz kıyısının alınışı: Amasra", gun:"1460", yer:"Amasra, Bartın", yer_id:"Amasra", kisiler:"Fatih Sultan Mehmed", d:"Ceneviz'in Batı Karadeniz'deki müstahkem kolonisi Amasra, Fatih Sultan Mehmed'in donanma ve kara kuvvetlerinin ortak baskısıyla direnmeden teslim oldu. Bartın-Zonguldak kıyısındaki bu liman, Candaroğulları ile Osmanlı toprakları arasında bir Latin cebi olarak duruyordu; alınmasıyla kıyı bütünleşti. Amasra'nın düşüşü, ertesi yıl Sinop ve Trabzon'a yönelecek büyük Karadeniz seferinin ilk adımıdır.", kaynak:"osmanlilar", duygu:["🎉"] },
{ t:"1482-06-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Taman yarımadasının katılışı", gun:"1482", yer:"Taman, Kerç Boğazı", yer_id:"Taman", kisiler:"II. Bayezid", d:"Kefe ve Kerç'in 1475'te alınmasının ardından, Kerç Boğazı'nın doğu yakasındaki Taman yarımadası da Ceneviz elinden çıkarak Osmanlı idaresine girdi. Böylece boğazın iki yakası da denetim altına alındı ve Azak denizine giriş tamamen kontrol edilir hâle geldi. Taman, Kuzey Kafkasya'ya açılan kapı olarak Kefe sancağına bağlandı.", kaynak:"osmanlilar", duygu:["🎉"] },
{ t:"1516-09-26", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Trablusşam ve Hama'nın Osmanlı idaresine girişi", gun:"Eylül 1516", yer:"Trablusşam (Trablus, Lübnan)", yer_id:"Trablusşam", kisiler:"Yavuz Sultan Selim", d:"Halep ve Hama'nın ardından Suriye kıyısındaki Trablusşam da direnmeden Osmanlı idaresine geçti. Doğu Akdeniz'in en işlek limanlarından biri olan şehir, Şam'ın denize açılan kapısıydı ve ipek ile şeker ticaretinin merkeziydi. Alınmasıyla Bilâdüşşam'ın kıyı şeridi bütünüyle el değiştirdi.", kaynak:"trablussam", duygu:["🎉"] },
{ t:"1516-12-28", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Şeria'nın doğusu: Amman'ın Osmanlı idaresine girişi", gun:"Aralık 1516", yer:"Amman", yer_id:"Amman", kisiler:"Yavuz Sultan Selim, Hadım Sinan Paşa", d:"Gazze muharebesinin ardından Mısır seferine hazırlanan Osmanlı kuvvetleri güneye inerken Şeria'nın doğusundaki Amman da Osmanlı idaresine girdi. Filistin'in kıyı ve iç şehirleri (Yafa, Nablus, Sayda, Akkâ, Kudüs) ise Mercidâbık'tan sonra 1516 sonbaharında zaten el değiştirmişti. Bu şehirler dört asır boyunca Şam eyaletinin sancakları olarak yönetildi.", ic_not_d:"17 Eyl 2026 (KOSU13-YAMA · YAMA-KOSU10-KALAN G4-A6A-Y8): Yafa ve Nablus bu günden 1516-09-27'ye taşındı (TDV nablus '922 sonbaharı'); madde Amman'a daraltıldı. Amman'ın 28 Aralık günü ölçülmedi.", kaynak:"yafa", duygu:["🎉"] },
{ t:"1517-01-22", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Süveyş'in alınışı — Kızıldeniz'e açılan kapı", gun:"Ocak 1517", yer:"Süveyş", yer_id:"Süveyş", kisiler:"Yavuz Sultan Selim", d:"Ridâniye zaferiyle birlikte Kızıldeniz'in kuzey ucundaki Süveyş de Osmanlı idaresine geçti. Memlükler'in Hint Okyanusu'na donanma gönderdiği bu tersane-liman, Portekiz'e karşı yürütülecek güney siyasetinin üssü hâline geldi. Süveyş, üç asır sonra kanalın açılacağı hattın kuzey ağzıdır.", kaynak:"suveys", duygu:["🎉"] },

// ---------- 0) KOMŞU BEYLİK VE HANEDANLARIN SONU ----------
// Haritada bir beyliğin rengi kaybolduğunda sebebinin okunabilmesi için,
// Osmanlı'nın doğrudan taraf olmadığı yıkılışlar da madde hâline getirildi.
{ t:"1381-10-01", k:"siyaset", etiket:["siyaset","toprak-kayip","konu-askeri","konu-siyasi"], b:"Eretna Beyliği'nin sona ermesi ve Kadı Burhâneddin Devleti'nin kuruluşu", gun:"1381 sonbaharı", yer:"Sivas, Kayseri", yer_id:"Sivas", kisiler:"Kadı Burhâneddin, Alâeddin Ali Bey'in oğlu Mehmed Bey", d:"1335'te İlhanlı valiliğinden doğan ve Sivas ile Kayseri merkezli Orta Anadolu'yu kırk altı yıl yöneten Eretnaoğulları, saray içi çekişmelerle çözüldü. Mayıs 1378'de vezir olan Kadı Burhâneddin, rakipleri Kılıcarslan ve Hacı Şadgeldi'yi bertaraf ettikten sonra 1381 sonbaharında sultanlığını ilân ederek beyliğe son verdi ve kendi adıyla anılan devleti kurdu. Böylece Osmanlı'nın doğu komşusu el değiştirdi; Sivas-Kayseri hattı bundan sonra on yedi yıl Kadı Burhâneddin'in elinde kalacaktı.", kaynak:"eretnaogullari", duygu:["🏛"] },
{ t:"1398-07-15", k:"siyaset", etiket:["siyaset","savas","toprak-kazanc","konu-askeri","konu-siyasi"], b:"Kadı Burhâneddin Devleti'nin yıkılışı", gun:"1398 (Temmuz)", yer:"Sivas önleri", yer_id:"Sivas", kisiler:"Kadı Burhâneddin, Akkoyunlu Karayülük Osman Bey, Yıldırım Bayezid, Süleyman Çelebi", d:"Akkoyunlu hükümdarı Karayülük Osman Bey'e esir düşen Kadı Burhâneddin, Sivas'ın teslimi karşılığında serbest bırakılmayı teklif ettiyse de şehir halkı direndi ve sultan surların önünde idam edildi. Sivas ileri gelenleri oğlu Alâeddin Ali Çelebi'yi başa geçirdilerse de Akkoyunlu baskısı karşısında Yıldırım Bayezid'den yardım istediler; Süleyman Çelebi kumandasındaki Osmanlı kuvvetleri Karayülük'ü yenerek şehre hâkim oldu. Böylece Kadı Burhâneddin Devleti tarihe karıştı ve Sivas, Tokat, Niksar ile Kayseri Osmanlı topraklarına katıldı. Aynı tarihte katılan öteki yerler: Kırşehir, Çorum.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"kadi-burhaneddin", duygu:["🏛","😔"] },
{ t:"1409-01-01", k:"siyaset", etiket:["siyaset","toprak-kayip","konu-askeri","konu-siyasi","konu-hanedan"], b:"Artuklu hanedanının sonu: Mardin'in Karakoyunlulara teslimi", gun:"1409", yer:"Mardin", yer_id:"Mardin", kisiler:"Artuklu Melik Ahmed, Karakoyunlu Kara Yûsuf", d:"1106'dan beri Mardin'de hüküm süren ve hanedanın en uzun ömürlü kolu olan Artuklular, Akkoyunlu baskısı karşısında tutunamadı. Şehri savunamayacağını anlayan Melik Ahmed, Karakoyunlu hükümdarı Kara Yûsuf ile anlaşarak Mardin'i ona teslim etti. Üç asrı aşan Artuklu hâkimiyeti böylece sona erdi; Mardin ve çevresi, bir asır sonra Osmanlı'ya geçene kadar Karakoyunlu-Akkoyunlu mücadelesinin sahnesi oldu.", kaynak:"artuklular", duygu:["🏛"] },
{ t:"1467-11-10", k:"savas", etiket:["savas","siyaset","konu-askeri","konu-siyasi","konu-kisiler"], kapsam:"dis", onem:4, b:"Karakoyunlu Devleti'nin çöküşü: Cihan Şah'ın öldürülmesi", gun:"10 Kasım 1467", yer:"Bingöl – Kiğı arası", kisiler:"Karakoyunlu Cihan Şah, Akkoyunlu Uzun Hasan", d:"Uzun Hasan üzerine çıktığı seferden kışın bastırması yüzünden dönerken baskına uğrayan Karakoyunlu hükümdarı Cihan Şah, Bingöl ile Kiğı arasında kaçarken öldürüldü. Bu darbeden sonra devlet toparlanamadı; son hükümdar Hasan Ali 1469'da Uzun Hasan'ın oğlu Uğurlu Mehmed tarafından esir alınıp öldürüldü. Doğu Anadolu, Azerbaycan ve Irak'ta bir asra yakın hüküm süren Karakoyunlu hâkimiyeti böylece Akkoyunlulara geçti.", kaynak:"karakoyunlular", duygu:["⚔️"], yer_kon:[39.1,40.4] },
{ t:"1516-08-24", k:"siyaset", etiket:["siyaset","toprak-kazanc","konu-askeri","konu-siyasi"], b:"Ramazanoğulları Beyliği'nin Osmanlı'ya bağlanması", gun:"24 Ağustos 1516", yer:"Adana, Çukurova", yer_id:"Adana", kisiler:"Yavuz Sultan Selim, Ramazanoğlu Mahmud Bey", d:"Mercidâbık zaferinin ardından yapılan tevcihler sırasında Adana merkezli Ramazanoğulları Beyliği Mahmud Bey'e verilerek Osmanlı hâkimiyetine alındı. Memlük tâbiiyetinden çıkan beylik, ortadan kaldırılmak yerine 'ocaklık' statüsüyle aileye bırakıldı; Ramazanoğulları Çukurova'nın idaresini Osmanlı sancak beyi sıfatıyla sürdürdü. Bu ayrıcalıklı düzen, Pîr Mansûr'un beyliği bıraktığı 1608 yılına kadar devam etti. Aynı tarihte katılan öteki yerler: Malatya, Tarsus, Musul, Antep.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"ramazanogullari", duygu:["🏛"] },

// ---------- A) KURULUŞ VE YÜKSELİŞ (1299-1512) ----------
{ t:"1324-01-01", kesinlik:"yil", ic_not_t:"eski: t:1324-08-01 — ay/gün hiçbir TDV cümlesinde yok (TDV osman-i: \"Osman 724'te (1324) ölmüştür\"); 08-01, 28 Temmuz 2026 senkron taramasında (b47d09a7) 1324-01-01'den çekilmişti, bugün ±30 gün içinde ona dayanan kırılma yok. D263 sınandı: TDV penceresi 1 Muharrem 724 (≈30 Aralık 1323) – Rebîülevvel 724 ortası (≈13 Mart 1324, orhan: Şerefeddin Mukbil beratı) ⇒ 1324-01-01 penceresinin İÇİNDE; eski 08-01 DIŞINDAYDI · UMIT-W4-DALGA2-1006", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler"], b:"Osman Gazi'nin vefatı ve Orhan Bey'in beyliğe geçişi", gun:"1324", yer:"Söğüt – Bursa", yer_id:"Söğüt", kisiler:"Osman Gazi, Orhan Bey", d:"Beyliğe adını veren Osman Gazi, Asporça Hatun ve Mekece vakfiyelerinin tanıklığıyla 724 (1324) yılında vefat etti. 1305'ten beri seferlerde ordunun başında bulunan oğlu Orhan, babasının ölümü üzerine hiçbir taht kavgası yaşanmadan beyliğin başına oturdu. Kurucu neslin sancağı sarsıntısız devretmesi, uç beyliğinden devlete uzanan yolda hanedanın ilk büyük sınavını sükûnetle geçtiğini gösterir.", kaynak:"osman-i", vefat_id:"osman1", duygu:["🏛"] },
{ t:"1331-03-03", k:"bilim", etiket:["bilim","kultur","imar","konu-bilim","konu-kultur","konu-imar","konu-egitim"], b:"İznik'te ilk Osmanlı medresesinin kurulması", gun:"1331, fethin ardından (bina 1336'da tamamlandı)", ic_not_gun:"0042/H-0010 (PAKET-A3, 13 Eylül 2026): kaynak kuruluş GÜNÜ vermiyor. Eski t:1331-01-01 maddeyi İznik'in fethinden (olaylar.js t:1331-03-02) önce sıralıyordu. Gün, fetih maddesinin ertesi günü olarak DEVRALINDI (1.MURAT kuralı: kaynak gün vermiyorsa fetihten sonraki gün). TDV iznik imarı fetihten hemen sonraya koyar; TDV davud-i-kayseri inşaatın 1336'da bittiğini yazar.", yer:"İznik", yer_id:"İznik", kisiler:"Orhan Bey, Çandarlı Kara Halil, Dâvûd-i Kayserî", d:"Orhan Bey, İznik'i aldıktan hemen sonra Çandarlı Kara Halil'i buraya kadı tayin etti, bir bazilikayı camiye çevirdi ve yanına bir imaretle bir medrese yaptırarak şehrin imarını başlattı. TDV'nin Dâvûd-i Kayserî maddesine göre medresenin inşaatı 1336'da tamamlandı ve Orhan Gazi müderrisliğine günlük 30 akçe ile Dâvûd-i Kayserî'yi getirdi. Bu medrese Osmanlı ilim hayatının ilk kurumsal adımıdır; beylik, fetih gücünün yanına bir ilim geleneği de eklemiş oldu. Fetihle alınan bir Bizans başkentinin İslâm ilim merkezine dönüşmesi, Osmanlı'nın yerleşik devlet olma iddiasının ilk somut işaretiydi.", kaynak:"iznik · davud-i-kayseri", duygu:["🔬"] },
{ t:"1352-01-01", k:"antlasma", etiket:["diplomasi","ekonomi","konu-diplomasi","konu-ekonomi"], b:"Orhan Gazi'nin Cenevizlilerle ilk kapitülasyonu", gun:"1352 başları", yer:"İzmit körfezi — Pera (Galata)", yer_id:"İzmit", kisiler:"Orhan Gazi, Paganino Doria", d:"Venedik-Ceneviz savaşı sırasında Cenevizliler'le anlaşan Orhan Gazi, Şubat 1352'deki Boğaz savaşının ardından Pera'nın savunmasına 1000 okçu gönderdi ve asker taşınması için 60.000 altın sağladı; karşılığında Cenevizliler'e ilk kapitülasyonu bağışladı. Antlaşmanın tam metni günümüze ulaşmamıştır. Bu, Osmanlı'nın bir Avrupa deniz gücüyle yaptığı ilk resmî anlaşmadır ve otuz beş yıl sonra 1387'de yenilenecekti.", kaynak:"orhan", duygu:["🤝"] },
{ t:"1354-03-02", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri","konu-imar","konu-ulastirma","afet","afet-deprem"], b:"Gelibolu'nun alınışı — Rumeli'de kalıcı köprübaşı", gun:"2 Mart 1354", yer:"Gelibolu", yer_id:"Gelibolu", kisiler:"Süleyman Paşa, Orhan Gazi", d:"1349-1352 yılları arasında Kantakuzenos'un müttefiki sıfatıyla civarını tanıdıkları Gelibolu'yu Osmanlılar 1354'te ele geçirdiler; şehrin surlarını yıkan büyük deprem fırsatı doğurmuştu. Çimpe'deki dar köprübaşı böylece Boğaz'ın Rumeli yakasında gerçek bir üsse dönüştü ve Trakya'ya açılan kapı ardına kadar aralandı. Gelibolu 1366'da Savoy Haçlı seferiyle elden çıkacak, ancak 1376'daki ikinci fetihle kesin olarak Osmanlı hâkimiyetine girecekti. Aynı tarihte katılan öteki yerler: Kilitbahir.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"gelibolu", duygu:["🎉"] },
{ t:"1357-09-01", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler"], b:"Rumeli fâtihi Süleyman Paşa'nın ölümü", gun:"1357 sonbaharı", yer:"Bolayır", yer_id:"Bolayır", kisiler:"Süleyman Paşa, Orhan Gazi", d:"Orhan Bey'in büyük oğlu ve Rumeli fetihlerinin mimarı Süleyman Paşa, kaynaklarda 758 (1357), 759 ve 760 (1359) olarak verilen tarihlerden en çok kabul göreni olan 1357 sonbaharında, bir av sırasında attan düşerek öldü. 1352-1354 yılları arasındaki geçişleriyle Rumeli'deki kalıcı Osmanlı varlığını kuran şehzadenin ölümü, veliahtlık sırasını kardeşi Murad'a bıraktı. Bolayır'a defnedilen Süleyman Paşa'nın türbesi, Osmanlı'nın Avrupa'daki en eski hanedan anıtı olarak kaldı.", kaynak:"suleyman-pasa", duygu:["🏛"] },
{ t:"1361-01-01", k:"siyaset", etiket:["siyaset","ekonomi","konu-siyasi","konu-ekonomi","konu-hukuk"], b:"Pençik Kanunu — Yeniçeri Ocağı'nın temelinin atılması", gun:"1361", yer:"Edirne", yer_id:"Edirne", kisiler:"I. Murad, Karamanlı Kara Rüstem, Çandarlı Kara Halil", d:"Rumeli fetihlerinin ardından ulemâdan Karamanlı Kara Rüstem'in tavsiyesiyle, savaş esirlerinin beşte birinin veya bunun para karşılığının devlete ayrılmasını öngören pençik sistemi yürürlüğe kondu. Bu esirlerden seçilenlerin Türk ailelerinin yanında yetiştirilip askere alınmasıyla, doğrudan padişaha bağlı daimî bir piyade gücünün — Yeniçeri Ocağı'nın — çekirdeği oluştu. Aşiret süvarisine dayanan bir uç beyliğinin merkezî orduya sahip bir devlete dönüşmesi bu düzenlemeyle başladı.", kaynak:"pencik", duygu:["🏛"] },
{ t:"1373-05-15", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan","konu-hanedan"], b:"Savcı Bey isyanı — şehzade ile Bizans veliahdinin ortak başkaldırısı", gun:"Mayıs 1373 başı", yer:"Bursa – İstanbul", yer_id:"Bursa", kisiler:"I. Murad, Savcı Bey, Andronikos Palaiologos, V. Ioannes", d:"I. Murad'ın oğlu Savcı Bey ile Bizans İmparatoru V. Ioannes'in oğlu Andronikos Palaiologos, 1373 Mayıs'ının başında Bursa ve İstanbul'da eş zamanlı olarak babalarına karşı ayaklandılar. İki hanedanın veliahtlarını birleştiren bu ittifak hızla bastırıldı; Savcı Bey yakalanarak gözlerine mil çekildi ve idam edildi. Osmanlı rivayetinin isyan için verdiği 787 (1385) tarihi hatalıdır; olay Bizans'ın Osmanlı vasallığına girdiği yılların hemen ardına düşer ve iki sarayın ne kadar iç içe geçtiğini gösterir.", kaynak:"murad-i", duygu:["✊"] },
{ t:"1385-09-18", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Savra Savaşı — Arnavutluk kapılarının açılması", gun:"18 Eylül 1385", yer:"Savra ovası, Arnavutluk", kisiler:"Hayreddin Paşa, Karlo Topya, II. Balşa", d:"Balşa hânedanına karşı sıkışan Arnavut beyi Karlo Topya'nın yardım çağrısı üzerine Osmanlı kuvvetleri Savra ovasında II. Balşa'nın ordusunu bozguna uğrattı; Balşa savaş meydanında hayatını kaybetti. Bir yerli beyin daveti üzerine girilen bu savaş, Osmanlılara Adriyatik kıyılarına kadar uzanan Arnavut topraklarında ilk kalıcı nüfuzu kazandırdı. Bölgedeki beylerin birbirine düşmesini fırsata çeviren bu siyaset, önümüzdeki yüzyıl boyunca Balkan fetihlerinin değişmez yöntemi olacaktı.", kaynak:"arnavutluk", duygu:["⚔️"], yer_kon:[40.65,19.75] },
{ t:"1386-06-01", k:"savas", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Frenkyazısı Savaşı ve Konya kuşatması — ilk Karaman seferi", gun:"788 / 1386", yer:"Konya ovası (Frenkyazısı)", yer_id:"Konya", kisiler:"I. Murad, Karamanoğlu Alâeddin Ali Bey", d:"Damadı olmasına rağmen Osmanlı'nın Batı Anadolu'daki genişlemesinden rahatsız olan Karamanoğlu Alâeddin Ali Bey'e karşı I. Murad bizzat sefere çıktı; Frenk Yazısı denilen mevkide yapılan savaşta tâlimli ve tecrübeli Osmanlı ordusu Karamanlı kuvvetlerini yendi. Ardından Konya Kalesi kuşatıldı, ancak Alâeddin Bey'in affedilmesiyle beylik tamamen ortadan kaldırılmadı. Bu sefer, Osmanlı ile Karaman arasında bir yüzyıl sürecek ve ancak 1468'de kesin ilhakla bitecek uzun hesaplaşmanın açılış perdesidir.", kaynak:"karamanogullari", duygu:["⚔️"] },
{ t:"1390-06-01", k:"diger", etiket:["siyaset","ekonomi","imar","islahat","konu-siyasi","konu-ekonomi","konu-imar","konu-islahat"], b:"Gelibolu Tersanesi'nin kurulması — Osmanlı donanmasının doğuşu", gun:"1390", yer:"Gelibolu", yer_id:"Gelibolu", kisiler:"Yıldırım Bayezid", d:"Osmanlı Devleti'nin ilk teşekküllü tersanesi 1390'da Yıldırım Bayezid tarafından Gelibolu'da, Bizans'tan kalan tersanenin yerinde kuruldu. Batı Anadolu beyliklerinin denizci mirasını devralan Osmanlı, böylece ilk defa kendi gemisini kendi yapan bir deniz gücü hâline geldi. Çanakkale Boğazı'nın kilit noktasında konumlanan tersane, İstanbul'un kuşatılmasından Ege seferlerine kadar bir buçuk asır boyunca Osmanlı donanmasının ana üssü olarak hizmet verdi.", kaynak:"tersane-i-amire", duygu:["📌"] },
{ t:"1393-06-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Amasya'nın Osmanlı topraklarına katılması", gun:"1393", yer:"Amasya", yer_id:"Amasya", kisiler:"Yıldırım Bayezid, Şehzade Mehmed Çelebi", d:"Yıldırım Bayezid'in Orta Anadolu harekâtı sırasında kuşatılan Amasya emîri şehri Osmanlılara teslim etti ve Bayezid 1393'te şehre girdi. Sultan, buranın idaresini oğlu Mehmed Çelebi'ye bıraktı; şehzade sancağı olarak Amasya bundan sonra Osmanlı hanedanının en önemli eğitim ocaklarından biri hâline geldi. Bu tercih ilerideki Fetret Devri'nde belirleyici olacak, Çelebi Mehmed devleti yeniden birleştirme mücadelesini işte bu Amasya tabanından yürütecekti.", kaynak:"bayezid-i", duygu:["🎉"] },
{ t:"1400-01-01", k:"bilim", etiket:["bilim","kultur","imar","konu-bilim","konu-kultur","konu-imar"], b:"Bursa'da Yıldırım Darüşşifası — ilk Osmanlı hastanesi", gun:"1400", yer:"Bursa", yer_id:"Bursa", kisiler:"Yıldırım Bayezid", d:"Yıldırım Bayezid, Bursa'da muhteşem Ulucami'yi yaptırdığı yıllarda şehre bir de dârüşşifa kazandırdı; imaret, medrese, han ve köprüden oluşan geniş hayrat programının tıbba ayrılan halkası buydu. Devletin kurduğu ilk hastane olan bu yapı, hekim yetiştiren bir tıp mektebi işlevi de görerek Osmanlı sağlık kurumlarının modelini belirledi. Ankara felâketinden yalnızca iki yıl önce tamamlanan eser, Yıldırım'ın Bursa'yı bir imparatorluk başkentine dönüştürme tasavvurunun son halkalarındandır.", kaynak:"bayezid-i", duygu:["🔬"] },
{ t:"1415-03-01", k:"antlasma", etiket:["antlasma","savas","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Konya kuşatması ve Karamanoğulları ile antlaşma — Hamîd-ili, Said-ili, Beyşehir, Seydişehir ve Akşehir geri alındı", gun:"Muharrem 818 / Mart 1415", ic_not_gun:"Ay düzeyi (Muharrem 818 = Mart-Nisan 1415). 1414-06-01 tarihli mükerrer madde buraya BİRLEŞTİRİLDİ (Emre kararı A, GEMINI-DOGRULA 19 Eyl 2026): TDV kendi içinde çelişiyor — mehmed-i 'Muharrem 818 / Mart 1415', karamanogullari '817/1414'. 817 H 12 Mart 1415'te biter; mehmed-i sefer öncesi mektubu 'evâsıt-ı Zilhicce 817 [Şubat 1415 ortaları]' diye tarihliyor, bu yüzden ay veren mehmed-i esas alındı.", yer:"Konya, Beyşehir, Seydişehir, Akşehir, Isparta", yer_id:"Konya", kisiler:"Çelebi Mehmed, Karamanoğlu II. Mehmed Bey", d:"Fetret Devri'nde Osmanlı topraklarına saldıran ve Bursa'yı kuşatıp yakan Karamanoğulları'na karşı Çelebi Mehmed büyük bir sefer düzenleyerek Muharrem 818'de Konya'yı kuşattı. Karamanoğlu II. Mehmed Bey barış istemek zorunda kaldı; antlaşma sonucunda Hamîd-ili (Isparta yöresi) ve Said-ili yeniden Osmanlı topraklarına katıldı, Beyşehir, Seydişehir ve Akşehir de geri verildi. Ankara Savaşı'yla dağılan Anadolu birliğinin yamanmaya başladığı bu sefer, Çelebi Mehmed'in 'ikinci kurucu' sayılmasının somut gerekçelerindendir.", kaynak:"mehmed-i AYNEN: 'Mehmed bu seferde Karamanlılar'ı yendi ve Konya'yı kuşatma altına aldı (Muharrem 818 / Mart 1415).' · 'Karamanoğlu barış istedi, Hamîd-ili (Isparta yöresi), Said-ili toprakları Osmanlı ülkesine katıldı.' · ÇELİŞKİ: karamanogullari AYNEN 'Mehmed Bey Beyşehir, Seydişehir ve Akşehir'i Osmanlılar'a geri vermek zorunda kaldı (817/1414).'", duygu:["🤝","🎉"] },
{ t:"1417-01-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Avlonya, Berat ve Kanina'nın fethi", gun:"1417", yer:"Avlonya (Vlorë), Arnavutluk", yer_id:"Avlonya", kisiler:"Çelebi Mehmed", d:"Osmanlılar 1417'de Adriyatik kıyısındaki Avlonya'yı, ülkenin iç kesimindeki Berat şehri ve Kanina Kalesi ile birlikte hâkimiyetleri altına aldılar. Bir yıl sonra Venedik'in şehri geri alma teşebbüsü başarısızlığa uğradı ve burada bir sancak teşkilâtı kurularak Osmanlı otoritesi kalıcılaştı. Avlonya'nın alınması, Osmanlı'yı ilk defa Adriyatik'te doğrudan bir liman sahibi yaparak İtalya karşısında deniz aşırı bir sıçrama tahtası kazandırdı.", kaynak:"avlonya", duygu:["🎉"] },
{ t:"1423-05-01", k:"savas", etiket:["savas","antlasma","konu-askeri","konu-diplomasi"], b:"Turahan Bey'in Mora seferi ve Hexamilion Suru'nun yıkılışı", gun:"1423", yer:"Mora yarımadası – Korint Berzahı", yer_id:"Mora (Tripoliçe)", kisiler:"II. Murad, Turahan Bey", d:"Bizans'ın rakip taht iddiacısı Mustafa Çelebi'yi desteklemesi üzerine II. Murad, Turahan Bey'i Mora üzerine gönderdi. Turahan Bey, Korint Berzahı'nı baştan başa kapatan Hexamilion duvarını yıkıp yarımadaya girdi ve büyük tahribata yol açtı. Barış, surun bir daha inşa edilmemesi ve yıllık vergi ödenmesi şartıyla sağlandı; Mora despotluğu böylece askerî olarak savunmasız bırakılarak 1460'taki nihaî fethin zemini otuz yedi yıl önceden hazırlandı.", kaynak:"mora", duygu:["⚔️","😔"] },
{ t:"1446-05-05", k:"isyan", etiket:["isyan","siyaset","darbe-askeri","konu-siyasi","konu-isyan","konu-darbe"], b:"Buçuktepe Vak'ası — ilk yeniçeri ayaklanması ve II. Murad'ın tahta dönüşü", gun:"5 Mayıs 1446", yer:"Edirne", yer_id:"Edirne", kisiler:"II. Murad, II. Mehmed, Çandarlı Halil Paşa", d:"Edirne'de patlak veren ve tarihin bildiği ilk yeniçeri ayaklanması olan Buçuktepe Vak'ası, ulûfelerinin yarım akçe artırılması talebiyle başladı ve genç II. Mehmed'in tahttan indirilmesiyle sonuçlandı. II. Murad 8 Safer 850'de Manisa'dan acele yola çıkarak ikinci saltanatına başladı. Olay, kapıkulu ocağının artık taht üzerinde söz sahibi bir güç hâline geldiğini gösteren ilk işaret oldu ve Fatih'in yeniçeriye karşı ömür boyu sürecek temkinini şekillendirdi.", kaynak:"bucuktepe-vakasi", duygu:["✊"] },
{ t:"1451-02-18", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"II. Murad'ın vefatı ve II. Mehmed'in ikinci cülûsu", gun:"3 Şubat 1451 (vefat) – 18 Şubat 1451 (cülûs)", yer:"Edirne", yer_id:"Edirne", kisiler:"II. Murad, II. Mehmed (Fatih), Çandarlı Halil Paşa", d:"Oğlunun düğününün ardından hastalanan II. Murad, 1 Muharrem 855'te (3 Şubat 1451) Edirne'de vefat etti. On dokuz yaşındaki II. Mehmed, 16 Muharrem 855'te (18 Şubat 1451) ikinci defa Osmanlı tahtına çıktı — bu kez kalıcı olarak. Beş yıl önce Buçuktepe'de tahtından indirilen genç hükümdarın dönüşü, iki yıl sonra İstanbul'un fethiyle taçlanacak ve Osmanlı Beyliği'ni bir dünya imparatorluğuna dönüştürecek saltanatın başlangıcıdır.", kaynak:"mehmed-ii", duygu:["🏛","😔"], vefat_id:"murad2" },
{ t:"1454-07-14", k:"savas", etiket:["savas","konu-askeri"], b:"Osmanlı-Kırım müşterek kuvvetlerinin ilk Kefe muhasarası", gun:"14 Temmuz 1454", yer:"Kefe (Feodosya), Kırım", yer_id:"Kefe", kisiler:"Hacı Giray, Fâtih Sultan Mehmed", d:"Haziran 1454'te Fâtih Sultan Mehmed ile anlaşan Kırım Hanı Hacı Giray, 7000 atlısıyla Kefe'yi karadan kuşattı; kırk-elli parçalık bir Osmanlı donanması da açıklarda mevzilendi. Cenevizli Kefe, kuşatmayı haraç ödeyerek kaldırttı ve kesin fetih yirmi bir yıl sonraya, 1475'e kaldı. Bu ilk ortak harekât, Osmanlı-Kırım askerî iş birliğinin ileride Kefe'nin kesin fethinde tekrarlanacak ilk örneğiydi.", kaynak:"haci-giray-i", duygu:["⚔️"] },
{ t:"1455-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Kuzey Ege adalarının alınışı: Bozcaada, İmroz ve Taşoz", gun:"1455", yer:"Bozcaada, İmroz (Gökçeada), Taşoz", yer_id:"Bozcaada", kisiler:"Fatih Sultan Mehmed, Gattilusio ailesi", d:"İstanbul'un fethinden hemen sonra Fatih Sultan Mehmed, yeni başkentin deniz yolunu güvenceye almak için Çanakkale Boğazı'nın Ege ağzındaki adalara yöneldi; Bozcaada ile İmroz Bizans'tan, Taşoz ise Ceneviz asıllı Gattilusio ailesinden alındı. Boğazın iki yakasını kilitleyen bu adalar, bundan sonra İstanbul'un iaşe ve savunma hattının ilk halkası oldu. Papalık ve Venedik donanmalarının müdahaleleriyle hâkimiyet bir süre gidip geldi ve ancak 1459'da kesinleşti.", kaynak:"mehmed-ii", duygu:["🎉"] },
{ t:"1455-06-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Kosova'nın fethi: Priştine ve Yenipazar'ın alınması", gun:"1455", yer:"Priştine, Yenipazar (Novi Pazar), Kosova", yer_id:"Priştine", kisiler:"Fatih Sultan Mehmed, Brankoviç hânedanı", d:"Sırp Despotluğu üzerine yürüyen Osmanlı ordusu, Kosova ovasındaki Priştine ile Raşka bölgesinin merkezi Yenipazar'ı ele geçirdi; aynı harekâtta gümüş madenleriyle ünlü Novoberda da alındı. Böylece Sırbistan'ın güney yarısı doğrudan Osmanlı idaresine bağlandı ve Semendire'deki despotluk merkezî topraklarından koparıldı. Bu fetih, dört yıl sonra Sırbistan'ın tamamen ilhakına giden yolun belirleyici adımıydı.", kaynak:"sirbistan", duygu:["🎉"] },
{ t:"1456-01-24", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Enez'in ve Semadirek'in fethi — Batı Trakya kıyısının tamamlanması", gun:"Ocak 1456", yer:"Enez (Meriç ağzı), Semadirek", yer_id:"Enez", kisiler:"Fatih Sultan Mehmed, Dorino Gattilusio", d:"Meriç nehrinin denize döküldüğü yerdeki Enez, seksen yıldır burayı elinde tutan Ceneviz asıllı Gattilusio ailesinden alındı; buraya bağlı Semadirek adası da aynı harekâtta ele geçirildi. Enez'in düşmesiyle Batı Trakya kıyı şeridi Selanik'ten Gelibolu'ya kadar kesintisiz Osmanlı toprağı hâline geldi. Gattilusio ailesinin elinde yalnız Midilli kaldı; o da altı yıl sonra alınacaktı.", kaynak:"mehmed-ii", duygu:["🎉"] },
{ t:"1456-07-22", k:"savas", etiket:["savas","konu-askeri"], b:"Belgrad kuşatmasının başarısızlığı", gun:"4-22 Temmuz 1456", yer:"Belgrad", yer_id:"Belgrad", kisiler:"Fatih Sultan Mehmed, Jan Hunyadi, Kapistrano", d:"Fatih Sultan Mehmed, İstanbul'un fethinden sonra Orta Avrupa'nın kilidi sayılan Belgrad'ı kuşattı; ancak Jan Hunyadi'nin Tuna'dan getirdiği takviye ve haçlı vaizi Kapistrano'nun topladığı gönüllüler kalenin düşmesini önledi. Padişah, kuşatma önünde gösterdiği şahsî kahramanlığa rağmen yaralanarak çekilmek zorunda kaldı. Bu başarısızlık, Macaristan sınırını altmış beş yıl boyunca Osmanlı ilerleyişine kapatacak; Belgrad ancak 1521'de Kanûnî tarafından alınabilecekti.", kaynak:"mehmed-ii", duygu:["⚔️"] },
{ t:"1462-09-17", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Midilli adasının fethi", gun:"Zilhicce 866 / Eylül 1462", yer:"Midilli (Lesbos), Molova", yer_id:"Midilli", kisiler:"Fatih Sultan Mehmed, Dorino Gattilusio", d:"Fâtih Sultan Mehmed kumandasındaki Osmanlı ordusu Zilhicce 866'da Midilli'yi kısa fakat şiddetli bir kuşatmanın ardından Ceneviz asıllı Gattilusio ailesinin elinden alarak ilhak etti. Kuzey Ege'nin en büyük adasının düşüşü, Cenevizlilerin bölgedeki son önemli üssünü de tasfiye etti. Ada, Anadolu sahiline yakınlığı sayesinde bundan sonra Osmanlı donanması için ileri karakol görevi görecek, aynı zamanda Barbaros kardeşlerin yetiştiği yer olarak denizcilik tarihine geçecekti.", kaynak:"midilli", duygu:["🎉"] },
{ t:"1463-07-01", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"On altı yıllık Osmanlı-Venedik Savaşı'nın başlaması", gun:"1463", yer:"Ege – Mora – Arnavutluk", yer_id:"Mora (Tripoliçe)", kisiler:"Fatih Sultan Mehmed, Venedik Cumhuriyeti, Uzun Hasan", d:"Venedikliler, Osmanlı'nın Mora ve Ege'deki ilerleyişini durdurmak için Karaman ve Akkoyunlu idarecileriyle ittifak yaparak 1463'te savaşı başlattılar. Doğuda Uzun Hasan, batıda Venedik ve arada Karaman ile kurulan bu kuşatma stratejisi, Fatih'i aynı anda birden çok cephede savaşmaya zorladı. On altı yıl süren mücadele Otlukbeli'nden Arnavutluk seferlerine kadar dönemin bütün büyük harekâtlarını kapsayacak ve ancak 1479 İstanbul Antlaşması ile sona erecekti.", kaynak:"venedik", duygu:["⚔️"] },
{ t:"1466-06-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"II. Arnavutluk seferi — Fatih'in İskender Bey üzerine bizzat yürüyüşü", gun:"1466-1467", yer:"Arnavutluk – Akçahisar (Kruja)", yer_id:"Akçahisar (Kruja)", kisiler:"Fatih Sultan Mehmed, İskender Bey (Skanderbeg)", d:"İskender Bey'in çeyrek asrı aşan direnişini kırmak için Fatih Sultan Mehmed 1466-1467 yıllarında bizzat kumanda ettiği büyük seferleri düzenledi. Osmanlı ordusu Akçahisar'ı kuşattı ve bölgeyi denetim altına almak üzere İlbasan (Elbasan) Kalesi'ni inşa etti. Sefer, Arnavut direnişinin belini kırmakla birlikte kaleyi düşürmeyi başaramadı; bölgenin tam tâbiiyeti İskender Bey'in ölümünden sonraki on yılı bulacaktı.", kaynak:"iskender-bey", duygu:["⚔️"] },
{ t:"1468-01-17", k:"siyaset", etiket:["siyaset","savas","konu-askeri","konu-siyasi","konu-kisiler"], b:"İskender Bey'in ölümü — Arnavut direnişinin sönmesi", gun:"17 Ocak 1468", yer:"Leş (Alessio), Arnavutluk", kisiler:"İskender Bey (Skanderbeg), Fatih Sultan Mehmed", d:"Osmanlı sarayında yetişmişken 1444'te İzlâdi bozgununun ardından isyan eden ve çeyrek asrı aşkın süre Arnavutluk'ta direnen İskender Bey, sığındığı Leş'te öldü. II. Murad ve Fatih devirlerinde Osmanlı ordularını defalarca oyalayan bu direniş, onun ölümüyle merkezî önderliğini yitirdi. Papalık ve Venedik'in beslediği Arnavut cephesinin çökmesiyle Osmanlılar on yıl içinde Akçahisar ve İşkodra'yı alarak bölgeyi kesin olarak topraklarına kattılar.", kaynak:"iskender-bey", duygu:["🏛"], yer_kon:[41.7833,19.65] },
{ t:"1475-01-10", k:"savas", etiket:["savas","konu-askeri"], b:"Boğdan'da Racova (Vaslui) bozgunu", gun:"10 Ocak 1475", yer:"Racova – Vaslui, Boğdan", kisiler:"Hadım Süleyman Paşa, Stefan cel Mare (Büyük Ştefan)", d:"Boğdan voyvodası Stefan cel Mare, Rumeli Beylerbeyi Hadım Süleyman Paşa kumandasındaki Osmanlı kuvvetlerini bataklık araziye çekerek ağır bir yenilgiye uğrattı. Fatih devrinin en ağır kara mağlubiyetlerinden biri olan bu bozgun, Avrupa'da büyük yankı uyandırdı ve Stefan'a haçlı âleminde ün kazandırdı. Padişah ertesi yıl misilleme için bizzat sefere çıkacaktı.", kaynak:"bogdan", duygu:["⚔️","😔"], yer_kon:[46.6407,27.7276] },
{ t:"1476-07-26", k:"savas", etiket:["savas","konu-askeri"], b:"Akdere (Valea Albă) zaferi — Boğdan seferi", gun:"26 Temmuz 1476", yer:"Akdere (Valea Albă) – Suceava, Boğdan", kisiler:"Fatih Sultan Mehmed, Stefan cel Mare", d:"Bir yıl önceki Racova bozgununun intikamını almak üzere bizzat sefere çıkan Fatih Sultan Mehmed, Osmanlı ordusuyla Boğdan birliklerini Akdere mevkiinde büyük bir hezimete uğrattı ve beyliğin merkezi Suceava'ya girdi. Ancak kaleler ele geçirilemedi; erzak sıkıntısı, yeniçeriler arasında baş gösteren veba ve Macar hazırlıkları yüzünden ordu geri çekilmek zorunda kaldı. Boğdan'ın kesin bağlılığı ancak müteakip yıllarda ve Kili ile Akkirman'ın 1484'te alınmasıyla sağlanabilecekti.", kaynak:"bogdan", duygu:["⚔️","😔"], yer_id:"Suçava (Suceava)" },
{ t:"1478-06-15", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Akçahisar'ın (Kruja) fethi ve Arnavutluk'un tamamlanması", gun:"1478", yer:"Akçahisar (Kruja), Drivasto, Leş", yer_id:"Akçahisar (Kruja)", kisiler:"Fatih Sultan Mehmed, Gedik Ahmed Paşa", d:"İskender Bey'in ölümünden on yıl sonra, 1478'de Akçahisar, Drivasto, Leş ve Jabyak'ın ele geçirilmesiyle Arnavutluk'un fethi büyük ölçüde tamamlandı. Yıllarca Osmanlı ordularına direnen ve İskender Bey direnişinin simgesi olan Kruja Kalesi'nin düşüşü, bölgedeki Venedik-Arnavut ittifakının sonu anlamına geliyordu. Geriye kalan İşkodra ise ertesi yıl imzalanacak İstanbul Antlaşması ile Osmanlı'ya bırakılacaktı.", kaynak:"arnavutluk", duygu:["🎉"] },
{ t:"1480-07-28", k:"savas", etiket:["savas","konu-askeri"], b:"Rodos kuşatmasının başarısızlığı", gun:"28 Temmuz 1480", yer:"Rodos adası", yer_id:"Rodos", kisiler:"Mesih Paşa, Pierre d'Aubusson, Fatih Sultan Mehmed", d:"Fatih Sultan Mehmed'in emriyle Mesih Paşa kumandasındaki 160 parçalık donanma 885 (1480) baharında Rodos'u kuşattı ve ada üç ay boyunca ablukada kaldı. Büyük üstat Pierre d'Aubusson önderliğindeki Saint-Jean şövalyeleri ağır kayıplara rağmen şiddetle direndi; 20 Cemâziyelevvel 885'te yapılan son büyük hücumun da püskürtülmesi üzerine donanma 3 Ağustos'ta çekildi. Bu başarısızlığın ardından şehrin surları baştan yenilenerek Avrupa'nın en güçlü istihkâmı hâline getirildi ve ada ancak 1522'de Kanûnî tarafından alınabildi.", kaynak:"rodos", duygu:["⚔️"] },
{ t:"1481-06-20", k:"savas", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Yenişehir Muharebesi — Cem Sultan'ın yenilgisi", gun:"20 Haziran 1481", yer:"Yenişehir, Bursa", yer_id:"Yenişehir (Bursa)", kisiler:"II. Bayezid, Cem Sultan, Gedik Ahmed Paşa", d:"Fatih'in ölümünün ardından taht için harekete geçen iki kardeş Yenişehir ovasında karşı karşıya geldi ve Cem Sultan kesin bir yenilgiye uğradı. Bursa'da on sekiz gün hüküm sürüp adına hutbe okutan şehzade, mağlubiyetin ardından önce Konya'ya, oradan Memlük topraklarına sığınmak zorunda kaldı. Yenişehir, Osmanlı tarihinin en uzun soluklu hanedan krizini başlattı: Cem meselesi on dört yıl boyunca Osmanlı dış siyasetini Avrupa karşısında felç edecekti.", kaynak:"cem-sultan", duygu:["⚔️","😔"] },
{ t:"1482-07-29", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi"], b:"Cem Sultan'ın Rodos'a sığınması", gun:"29 Temmuz 1482", yer:"Rodos", yer_id:"Rodos", kisiler:"Cem Sultan, Pierre d'Aubusson, II. Bayezid", d:"Konya'yı kuşatma teşebbüsü de sonuçsuz kalan Cem Sultan, otuz kadar adamıyla Anadolu'dan kaçarak Rodos'a ulaştı ve Saint-Jean şövalyeleri tarafından merasimle karşılandı. Ancak misafirlik kısa sürede esarete dönüştü; şehzade önce Fransa'ya, ardından Papalık'a devredilerek Avrupa siyasetinin elinde bir koz hâline geldi. II. Bayezid, kardeşinin alıkonulması karşılığında yıllık ödeme yapmak zorunda kaldı ve Osmanlı'nın Batı'ya yönelik askerî hamleleri Cem'in ölümüne kadar askıya alındı.", kaynak:"cem-sultan", duygu:["🏛"] },
{ t:"1483-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Hersek'in ilhakı", gun:"1483", yer:"Hersek (Hercegovina)", kisiler:"II. Bayezid, Hersekzâde Ahmed Paşa", d:"Bosna'nın 1463'te fethinin ardından ayakta kalan Hersek Dukalığı'nın toprakları aşama aşama Osmanlı idaresine geçti: Hersek sancağı 1470'te teşkil edilmiş, bölgenin diğer bir kısım toprakları 1482 başlarında fethedilerek sancağa katılmış, 1483'te ilhak tamamlanmıştı. Böylece Adriyatik'in arkasındaki dağlık bölge bütünüyle Osmanlı'nın oldu ve Bosna ile Hersek tek bir idarî coğrafya hâline geldi. Son dukanın Osmanlı sarayına giren oğlu, ileride sadrazamlığa kadar yükselecek Hersekzâde Ahmed Paşa'dır. Aynı tarihte katılan öteki yerler: Mostar.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"bosna-hersek", duygu:["🎉"], yer_id:"Mostar" },
{ t:"1485-01-01", k:"savas", etiket:["savas","konu-askeri"], b:"Osmanlı-Memlük Savaşı'nın başlaması (Çukurova cephesi)", gun:"1485", yer:"Çukurova – Adana, Tarsus", yer_id:"Adana", kisiler:"II. Bayezid, Memlük Sultanı Kayıtbay, Karagöz Paşa", d:"Dulkadıroğulları üzerindeki nüfuz mücadelesi ve Cem Sultan'ın Memlük topraklarına sığınmasının bıraktığı husumet, 1485'te iki Sünnî büyük güç arasında altı yıl sürecek bir savaşı başlattı. Çukurova'da Adana ve Tarsus çevresinde cereyan eden çarpışmalarda taraflar birbirine üstünlük sağlayamadı; Osmanlı orduları birkaç ağır darbe aldı. Bu savaş, Osmanlı-Memlük ilişkilerindeki kırılmanın ilk safhasıdır ve otuz yıl sonra Yavuz'un Mercidâbık ve Ridâniye seferleriyle noktalanacak sürecin açılışıdır.", kaynak:"bayezid-ii", duygu:["⚔️","😔"] },
{ t:"1491-05-01", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Osmanlı-Memlük barışı — Tunus arabuluculuğu", gun:"1491", yer:"Kahire – İstanbul", yer_id:"Kahire", kisiler:"II. Bayezid, Kayıtbay, Tunus Hükümdarı Osman Hafsî", d:"1485'te başlayan Osmanlı-Memlük savaşında taraflar kesin bir zafer kazanamadılar; Tunus Hükümdarı Osman Hafsî'nin aracılığı ile 1491'de anlaşmaya varıldı. Antlaşma sınırları büyük ölçüde savaş öncesi hâline döndürdü ve iki İslâm devleti arasındaki hesaplaşma bir kuşak boyunca ertelendi. Altı yıllık yıpratıcı mücadele, II. Bayezid'in ihtiyatlı dış siyasetinin ve doğuya yönelmek yerine iç düzenlemelere ağırlık vermesinin başlıca sebeplerindendir.", kaynak:"bayezid-ii", duygu:["🤝"] },
{ t:"1492-08-01", k:"siyaset", etiket:["siyaset","kultur","ekonomi","konu-siyasi","konu-ekonomi","konu-kultur"], b:"İspanya'dan sürülen Sefarad Yahudilerinin Osmanlı'ya kabulü", gun:"1492", yer:"İstanbul, Selanik, Edirne, İzmir", yer_id:"İstanbul", kisiler:"II. Bayezid, Sefarad Yahudileri", d:"Gırnata'nın düşmesinin ardından İspanya'da engizisyonun zulmünden kaçan Yahudilerden bir kısmı Osmanlı topraklarına sığınarak çeşitli şehirlere yerleştirildi. Osmanlı idaresinde bu Sefarad cemaatleri, istedikleri yere yerleşme, inançlarını yaşama, eğitim kurumları açma ve yeni havralar inşa etme gibi o güne dek görmedikleri bir serbestliğe kavuştular. Yanlarında getirdikleri matbaa, tıp ve maliye bilgisiyle Selanik ve İstanbul'un iktisadî hayatını dönüştüren bu göç, Osmanlı hoşgörü düzeninin Avrupa'da en çok konuşulan örneği oldu.", kaynak:"bayezid-ii", duygu:["🏛"] },
{ t:"1495-02-25", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-kisiler"], b:"Cem Sultan'ın ölümü — on dört yıllık rehinenin sonu", gun:"25 Şubat 1495", yer:"Castel Capuana, Napoli", yer_id:"Napoli", kisiler:"Cem Sultan, II. Bayezid, VIII. Charles", d:"Papalık'tan Fransa Kralı VIII. Charles'a devredilen Cem Sultan, 27 Ocak 1495'te Roma'dan yola çıktıktan sonra Castel Capuana denilen yerde öldü; kaynaklar papalık çevrelerince zehirlenmiş olabileceğini kaydeder. On dört yıl boyunca Avrupa devletlerinin elinde Osmanlı'ya karşı bir tehdit kartı olarak tutulan şehzadenin ölümü, II. Bayezid'in elini nihayet serbest bıraktı. Nitekim padişah bundan sonra Venedik'e savaş açacak ve donanmasını ilk büyük zaferine götürecekti.", kaynak:"cem-sultan", duygu:["🏛"] },
{ t:"1499-08-28", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Sapienza (Zonchio) Deniz Zaferi — Akdeniz'de ilk büyük donanma başarısı", gun:"12-25 Ağustos 1499", yer:"Sapienza (Zonchio) açıkları, Mora'nın güneybatısı", yer_id:"Mora (Tripoliçe)", kisiler:"II. Bayezid, Kemal Reis", d:"Cem meselesinin sona ermesiyle elini serbest bulan II. Bayezid 1499'da Venedik'e savaş açtı; Osmanlı donanması Sapienza (Zonchio) açıklarında Venedik filosunu yenerek Akdeniz'de ilk büyük deniz zaferini kazandı. Bu zaferle donanma, artık Venedik'e denizde karşı koyabileceğini ilân etmiş oldu.", kaynak:"inebahti", duygu:["🎉"] },
{ t:"1502-03-01", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"Altın Orda Hanlığı'nın yıkılışı ve Kırım'ın yükselişi", gun:"1502", yer:"Deşt-i Kıpçak – Saray", kisiler:"Şeyh Ahmed Han, Mengli Giray", d:"Son hükümdarı Şeyh Ahmed Han (1481-1502) memleketini içine düştüğü buhrandan kurtaramadı ve Altın Orda Hanlığı 1502'de Kırım Hanı Mengli Giray'ın darbesiyle tarihe karıştı. Taht kavgaları ve parçalanma sonucunda eski Altın Orda topraklarında Kırım, Kazan, Nogay, Astrahan ve Sibir hanlıkları ortaya çıktı. Osmanlı himayesindeki Kırım'ın bu zaferi, Karadeniz'in kuzeyinde Osmanlı nüfuzunu tartışmasız kılarken bölgede doğan boşluğu ilerleyen yüzyılda Moskova dolduracaktı.", kaynak:"altin-orda-hanligi", duygu:["🏛","😔"], yer_id:"Saray (Selitrennoye)" },
{ t:"1502-12-14", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Osmanlı-Venedik Savaşı'nın sona ermesi ve barış", gun:"1502", yer:"İstanbul – Venedik", yer_id:"İstanbul", kisiler:"II. Bayezid, Venedik Cumhuriyeti", d:"1499'da başlayan ve Sapienza, İnebahtı, Modon ile Koron'un kaybıyla Venedik'i sarsan savaş 1502'de barışla sona erdi. Venedik, Mora'daki en önemli üslerini kaybederek Doğu Akdeniz'deki ticarî imtiyazlarını korumak karşılığında Osmanlı üstünlüğünü tanımak zorunda kaldı. II. Bayezid'in ihtiyatlı sayılan saltanatı, bu savaşla Osmanlı'yı Akdeniz'de ilk kez ciddi bir deniz gücü konumuna yükseltmişti.", kaynak:"venedik", duygu:["🤝"] },
{ t:"1511-07-02", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"Şahkulu İsyanı — Teke yöresinden Sivas'a uzanan Kızılbaş ayaklanması", gun:"2 Temmuz 1511", yer:"Antalya, Kütahya, Sivas", yer_id:"Sivas", kisiler:"Şahkulu Baba Tekeli, Sadrazam Hadım Ali Paşa, Şehzade Ahmed", d:"Safevî propagandasının Anadolu'daki etkisiyle 1510'da isyanını açığa vuran Şahkulu Baba Tekeli, Mart 1511'de Antalya çarşısını basmış, Nisan'da Kütahya ve çevresinde Osmanlı kuvvetlerini yenmişti. Sivas yakınlarında sadrazam Hadım Ali Paşa ile giriştiği son çarpışmada her iki taraf da ağır kayıplar verdi; sadrazam da isyan lideri de hayatını kaybetti. Devletin Anadolu'daki otoritesini sarsan bu ayaklanma, II. Bayezid'in son yıllarındaki iktidar boşluğunu gözler önüne serdi ve Şehzade Selim'in tahta yürüyüşünün en güçlü gerekçesi oldu.", kaynak:"sahkulu-baba-tekeli", duygu:["✊"] },
{ t:"1512-04-24", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-hanedan"], b:"II. Bayezid'in tahttan çekilişi ve Yavuz Sultan Selim'in cülûsu", gun:"24 Nisan 1512", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Bayezid, I. Selim (Yavuz), Şehzade Ahmed", d:"Kardeşleriyle giriştiği taht mücadelesinde yeniçerinin desteğini arkasına alan Şehzade Selim'in baskısıyla II. Bayezid 24 Nisan 1512'de tahttan çekildi ve I. Selim aynı gün dokuzuncu Osmanlı hükümdarı olarak tahta çıktı. Yaşlı padişah, doğduğu Dimetoka'ya giderken yolda, Çorlu yakınındaki Abalar köyünde 25 Rebîülevvel 918'de (10 Haziran 1512) vefat etti. Otuz bir yıllık ihtiyatlı ve içe dönük bir saltanatın yerini, sekiz yılda imparatorluğun sınırlarını ikiye katlayacak Yavuz devri aldı.", ic_not_d:"13 Eylül 2026 · KART-MADDE-CELISKI-0913: metin '5 Rebîülevvel 918 (21 Mayıs 1512)' diyordu; kendi kaynağı TDV `selim-i` '25 Rebîülevvel 918'de (10 Haziran 1512) Abalar köyünde vefatı' der — '25' → '5' düşmesi. Yalnız d düzeltildi, t (cülus günü) doğru.", kaynak:"selim-i", duygu:["🏛"] },

// ---------- B) KLASİK ÇAĞ VE DURAKLAMA (1512-1699) ----------
// --- B1) Yavuz dönemi fetih zinciri: Çaldıran → Mercidâbık → Ridâniye → Hicaz ---
// Kullanıcı tespiti: Mısır Ridâniye'de tek seferde düşmedi, Hicaz ise savaşla değil
// bîatla katıldı. Zincirin ara halkaları ayrı maddeler hâline getirildi.
{ t:"1515-05-19", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Kemah Kalesi'nin Safevîler'den fethi", gun:"19 Mayıs 1515", yer:"Kemah (Erzincan)", yer_id:"Kemah", kisiler:"Yavuz Sultan Selim, Bıyıklı Mehmed Paşa", d:"Çaldıran dönüşünde kışı Amasya'da geçiren Yavuz Sultan Selim, Fırat'ın geçit noktasını tutan müstahkem Kemah Kalesi'nin fethine Bıyıklı Mehmed Paşa'yı memur etti. Padişahın bizzat katıldığı kuşatma sonunda kale Safevî elinden alındı ve Doğu Anadolu'nun kapısı açıldı. Bu fetih, Çaldıran zaferini kalıcı bir toprak kazancına dönüştüren ilk somut adımdır.", kaynak:"kemah", duygu:["🎉"] },
{ t:"1515-09-19", k:"fetih", etiket:["toprak-kazanc","konu-askeri","konu-idari"], b:"Âmid'in (Diyarbekir) fethi ve Diyarbekir beylerbeyiliğinin kuruluşu", gun:"10 Şâban 921 / 19 Eylül 1515", yer:"Âmid (Diyarbakır)", yer_id:"Diyarbakır", kisiler:"Bıyıklı Mehmed Paşa, İdrîs-i Bitlisî, Yavuz Sultan Selim", d:"İdrîs-i Bitlisî'nin bölgedeki Sünnî Kürt beylerini Osmanlı'ya kazandırmasının ardından Safevî kuvvetleri uzun bir kuşatmaya dayanamadı ve Âmid'in anahtarları Bıyıklı Mehmed Paşa'ya teslim edildi. Şehir, yeni kurulan Diyarbekir beylerbeyiliğinin merkezi yapıldı. Böylece Yukarı Mezopotamya'nın idarî çekirdeği Osmanlı eline geçti.", kaynak:"selim-i", duygu:["🎉"] },
{ t:"1516-05-01", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Koçhisar (Kızıltepe) Savaşı ve Mardin ile Urfa'nın fethi", gun:"Mayıs 1516", yer:"Dede Garkın sahrası, Koçhisar (Kızıltepe) – Mardin, Palu", yer_id:"Mardin", kisiler:"Bıyıklı Mehmed Paşa, Kara Han (Karahan Ustaclu)", d:"Bıyıklı Mehmed Paşa kumandasındaki Osmanlı ordusu, Koçhisar yakınında Dede Garkın sahrasının Koruk mevkiinde Safevî valisi Kara Han'ı gün boyu süren bir meydan savaşında yendi; Kara Han'ın kesik başı padişahın ordugâhına gönderildi. Ardından Mardin topa tutularak alındı ve Şah İsmâil'in Diyarbekir bölgesindeki son direnç noktası çöktü. Bu zafer, Yavuz'un güney sınırını güvenceye alarak Mısır seferine yönelmesini mümkün kıldı. Aynı tarihte katılan öteki yerler: Harput (Elazığ).", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"mardin", duygu:["⚔️"] },
{ t:"1516-06-05", k:"siyaset", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Yavuz Sultan Selim'in Mısır seferi için İstanbul'dan hareketi", gun:"5 Haziran 1516", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Yavuz Sultan Selim, Hadım Sinan Paşa", d:"Yavuz Sultan Selim, görünüşte Safevîler'e karşı yeni bir doğu seferi hazırlığıyla İstanbul'dan hareket etti ve Akşehir üzerinden güneye yöneldi. Memlük Sultanı Kansu Gavri'nin Şah İsmâil'le temas kurması ve Osmanlı'nın doğu kanadını tehdit etmesi, hedefin kısa sürede değişmesine yol açacaktı. Sefer, iki yıl sürecek ve Osmanlı'yı bir Ortadoğu imparatorluğuna dönüştürecek büyük harekâtın başlangıcıdır.", kaynak:"selim-i", duygu:["🏛"] },
{ t:"1516-06-20", k:"fetih", etiket:["savas","ekonomi","konu-askeri","konu-ekonomi"], b:"Zebîd'in alınması: Osmanlı denizcilerinin Kızıldeniz'e ilk girişi", gun:"20 Haziran 1516", yer:"Zebîd (Yemen)", yer_id:"Zebîd", kisiler:"Selman Reis, Hüseyin Rûmî, Kansu Gavri", d:"Portekiz'in Hint Okyanusu'ndaki baskısı karşısında Memlük Sultanı Kansu Gavri'nin talebiyle Kızıldeniz'e gönderilen Osmanlı asıllı denizciler Hüseyin Bey ve Selman Reis, donanmalarıyla Zebîd'i ele geçirdi. Henüz Memlük hizmetinde yürütülen bu harekât, Osmanlı bahriyesinin Kızıldeniz-Hint hattındaki ilk fiilî varlığıdır. Bir yıl sonra Mısır Osmanlı'ya geçince aynı filo doğrudan İstanbul'a bağlanacaktır.", kaynak:"yemen", duygu:["🎉"] },
{ t:"1516-07-30", k:"siyaset", etiket:["savas","siyaset","diplomasi","konu-askeri","konu-siyasi","konu-diplomasi"], b:"Seferin hedefinin Memlükler ve Halep olarak resmen ilânı", gun:"30 Temmuz 1516", yer:"Anadolu ordugâhı (Sivas–Elbistan hattı)", yer_id:"Sivas", kisiler:"Yavuz Sultan Selim, Kansu Gavri", d:"Yavuz Sultan Selim, Kansu Gavri'nin Safevîler'le anlaşarak ordusunu Halep'e sürmesi üzerine seferin hedefini açıkça Memlük sultanı ve Halep olarak ilân etti. Böylece iki Sünnî devlet arasında yıllardır süren örtülü rekabet, açık savaşa dönüştü. Bu ilân, Mercidâbık'a giden dört haftalık geri sayımı başlatmıştır.", kaynak:"selim-i", duygu:["🏛"] },
{ t:"1516-08-02", k:"savas", etiket:["savas","konu-askeri"], b:"Aden kuşatmasının başarısızlığı: Portekiz'e karşı ilk Kızıldeniz teşebbüsü", gun:"2-10 Ağustos 1516", yer:"Aden (Yemen)", yer_id:"Aden", kisiler:"Selman Reis, Hüseyin Rûmî", d:"Selman Reis ve Hüseyin Bey, Kızıldeniz'in Hint Okyanusu'na açılan kapısı olan Aden'i ele geçirmek için sekiz gün süren bir kuşatma yürüttüler, ancak şehrin güçlü tahkimatı karşısında geri çekilmek zorunda kaldılar. Aden'in alınamaması, Portekiz'e karşı yürütülecek güney stratejisini uzun yıllar aksatacaktır. Bu teşebbüs, Osmanlı'nın okyanus siyasetindeki ilk sınavıdır.", kaynak:"selman-reis", duygu:["⚔️"] },
{ t:"1516-08-28", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Halep, Rakka ve Deyrizor'un Osmanlı hâkimiyetine girişi", gun:"28 Ağustos 1516", yer:"Halep", yer_id:"Halep", kisiler:"Yavuz Sultan Selim, Hayır Bey", d:"Mercidâbık'tan dört gün sonra Yavuz Sultan Selim direnişle karşılaşmadan Halep'e girdi ve şehrin camilerinde hutbe onun adına okundu. Suriye'nin ticarî ve idarî başkenti sayılan Halep'in bu kadar hızlı düşmesi, Memlük otoritesinin bölgede çökmüş olduğunu gösterir. Şehrin ele geçirilmesi, Şam'a ve oradan Mısır'a uzanan yolu bir anda açmıştır. Aynı tarihte katılan öteki yerler: Antakya, Rakka, Deyrizor.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"halep", duygu:["🎉"] },
{ t:"1516-08-29", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-din"], b:"Halep Gökmeydan'da Abbâsî Halifesi III. Mütevekkil ile görüşme", gun:"Ağustos 1516 sonu", yer:"Gökmeydan, Halep", yer_id:"Halep", kisiler:"Yavuz Sultan Selim, III. Mütevekkil-Alellah", d:"Mercidâbık'ta Memlük ordusuyla birlikte esir düşen Kahire Abbâsî halifesi III. Mütevekkil, Halep'te Gökmeydan'da padişahın huzuruna çıkarıldı ve Yavuz Sultan Selim ona büyük saygı gösterdi. 1261'den beri Memlük sultanlarının gölgesinde sembolik bir makam olan Kahire hilâfeti, bu görüşmeyle fiilen Osmanlı himayesine geçmiş oldu. Halife daha sonra padişahla birlikte İstanbul'a götürülecektir.", kaynak:"selim-i", duygu:["🏛"] },
{ t:"1516-09-27", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Şam'ın (Dımaşk) Osmanlı hâkimiyetine girişi", gun:"27 Eylül 1516", yer:"Şam", yer_id:"Şam", kisiler:"Yavuz Sultan Selim", d:"Halep'ten sonra Hama ve Humus'un teslim olmasıyla önü açılan Yavuz Sultan Selim 27 Eylül'de Şam önlerine ulaştı; şehre hemen girmeyip dışarıda Mastaba mevkiinde otağını kurdu ve gelişinin on ikinci günü büyük bir merasimle içeri girdi. Şam'da uzunca kalarak Suriye'nin idarî düzenini kurdu ve Muhyiddin İbnü'l-Arabî'nin kabrini yaptırdı. Böylece Bilâdüşşam'ın tamamı Memlük idaresinden çıkmış oldu. Aynı tarihte katılan öteki yerler: Beyrut.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"selim-i", duygu:["🎉"] },
{ t:"1516-10-10", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"Tomanbay'ın Kahire'de Memlük sultanı ilân edilmesi", gun:"13 Ramazan 922 / 10 Ekim 1516", yer:"Kahire", yer_id:"Kahire", kisiler:"Tomanbay, Kansu Gavri", d:"Mercidâbık'ta ölen Kansu Gavri'nin ardından Memlük emîrleri, devletin son sultanı olacak Tomanbay'ı tahta çıkardılar. Çerkez asıllı yeni sultan, Suriye'yi kaybetmiş, hazinesi tükenmiş ve ateşli silahlardan yoksun bir devleti devraldı. Buna rağmen Kahire önlerinde savunma hattı kurarak Osmanlı ilerleyişine karşı son bir direniş örgütleyecektir.", kaynak:"tomanbay", duygu:["🏛"] },
{ t:"1516-12-21", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Gazze (Han Yûnus) Muharebesi: Canbirdi Gazâlî'nin yenilmesi", gun:"21 Aralık 1516", yer:"Gazze – Han Yûnus hattı", yer_id:"Gazze", kisiler:"Hadım Sinan Paşa, Canbirdi Gazâlî", d:"Yavuz Sultan Selim, dört bin kişilik öncü kuvvetle Sadrazam Hadım Sinan Paşa'yı Gazze'ye gönderdi. Tomanbay tarafından Şam nâibliğine getirilen Canbirdi Gazâlî, Osmanlı öncüsünü Gazze-Han Yûnus hattında durdurmaya çalıştıysa da ağır bir yenilgiye uğradı ve Mısır'a kaçtı. Filistin'deki son Memlük tampon kuvvetin dağılmasıyla Sina çölüne giden yol tamamen açıldı.", kaynak:"canbirdi-gazali", duygu:["⚔️"] },
{ t:"1516-12-29", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-din"], b:"Yavuz Sultan Selim'in Kudüs'e gelişi", gun:"4 Zilhicce 922 / 29 Aralık 1516", yer:"Kudüs", yer_id:"Kudüs", kisiler:"Yavuz Sultan Selim", ic_not_d:"17 Eyl 2026 (KOSU13-YAMA): TDV kudus 'Kudüs, padişahın gelişinden önce muhtemelen Ekim 1516'da Osmanlı yönetimine girmişti' — el değiştirme 1516-10-01 maddesine taşındı; bu gün padişahın gelişidir.", d:"Mercidâbık sonrası Osmanlı yönetimine direnmeden geçmiş olan Kudüs'e, Gazze muharebesinin ardından Yavuz Sultan Selim devletin ileri gelenleri ve askerle birlikte geldi. Padişah Kubbetü's-sahre ve Mescid-i Aksâ'yı ziyaret ederek şehrin kutsal statüsünü teyit etti. Kudüs, bu tarihten Aralık 1917'ye kadar tam dört asır Osmanlı idaresinde kalacaktır.", kaynak:"kudus", duygu:["🎉"] },
{ t:"1517-01-02", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Yavuz Sultan Selim'in Gazze'ye girişi ve Sina çölüne yönelmesi", gun:"8 Zilhicce 922 / 2 Ocak 1517", yer:"Gazze", yer_id:"Gazze", kisiler:"Yavuz Sultan Selim, Hadım Sinan Paşa", d:"Padişah 2 Ocak 1517'de Gazze'ye girerek burada öncü kuvvetin başındaki Sinan Paşa ile buluştu ve ordu Mısır'a geçiş için son hazırlıklarını yaptı. Gazze'den Sâlihiye'ye kadar uzanan susuz Katya (Sina) çölünde sekiz konak yürünecek, develerle su taşınacaktı. Bu geçiş, seferin en riskli ve lojistik açıdan en zorlu safhasıdır.", kaynak:"ridaniye-savasi", duygu:["⚔️"] },
{ t:"1517-01-24", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Osmanlı birliklerinin Kahire'ye ilk girişi", gun:"24 Ocak 1517", yer:"Kahire", yer_id:"Kahire", kisiler:"Yavuz Sultan Selim, Tomanbay", d:"Ridâniye zaferinin ertesi günü Osmanlı ordularının Kahire'ye girmesine izin verildi ve 24 Ocak'ta birlikler şehre yerleşti. Ancak bu giriş şehrin tam kontrolü anlamına gelmiyordu; Tomanbay Yukarı Mısır'a çekilmiş, Memlük direnişi henüz kırılmamıştı. Kahire'nin fethi tek bir günde değil, haftalara yayılan kanlı bir süreçte tamamlanacaktır.", kaynak:"selim-i", duygu:["🎉"] },
{ t:"1517-01-27", k:"savas", etiket:["savas","isyan","konu-askeri","konu-isyan"], b:"Tomanbay'ın Kahire baskını ve üç gün süren sokak savaşları", gun:"27-28 Ocak 1517", yer:"Kahire", yer_id:"Kahire", kisiler:"Tomanbay, Yavuz Sultan Selim", d:"Yukarı Mısır'a çekilen Tomanbay, yanındaki yaklaşık yedi bin kişiyle 27-28 Ocak gecesi ansızın Kahire'ye girip şehir içinde direniş başlattı ve Osmanlı birliklerini son derece zor durumda bıraktı. Üç gün süren şiddetli sokak çatışmalarında Memlükler şehrin büyük bölümünü geçici olarak ellerinde tuttu. Direniş ancak Osmanlı topçusunun ve takviye kuvvetlerin devreye girmesiyle kırılabildi.", kaynak:"ridaniye-savasi", duygu:["⚔️"] },
{ t:"1517-02-08", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi"], b:"Canbirdi Gazâlî'nin Osmanlı hizmetine girmesi", gun:"8 Şubat 1517", yer:"Kahire çevresi", yer_id:"Kahire", kisiler:"Canbirdi Gazâlî, Yavuz Sultan Selim", d:"Ridâniye'nin ardından Sâlihiye'ye çekilen eski Memlük emîri Canbirdi Gazâlî, padişaha başvurarak aman diledi. Yavuz Sultan Selim, Mısır ve Suriye'de asayişin kurulmasında faydalı olacağını düşünerek onu hizmetine kabul etti. Bu tercih, Osmanlı'nın Memlük kadrolarını tasfiye etmek yerine sisteme dâhil etme siyasetinin ilk büyük örneğidir.", kaynak:"canbirdi-gazali", duygu:["🏛"] },
{ t:"1517-02-15", k:"fetih", etiket:["toprak-kazanc","siyaset","konu-askeri","konu-siyasi"], b:"Yavuz Sultan Selim'in Kahire'ye merasimle girişi ve hutbenin okunması", gun:"15 Şubat 1517", yer:"Kahire", yer_id:"Kahire", kisiler:"Yavuz Sultan Selim", d:"Sokak çatışmalarının bastırılmasından sonra padişah 15 Şubat 1517'de çok parlak bir törenle Kahire'ye girdi ve camilerde onun adına hutbe okundu. Hutbenin Kahire'de Osmanlı sultanı adına okunması, 1250'den beri süren Memlük hâkimiyetinin hukuken sona erdiğinin ilânıdır. Bu tarih, Mısır'ın fiilî fethinin sembolik tamamlanma anı sayılır.", kaynak:"selim-i", duygu:["🎉"] },
{ t:"1517-03-30", k:"savas", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Son Memlük sultanı Tomanbay'ın Terrûce'de yakalanması", gun:"30 Mart 1517", yer:"Terrûce, Aşağı Mısır", kisiler:"Tomanbay, Yavuz Sultan Selim", d:"Kahire'yi terk ettikten sonra Nil deltasında saklanan Tomanbay, kendisine sığınak veren bedevîler tarafından ihbar edilerek Terrûce bölgesinde ele geçirildi. Yakalanışı, Memlük direnişinin örgütlü merkezini ortadan kaldırdı. Son sultan bundan sonra on dört gün Osmanlı elinde tutulacaktır.", kaynak:"tomanbay", duygu:["⚔️"], yer_kon:[30.7,30.5] },
{ t:"1517-04-13", k:"savas", etiket:["savas","siyaset","toprak-kazanc","konu-askeri","konu-siyasi","konu-kisiler"], b:"Tomanbay'ın Bâbüzüveyle'de idamı ve Memlük Devleti'nin sonu", gun:"21 Rebîülevvel 923 / 13 Nisan 1517", yer:"Bâbüzüveyle, Kahire", yer_id:"Kahire", kisiler:"Tomanbay, Yavuz Sultan Selim", d:"Yakalanışından on dört gün sonra Tomanbay, Kahire'nin ünlü kapısı Bâbüzüveyle'de astırıldı; cesedi daha sonra amcasının yaptırdığı medreseye defnedildi. Böylece 1250'den beri Mısır ve Suriye'ye hükmeden Memlük Devleti resmen tarihe karıştı. Direnişin kırılmasıyla Yukarı Mısır'daki (Said) Asyut ve Asvan gibi şehirler de Osmanlı idaresine bağlandı.", kaynak:"tomanbay", duygu:["⚔️","😔"] },
{ t:"1517-04-18", k:"savas", etiket:["savas","ekonomi","konu-askeri","konu-ekonomi"], b:"Portekiz donanmasının Cidde'ye saldırısı ve Selman Reis'in savunması", gun:"18 Nisan 1517", yer:"Cidde", yer_id:"Cidde", kisiler:"Selman Reis, Lopo Soares de Albergaria", d:"Otuz kadar kadırga ve kalyondan oluşan Portekiz donanması Cidde'ye saldırdı; Selman Reis şehrin savunmasını yöneterek düşmanın karaya çıkmasını engelledi ve birkaç Portekiz gemisini batırdı. Bu savunma, Mekke'nin limanının ve dolayısıyla hac yolunun Hıristiyan bir devletin eline geçmesini önledi. Cidde birkaç ay sonra Hicaz'ın bîatıyla resmen Osmanlı idaresine dâhil olacaktır.", kaynak:"selman-reis", duygu:["⚔️"] },
{ t:"1517-05-19", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"İskenderiye'nin donanmayla teslim alınması — Mısır fethinin tamamlanması", gun:"27 Rebîülâhir 923 / 19 Mayıs 1517", yer:"İskenderiye, Reşîd, Dimyat", yer_id:"İskenderiye", kisiler:"Câfer Bey, Yavuz Sultan Selim", d:"Ridâniye'den tam dört ay, Tomanbay'ın idamından otuz altı gün sonra, Câfer Bey idaresindeki Osmanlı donanmasının limana gelmesiyle İskenderiye Osmanlı idaresine geçti; Reşîd ve Dimyat gibi delta limanları da aynı süreçte bağlandı. Mısır'ın Akdeniz'e açılan bu büyük limanının Kahire'nin düşüşünden aylar sonra ve karadan değil denizden teslim alınması, fethin tek bir savaşla değil bölge bölge tamamlandığını açıkça gösterir. İskenderiye bundan sonra İstanbul ile Kahire'yi bağlayan hayatî liman hâline gelecektir. Aynı tarihte katılan öteki yerler: Reşîd (Rosetta).", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"iskenderiye", duygu:["🎉"] },
{ t:"1517-07-06", k:"siyaset", etiket:["diplomasi","toprak-kazanc","siyaset","konu-askeri","konu-siyasi","konu-diplomasi"], b:"Hicaz'ın savaşsız katılışı: Mekke Şerifi'nin oğlu Ebû Nümeyy'in bîatı", gun:"16 Cemâziyelâhir 923 / 6 Temmuz 1517", yer:"Kahire – Mekke, Cidde, Tâif", yer_id:"Mekke", kisiler:"Ebû Nümeyy, Şerîf Berekât, Yavuz Sultan Selim", d:"Yavuz Sultan Selim önce Mekke ve çevresinin zaptı için asker sevketmeyi düşünmüş, fakat Mekke Emîri Şerîf Berekât'ın itaatini bildirmesi üzerine bundan vazgeçmişti. Berekât'ın on iki yaşındaki oğlu Ebû Nümeyy, babasının hediyeleri ve Mekke'nin anahtarlarıyla Kahire'ye gelerek padişahın huzuruna kabul edildi. Böylece Hicaz, Ridâniye'nin otomatik bir sonucu olarak değil, beş buçuk ay sonra ve tek kurşun atılmadan, sulhen ve bîat yoluyla Osmanlı'ya katılmış oldu. Aynı tarihte katılan öteki yerler: Tâif.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"mekke", duygu:["🏛"] },
{ t:"1517-07-12", k:"siyaset", etiket:["siyaset","diplomasi","kultur","toprak-kazanc","konu-askeri","konu-siyasi","konu-diplomasi","konu-kultur"], b:"Hâdimü'l-Haremeyn unvanının kabulü ve Medine'de hutbe", gun:"22 Cemâziyelâhir 923 / 12 Temmuz 1517", yer:"Kahire – Mekke – Medine", yer_id:"Medine", kisiler:"Yavuz Sultan Selim, Şerîf Berekât", d:"Mekke heyetinin ikinci kabulünün ardından Yavuz Sultan Selim, Haremeyn'in himayesini resmen üstlendi ve 'hâdimü'l-Haremeyni'ş-şerîfeyn' unvanını kullanmaya başladı. Şerîf Berekât kendisine gönderilen hil'ati giyerek padişah adına hutbe okuttu; Medine heyetinin de İstanbul'a gitmesiyle Berekât'ın emîrliği beratla tasdik edildi. Padişah Haremeyn halkına iki yüz bin altın ile bol erzak göndererek her yıl tekrarlanacak surre geleneğini başlattı. Aynı tarihte katılan öteki yerler: Yenbu, Tebük.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"haremeyn", duygu:["🏛"] },
{ t:"1517-08-28", k:"siyaset", etiket:["siyaset","ekonomi","konu-siyasi","konu-ekonomi"], b:"Selman Reis'in Osmanlı hizmetine girmesi ve Kızıldeniz siyasetinin devri", gun:"28 Ağustos 1517", yer:"Kahire", yer_id:"Kahire", kisiler:"Selman Reis, Yavuz Sultan Selim", d:"Cidde'yi Portekizliler'e karşı savunan Selman Reis, Kahire'ye gelerek Yavuz Sultan Selim'in huzuruna çıktı; bir süre alıkonulduysa da 1519'da İstanbul'a çağrıldı ve Portekiz tehdidine karşı otuz kadırga ile birkaç kalyata hazırlamayı taahhüt etti. Bu görüşme, Kızıldeniz ve Hint Okyanusu siyasetinin Memlük mirasından devralınıp doğrudan İstanbul'a bağlanmasının başlangıcıdır. Osmanlı artık bir Akdeniz devleti olmanın yanında okyanus siyaseti de güden bir güçtü.", kaynak:"selman-reis", duygu:["🏛"] },
{ t:"1517-09-10", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-idari"], b:"Yavuz Sultan Selim'in Kahire'den ayrılışı ve Hayır Bey'in beylerbeyiliği", gun:"10 Eylül 1517 (Hayır Bey'in tayini 13 Eylül)", yer:"Kahire", yer_id:"Kahire", kisiler:"Yavuz Sultan Selim, Hayır Bey, III. Mütevekkil-Alellah", d:"Mısır'da yaklaşık sekiz ay kalarak idarî, malî ve askerî düzeni kuran Yavuz Sultan Selim Kahire'den ayrıldı; Mercidâbık'ta sol kanadı çekerek Memlük hezimetini hızlandıran eski Halep nâibi Hayır Bey, Mısır'ın ilk Osmanlı beylerbeyi olarak Kal'atülcebel'den idareye başladı. Memlük asıllı bir valinin seçilmesi, yeni idarenin yerli halka yabancı gelmemesini sağlayan bilinçli bir geçiş siyasetiydi. Padişah dönüş yolunda yanında son Abbâsî halifesi III. Mütevekkil ile Mısır'ın seçkin sanatkâr ve âlimlerini de İstanbul'a götürdü.", kaynak:"hayir-bey", duygu:["🏛"] },
{ t:"1517-09-11", k:"siyaset", etiket:["siyaset","kultur","konu-siyasi","konu-din","konu-kultur"], b:"Kahire Abbâsî hilâfetinin sona ermesi — 'devir töreni' rivayeti", gun:"923 / 1517", yer:"Kahire – İstanbul", yer_id:"Kahire", kisiler:"Yavuz Sultan Selim, III. Mütevekkil-Alellah", d:"Yavuz Sultan Selim Mısır'ı zaptedince, Mercidâbık'ta esir düşen son halife III. Mütevekkil-Alellah'ı beraberinde İstanbul'a getirdi; 1261'den beri Memlük sultanlarının gölgesinde yetkisiz biçimde süregelen Kahire Abbâsî hilâfeti böylece sona erdi. Buna karşılık hilâfetin Ayasofya'da resmî bir törenle Yavuz'a devredildiğine dair meşhur rivayet, ilk defa XVIII. yüzyıl sonunda d'Ohsson'un eserinde geçer ve Yavuz dönemi kaynaklarının hiçbirinde bulunmaz. TDV İslâm Ansiklopedisi, merasimi belgeleyen orijinal bir kaynak bulunmadığından rivayeti uydurma sayar; ancak hilâfetin intikali için şer'an böyle bir devir törenine ihtiyaç olmadığını da kaydeder.", kaynak:"hilafet", duygu:["🏛"] },

{ t:"1513-04-01", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-hanedan"], b:"Yenişehir Muharebesi ve Şehzade Ahmed'in bertarafı", gun:"Nisan 1513", yer:"Yenişehir (Bursa)", yer_id:"Yenişehir (Bursa)", kisiler:"I. Selim, Şehzade Ahmed", d:"Yavuz Sultan Selim, tahtın en güçlü rakibi olan ağabeyi Şehzade Ahmed'i Bursa yakınlarındaki Yenişehir ovasında bozguna uğrattı ve esir alarak ortadan kaldırdı. Böylece 1511'den beri süren kardeş kavgası kapandı, Anadolu'daki iç bölünme sona erdi. Selim, arkasını sağlama alarak Safevî meselesine yönelebilecek serbestliği kazandı.", kaynak:"selim-i", duygu:["🏛"] },
{ t:"1514-09-06", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Yavuz Sultan Selim'in Tebriz'e girişi", gun:"6 Eylül 1514", yer:"Tebriz", yer_id:"Tebriz", kisiler:"I. Selim, Şah İsmail", d:"Çaldıran zaferinin ardından Osmanlı ordusu Safevî başkenti Tebriz'e girdi ve şehirde hutbe padişah adına okundu. Selim burada bir hafta kalıp Tebrizli sanatkâr ve ulemânın bir kısmını İstanbul'a naklettirdi; bu nakil Osmanlı saray sanatını derinden etkileyecekti. Kışın yaklaşması ve yeniçerilerin hoşnutsuzluğu üzerine şehir terk edildiyse de Doğu'da Safevî üstünlüğü kırılmıştı.", kaynak:"tebriz — TDV tebriz birebir: 'Tebriz 16 Receb 920’de (6 Eylül 1514) Yavuz Sultan Selim tarafından Osmanlı hâkimiyetine alındı.' · ⚠️ TDV caldiran-savasi hicrî tarih vermeden '5 Eylül’de şehre girdi' diyor: iki TDV maddesi 1 gün ayrışıyor. Hicrî günü veren tebriz maddesine göre 6 Eylül korundu (bu çelişki olaylar_ok107.js H-0018 notunda da ölçülmüştü; KITA 14, 13 Eylül 2026 yeniden doğruladı).", duygu:["🎉"] },
{ t:"1515-06-13", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Turnadağ Zaferi — Dulkadir Beyliği Osmanlı'ya tâbi oldu", gun:"13 Haziran 1515", yer:"Turnadağ (Elbistan) – Maraş, Göksun", yer_id:"Elbistan", kisiler:"Sinan Paşa, Alâüddevle Bozkurt Bey, Şehsuvaroğlu Ali Bey", d:"Osmanlı kuvvetleri, Çaldıran seferi sırasında ikircikli tavır takınan Dulkadir Beyi Alâüddevle Bozkurt'u Göksun ile Andırın arasındaki Ördekli mevkiinde yenilgiye uğrattı; Alâüddevle bu savaşta öldürüldü. Beylik bu tarihte İLHAK EDİLMEDİ: Alâüddevle'den sonra Dulkadıroğulları Beyliği'nin başına Yavuz Sultan Selim tarafından Şehsuvaroğlu Ali Bey getirildi ve Maraş-Elbistan merkezli ülke Osmanlı'ya tâbi bir beylik olarak sürdü. Memlük sınırındaki tampon böylece Osmanlı denetimine girdi ve iki yıl sonraki Mısır seferinin yolu açıldı; ilhak ise Ali Bey'in öldürülmesinden sonra gerçekleşecektir.", ic_not_d:"TARIH-SUPHE-0920 (20 Eylül 2026): başlık ve detay TDV dulkadirogullari gövdesine göre düzeltildi — 1515'te ilhak YOK, tâbiyet var. Yerleşim tarafında 6 kaydın (Maraş · Elbistan · Göksun · Gürün · Zamantı · Darende) 1515-1522 arası v: tâbi dönemine çevrildi; ilhak 1522 maddesine taşındı.", kaynak:"dulkadirogullari", duygu:["🎉"] },
{ t:"1518-01-01", k:"fetih", etiket:["fetih","siyaset","konu-askeri","konu-siyasi"], b:"Erzurum Osmanlı idaresine katıldı — Doğu Anadolu'da Safevî nüfuzu kırıldı", gun:"1518", yer:"Erzurum", yer_id:"Erzurum", kisiler:"Yavuz Sultan Selim", d:"Çaldıran zaferinden (1514) sonra bölgedeki Osmanlı nüfuzu arttıysa da Erzurum'un tam zaptı, İran nüfuzunun kırılmasına kadar gecikti; şehir ancak Mısır seferinin ardından 1518-19'da Osmanlı idaresine katıldı. Erzurum 1502'de Şah İsmâil'in Akkoyunlu Beyliği'ne son vermesiyle Safevî hâkimiyetine girmişti; on altı yıllık bu dönem böylece kapandı. 1534'te Irakeyn Seferi sırasında Erzurum beylerbeyiliği kurulacaktır.", kaynak:"erzurum", duygu:["🎉"] },
{ t:"1519-03-01", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan","konu-din"], b:"Celâlî isyanlarının başlangıcı: Bozoklu Şeyh Celâl ayaklanması", gun:"1519", yer:"Bozok – Tokat", yer_id:"Tokat", kisiler:"Şeyh Celâl", d:"Bozok yöresinde Şeyh Celâl adlı bir kişi mehdîliğini ilân ederek Tokat civarında ayaklandı; isyan bastırıldıysa da adı bir asır boyunca Anadolu'daki bütün eşkıya ve ayaklanma hareketlerine ad oldu. Celâlîlik, XVI. yüzyıl sonunda tımar düzeninin çözülmesi ve nüfus baskısıyla birleşerek imparatorluğun en uzun soluklu iç güvenlik sorununa dönüştü. Ayaklanmalar Anadolu'da 'büyük kaçgunluk' denen kitlesel göçlere yol açtı.", kaynak:"celali-isyanlari", duygu:["✊"] },
{ t:"1519-09-01", k:"fetih", etiket:["toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Cezayir'in Osmanlı Devleti'ne bağlanması", gun:"1519", yer:"Cezayir", yer_id:"Cezayir", kisiler:"Barbaros Hayreddin Paşa, Yavuz Sultan Selim", d:"Kuzey Afrika'da İspanyol baskısına karşı direnen Hayreddin Reis, tutunabilmek için İstanbul'a başvurup Cezayir'i padişaha arz etti ve hutbe Yavuz Sultan Selim adına okundu. Böylece Cezayir resmen Osmanlı topraklarına katıldı, Hayreddin'e beylerbeyi unvanıyla asker ve top gönderildi. Bu bağlanma, Osmanlı'nın Batı Akdeniz'de yüzyıllar sürecek deniz hâkimiyetinin temelini attı. Aynı tarihte katılan öteki yerler: Konstantin, Şerşel (Cherchell), Medea (Titteri), Setif.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"barbaros-hayreddin-pasa", duygu:["🎉"] },
  { t:"1520-09-21", k:"kayip", etiket:["siyaset","konu-askeri","konu-siyasi","konu-kisiler"], b:"Yavuz Sultan Selim'in Çorlu'da vefatı", gun:"21-22 Eylül 1520", yer:"Çorlu", yer_id:"Çorlu", kisiler:"I. Selim (Yavuz)", d:"Sekiz yılda devletin toprağını iki katından fazla büyüten I. Selim, 18 Temmuz 1520'de yeni bir sefer için İstanbul'dan çıktı; sırtında çıkan büyük bir ur yüzünden Çorlu'dan ileri gidemedi. Hekimlerin müdahalesine rağmen hastalığı ağırlaştı ve iki ay süren umutsuz bir tedaviden sonra 8-9 Şevval 926'da (21-22 Eylül 1520) burada vefat etti. Çaldıran, Mercidabık ve Ridâniye ile İran'ı durdurup Memlük Devleti'ni ortadan kaldırmış, hilâfeti ve Haremeyn'in hâmiliğini Osmanlı'ya getirmişti. Geriye tek erkek evlât bıraktı: Süleyman.", kaynak:"selim-i", duygu:["😔","👑"], vefat_id:"selim1" },
{ t:"1524-01-01", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"Mısır'da Hain Ahmed Paşa isyanı", gun:"Ocak 1524", yer:"Kahire", yer_id:"Kahire", kisiler:"Hain Ahmed Paşa, Kanunî Sultan Süleyman, Pargalı İbrahim Paşa", d:"Sadrazamlık beklerken Mısır valiliğine gönderilen Ahmed Paşa, Kahire'de kendini 'el-Melikü'l-Mansûr Sultan Ahmed' ilan ederek bağımsızlığını duyurdu. İsyan kısa sürede bastırılıp paşa öldürüldü, ancak olay imparatorluğun en zengin eyaletinde merkezî denetimin kırılganlığını gösterdi. Bunun üzerine İbrahim Paşa Mısır'a giderek eyaletin idaresini yeniden düzenleyen ünlü Mısır Kanunnâmesi'ni hazırlattı.", kaynak:"ahmed-pasa-hain", duygu:["✊"] },
{ t:"1529-09-08", k:"fetih", etiket:["toprak-kazanc","savas","diplomasi","konu-askeri","konu-diplomasi"], b:"Budin'in alınıp Zapolya'ya verilmesi", gun:"Eylül 1529", yer:"Budin (Buda)", yer_id:"Budin", kisiler:"Kanunî Sultan Süleyman, János Szapolyai, Ferdinand", d:"Viyana seferi yolunda Osmanlı ordusu, Ferdinand'ın eline geçmiş olan Budin'i kuşatarak geri aldı ve şehri Osmanlı himayesindeki Macar kralı János Szapolyai'ye teslim etti. Böylece Macaristan üzerinde Habsburg–Osmanlı rekabetinde tampon bir vasal krallık modeli kuruldu. Bu düzen 1541'e kadar sürecek, Zapolya'nın ölümünden sonra Budin doğrudan Osmanlı eyaleti hâline getirilecekti.", kaynak:"budin", duygu:["🎉"] },
{ t:"1532-08-05", k:"savas", etiket:["savas","konu-askeri"], b:"Alman Seferi ve Güns (Kőszeg) kuşatması", gun:"5-30 Ağustos 1532", yer:"Güns (Kőszeg) – Aşağı Avusturya", kisiler:"Kanunî Sultan Süleyman, Şarlken, Nikola Jurišić", d:"Kanunî, Şarlken'i meydan muharebesine zorlamak amacıyla ordusuyla Avusturya üzerine yürüdü; küçük Güns kalesi yirmi beş gün direnerek ordunun ilerleyişini geciktirdi. İmparator savaşa çıkmayınca akıncılar Viyana çevresini vurdu ve mevsimin ilerlemesi üzerine dönüldü. Sefer toprak kazancı getirmedi, fakat Habsburgları masaya oturtarak ertesi yılki barışın zeminini hazırladı.", kaynak:"suleyman-i", duygu:["⚔️"], yer_kon:[47.3897,16.5433] },
{ t:"1533-01-01", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"İstanbul Antlaşması — Habsburglarla ilk barış", gun:"Ocak 1533", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Kanunî Sultan Süleyman, Ferdinand, Pargalı İbrahim Paşa", d:"Ferdinand'ın elçisi Cornelius'u kabul eden padişah ateşkese rıza gösterdi ve Osmanlı ile Avusturya arasındaki ilk resmî barış metni ortaya çıktı. Antlaşmayla Ferdinand elinde tuttuğu Macar topraklarına karşılık yıllık vergi ödemeyi kabul etti, Avusturya arşidükü protokolde sadrazama denk sayıldı. Bu eşitsiz statü, Osmanlı diplomasisinin XVI. yüzyıldaki üstünlük iddiasının açık ifadesiydi.", kaynak:"suleyman-i", duygu:["🤝"] },
{ t:"1534-09-22", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Barbaros'un Tunus'u fethi", gun:"22 Eylül 1534", yer:"Tunus", yer_id:"Tunus", kisiler:"Barbaros Hayreddin Paşa, Mevlây Hasan", d:"Kaptan-ı deryâ Barbaros Hayreddin Paşa, donanmasıyla İtalya kıyılarını vurduktan sonra Tunus'a yönelip Hafsî hükümdarı Mevlây Hasan'ı kaçırarak şehre girdi. Tunus'un alınması, Sicilya Boğazı'nı kontrol eden konumuyla Batı Akdeniz'deki güç dengesini bir anda Osmanlı lehine çevirdi. Ancak bu hâkimiyet uzun sürmeyecek, Şarlken ertesi yıl büyük bir donanmayla karşılık verecekti.", kaynak:"barbaros-hayreddin-pasa", duygu:["🎉"] },
{ t:"1535-07-21", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Tunus'un Şarlken'e kaybı", gun:"21 Temmuz 1535", yer:"Tunus – Halkulvâd (La Goletta)", yer_id:"Tunus", kisiler:"Şarlken, Barbaros Hayreddin Paşa, Mevlây Hasan", d:"Şarlken, Ceneviz ve Papalık donanmalarıyla desteklenen büyük bir seferle Halkulvâd'ı düşürdükten sonra Tunus'u ele geçirdi ve Mevlây Hasan'ı İspanyol himayesinde tahta iade etti. Şehre bir İspanyol garnizonu yerleştirilerek Osmanlı'nın Orta Akdeniz'deki ilerleyişi geçici olarak durduruldu. Tunus'un kesin fethi ancak kırk yıl sonra, 1574'te mümkün olacaktı.", kaynak:"barbaros-hayreddin-pasa", duygu:["😔"] },
{ t:"1536-03-15", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler"], b:"Makbul İbrahim Paşa'nın idamı", gun:"14-15 Mart 1536", yer:"Topkapı Sarayı, İstanbul", yer_id:"İstanbul", kisiler:"Pargalı (Makbul) İbrahim Paşa, Kanunî Sultan Süleyman", d:"On üç yıl sadrazamlık yapan, Kanunî'nin en yakın dostu ve devletin fiilî ikinci adamı olan İbrahim Paşa, iftara çağrıldığı sarayda hiçbir gerekçe gösterilmeden boğdurularak idam edildi. Irakeyn seferinde takındığı tavır, 'serasker sultan' unvanını kullanması ve saray içi dengeler ölümünde etkili sayılır. İdam, Osmanlı merkez yönetiminde vezir-i âzamların mutlak güvenliğinin bulunmadığını gösteren bir dönüm noktasıdır.", kaynak:"ibrahim-pasa-makbul", duygu:["🏛","😔"] },
{ t:"1537-03-12", k:"fetih", etiket:["toprak-kazanc","konu-askeri","konu-idari"], b:"Klis Kalesi'nin fethi ve Dalmaçya sancağının kuruluşu", gun:"1537", ic_not_gun:"1537 (TDV yalnız yılı veriyor)", yer:"Klis, Dalmaçya", yer_id:"Klis", kisiler:"Gazi Hüsrev Bey, Murad Bey", d:"Gazi Hüsrev Bey'in kethüdâsı, Hırvat asıllı mühtedi Murad Bey, Split'in hemen kuzeyindeki stratejik Klis Kalesi'ni Venedik'ten aldı. Fetihten hemen sonra Klis, çevresini kapsayan yeni bir sancak ve kaza merkezi yapıldı; bu sancağın sınırları büyük ölçüde Osmanlı Hırvatistanı'nın çerçevesini çizdi. Knin'den on beş yıl sonra gelen bu fetih, Dalmaçya iç kesiminin idari iskeletini tamamladı.", kaynak:"klis", duygu:["🎉"] },
{ t:"1537-08-25", k:"savas", etiket:["savas","konu-askeri"], b:"Korfu kuşatması ve Venedik'le savaş", gun:"25 Ağustos 1537", yer:"Korfu Adası", yer_id:"Korfu", kisiler:"Kanunî Sultan Süleyman, Barbaros Hayreddin Paşa", d:"Pulya (Apulia) seferinin ardından Osmanlı ordusu Korfu'ya asker çıkardı ve adanın güçlü Venedik kalesini kuşattı. Kalenin sarp yapısı, ağır kayıplar ve mevsim şartları yüzünden 6 Eylül'de abluka kaldırılarak çekildi. Kuşatma sonuçsuz kaldıysa da Venedik'le açılan savaş, Ege ve Adriyatik'te çok sayıda adanın Osmanlı'ya katılmasıyla ve ertesi yıl Preveze zaferiyle sonuçlandı.", kaynak:"korfu", duygu:["⚔️"] },
{ t:"1538-09-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Boğdan Seferi ve Bucak (Bender) bölgesinin ilhakı", gun:"1538", yer:"Boğdan – Suçava, Yaş, Bender", yer_id:"Bender", kisiler:"Kanunî Sultan Süleyman, Petru Rareş, Sâhib Giray", d:"Osmanlı yükümlülüklerini yerine getirmeyen Boğdan voyvodası Petru Rareş üzerine çıkılan seferde Suçava zaptedildi, Yaş şehri Kırım Hanı Sâhib Giray tarafından yağmalandı. Padişah Çekirge Stefan'ı voyvodalığa getirdi ve Bender ile birlikte Bucak (Güney Besarabya) bölgesini doğrudan Osmanlı topraklarına kattı. Bu ilhak, Karadeniz'in kuzeybatı kıyılarını bir Osmanlı iç denizi hâline getiren halkalardan biri oldu. Boğdan zaten Osmanlı'ya tâbi bir voyvodalıktı ve harita onu tâbi renkte gösteriyordu — bu sefer toprağı yabancı bir devletten almadı, yalnızca Bender ve Bucak'ın iç idaresini voyvodadan alıp doğrudan padişaha bağladı; voyvodalığın geri kalanı tâbi statüsünü sürdürdü. Aynı yapı 1484'te Kili ve Akkirman'da, 1713'te Hotin'de de tekrarlanacaktı: sınır kaleleri doğrudan, iç topraklar tâbi.", statu_dogrudan:["İbrail","Bender","İsmail"], kaynak:"bogdan", duygu:["🎉","😔"] },
{ t:"1543-08-10", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Estergon ve İstolni Belgrad'ın fethi", gun:"10 Ağustos 1543", yer:"Estergon (Esztergom) – Macaristan", yer_id:"Estergon", kisiler:"Kanunî Sultan Süleyman", d:"Kanunî'nin bizzat çıktığı Macaristan seferinde, iki buçuk haftalık kuşatmanın ardından Macar Krallığı'nın dinî merkezi ve başpiskoposluk şehri Estergon Osmanlı idaresine girdi. Ardından Macar krallarının taç giyme şehri İstolni Belgrad da alınarak Budin eyaletinin savunma kuşağı tamamlandı. Estergon, 1595'e kadar Tuna hattının kilit kalesi olarak Osmanlı elinde kalacaktı.", kaynak:"estergon", duygu:["🎉"] },
{ t:"1547-06-18", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"İstanbul Antlaşması — Habsburglarla beş yıllık barış", gun:"18 Haziran 1547", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Kanunî Sultan Süleyman, Şarlken, Ferdinand", d:"Osmanlı ile Habsburglar arasında beş yıl süreli bir barış imzalandı; Ferdinand elinde tuttuğu Macar toprakları için yıllık 30.000 duka ödemeyi kabul etti. Antlaşma, Macaristan'ın üçe bölünmüş fiilî durumunu hukukî olarak tescil etti. Batı cephesinin böylece emniyete alınması, Kanunî'ye İran üzerine yeni seferler düzenleme imkânı verdi.", kaynak:"suleyman-i", duygu:["🤝"] },
{ t:"1553-02-01", k:"antlasma", etiket:["ittifak","diplomasi","konu-diplomasi"], b:"Osmanlı-Fransız ittifakı — Fransız donanmasının Osmanlı emrine girmesi", gun:"1 Şubat 1553", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Kanunî Sultan Süleyman, I. Henri (Fransa)", d:"1 Şubat 1553 tarihli antlaşmayla Fransa donanması Osmanlı donanmasının emrine verildi; İspanya'ya karşı Batı Akdeniz'de ortak harekât öngörüldü. Antlaşmanın ardından Turgut Reis 15 Haziran 1553'te kırk beş kadırgayla Fransa'yı desteklemek üzere sefere çıktı. Bu, 1536 kapitülasyonlarının ticari zeminini askerî bir iş birliğine taşıyan ilk resmî ittifak antlaşmasıydı.", kaynak:"turgut-reis", duygu:["🤝"] },
{ t:"1553-10-05", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"Şehzade Mustafa'nın Konya Ereğlisi'nde idamı", gun:"27 Şevval 960 (6 Ekim 1553)", ic_not_gun:"eski gun: 5 Ekim 1553 · EK1 §4a: TDV mustafa-celebi: padişah 26 Şevval (5 Ekim) Aktepe'de ordugâh kurdu, şehzade aynı gün geldi; idam '27 Şevval 960 / 6 Ekim 1553 Cuma'. t:1553-10-05 KORUNDU — ekokuma_hanedan/kadin/magazin ve merak kardes-katli '1553-10-05|Mustafa' bağları; aynı gün Kara Ahmed Paşa maddesi (ek7) de duruyor; D147 ③ 1553-10-06 = 0 · öneri YAMA-KRON2 15", yer:"Konya Ereğlisi (Aktepe) ordugâhı", yer_id:"Konya", kisiler:"Şehzade Mustafa, Kanunî Sultan Süleyman, Rüstem Paşa", d:"Nahcıvan seferi için toplanan orduya katılmak üzere babasının otağına giren Şehzade Mustafa, huzura çıkacağı sırada cellâtlarla karşılaştı ve boğdurularak öldürüldü. Ordu içinde büyük sevgi gören veliaht adayının katli yeniçeriler arasında derin bir öfke doğurdu, Rüstem Paşa sadaretten alındı. Olay, Osmanlı şehzade siyasetinin en tartışmalı kırılmalarından biri olarak edebiyata ve halk hafızasına geçti.", ic_not_d:"eski kaynak: suleyman-i", kaynak:"mustafa-celebi · suleyman-i", duygu:["🏛","😔"] },
{ t:"1559-05-30", k:"savas", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Konya Şehzâdeler Muharebesi", gun:"29-30 Mayıs 1559", yer:"Konya", yer_id:"Konya", kisiler:"Şehzade Selim, Şehzade Bayezid", d:"Taht mücadelesine giren Şehzade Bayezid yaklaşık 30.000 kişilik kuvvetiyle Konya önlerine geldi ve iki gün süren çarpışmada kardeşi Şehzade Selim'e yenildi. Bozguna uğrayan Bayezid Amasya üzerinden İran'a, Şah Tahmasb'a sığındı. Muharebe, Kanunî'nin son yıllarında saltanat veraseti krizini bir dış politika sorununa dönüştürdü.", kaynak:"bayezid-sehzade", duygu:["⚔️"] },
{ t:"1560-05-14", k:"savas", etiket:["savas","konu-askeri"], b:"Cerbe Deniz Zaferi", gun:"14 Mayıs 1560", yer:"Cerbe (Djerba) Adası, Tunus açıkları", yer_id:"Cerbe (Djerba)", kisiler:"Piyâle Paşa, Turgut Reis", d:"Piyâle Paşa kumandasındaki Osmanlı donanması, Trablus'u geri almak için toplanan İspanyol-Ceneviz-Malta müttefik filosunu Cerbe önlerinde ikiye ayrılma manevrasıyla dağıttı. Müttefikler donanmalarının büyük bölümünü kaybetti, adadaki kale de kısa sürede düştü. Cerbe, Preveze'den sonra Osmanlı'nın Akdeniz'deki üstünlüğünü perçinleyen ikinci büyük deniz zaferi sayılır.", kaynak:"cerbe", duygu:["⚔️"] },
{ t:"1562-07-23", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-kisiler","konu-hanedan"], b:"Şehzade Bayezid'in Kazvin'de idamı", gun:"23 Temmuz 1562", yer:"Kazvin, İran", yer_id:"Kazvin", kisiler:"Şehzade Bayezid, Şah Tahmasb, Ali Ağa", d:"İran'a sığınan Şehzade Bayezid, uzun pazarlıklar sonucunda Şah Tahmasb tarafından Osmanlı heyetine teslim edildi ve dört oğluyla birlikte boğdurularak öldürüldü. Teslim karşılığında Safevîler önemli maddî tavizler ve sınır güvencesi elde etti. Bu infazla II. Selim'in tahta çıkışının önündeki son engel kalktı ve Amasya Antlaşması'nın barış düzeni korundu.", kaynak:"bayezid-sehzade", duygu:["🏛","😔"] },
{ t:"1567-04-01", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Yemen isyanı ve Koca Sinan Paşa'nın Yemen seferi", gun:"1567 (sefer 1568-1570)", yer:"Yemen – San'a, Kevkebân", kisiler:"İmam Mutahhar, Koca Sinan Paşa, Özdemiroğlu Osman Paşa", d:"Zeydî imam Mutahhar, zorla vergi toplandığı gerekçesiyle ayaklanarak Osmanlı idaresini Yemen'in büyük bölümünden söküp attı. İstanbul'dan gönderilen Koca Sinan Paşa 1568-1570 arasında yürüttüğü harekâtla Kevkebân'ı uzun bir kuşatmanın ardından alarak bölgede Osmanlı hâkimiyetini yeniden kurdu. Sefer, Kızıldeniz'in güney kapısının ve Hint Okyanusu ticaret yolunun denetimini korumak bakımından hayatî önemdeydi.", kaynak:"yemen", duygu:["✊"], yer_id:"Sana" },
{ t:"1567-10-01", k:"diger", etiket:["ittifak","diplomasi","konu-diplomasi"], b:"Açe Sultanlığı'yla savunma ittifakı ve Hint Okyanusu yardımı", gun:"1567", yer:"Açe (Sumatra) – İskenderiye", yer_id:"Banda Açe", kisiler:"II. Selim, Sultan Alâeddin Riâyet Şah", d:"Portekiz saldırıları karşısında Kanunî'den yardım isteyen Açe elçileri, padişahın Zigetvar'da vefatı üzerine bağlılıklarını II. Selim'e sundular ve onunla bir savunma antlaşması imzalandı. Padişah İskenderiye'den top, tüfek, cephane ve usta gönderilmesini emretti; Hint sularına sevk edilmek üzere on yedi savaş gemisi hazırlandı. Yemen isyanının büyümesi filonun yola çıkmasını engelledi, ancak Açe'ye ulaşan Osmanlı topçu ve ustaları bölgede kalıcı iz bıraktı.", kaynak:"ace", duygu:["📌"] },
{ t:"1570-09-09", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Lefkoşa'nın fethi", gun:"9 Eylül 1570", yer:"Lefkoşa, Kıbrıs", yer_id:"Lefkoşa", kisiler:"Lala Mustafa Paşa, Piyâle Paşa", d:"25 Temmuz 1570'te başlayan ve kırk beş gün süren kuşatmanın ardından Kıbrıs'ın Venedik idaresindeki başkenti Lefkoşa Osmanlı ordusuna teslim oldu. Adanın merkezinin düşmesi, Venedik direncini Magosa kalesine sıkıştırdı. Fetih Batı'da büyük yankı uyandırdı ve Papa'nın öncülüğünde Kutsal İttifak donanmasının kurulmasına giden süreci hızlandırdı.", kaynak:"kibris", duygu:["🎉"] },
{ t:"1572-06-01", k:"diger", etiket:["savas","ekonomi","konu-askeri","konu-ekonomi","konu-imar"], b:"İnebahtı sonrası donanmanın yeniden inşası", gun:"Haziran 1572", yer:"İstanbul Tersanesi – Akdeniz", yer_id:"İstanbul", kisiler:"Kılıç Ali Paşa, Sokullu Mehmed Paşa", d:"İnebahtı hezimetinden sonra kaptan-ı deryâlığa getirilen Kılıç Ali Paşa'nın ilk işi ağır kayıplara uğrayan donanmayı yeniden kurmak oldu; tersaneler 1571-1572 kışı boyunca aralıksız çalıştı. Haziran 1572'de yaklaşık 250 kadırga ve 300 gönüllü reis kadırgasından oluşan yeni bir filo Akdeniz'e açıldı. Bu hızlı toparlanma, İnebahtı'nın Osmanlı deniz gücünü kalıcı biçimde kıramadığını gösterdi.", kaynak:"kilic-ali-pasa", duygu:["📌"] },
{ t:"1573-03-07", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Venedik'le İstanbul Antlaşması — Kıbrıs'ın tanınması", gun:"1573", yer:"İstanbul", yer_id:"Lefkoşa", kisiler:"Sokullu Mehmed Paşa, Venedik Cumhuriyeti", d:"Kutsal İttifak'ın dağılması üzerine yalnız kalan Venedik, Osmanlı ile ayrı barış yaparak Kıbrıs'ın Osmanlı'ya ait olduğunu resmen kabul etti ve savaş tazminatı ödemeyi kabullendi. Antlaşma, İnebahtı zaferinin Hıristiyan dünyasına siyasî bir kazanç sağlamadığını açıkça ortaya koydu. Venedik bundan sonra yetmiş yıl boyunca Osmanlı ile doğrudan savaşa girmekten kaçınacaktı.", kaynak:"kibris", duygu:["🤝"] },
{ t:"1574-12-22", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"II. Selim'in vefatı ve III. Murad'ın cülûsu", gun:"22 Aralık 1574", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Selim, III. Murad, Sokullu Mehmed Paşa", d:"II. Selim'in ölümü ve Manisa'dan getirilen III. Murad'ın cülûsu 22 Aralık 1574'te resmen ilân edildi. Yeni padişah yirmi bir yıl tahtta kalacak, saltanatı Doğu'da uzun İran savaşları, Batı'da Uzun Savaş'ın arifesi ve içeride akçe tağşişiyle anılacaktı. Sokullu Mehmed Paşa'nın 1579'daki ölümüne kadar devlet yönetiminde eski düzen sürdü.", kaynak:"murad-iii", duygu:["🏛"], vefat_id:"selim2" },
{ t:"1578-08-04", k:"savas", etiket:["savas","ittifak","konu-askeri","konu-diplomasi"], b:"Vâdisseyl (Kasrılkebir) Savaşı — Osmanlı desteğindeki Abdülmelik Portekiz ordusunu imha etti", ic_not_b:"eski b: Vâdisseyl (Kasrılkebir) Savaşı ve Fas'ın Osmanlı himayesine girmesi · EK1 §4a: başlık kaynağın diliyle düzeltildi ('himaye' TDV fas'ta yok). Bağlar: ekokuma_statu '1578-08-04' ayırıcısız, savaslar.js t ile — başlık değişikliği kopartmaz", gun:"4 Ağustos 1578", yer:"Kasrılkebir, Fas", kisiler:"Abdülmelik, Portekiz Kralı Sebastian, Ramazan Paşa", d:"Osmanlı desteğiyle Fas tahtına oturan Abdülmelik, Portekiz Kralı Sebastian'ın büyük ordusunu Vâdisseyl'de imha etti; savaşta üç hükümdar birden öldüğü için Batı kaynaklarında 'Üç Krallar Savaşı' diye anılır. Portekiz'in askerî gücü çöktü ve ülke kısa süre sonra İspanya'nın eline geçti. Abdülmelik de savaşta öldü; yerine geçen kardeşi Ahmed el-Mansûr zaferi İstanbul'a bir heyetle bildirdi. İki devlet arasındaki ilişki haraç ya da tâbiiyet değil elçi ve hediye teatisi düzeyinde kaldı ve kısa süre sonra hediye meselesi yüzünden gerginleşti.", ic_not_d:"EK1 §4a: eski son cümle 'Fas ise Osmanlı nüfuzuna girerek Kuzey Afrika'da Osmanlı-İspanyol dengesini belirledi.' — TDV fas: 'Osmanlı desteğindeki Sultan Abdülmelik'; ilişki elçi/hediye teatisi, Ahmed el-Mansûr'un hediye krizi; 'himaye' ve haraç/tâbiiyet kaydı YOK · eski kaynak: murad-iii", kaynak:"fas · murad-iii", duygu:["⚔️"], yer_id:"Kasrülkebîr" },
{ t:"1592-06-19", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Bihaç'ın fethi", gun:"19 Haziran 1592", ic_not_gun:"(TDV yalnız yılı veriyor; gün, 10-19 Haziran kuşatmasını ve kumandan Lamberg'in tesliminin tarihini veren TDV dışı kaynaktan)", yer:"Bihaç, Hırvatistan sınırı", kisiler:"Telli (Gazi) Hasan Paşa", d:"Bosna beylerbeyi Telli Hasan Paşa, Kasım 1591'de Bihaç'ın ön kalesi Ripaç'ı aldıktan sonra 1592'de şehrin ve kalenin kendisini de ele geçirdi; on günlük kuşatmanın ardından kumandan Lamberg teslim oldu. Bu fetih, Bosna sınırını Una nehri boyunca ileri itti ve bir yıl sonra Telli Hasan Paşa'nın Kulpa önünde şehit düşmesiyle patlak verecek Uzun Savaş'ın arifesindeki son büyük Osmanlı kazancı oldu.", kaynak:"bihac", duygu:["🎉"], yer_id:"Bihaç (Bihać)" },
{ t:"1593-07-01", k:"savas", etiket:["savas","konu-askeri"], b:"Osmanlı-Avusturya 'Uzun Savaş'ının başlaması", gun:"1593", yer:"Hırvatistan – Macaristan sınırı", kisiler:"Koca Sinan Paşa, Telli Hasan Paşa", d:"Bosna Beylerbeyi Telli Hasan Paşa'nın Kulpa (Siszek) önünde bozguna uğrayıp şehid düşmesi üzerine Osmanlı Devleti Avusturya'ya savaş ilan etti ve on üç yıl sürecek Uzun Savaş başladı. Ateşli silahlı piyadenin belirleyici olduğu bu savaş, Osmanlı ordu düzeninde sekban ve tüfekli asker istihdamını hızlandırdı, tımarlı sipahinin gerilemesini derinleştirdi. Savaş 1606'da Zitvatorok Antlaşması ile sona erecekti.", kaynak:"avusturya", duygu:["⚔️"], yer_kon:[45.4867,16.3763] },
{ t:"1594-09-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Yanıkkale'nin (Győr) fethi", gun:"27 Eylül 1594", yer:"Yanıkkale (Győr), Macaristan", yer_id:"Yanıkkale (Győr)", kisiler:"Koca Sinan Paşa", d:"Sadrazam Koca Sinan Paşa, bir aydan uzun süren kuşatmanın ardından Viyana yolunun kilidi sayılan Yanıkkale'yi teslim aldı. Kalenin düşmesi Avrupa'da büyük paniğe yol açtı ve Osmanlı'nın Uzun Savaş'taki en parlak kazancı oldu. Ancak kale yalnızca dört yıl elde tutulabilecekti.", kaynak:"yanikkale", duygu:["🎉"] },
{ t:"1595-01-16", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"III. Murad'ın vefatı ve III. Mehmed'in cülûsu", gun:"15-16 Ocak 1595", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Murad, III. Mehmed, Safiye Sultan", d:"Yirmi bir yıllık saltanatın ardından III. Murad vefat etti ve Manisa'dan gelen oğlu III. Mehmed tahta çıktı. Yeni padişah cülûsunda on dokuz kardeşini boğdurttu; bu, Osmanlı tarihindeki en geniş kapsamlı kardeş katli uygulaması oldu ve kısa süre sonra veraset usulünün değişmesine zemin hazırladı. III. Mehmed, Uzun Savaş'ın ortasında sefere bizzat çıkan son padişah olacaktı.", kaynak:"mehmed-iii", vefat_id:"murad3", duygu:["🏛"] },
{ t:"1595-09-02", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Estergon'un Avusturya'ya kaybı", gun:"Eylül 1595", yer:"Estergon (Esztergom), Macaristan", yer_id:"Estergon", kisiler:"Arşidük Matthias, Karl von Mansfeld", d:"Karl von Mansfeld'in yönettiği kuşatmada yeterli yardım alamayan Estergon muhafızları kaleyi Arşidük Matthias'a teslim etti. Elli iki yıllık Osmanlı hâkimiyetinin sona ermesiyle Tuna hattındaki savunma zinciri kırıldı ve Budin doğrudan tehdit altına girdi. Kale ancak on yıl sonra, 1605'te geri alınabilecekti.", kaynak:"estergon", duygu:["😔"] },
{ t:"1596-10-12", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Eğri Kalesi'nin fethi", gun:"12 Ekim 1596", yer:"Eğri (Eger), Macaristan", yer_id:"Eğri", kisiler:"III. Mehmed, Cigalazâde Sinan Paşa", d:"Üç hafta süren mücadelenin ardından, Osmanlıların daha önce bir türlü alamadığı güçlü Eğri Kalesi muhafızların teslim olmasıyla düştü. Padişahın bizzat bulunduğu bu fetih, kaybedilen Estergon'un yarattığı morali bir ölçüde onardı ve Eğri Eyaleti kuruldu. İki hafta sonra kazanılan Haçova zaferiyle birlikte 1596, Uzun Savaş'ın en başarılı Osmanlı yılı oldu.", kaynak:"egri", duygu:["🎉"] },
{ t:"1598-03-29", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Yanıkkale'nin (Győr) kaybı", gun:"29 Mart 1598", yer:"Yanıkkale (Győr), Macaristan", yer_id:"Yanıkkale (Győr)", kisiler:"Miklós Pálffy, Adolf von Schwarzenberg", d:"Miklós Pálffy ve Adolf von Schwarzenberg kumandasındaki birlikler baskınla kale kapılarını patlatarak Yanıkkale'yi geri aldı. Dört yıl önce Koca Sinan Paşa'nın büyük emeklerle elde ettiği kalenin kaybı, Osmanlı'nın Macaristan'daki ileri hattını çökertti. Aynı yıl Budin'i kuşatan düşman kuvvetleri püskürtülse de savaşın dengesi giderek yıpratma savaşına dönüştü.", kaynak:"yanikkale", duygu:["😔"] },
{ t:"1599-01-01", k:"isyan", etiket:["isyan","konu-isyan"], b:"Karayazıcı Abdülhalim ayaklanması", gun:"1599", yer:"Urfa – Orta Anadolu", yer_id:"Urfa", kisiler:"Karayazıcı Abdülhalim, Deli Hasan", d:"Uzun Savaş'ta ordudan kaçan sekban ve levendleri toplayan Karayazıcı Abdülhalim, Orta Anadolu'da geniş bir bölgeyi denetimine aldı, Urfa Kalesi'ni ele geçirdi (Kasım 1599) ve 'Halim Şah' unvanıyla padişahlığını ilân ederek kendi tuğrasını taşıyan fermanlar gönderdi. Büyük Celâlî dalgasının ilk lideri sayılan Karayazıcı 1602'de ölmüş, hareketi kardeşi Deli Hasan sürdürmüştür. Ayaklanma, Anadolu köylüsünün kitleler hâlinde toprağını terk ettiği 'büyük kaçgunluk' döneminin başlangıcıdır.", ic_not_d:"EK2 §4: 'Urfa'da kendi adına hutbe okuttu' TDV karayazici-abdulhalim'de YOK; TDV: 'Halim Şah muzaffer bâdâ' tuğralı fermanlar (hutbe-sikke Canbolatoğlu için anlatılıyor). t:1599-06-01 günü kaynaksız (TDV: serdar Ağustos 1599'da yola çıktı, Urfa Kasım 1599) — t korundu: ekokuma_celali/ekonomi/savas '1599-06-01|Karayazıcı' bağları + savaslar.js · öneri YAMA-KRON2 · eski cümle: …Orta Anadolu'da geniş bir bölgeyi denetimine alarak Urfa'da kendi adına hutbe okuttu.", kaynak:"karayazici-abdulhalim", duygu:["✊"] },
{ t:"1601-09-10", k:"savas", etiket:["savas","konu-askeri"], b:"Tiryaki Hasan Paşa'nın Kanije savunması", gun:"9-10 Eylül – 17-18 Kasım 1601", ic_not_gun:"EK2 §4: TDV kanije 10 Eylül–17 Kasım · tiryaki-hasan-pasa 9 Eylül varış, çekiliş '22 Cemâziyelevvel 1010 / 18 Kasım 1601' · mehmed-iii 18 Kasım (§4⑥ iç ayrışma, iki uç birlikte gösterildi). t korundu (ekokuma_savas '1601-09-10|Kanije') · eski gun: 10 Eylül – 17 Kasım 1601", yer:"Kanije (Nagykanizsa), Macaristan", yer_id:"Kanije", kisiler:"Tiryaki Hasan Paşa, Arşidük Ferdinand", d:"Bir yıl önce fethedilen Kanije'yi geri almak isteyen Arşidük Ferdinand ve müttefikleri kaleyi iki aydan uzun süre kuşattı; Tiryaki Hasan Paşa 9000 kişilik kuvvetiyle direndi. Dışarıdan yardım alamamasına rağmen genel hücumları püskürttü ve huruç harekâtlarıyla düşmanı ağır kayıplar vererek çekilmeye zorladı. Savunma, Osmanlı tarih yazımında destanlaşmış ve 'Kanije Muhasarası' başlı başına bir edebî tür hâline gelmiştir.", ic_not_d:"EK2 §4: 'yaklaşık iki bin kişilik garnizon' — TDV tiryaki-hasan-pasa '9000 kişilik kuvvet' (kanije: olağan kadro ~1400); 'hileleriyle' TDV'de yok · eski kaynak: kanije · eski cümle: …yaklaşık iki bin kişilik garnizonla direndi. Yaptığı ani huruç harekâtları ve hileleriyle düşmanı…", kaynak:"kanije · tiryaki-hasan-pasa · mehmed-iii", duygu:["⚔️"] },
{ t:"1603-12-22", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"III. Mehmed'in vefatı ve I. Ahmed'in cülûsu", gun:"22 Aralık 1603", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Mehmed, I. Ahmed", d:"III. Mehmed'in 20 Aralık'ta ölümü üzerine on dört yaşındaki oğlu I. Ahmed tahta çıktı. Çocuk yaşta ve sancağa çıkmadan tahta oturan ilk padişah olması, şehzadelerin taşrada yetiştirilmesi usulünün fiilen sona erdiğini gösterir. I. Ahmed'in saltanatında kardeş katli terk edilerek 'ekberiyet' (en yaşlı erkek üyenin tahta geçmesi) esasına geçilecekti.", kaynak:"ahmed-i", vefat_id:"mehmed3", duygu:["🏛"] },
{ t:"1605-10-03", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Estergon'un geri alınışı", gun:"3 Ekim 1605", yer:"Estergon (Esztergom), Macaristan", yer_id:"Estergon", kisiler:"Lala Mehmed Paşa", d:"Sadrazam Lala Mehmed Paşa, on yıl önce kaybedilen Estergon'u kuşatarak yeniden Osmanlı idaresine kattı. Aynı sefer içinde Peşte ve Vaç da kurtarılmış, Osmanlı Macaristan'daki hattını toparlamıştı. Bu başarı, ertesi yıl Zitvatorok'ta masaya nispeten güçlü oturulmasını sağladı; Estergon 1683'e kadar Osmanlı elinde kalacaktı.", kaynak:"estergon", duygu:["🎉"] },
{ t:"1607-10-24", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Oruç Ovası zaferi ve Canbolatoğlu isyanının bastırılması", gun:"23-24 Ekim 1607 (asıl savaş 24 Ekim)", ic_not_gun:"17 Eyl 2026: t kaynak gününe alındı, bağlar birlikte taşındı (KOSU13-YAMA · YAMA-KOSU10-KALAN G6). ÖNCEKİ NOT — EK2 §4: TDV kuyucu-murad-pasa: çatışmalar 2 Receb 1016 (23 Ekim) başladı, esas savaş ertesi gün; canbolatogullari '3 Receb 1016 / 24 Ekim 1607'; ahmed-i '24 Ekim 1607'. t:1607-10-23 KORUNDU — ekokuma_celali '1607-10-23|Canbolatoğlu' bağları + savaslar.js; D147 ③ 1607-10-24 = 0 · öneri YAMA-KRON2 · eski gun: 23 Ekim 1607", yer:"Oruç Ovası, Halep civarı", yer_id:"Halep", kisiler:"Kuyucu Murad Paşa, Canbolatoğlu Ali Paşa", d:"Halep'te bağımsız bir beylik kurup Toskana ile ittifak arayışına giren Canbolatoğlu Ali Paşa, Sadrazam Kuyucu Murad Paşa tarafından Oruç Ovası'nda ağır bir bozguna uğratıldı. Suriye'de merkezî otoritenin yeniden kurulmasıyla Celâlî dalgasının en tehlikeli kolu kırıldı. Kuyucu Murad Paşa'nın iki yıl süren acımasız tasfiyesi, Anadolu'da asayişi geçici de olsa sağladı.", ic_not_d:"eski kaynak: kuyucu-murad-pasa", kaynak:"kuyucu-murad-pasa · canbolatogullari · ahmed-i", duygu:["✊"] },
{ t:"1608-08-09", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Alaçayır zaferi ve Kalenderoğlu isyanının bastırılması", gun:"26 Rebîülâhir 1017 (9 Ağustos 1608)", ic_not_gun:"17 Eyl 2026: t kaynak gününe alındı, bağlar birlikte taşındı (KOSU13-YAMA · YAMA-KOSU10-KALAN G6). ÖNCEKİ NOT — EK2 §4: 5 Ağustos günü kaynakta YOK — TDV kalenderoglu-mehmed '26 Rebîülâhir 1017 / 9 Ağustos 1608' (Göksun Boğazı), kuyucu-murad-pasa 'Rebîülâhir 1017 (Ağustos 1608)'. t:1608-08-05 KORUNDU — ekokuma_celali '1608-08-05|Kalenderoğlu' bağları + savaslar.js; D147 ③ 1608-08-09 = 0 · öneri YAMA-KRON2 · eski gun: Ağustos 1608", yer:"Alaçayır (Göksun civarı)", kisiler:"Kuyucu Murad Paşa, Kalenderoğlu Mehmed", d:"Manisa ve Bursa yörelerini haraca kesen Celâlî lideri Kalenderoğlu, Kuyucu Murad Paşa tarafından Alaçayır'da bozguna uğratıldı ve İran'a kaçmak zorunda kaldı. Bu zaferle Anadolu'daki büyük Celâlî ordularının sonuncusu dağıtıldı. Kuyucu Murad Paşa'nın, öldürttüğü âsileri kazdırdığı kuyulara doldurduğu rivayet edilen sert tasfiyesi, kısa vadede düzeni sağladıysa da Anadolu'nun nüfus ve üretim kaybını telafi edemedi.", ic_not_d:"EK2 §4: 'kuyulara doldurma' olgu gibi yazılmıştı; TDV kuyucu-murad-pasa bunu (ve 60-70.000 sayısını) 'rivayet edilir' diye veriyor; lakabın öteki rivayeti 1585 Tebriz seferinde atıyla kuyuya düşmesi · eski kaynak: kuyucu-murad-pasa · eski cümle: Kuyucu Murad Paşa'nın kuyulara doldurduğu isyancılarla anılan tasfiyesi…", kaynak:"kuyucu-murad-pasa · kalenderoglu-mehmed", duygu:["✊"], yer_kon:[38.0169,36.4967] },
{ t:"1612-07-06", k:"antlasma", etiket:["diplomasi","ekonomi","konu-diplomasi","konu-ekonomi"], b:"Hollanda'ya ilk ahidnâme verilmesi", gun:"6 Temmuz 1612", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Ahmed, Cornelis Haga", d:"Felemenk Birleşik Cumhuriyeti'nin elçisi Cornelis Haga, I. Ahmed'den Fransa ve İngiltere'ye verilenlerle aynı kapsamda bir ahidnâme almayı başardı. Hollanda böylece İstanbul'da elçilik, Osmanlı iskelelerinde konsolosluk açma ve kendi bayrağıyla ticaret yapma hakkı kazandı. Bu ahidnâme, Akdeniz ticaretinde Venedik'in yerini alan kuzeyli deniz güçlerinin Osmanlı pazarına girişini simgeler.", kaynak:"hollanda", duygu:["🤝"] },
{ t:"1617-11-22", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"I. Ahmed'in ölümü ve I. Mustafa'nın cülûsu — ekberiyet usulü", gun:"22 Kasım 1617", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Ahmed, I. Mustafa", d:"Elli bir gün süren mide hastalığının ardından yirmi sekiz yaşındaki I. Ahmed vefat etti ve tahta oğlu yerine kardeşi I. Mustafa çıkarıldı. Böylece babadan oğula geçen veraset usulü terk edilerek hanedanın en yaşlı erkek üyesinin tahta geçtiği 'ekberiyet' sistemine fiilen geçilmiş oldu. Doksan altı gün süren bu ilk saltanat, şehzadelerin 'kafes'te yetişmesi devrinin de başlangıcıdır.", kaynak:"mustafa-i", vefat_id:"ahmed1", duygu:["🏛"] },
{ t:"1618-02-26", k:"siyaset", etiket:["siyaset","darbe-siyasi","konu-siyasi","konu-darbe","konu-hanedan"], b:"I. Mustafa'nın hal'i ve Genç Osman'ın (II. Osman) cülûsu", gun:"26 Şubat 1618", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Mustafa, II. Osman", d:"Ruh sağlığı yerinde olmadığı gerekçesiyle I. Mustafa doksan altı günün sonunda tahttan indirildi ve I. Ahmed'in on dört yaşındaki oğlu II. Osman padişah oldu. Genç Osman, yeniçeri ocağını kaldırıp yeni bir ordu kurma tasarısıyla Osmanlı reform tartışmalarının ilk radikal ismi sayılır. Bu tasarı dört yıl sonra kendi hayatına mal olacaktı.", kaynak:"osman-ii", duygu:["🏛"] },
{ t:"1618-09-26", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Serav Antlaşması — İran'la barışın yenilenmesi", gun:"1618", yer:"Serav (Serâb), Azerbaycan", kisiler:"II. Osman, Şah Abbas, Dilâver Paşa", d:"Pül-i Şikeste bozgunundan sonra İran'la varılan Serav Antlaşması, 1612 Nasuh Paşa Antlaşması'nın şartlarını büyük ölçüde teyit etti; Safevîlerin göndereceği yıllık ipek miktarı iki yüz yükten yüz yüke indirildi. Böylece 1603'ten beri süren doğu savaşlarının ikinci evresi kapandı. Barış uzun ömürlü olmayacak, Bağdat'ın 1623'te elden çıkmasıyla savaş yeniden alevlenecekti.", kaynak:"osman-ii", duygu:["🤝"], yer_kon:[37.9414,47.5344] },
{ t:"1621-10-09", k:"antlasma", etiket:["antlasma","savas","konu-askeri","konu-diplomasi"], b:"Hotin Seferi ve Hotin Antlaşması", gun:"9 Ekim 1621", yer:"Hotin, Boğdan (Dinyester boyu)", yer_id:"Hotin", kisiler:"II. Osman, Jan Karol Chodkiewicz", d:"II. Osman'ın bizzat kumanda ettiği büyük orduya karşı Chodkiewicz'in Hotin önünde kurduğu tahkimatlı ordugâh aşılamadı ve aylarca süren hücumlardan sonuç alınamadı. 9 Ekim'de imzalanan antlaşmayla Dinyester nehri sınır kabul edildi, Lehler Kazak akınlarını engellemeyi taahhüt etti. Zafer diye sunulmasına rağmen sonuç veremeyen sefer, genç padişahın yeniçeriye duyduğu güvensizliği ve ocağı tasfiye niyetini pekiştirdi.", kaynak:"hotin", duygu:["🤝"] },
{ t:"1623-09-10", k:"siyaset", etiket:["siyaset","darbe-siyasi","konu-siyasi","konu-darbe","konu-hanedan"], b:"I. Mustafa'nın ikinci hal'i ve IV. Murad'ın cülûsu", gun:"10 Eylül 1623", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Mustafa, IV. Murad, Kösem Sultan", d:"II. Osman'ın katlinden sonra ikinci kez tahta çıkarılan I. Mustafa bir yıl üç ay sonra yeniden indirildi ve on bir yaşındaki IV. Murad padişah ilan edildi. İlk dokuz yıl devlet fiilen annesi Kösem Sultan ve saray ricâli tarafından yönetildi. IV. Murad 1632'den itibaren yönetime bizzat el koyarak sert bir merkezîleşme dönemi başlatacaktı.", kaynak:"murad-iv", duygu:["🏛"] },
{ t:"1623-11-28", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Bağdat'ın Safevîlere kaybı", gun:"28 Kasım 1623", yer:"Bağdat", yer_id:"Bağdat", kisiler:"Bekir Subaşı, Şah Abbas, Derviş Mehmed", d:"Bağdat'ta ayaklanan Bekir Subaşı'nın Safevîlerle giriştiği pazarlıklar sonunda, iç kaleyi savunan oğlu Derviş Mehmed şehri Şah Abbas'ın kuvvetlerine teslim etti. Hilâfet mirasının sembol şehirlerinden birinin ve Irak'ın büyük bölümünün elden çıkması İstanbul'da büyük infial uyandırdı. Bağdat'ı geri almak, on beş yıl boyunca Osmanlı doğu politikasının tek hedefi olacaktı.", kaynak:"bagdat", duygu:["😔"] },
{ t:"1628-09-22", k:"isyan", etiket:["isyan","konu-isyan"], b:"Abaza Mehmed Paşa'nın Erzurum merkezli isyanının bastırılması", gun:"1628", yer:"Erzurum", yer_id:"Erzurum", kisiler:"Abaza Mehmed Paşa, Hüsrev Paşa, IV. Murad", d:"II. Osman'ın katlinin intikamını almak iddiasıyla yeniçerilere karşı ayaklanan Erzurum Beylerbeyi Abaza Mehmed Paşa, yıllarca Doğu Anadolu'yu denetiminde tuttu ve merkeze karşı direndi. Sadrazam Hüsrev Paşa'nın Erzurum kuşatmasıyla teslim olmak zorunda kaldı, affedilerek Bosna'ya tayin edildi. İsyanın sona ermesi, IV. Murad'ın İran üzerine sefere çıkabilmesinin ön şartıydı.", kaynak:"murad-iv", duygu:["✊"] },
{ t:"1634-01-08", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-burokrasi","konu-din"], b:"İlk şeyhülislâm idamı: Ahîzâde Hüseyin Efendi", gun:"1634", yer:"Büyükçekmece, İstanbul", yer_id:"İstanbul", kisiler:"Ahîzâde Hüseyin Efendi, IV. Murad", d:"Askerî kargaşada arabuluculuk yapması ve padişaha yargı usulüne dair yazılı bir uyarı göndermesi gerekçe gösterilerek Şeyhülislâm Ahîzâde Hüseyin Efendi Büyükçekmece yakınlarında idam edildi. İdam edilen ilk Osmanlı şeyhülislâmı olması, ilmiye mensuplarına en ağır cezanın sürgün olduğu köklü geleneği kırdı. Olay, IV. Murad'ın sertleşen otoritesinin ve devlet-ulemâ dengesinin bozulmasının simgesi sayılır.", kaynak:"ahizade-huseyin-efendi", duygu:["🏛","😔"] },
{ t:"1635-08-08", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"IV. Murad'ın Revan'ı fethi", gun:"8 Ağustos 1635", yer:"Revan (Erivan)", yer_id:"Revan", kisiler:"IV. Murad", d:"28 Mart 1635'te İstanbul'dan hareket eden IV. Murad, 28-29 Temmuz'da Revan'ı kuşattı ve 8 Ağustos'ta kaleyi teslim aldı; ardından boşaltılmış Tebriz'e girerek şehri tahrip ettirdi. Padişah, zaferin anısına Topkapı Sarayı'nda Revan Köşkü'nü inşa ettirdi. Bu sefer, padişahın bizzat orduya kumanda ettiği otuz yıllık aradan sonraki ilk büyük doğu harekâtıydı.", kaynak:"revan", duygu:["🎉"] },
{ t:"1636-04-01", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Revan'ın Safevîlere kaybı", gun:"1 Nisan 1636", yer:"Revan (Erivan)", yer_id:"Revan", kisiler:"Şah Safî, IV. Murad", d:"Osmanlı ordusunun çekilmesinin ardından Şah Safî kuvvetleri Revan'ı kuşatarak sekiz ay içinde geri aldı. Kalenin bu kadar çabuk elden çıkması, Kafkasya'da kalıcı hâkimiyetin lojistik olarak ne kadar güç olduğunu gösterdi. Revan, 1639 Kasr-ı Şirin Antlaşması'yla da İran'da bırakılacak ve Osmanlı Azerbaycan iddiasından vazgeçecekti.", kaynak:"revan", duygu:["😔"] },
{ t:"1638-12-24", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Bağdat'ın geri fethi", gun:"24 Aralık 1638", yer:"Bağdat", yer_id:"Bağdat", kisiler:"IV. Murad, Tayyar Mehmed Paşa", d:"8 Mayıs 1638'de İstanbul'dan çıkan IV. Murad, kırk gün süren şiddetli bir kuşatmanın ardından on beş yıldır Safevî elinde bulunan Bağdat'ı geri aldı; kuşatmada Vezir Tayyar Mehmed Paşa şehid düştü. Şehrin fethiyle Irak'ta Osmanlı idaresi yeniden kuruldu ve padişah 'Bağdat Fâtihi' unvanını aldı. Fetih, ertesi yılki Kasr-ı Şirin Antlaşması'yla kalıcılaşarak bugünkü Türkiye-İran sınırının temelini attı.", kaynak:"murad-iv", duygu:["🎉"] },
{ t:"1640-02-09", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"IV. Murad'ın ölümü ve Sultan İbrahim'in cülûsu", gun:"9 Şubat 1640", yer:"İstanbul", yer_id:"İstanbul", kisiler:"IV. Murad, Sultan İbrahim, Kösem Sultan", d:"Yirmi sekiz yaşında ölen IV. Murad'ın ardından hanedanın hayatta kalan tek erkek üyesi olan kardeşi İbrahim tahta çıktı. Yıllarca kafeste yaşamış olan yeni padişahın saltanatında saray harcamaları ve saray içi nüfuz mücadeleleri devlet düzenini sarstı. Sekiz yıl sonra hal'edilip katledilmesiyle Osmanlı tarihinin ikinci padişah katli yaşanacaktı.", kaynak:"murad-iv", vefat_id:"murad4", duygu:["🏛"] },
{ t:"1642-02-26", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Azak Kalesi'nin Kazaklardan geri alınışı", gun:"1642", yer:"Azak Kalesi, Don deltası", yer_id:"Azak", kisiler:"Sultanzâde Mehmed Paşa, IV. Mehmed Giray", d:"1637'de Don Kazaklarının ele geçirdiği Azak Kalesi, Sultanzâde Mehmed Paşa ile Kırım Hanı IV. Mehmed Giray'ın ortak harekâtı karşısında boşaltıldı; Kazaklar kaleyi ateşe vererek çekildi. Karadeniz'in kuzey kapısının geri alınması, Kazak akınlarının İstanbul Boğazı'na kadar uzandığı tehlikeli dönemi kapattı. Kale 1696'da bu kez Rus Çarı I. Petro'ya kaptırılacaktı.", kaynak:"azak", duygu:["🎉"] },
{ t:"1645-08-22", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Girit seferinin başlaması ve Hanya'nın fethi", gun:"Ağustos 1645", yer:"Hanya (Chania), Girit", yer_id:"Hanya", kisiler:"Sultan İbrahim, Silâhdar Yûsuf Paşa", d:"Malta korsanlarının Osmanlı hac gemisini vurup Girit'e sığınması bahanesiyle Venedik'e savaş açıldı ve Yûsuf Paşa kumandasındaki donanma adaya asker çıkardı. Elli dört günlük kuşatmanın ardından Hanya kalesi alınarak Girit'te ilk kalıcı Osmanlı üssü kuruldu. Böylece Osmanlı tarihinin en uzun süren savaşı başladı; ada ancak yirmi dört yıl sonra, 1669'da tamamen fethedilebilecekti.", kaynak:"girit", duygu:["🎉"] },
{ t:"1648-03-31", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Klis'in Venedik'e kaybı", gun:"31 Mart 1648 (Leonardo Foscolo); kaynaklarda 1645-1648 arası", ic_not_gun:"eski gun soneki: — TDV yalnız 1645-1648 aralığını veriyor", yer:"Klis, Dalmaçya", yer_id:"Klis", kisiler:"Sultan İbrahim, Leonardo Foscolo", d:"Girit (Kandiye) Savaşı'nın Dalmaçya cephesinde Venedik komutanı Leonardo Foscolo'nun karşı taarruzu, 1537'den beri sancak merkezi olan Klis'i de kapsadı; kale Venedik'e geçti. Osmanlı'nın bütün gücüyle Girit'e odaklanması, Dalmaçya sınırındaki bu kaybın geri alınmasını imkânsız kıldı — Klis bir daha Osmanlı idaresine dönmeyecekti; sancak merkezi Livno'ya taşındı.", kaynak:"ibrahim--padisah", duygu:["😔"] },
{ t:"1648-05-01", k:"savas", etiket:["savas","konu-askeri"], b:"Kandiye kuşatmasının başlaması", gun:"1648", yer:"Kandiye (Herakleion), Girit", kisiler:"Deli Hüseyin Paşa", d:"Hanya ve Resmo'nun alınmasından sonra Osmanlı ordusu, Venedik'in adadaki son büyük dayanağı Kandiye'yi kuşatma altına aldı. Yirmi bir yıl sürecek olan bu abluka, dünya askerî tarihinin en uzun kuşatmalarından biri olarak kayda geçti. Kuşatma boyunca Venedik donanmasının Çanakkale Boğazı'nı kapatma girişimleri savaşı Ege'nin göbeğine taşıyacaktı.", kaynak:"girit", duygu:["⚔️"], yer_id:"Kandiye (Girit)" },
{ t:"1651-09-02", k:"siyaset", etiket:["siyaset","darbe-siyasi","konu-siyasi","konu-kisiler","konu-darbe"], b:"Büyük Vâlide Kösem Sultan'ın öldürülmesi", gun:"2-3 Eylül 1651", yer:"Topkapı Sarayı Harem'i, İstanbul", yer_id:"İstanbul", kisiler:"Kösem Sultan, Turhan Sultan, Uzun Süleyman Ağa", d:"Yaklaşık altmış iki yaşındaki Kösem Sultan, IV. Mehmed'in annesi Turhan Sultan'ın emriyle hareket eden Başlala Uzun Süleyman Ağa ve adamlarınca Harem'de bir odada bulunarak öldürüldü. Üç padişah döneminde devlet siyasetini yönlendiren bu güçlü hanedan kadınının ölümü, 'Kadınlar Saltanatı' denen dönemin fiilen sonu sayılır. Boşalan otorite, beş yıl sonra Köprülü Mehmed Paşa'nın olağanüstü yetkilerle sadrazam olmasına giden yolu açtı.", kaynak:"kosem-sultan", duygu:["🏛"] },
{ t:"1656-07-13", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Çanakkale bozgunu ve Bozcaada ile Limni'nin kaybı", gun:"13 Temmuz 1656", yer:"Çanakkale Boğazı – Bozcaada, Limni", yer_id:"Çanakkale", kisiler:"Lazzaro Mocenigo, Abaza Ahmed Paşa", d:"Venedik amirali Mocenigo'nun Haziran 1656'da Çanakkale Boğazı önünde kazandığı büyük deniz zaferi Osmanlı donanmasını neredeyse tamamen imha etti; ardından Bozcaada, Limni ve Semadirek işgal edildi. Boğazın Venedik ablukasına girmesiyle İstanbul'da yiyecek fiyatları fırladı ve başkente saldırı korkusu yayıldı. Bu felaket, Eylül 1656'da Köprülü Mehmed Paşa'nın şartlı ve olağanüstü yetkilerle sadrazamlığa getirilmesinin doğrudan sebebi oldu.", kaynak:"bozcaada", duygu:["😔"] },
{ t:"1657-08-25", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Çanakkale zaferi ve Bozcaada'nın geri alınışı", gun:"25 Ağustos 1657", yer:"Bozcaada – Çanakkale Boğazı", yer_id:"Bozcaada", kisiler:"Köprülü Mehmed Paşa, Kurd Paşa", d:"Köprülü Mehmed Paşa'nın seferber ettiği donanma 19 Temmuz 1657'de Boğaz önünde Venedik filosunu bozguna uğrattı; ardından Kurd Paşa kumandasındaki kuvvetler 25 Ağustos'ta Bozcaada'yı geri aldı ve 30 Ağustos'ta Venedikliler adayı tamamen boşalttı. Kasım ayında Limni de kurtarılarak Çanakkale ablukası kırıldı ve İstanbul'un iaşe yolu yeniden açıldı. Köprülü bizzat adaya geçerek tahkimatları onarttı; bu başarı Köprülüler devrinin ilk büyük askerî kazancıdır.", kaynak:"bozcaada", duygu:["🎉"] },
{ t:"1658-08-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Yanova'nın (Ineu) fethi ve Erdel seferi", gun:"1658", yer:"Yanova (Ineu), Erdel", yer_id:"Yanova (Ineu)", kisiler:"Köprülü Mehmed Paşa, II. György Rákóczi", d:"İzinsiz Lehistan seferine çıkarak Osmanlı himayesini çiğneyen Erdel Prensi II. György Rákóczi'yi cezalandırmak için sefere çıkan Köprülü Mehmed Paşa, Belgrad üzerinden yürüyerek stratejik Yanova kalesini aldı. Erdel'e yeni bir prens tayin edilerek vasallik bağı sertçe hatırlatıldı. Bu sefer, Osmanlı'nın Orta Avrupa'da otoritesini yeniden kurma girişiminin ilk halkasıydı. Erdel zaten Osmanlı'ya tâbi bir prenslikti ve harita onu tâbi renkte gösteriyordu — Yanova'nın alınması yabancı bir devletten fetih değil, tâbi Erdel'in bu kalesini prenslik idaresinden çıkarıp doğrudan Osmanlı sancağına bağlamaktı; prensliğin geri kalanı tâbi statüsünde kaldı.", statu_dogrudan:["Yanova (Ineu)"], kaynak:"koprulu-mehmed-pasa", duygu:["🎉"] },
{ t:"1659-02-16", k:"isyan", etiket:["isyan","konu-isyan"], b:"Abaza Hasan Paşa isyanının bastırılması", gun:"Şubat 1659", yer:"Halep – Anadolu", yer_id:"Halep", kisiler:"Abaza Hasan Paşa, Köprülü Mehmed Paşa", d:"Köprülü Mehmed Paşa'nın sert tasfiyelerine karşı Anadolu beylerbeyleri ve sekban ağalarını arkasına alan Abaza Hasan Paşa, sadrazamın azlini talep ederek büyük bir ayaklanma başlattı. İsyan Halep'te bastırıldı ve elebaşları ortadan kaldırıldı; bu, taşra paşalarının merkeze karşı son toplu direnişi oldu. Köprülü'nün otoritesi böylece tartışmasız hâle geldi ve sadaret makamı yeniden devletin gerçek yürütme merkezi konumuna yükseldi.", kaynak:"koprulu-mehmed-pasa", duygu:["✊"] },
{ t:"1660-08-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Varad'ın (Oradea) fethi", gun:"27 Ağustos 1660", yer:"Varad (Oradea), Erdel", yer_id:"Varad (Oradea)", kisiler:"Köse Ali Paşa, II. György Rákóczi", d:"Osmanlı'ya savaş açan Erdel Prensi II. György Rákóczi'ye karşı düzenlenen sefer çerçevesinde Varad kalesi ve şehri alındı. Erdel'in kilit kalelerinden birinin düşmesiyle bölgede yeni bir Osmanlı eyaleti (Varad Eyaleti) kuruldu. Fetih Habsburgları alarma geçirdi ve üç yıl sonra başlayacak Osmanlı-Avusturya savaşının doğrudan sebeplerinden biri oldu. Aynı tarihte katılan öteki yerler: Varat. Burada da toprak yabancı bir devletten alınmadı: Erdel zaten tâbi bir Osmanlı prensliğiydi ve harita bunu tâbi renkte gösteriyordu — Varad'ın eyalet olması yalnızca bu kentin idaresini tâbi prenslikten alıp doğrudan padişaha bağladı, tıpkı iki yıl önce Yanova'da olduğu gibi.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", statu_dogrudan:["Varad (Oradea)"], kaynak:"varad", duygu:["🎉"] },
{ t:"1664-08-01", k:"savas", etiket:["savas","konu-askeri"], b:"Sen Gotar (St. Gotthard) Muharebesi", gun:"1 Ağustos 1664", yer:"Sen Gotar, Raab (Rába) nehri kıyısı", kisiler:"Köprülüzâde Fâzıl Ahmed Paşa, Raimondo Montecuccoli", d:"Raab nehrini geçen Osmanlı kuvvetleri, Montecuccoli kumandasındaki müttefik Avrupa ordusu tarafından durduruldu ve ağır kayıplar verdi. Muharebe, disiplinli ateşli piyade tüfek atışının Osmanlı süvari hücumu karşısındaki üstünlüğünü ilk kez açıkça ortaya koyması bakımından askerî tarihte dönüm noktası sayılır. Yenilgiye rağmen Osmanlı, dokuz gün sonra imzalanan Vasvar Antlaşması'nda avantajlı şartlar elde etmeyi başardı.", kaynak:"vasvar-antlasmasi", duygu:["⚔️"], yer_kon:[46.9558,16.2764] },
{ t:"1664-08-09", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Vasvar Antlaşması", gun:"9 Ağustos 1664", yer:"Vasvár, Macaristan", kisiler:"Köprülüzâde Fâzıl Ahmed Paşa, I. Leopold", d:"Sen Gotar bozgununa rağmen imzalanan antlaşma, Uyvar ve Varad'ın Osmanlı'da kalmasını, Erdel'in Osmanlı himayesinde tarafsız bırakılmasını ve Avusturya'nın 200.000 kuruş 'hediye' ödemesini hükme bağladı. Yirmi yıl süreli bu barış, savaşı kaybeden tarafın masada kazandığı nadir örneklerdendir. Antlaşmanın Habsburg kamuoyunda yarattığı hoşnutsuzluk, Orta Macar hareketini ve dolaylı olarak 1683 Viyana seferini besleyecekti.", kaynak:"vasvar-antlasmasi", duygu:["🤝"], yer_kon:[46.9333,16.8] },
{ t:"1672-06-04", k:"sefer", etiket:["savas","konu-askeri"], b:"Lehistan seferi başladı — IV. Mehmed ve Fâzıl Ahmed Paşa ordunun başında", gun:"7 Safer 1083 (4 Haziran 1672)", yer:"Lehistan seferi — Podolya yönü", odak_yer:["Edirne","Kamaniçe"], kisiler:"IV. Mehmed, Köprülüzâde Fâzıl Ahmed Paşa, Petro Doroşenko",
  d:"Osmanlı himayesine giren Ukrayna hatmanı Petro Doroşenko'ya karşı Lehistan'ın taarruzları sürünce İstanbul, Leh kralından saldırılardan vazgeçmesini istedi; olumlu cevap gelmeyince Lehistan'a sefer kararı alındı. Vezîriâzam Fâzıl Ahmed Paşa, padişahın da bulunduğu orduyla 4 Haziran 1672'de Lehistan'a hareket etti. Sefer Kamaniçe'nin fethi ve Bucaş Antlaşması'yla sonuçlanacaktı.",
  ic_not_t:"TDV kopruluzade-fazil-ahmed-pasa: 'Vezîriâzam Fâzıl Ahmed Paşa, bizzat padişahın da bulunduğu orduyla 7 Safer 1083'te (4 Haziran 1672) Lehistan'a hareket etti'. Hareket yeri TDV cümlesinde YAZMIYOR ⇒ yer_id YAZILMADI (olay yeri iddiası olurdu); yalnız odak_yer (kamera: sarayın bulunduğu Edirne ile hedef Kamaniçe arası — gösterim tercihi). SAVAS-ANLATI-0918'in 'başlangıç maddesi yok' dediği savaşlardan (1672-06-01) · KAPAT-0035-42-68 madde 6 · UYGULA-OLAYLAR-0930",
  kaynak:"kopruluzade-fazil-ahmed-pasa", duygu:["⚔️"] },
{ t:"1672-08-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri","konu-idari"], b:"Kamaniçe'nin fethi ve Podolya Eyaleti'nin kurulması", gun:"27 Ağustos 1672", yer:"Kamaniçe (Kamianets-Podilskyi), Podolya", yer_id:"Kamaniçe", kisiler:"IV. Mehmed, Köprülüzâde Fâzıl Ahmed Paşa", d:"Dokuz günlük kuşatmanın ardından Lehistan'ın doğudaki en güçlü kalesi sayılan Kamaniçe teslim alındı; IV. Mehmed 2 Eylül'de katedralden çevrilen camide ilk cuma namazını kıldı. Kale merkez yapılarak Podolya Eyaleti kuruldu ve Osmanlı bayrağı bugünkü Ukrayna topraklarında en kuzeye ulaştı. Kamaniçe, 1699 Karlofça Antlaşması'na kadar imparatorluğun kuzeybatı ucu olarak kalacaktı.", kaynak:"kamanice", duygu:["🎉"] },
{ t:"1674-01-01", kesinlik:"yil", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Kara Mustafa Paşa Uman'ı Lehistan'dan teslim aldı", gun:"Ağustos 1674 (Cemâziyelevvel 1085; gün bilinmiyor)", ic_not_gun:"§4: kaynak AY veriyor, t yıl hassasiyetinde yazıldı (YAMA-0052-UKRAYNA 10, UYGULA 16 Eylül 2026)", yer:"Uman, Sağ Yaka Ukrayna", yer_id:"Uman", kisiler:"Merzifonlu Kara Mustafa Paşa", d:"Lehistan'a karşı gönderilen Kara Mustafa Paşa, Lehistan'ın elindeki kalelerden Uman'ı teslim aldı; şehir Karlofça'ya kadar Osmanlı idaresinde kaldı.", kaynak:"merzifonlu-kara-mustafa-pasa", duygu:["🎉"] },
{ t:"1678-08-21", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Çehrin Kalesi'nin fethi", gun:"21 Ağustos 1678", ic_not_gun:"eski t:1678-07-19 — kuşatmanın başıydı (TDV merzifonlu 19 Temmuz, TDV cehrin-seferi 21 Temmuz); alınış iki maddede de 21 Ağustos 1678 (YAMA-0052-UKRAYNA 9)", yer:"Çehrin (Çigirin), Ukrayna", yer_id:"Çehrin (Çigirin)", kisiler:"Merzifonlu Kara Mustafa Paşa", d:"Bir önceki yıl Melek İbrahim Paşa'nın sonuç alamadığı harekâtın ardından Sadrazam Merzifonlu Kara Mustafa Paşa bizzat kumanda ederek müstahkem Çehrin Kalesi'ni kuşattı (19/21 Temmuz) ve 21 Ağustos'ta ele geçirdi. Ukrayna'daki Kazak hetmanlığı üzerinde Osmanlı-Rus rekabetinin sembolü olan kalenin düşmesi, Rusya'yı barışa zorladı. Bu başarı, Merzifonlu'nun Viyana'ya yönelecek özgüveninin de kaynaklarından biri oldu.", kaynak:"cehrin-seferi · merzifonlu-kara-mustafa-pasa", duygu:["🎉"] },
{ t:"1681-01-11", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Bahçesaray Antlaşması — Rusya ile ilk resmî barış", gun:"1681", yer:"Bahçesaray, Kırım", yer_id:"Bahçesaray", kisiler:"Merzifonlu Kara Mustafa Paşa, Kırım Hanı Murad Giray, Çar Fedor", d:"Çehrin seferlerinin ardından Kırım Hanı'nın aracılığıyla yürütülen görüşmeler sonunda, Özü (Dinyeper) nehri sınır kabul edilerek Osmanlı Devleti ile Rusya arasında yirmi yıllık bir barış imzalandı. Bu, iki devlet arasındaki ilk kapsamlı antlaşma olması bakımından Osmanlı-Rus ilişkilerinin başlangıç belgesi sayılır. Barış sayesinde doğu cephesi emniyete alınarak ordu Orta Avrupa'ya yönlendirilebildi.", kaynak:"merzifonlu-kara-mustafa-pasa", duygu:["🤝"] },
{ t:"1682-09-16", k:"siyaset", etiket:["ittifak","diplomasi","konu-siyasi","konu-diplomasi"], b:"Tököli İmre'ye Orta Macar krallığı beratının verilmesi", gun:"16 Eylül 1682", yer:"Budin – Orta Macaristan", yer_id:"Budin", kisiler:"Tököli İmre, Budin Beylerbeyi İbrahim Paşa, IV. Mehmed", d:"Habsburg baskısına karşı ayaklanan Protestan Macar asilzadesi Tököli İmre, Nisan 1682'den itibaren 'Orta Macaristan'ın seçilmiş kralı' sayılmaya başlandı ve 16 Eylül'de Budin Beylerbeyi İbrahim Paşa ona prenslik alâmetlerini sundu. Böylece Osmanlı himayesinde yeni bir vasal Macar devleti kuruldu. Bu müdahale, Avusturya ile savaşı kaçınılmaz kılarak ertesi yılki II. Viyana Kuşatması'na giden zinciri başlattı.", kaynak:"tokoli-imre", duygu:["🏛"] },
{ t:"1684-08-06", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Ayamavra'nın (Lefkada) Venedik'e kaybı", gun:"Yaz 1684", yer:"Ayamavra (Lefkada) Adası, İyon Denizi", yer_id:"Ayamavra (Lefkada)", kisiler:"Francesco Morosini", d:"Kutsal İttifak'a katılan Venedik'in donanması, şehri topa tuttuktan sonra İyon Denizi'ndeki Ayamavra Adası'nı işgal etti. Aynı yıl Preveze'nin de düşmesiyle Osmanlı'nın Adriyatik ağzındaki denetimi kırıldı. Bu kayıplar, Morosini'nin üç yıl içinde bütün Mora'yı ele geçireceği harekâtın başlangıç adımlarıydı.", kaynak:"ayamavra", duygu:["😔"] },
{ t:"1685-08-11", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Koron'un Venedik'e kaybı", gun:"Ağustos 1685", yer:"Koron (Koroni), Mora", yer_id:"Koron", kisiler:"Francesco Morosini", d:"Morosini kumandasındaki Venedik kuvvetleri Mora yarımadasının güneybatı ucundaki Koron kalesini ele geçirdi; şehir bundan sonra otuz yıl Venedik idaresinde kalacaktı. Koron'un düşmesi, Mora'nın fethine yönelik Venedik harekâtının ilk büyük kazancıydı. Kale ancak 1715'te Silâhdar Ali Paşa kumandasındaki Osmanlı ordusunca geri alınabildi.", kaynak:"koron", duygu:["😔"] },
{ t:"1688-10-20", k:"savas", etiket:["savas","konu-askeri"], b:"Venedik'in Eğriboz kuşatmasının püskürtülmesi", gun:"Ekim 1688", yer:"Eğriboz (Negroponte/Chalkis) Adası", yer_id:"Eğriboz", kisiler:"Francesco Morosini", d:"Mora'yı ele geçirdikten sonra Ege'ye yönelen Morosini, üç aydan uzun süren bir kuşatmayla Eğriboz'u almaya çalıştı; ancak 1687-1688 kışında güçlendirilen tahkimat ve garnizonun direnişi karşısında ağır kayıplar vererek çekilmek zorunda kaldı. Bu başarısızlık Venedik'in Ege'deki ilerleyişini durdurdu ve Morosini'nin askerî itibarını sarstı. Eğriboz, Karlofça'da da Osmanlı elinde kalacaktı.", kaynak:"egriboz", duygu:["⚔️"] },
{ t:"1690-04-13", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Kanije Kalesi'nin Avusturya'ya kaybı", gun:"1690", yer:"Kanije (Nagykanizsa), Macaristan", yer_id:"Kanije", kisiler:"Mustafa Paşa", d:"1690 Ocak ayından itibaren 60.000 kişilik Habsburg ordusunun sıkı ablukasına alınan Kanije, aylarca yardım alamadan direndikten sonra son muhafızı Mustafa Paşa'nın imzaladığı teslim anlaşmasıyla elden çıktı. Böylece Tiryaki Hasan Paşa'nın destansı savunmasıyla anılan kalede doksan yıllık Osmanlı hâkimiyeti sona erdi. Kanije'nin kaybı, Osmanlı'nın Macaristan'ın batısındaki son büyük dayanağının çöküşüydü.", kaynak:"kanije", duygu:["😔"] },
{ t:"1691-06-23", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-hanedan"], b:"II. Ahmed'in tahta çıkışı", gun:"23 Haziran 1691", yer:"Edirne", yer_id:"Edirne", kisiler:"II. Süleyman, II. Ahmed, Köprülüzâde Fâzıl Mustafa Paşa", d:"II. Süleyman'ın ölümü üzerine kırk dokuz yaşındaki kardeşi II. Ahmed Edirne'de tahta çıktı. Saltanatı, Kutsal İttifak savaşlarının en ağır yıllarına denk geldi; cülûsundan iki ay sonra Salankamen'de Sadrazam Fâzıl Mustafa Paşa şehid düştü. Buna karşılık döneminde uygulamaya konan mâlikâne sistemi, Osmanlı maliyesinin uzun vadeli yapısını değiştiren en önemli düzenlemelerden biri oldu.", kaynak:"ahmed-ii", duygu:["🏛"] },

// ---------- C) GERİLEME VE ISLAHAT ÇAĞI (1699-1839) ----------
{ t:"1700-07-14", k:"antlasma", etiket:["antlasma","toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"İstanbul Antlaşması — Azak'ın Rusya'ya bırakılması", gun:"14 Temmuz 1700", ic_not_gun:"A2 §4b: TDV karlofca '27 Muharrem 1112 (14 Temmuz 1700)' · TDV rusya '13 Temmuz 1700' — §4⑥ iç ayrışma; hicrî karşılığı yazılı olan karlofca günü korundu. Kırım vergisi hükmü karlofca'da var", yer:"İstanbul", yer_id:"Azak", kisiler:"II. Mustafa, Rami Mehmed Efendi, I. Petro", d:"Karlofça'da Rusya ile yalnızca iki yıllık mütareke yapılabilmişti; kalıcı barış İstanbul'da bir buçuk yıl süren çetin pazarlıklardan sonra imzalandı. Osmanlı Devleti 1696'da kaybettiği Azak Kalesi'ni ve çevresindeki toprakları resmen Rusya'ya terk etti, Kırım hanının Moskova'dan aldığı yıllık vergiden vazgeçti. Buna karşılık Rusya İstanbul'da daimî elçi bulundurma hakkını elde etti; böylece Karadeniz'in kuzey kıyısında Rus varlığı hukuken tescillenmiş oldu.", ic_not_d:"eski kaynak: osmanlilar", kaynak:"karlofca · rusya · mustafa-ii", duygu:["🤝"] },
{ t:"1704-01-01", k:"siyaset", etiket:["siyaset","diger","konu-siyasi"], b:"Bağdat'ta Kölemen (Memlûk) idaresinin başlaması", gun:"1704", yer:"Bağdat", yer_id:"Bağdat", kisiler:"Hasan Paşa, III. Ahmed", d:"Gürcü asıllı Hasan Paşa'nın Bağdat valiliğine getirilmesiyle Irak'ta merkezden atanan valiler yerine kendi kölelerinden yetişen bir yönetici zümresinin hâkim olduğu dönem başladı. Süleyman Paşa'nın 1749'daki valiliğiyle sistem iyice yerleşti ve Bâbıâli artık istediği kişiyi değil, nüfuzu eline geçirmiş kölemenlerden birini tayin etmek zorunda kaldı. Bu yarı özerk yapı, İran sınırının savunulmasında işe yaradıysa da merkezî otoritenin Irak üzerindeki denetimini bir buçuk asır boyunca zayıflattı.", kaynak:"bagdat", duygu:["🏛"] },
{ t:"1705-07-17", k:"siyaset", etiket:["siyaset","diger","konu-siyasi","konu-hanedan"], b:"Tunus'ta Hüseynî hanedanının kurulması", gun:"17 Temmuz 1705", yer:"Tunus", yer_id:"Tunus", kisiler:"Hüseyin b. Ali Türkî, III. Ahmed", d:"Cezayir kuvvetlerinin Tunus'u istilâsı üzerine ortaya çıkan otorite boşluğunda, Türk asıllı sipahi ağası Hüseyin b. Ali beyliği ele geçirdi ve Osmanlı padişahına bağlılığını bildirerek meşruiyet kazandı. Kurduğu hanedan 1705-1735 ve 1756-1957 yılları arasında Tunus'u yönetti; ocak yönetiminin yerini babadan oğula geçen bir beylik düzeni aldı. Böylece Garp ocaklarında merkeze bağlı ama fiilen özerk hanedan yapılarının ilk örneği doğmuş oldu.", statu_vasal:["Tunus","Kayrevan","Gabes","Sfaks","Cerbe (Djerba)","Kerkene (Kerkennah)"], kaynak:"huseyniler", duygu:["🏛"] },
{ t:"1708-04-04", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Vahran (Oran) ve Mersalkebîr'in İspanyollardan alınışı", gun:"4 Nisan 1708", yer:"Vahran (Oran), Cezayir", kisiler:"Mustafa Bûşelâgim, III. Ahmed", d:"Cezayir Ocağı beylerbeyi kuvvetleri, iki asırdır İspanyol garnizonunun elinde bulunan Vahran'ı ve limanı Mersalkebîr'i uzun bir kuşatmanın ardından ele geçirdi. Batı Akdeniz'de Osmanlı himayesindeki Garp ocaklarının İspanya'ya karşı kazandığı en büyük başarıydı ve Cezayir'in batı kanadını güvence altına aldı. Şehir 1732'de yeniden İspanyol işgaline uğrayacak, ancak 1792'de kesin olarak geri alınacaktı.", kaynak:"osmanlilar", duygu:["🎉"], yer_id:"Oran" },
{ t:"1711-07-29", k:"siyaset", etiket:["siyaset","diger","konu-siyasi","konu-hanedan"], b:"Trablusgarp'ta Karamanlı hanedanının kurulması", gun:"29 Temmuz 1711", yer:"Trablusgarp", kisiler:"Ahmed Karamanlı, III. Ahmed", d:"Ocak ağalarının çekişmesinden bunalan Trablusgarp'ta süvari zâbiti Ahmed Karamanlı yönetimi ele geçirdi ve İstanbul'dan aldığı beylerbeyilik beratıyla durumunu resmîleştirdi. Ahmed Paşa, oğlu Mehmed Paşa ve torunu Yûsuf Paşa eliyle 1711-1835 arasında süren bir hanedan doğdu; kendi donanmasını kuran, Avrupa devletleriyle doğrudan antlaşma imzalayan yarı bağımsız bir yapı ortaya çıktı. Bu dönem ancak 1835'te eyaletin doğrudan merkeze bağlanmasıyla sona erecekti.", statu_vasal:["Trablus","Misrata","Bingazi","Derne","Murzuk (Fizan)"], kaynak:"trablusgarp", duygu:["🏛"], yer_id:"Trablus" },
{ t:"1711-07-21", k:"antlasma", etiket:["antlasma","toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Prut Antlaşması — Azak ve Taygan'ın geri alınması", gun:"21 Temmuz 1711", yer:"Prut boyu, Yaş yakınları", kisiler:"Baltacı Mehmed Paşa, I. Petro, Devlet Giray", d:"Prut boyunda kuşatılan Rus ordusunun teslim olmasıyla imzalanan yedi maddelik antlaşma, Azak Kalesi'nin arazisi ve mühimmatıyla birlikte Osmanlı'ya iadesini hükme bağladı. Taygan, Kamenka ve Yenikale istihkâmları yıkılacak, taraflar bu bölgelerde yeni kale inşa etmeyecekti. I. Petro'nun Voronej ve Azak'ta on altı yıl boyunca kurduğu donanma ve üs düzeni çöktü; Rusya'nın Karadeniz'e inişi yaklaşık elli yıl gecikti.", kaynak:"prut-antlasmasi", duygu:["🤝"], yer_kon:[46.75,28.05] },
{ t:"1713-06-24", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Rusya ile Edirne Antlaşması", gun:"24 Haziran 1713", yer:"Edirne", yer_id:"Edirne", kisiler:"III. Ahmed, Silâhdar Ali Paşa, I. Petro", d:"Prut'ta verilen sözlerin yerine getirilmemesi üzerine iki kez daha savaş ilân edilmiş, nihayet Ruslar'ın taahhütleri kabul etmesiyle Edirne'de kalıcı barış imzalandı. Antlaşma Prut şartlarını teyit etti; Rusya Lehistan işlerine karışmayacak, Kazak topraklarından çekilecek ve İsveç kralı Demirbaş Şarl'ın ülkesine dönüşüne engel olmayacaktı. Kuzey cephesinin böylece kapanması, Osmanlı Devleti'nin yüzünü Mora ve Venedik cephesine çevirmesini mümkün kıldı. Aynı tarihte katılan öteki yerler: Hotin.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"ahmed-iii", duygu:["🤝"] },
{ t:"1714-12-08", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"Venedik'e savaş ilanı — Mora seferinin hazırlığı", gun:"8 Aralık 1714", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Ahmed, Silâhdar Damad Ali Paşa", d:"Venedik'in Karadağ isyancılarını desteklemesi, Osmanlı ticaret gemilerine el koyması ve Karlofça'da aldığı Mora'yı ağır vergilerle ezmesi gerekçe gösterilerek Divan'da savaş kararı alındı. Sadrazam Silâhdar Damad Ali Paşa'nın hazırladığı sefer, ertesi yıl yüz günden kısa sürede bütün Mora yarımadasının geri alınmasıyla sonuçlanacaktı. Ne var ki bu başarı Avusturya'yı harekete geçirecek ve 1716'da çok daha ağır bir savaşın kapısını aralayacaktı.", kaynak:"ahmed-iii", duygu:["⚔️"] },
{ t:"1716-08-05", k:"savas", etiket:["savas","konu-askeri"], b:"Varadin (Petrovaradin) Bozgunu — Damad Ali Paşa'nın şehâdeti", gun:"5 Ağustos 1716", yer:"Varadin (Petrovaradin), Sirem", kisiler:"Silâhdar Damad Ali Paşa, Prens Eugène de Savoie", d:"Belgrad üzerinden Tuna'yı geçen Osmanlı ordusu, Prens Eugène kumandasındaki Avusturya kuvvetleriyle Varadin önlerinde karşılaştı; ilk hamlede yeniçeri hücumu düşman siperlerini zorladıysa da süvari kanadının çökmesiyle saflar dağıldı. Sadrazam Silâhdar Damad Ali Paşa alnından vurularak şehid düştü, ordugâh ve topçu takımı bütünüyle düşman eline geçti. Osmanlı vekāyi'nâmelerinin 'Varadin senesi' diye andığı bu bozgun, Temeşvar'ın ve ertesi yıl Belgrad'ın kaybına giden zincirin ilk halkasıydı.", kaynak:"varadin", duygu:["⚔️","😔"], yer_id:"Varadin (Petrovaradin)" },
{ t:"1716-08-20", k:"savas", etiket:["savas","konu-askeri"], b:"Korfu Kuşatması'nın başarısızlıkla sonuçlanması", gun:"Yaz 1716", yer:"Korfu adası, İyon denizi", kisiler:"Kara Mustafa Paşa, Canım Hoca Mehmed Paşa, Johann Matthias von der Schulenburg", d:"Mora seraskeri Kara Mustafa Paşa karadan, Kaptanıderyâ Canım Hoca Mehmed Paşa donanmayla denizden Korfu'ya yüklendi; ada Venedik'in Adriyatik'teki kilit üssüydü. Ancak kalenin son derece güçlü tahkimatı, Venedik donanmasının getirdiği takviyeler ve Tuna cephesinden gelen bozgun haberleri kuşatmanın kaldırılmasına yol açtı. Korfu'nun alınamaması, Mora'nın yeniden fethiyle yükselen havayı söndürdü ve savaşın ağırlık merkezini Macaristan'a kaydırdı.", kaynak:"korfu", duygu:["⚔️"], yer_id:"Korfu" },
{ t:"1716-10-13", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Temeşvar'ın (Timişvar) Avusturya'ya kaybı", gun:"Ekim 1716", yer:"Temeşvar, Banat", kisiler:"Mustafa Paşa, Prens Eugène de Savoie", d:"Varadin bozgununun ardından Prens Eugène doğrudan Temeşvar üzerine yürüdü ve kale, kırk günü aşan bir kuşatmanın sonunda vire ile teslim edildi. 1552'de Kanûnî devrinde fethedilen ve 164 yıl boyunca bir beylerbeyilik merkezi olarak Macaristan savunmasının doğu direği sayılan şehir böylece elden çıktı. Temeşvar'ın düşüşüyle Banat bölgesinin tamamı Avusturya'ya geçti ve Osmanlı sınırı Tuna'nın güneyine itildi.", kaynak:"timisvar", duygu:["😔"], yer_id:"Temeşvar" },
{ t:"1723-06-15", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Doğu seferi: Tiflis'in alınışı ve İran savaşının başlaması", gun:"Haziran 1723", yer:"Tiflis, Gürcistan", kisiler:"III. Ahmed, Nevşehirli Damad İbrâhim Paşa, Çerkes Osman Paşa", d:"Safevî Devleti'nin Afgan istilâsıyla çökmesi ve Rusya'nın Hazar kıyılarına inmesi üzerine Osmanlı Devleti, boşluğun tamamen Rus nüfuzuna kalmaması için doğuya ordu sevketti. Tiflis ele geçirilerek Gürcistan Osmanlı idaresine bağlandı; ardından Gence, Revan ve Nahcıvan yönünde ilerleme sürdü. Lâle Devri'nin barışçı görüntüsünün ardında yürütülen bu sefer, on üç yıl sürecek ve sonunda kazanılan her yerin geri verilmesiyle bitecek uzun bir doğu macerasının başlangıcı oldu.", kaynak:"ahmed-iii", duygu:["🎉"], yer_id:"Tiflis" },
{ t:"1724-06-24", k:"antlasma", etiket:["antlasma","diplomasi","konu-askeri","konu-diplomasi"], ic_not_etiket:"toprak-kazanc KALDIRILDI (GEMINI-DOGRULA 0919): antlaşma günü hiçbir yer el değiştirmez — Derbend/Bakü 1722-23'ten beri Rus, Osmanlı kazanımları fetih günlerinde (Hemedan 1724-08-31, Tebriz 1725) kendi maddeleriyle.", b:"İstanbul Mukāsemenâmesi — İran'ın Rusya ile paylaşılması", gun:"24 Haziran 1724", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Ahmed, Nevşehirli Damad İbrâhim Paşa, I. Petro", d:"Çöken Safevî ülkesi üzerinde Osmanlı ile Rusya'nın karşı karşıya gelmesini önlemek için Fransız elçisinin arabuluculuğuyla bir taksim antlaşması imzalandı. Hazar denizinin batı ve güney kıyıları Rusya'ya, Gürcistan, Şirvan, Azerbaycan ve Batı İran şehirleri Osmanlı Devleti'ne bırakıldı. Kâğıt üzerinde büyük bir kazanç gibi görünen bu paylaşım, kısa süre sonra Nâdir Şah'ın yükselişiyle fiilen geçersiz kalacaktı.", kaynak:"ahmed-iii", duygu:["🤝"] },
{ t:"1725-07-28", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Tebriz'in zaptı — Azerbaycan'ın ele geçirilmesi", gun:"28 Temmuz 1725 (17 Zilkade 1137 — TDV tebriz)", yer:"Tebriz, Azerbaycan", kisiler:"Silâhdar İbrâhim Paşa, Köprülüzâde Abdullah Paşa", d:"Bir yıl önceki başarısız denemenin ardından yeniden kuşatılan Tebriz, sokak sokak süren çetin bir muharebeden sonra Osmanlı ordusuna teslim oldu. Tebriz eyaletine bağlı Merend, Merâga ve Sovukbulak (Mahabad) da Osmanlı idaresine girdi. Aynı yıl Lori, Gence, Erdebil ve Hürremâbâd da alınarak İstanbul Mukāsemenâmesi'yle Osmanlı payına düşen bölgeler fiilen işgal edildi. Doğuda ulaşılan bu genişlik, Ferhad Paşa Antlaşması devrinden sonraki en ileri sınırdı; ancak elde tutulması ordu ve hazineye ağır bir yük bindirdi.", kaynak:"ahmed-iii · tebriz", duygu:["🎉"], yer_id:"Tebriz" },
{ t:"1727-10-04", k:"antlasma", etiket:["antlasma","diplomasi","konu-askeri","konu-diplomasi"], ic_not_etiket:"toprak-kazanc KALDIRILDI (GEMINI-DOGRULA 0919): antlaşma fiilî fethi hukuken teyit ediyor; toprak 1724-1725 fetih günlerinde el değiştirdi.", b:"Hemedan Antlaşması — Batı İran'ın Osmanlı'ya katılması", gun:"4 Ekim 1727", yer:"Hemedan", yer_id:"Hemedan", kisiler:"III. Ahmed, Nevşehirli Damad İbrâhim Paşa, Eşref Şah", d:"Afgan hükümdarı Eşref Şah ile imzalanan antlaşmayla dört yıl süren savaş sona erdi ve Osmanlı Devleti'nin işgal ettiği Batı İran toprakları hukuken tanındı. Eşref Şah karşılığında Osmanlı padişahının halifeliğini kabul etti ve İran'da hutbenin padişah adına okunmasını üstlendi. Bu diplomatik zafer kısa ömürlü oldu; Nâdir Şah'ın 1730'da başlattığı karşı taarruz antlaşmanın kazanımlarını birkaç yıl içinde silip süpürecekti.", kaynak:"ahmed-iii", duygu:["🤝"] },
{ t:"1732-01-08", k:"antlasma", etiket:["antlasma","toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"Ahmed Paşa Antlaşması — Batı İran'ın büyük bölümünün iadesi", gun:"8 Ocak 1732 (10 Receb 1144)", ic_not_t:"önceki kayıt 1732-01-10 (kaynaksız); TDV hemedan: '10 Receb 1144'te (8 Ocak 1732) yapılan barış antlaşması ile Hemedan tekrar İran'a bırakıldı' — koordinatör hükmü (KAPAT-0035-42-68-0930) · UYGULA-OLAYLAR-0930", yer:"Bağdat / Kirmanşah", kisiler:"I. Mahmud, Bağdat valisi Ahmed Paşa, Nâdir Şah", d:"Nâdir Şah'ın Melâyir'de kazandığı zafer ve arka arkaya gelen İran taarruzları üzerine Bağdat valisi Ahmed Paşa merkeze danışmadan bir barış metni imzaladı. Antlaşmaya göre Aras nehri sınır kabul edildi; Hemedan, Kirmanşah, Erdelan, Erdebil ve Tebriz gibi Batı İran şehirleri İran'a geri verildi, Gence ve Tiflis Osmanlı'da kaldı. İstanbul'da tepkiyle karşılanan bu metin Nâdir Şah tarafından da yetersiz bulundu ve daha 1732 yılı dolmadan savaş yeniden alevlendi.", kaynak:"osmanlilar", duygu:["🤝"], yer_id:"Bağdat" },
{ t:"1732-07-01", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Vahran'ın (Oran) yeniden İspanya'ya kaybı", gun:"1732", yer:"Vahran (Oran), Cezayir", kisiler:"Kont Montemar, I. Mahmud", d:"İspanya kralı V. Felipe'nin gönderdiği büyük çıkarma filosu, Kont Montemar kumandasında Vahran önlerine geldi ve Cezayir Ocağı kuvvetlerini bozguna uğratarak şehri geri aldı. Yirmi dört yıl önce fethedilen liman, altmış yıl boyunca yeniden İspanyol garnizonunun elinde kalacaktı. Batı Akdeniz'de Garp ocaklarının gücünün sınırlarını gösteren bu kayıp, ancak 1792'de Vahran'ın kesin fethiyle telâfi edilebildi.", kaynak:"osmanlilar", duygu:["😔"], yer_id:"Oran" },
{ t:"1733-05-01", k:"bilim", etiket:["bilim","siyaset","konu-siyasi","konu-bilim"], b:"Humbaracı Ocağı'nın Avrupa usulünde ıslahı ve Humbarahâne'nin kurulması", gun:"1733", yer:"Üsküdar, İstanbul", kisiler:"Humbaracı Ahmed Paşa (Comte de Bonneval), Hekimoğlu Ali Paşa, I. Mahmud", d:"Osmanlı hizmetine giren Fransız asıllı Humbaracı Ahmed Paşa, sadrazam Hekimoğlu Ali Paşa'nın desteğiyle humbaracı ocağını maaşlı ve Avrupa tarzında düzenlenmiş bir birlik hâline getirdi. Bosna'dan devşirilen üç yüz askere hesap ve hendeseye dayalı düzenli eğitim verildi; teşkilât, teçhizat ve emeklilik için yeni nizamnâmeler hazırlandı, çağdaş teknikle yüz humbara topu ve elli bin humbara imal edildi. Geometri okutulan Humbarahâne, Osmanlı'da modern askerî mühendislik eğitiminin ilk çekirdeği sayılır.", kaynak:"humbaraci", duygu:["🔬"], yer_id:"Üsküdar" },
{ t:"1736-09-01", k:"antlasma", etiket:["antlasma","toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"İstanbul Antlaşması — Güney Kafkasya'nın İran'a terki", gun:"1736", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Mahmud, Nâdir Şah", d:"Dört yıl süren ikinci İran savaşı, Arpaçay bozgunu ile Gence ve Tiflis'in kaybının ardından imzalanan antlaşmayla sona erdi. Osmanlı Devleti 1723'ten beri ele geçirdiği bütün Güney Kafkasya ve Batı İran topraklarından çekildi, sınır 1639 Kasr-ı Şîrin çizgisine döndü. On üç yıllık doğu seferlerinden geriye ağır bir malî yük ve boşalmış bir hazine kaldı; buna karşılık Rusya ile başlayan yeni savaş için doğu cephesinin kapanması hayatî bir kazançtı.", kaynak:"osmanlilar", duygu:["🤝"] },
{ t:"1737-07-11", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Özi (Ochakov) Kalesi'nin Ruslara düşüşü", gun:"11 Temmuz 1737 (TDV özü; ESBE «Брянская флотилия» 2 Temmuz eski takvim = 13 Temmuz — ayrışma)", yer:"Özi, Karadeniz kuzeyi", kisiler:"Yahyâ Paşa, Mareşal Münnich, I. Mahmud", d:"Mareşal Münnich kumandasındaki Rus ordusu, Dinyeper ağzındaki Özi Kalesi'ni kuşattı; cephaneliğin infilâk etmesiyle savunma çöktü ve kale büyük can kaybıyla düştü. Karadeniz'in kuzeybatı kıyısının kilidi sayılan Özi'nin elden çıkması, Kırım'a giden yolu Ruslara açtı ve İstanbul'da büyük panik yarattı. Kale ertesi yıl salgın ve ikmal güçlüğü yüzünden Ruslar tarafından boşaltılarak yeniden Osmanlı'ya geçecekti.", kaynak:"ozu", duygu:["😔"], yer_id:"Özi" },
{ t:"1737-08-04", k:"savas", etiket:["savas","konu-askeri"], b:"Banaluka Zaferi — Bosna'nın kurtarılması", gun:"4 Ağustos 1737", yer:"Banaluka, Bosna", kisiler:"Hekimoğlu Ali Paşa", d:"Avusturya kuvvetleri Bosna'ya girip Banaluka'yı kuşatınca, Bosna valisi Hekimoğlu Ali Paşa yerli halktan topladığı kuvvetlerle imdada yetişti ve sayıca üstün düşmanı ağır bir yenilgiye uğrattı. Bu zafer Avusturya'nın Bosna'yı işgal planını daha ilk hamlede çökertti ve eyaletin kuzeyi tamamen geri alındı. Banaluka, 1683 sonrası Avusturya karşısında sürekli geri çekilen Osmanlı ordusunun moralini düzelten dönüm noktalarından biri oldu.", kaynak:"banaluka", duygu:["⚔️"], yer_id:"Banaluka" },
{ t:"1738-08-01", k:"fetih", etiket:["savas","toprak-kazanc","konu-askeri"], b:"Özi'nin geri alınışı ve Kırım'ın Rus istilâsından kurtarılması", gun:"1738", yer:"Özi ve Kırım yarımadası", kisiler:"Yeğen Mehmed Paşa, Mengli Giray II", d:"Salgın hastalık ve ikmal sıkıntısıyla boğuşan Rus ordusu Özi'yi tahliye etmek zorunda kalınca kale yeniden Osmanlı denetimine girdi; aynı yıl Kırım yarımadasına giren Rus kolları da geri püskürtüldü. Bender ve Turla boylarında kazanılan başarılar Tuna cephesinde dengeyi Osmanlı lehine çevirdi. Bu toparlanma, ertesi yıl Belgrad'ın geri alınmasına giden zaferler dizisinin zeminini hazırladı.", kaynak:"kirim", duygu:["🎉","😔"], yer_id:"Özi" },
{ t:"1739-07-22", k:"savas", etiket:["savas","konu-askeri"], b:"Hisarcık (Grocka) Zaferi — Belgrad yolunun açılması", gun:"22 Temmuz 1739", yer:"Hisarcık (Grocka), Belgrad yakınları", kisiler:"İvaz Mehmed Paşa, Hacı Mehmed Paşa, Mareşal Wallis", d:"Belgrad'ı korumak üzere ilerleyen Avusturya ordusu, Tuna kıyısındaki dar boğazda pusuya düşürülerek gün boyu süren muharebede ağır kayıplar verdi. Mareşal Wallis'in kuvvetleri düzensiz biçimde Belgrad'a çekilirken Osmanlı ordusu kalenin önüne dayandı ve kuşatmayı başlattı. Hisarcık, Karlofça'dan beri Avusturya karşısında kazanılan en kesin meydan zaferiydi ve doğrudan Belgrad'ın geri alınmasını sağladı.", kaynak:"belgrad", duygu:["⚔️"], yer_kon:[44.6717,20.7264] },
{ t:"1739-10-03", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Niş Antlaşması — Rusya ile barış, Azak'ın tarafsızlaştırılması ve Kırım akınlarının durdurulması", gun:"3 Ekim 1739", yer:"Niş", yer_id:"Azak", kisiler:"I. Mahmud, Marquis de Villeneuve, Çariçe Anna", d:"Avusturya'nın Belgrad'da barışa razı olmasıyla yalnız kalan Rusya, Fransız elçisi Villeneuve'ün arabuluculuğunda savaşı bitirmek zorunda kaldı. Azak Kalesi'nin istihkâmları yıkılarak bölge iki devlet arasında tarafsız arazi ilân edildi; Rusya Karadeniz'de savaş ve ticaret gemisi bulundurmama şartını kabul etti. Böylece Rusya'nın denize açılma hedefi bir kuşak daha ertelendi ve Osmanlı Devleti XVIII. yüzyılda son defa masadan kazançlı kalktı.", kaynak:"osmanlilar", duygu:["🤝"] },
{ t:"1743-10-23", k:"savas", etiket:["savas","konu-askeri"], b:"Musul Savunması — Nâdir Şah'ın püskürtülmesi", gun:"13 Eylül – 23 Ekim 1743", yer:"Musul", yer_id:"Musul", kisiler:"Hüseyin Paşa el-Celîlî, Nâdir Şah, I. Mahmud", d:"Kerkük ve Erbil'i alarak Musul önüne gelen Nâdir Şah, kırk gün boyunca şehri topa tuttu ve arka arkaya genel hücumlar düzenledi. Vali Hüseyin Paşa el-Celîlî'nin şehir halkını da silâhlandırarak yürüttüğü savunma, İran ordusunu ağır kayıplarla kuşatmayı kaldırmaya mecbur etti. Musul'un tutunması Irak'ın tamamının elden çıkmasını önledi ve Celîlî ailesinin şehirdeki nüfuzunu bir asır boyunca pekiştirdi.", kaynak:"osmanlilar", duygu:["⚔️"] },
{ t:"1744-01-01", k:"siyaset", etiket:["siyaset","diger","konu-siyasi"], b:"Dir'iye İttifakı — Necid'de ilk Suûdî Emirliği'nin kuruluşu", gun:"1744", yer:"Dir'iye, Necid", kisiler:"Muhammed b. Suûd, Muhammed b. Abdülvehhâb", d:"Uyeyne'den sürülen âlim Muhammed b. Abdülvehhâb'ı Dir'iye'de himayesine alan emîr Muhammed b. Suûd, onunla siyasî otoriteyi dinî davetin hizmetine sunan bir ittifak kurdu. Bu anlaşma Suûd ailesi için yeni bir tarih başlattı ve Necid'in dağınık vaha emirliklerini tek bir hareket etrafında birleştirdi. Yarım yüzyıl içinde Kerbelâ, Mekke ve Medine'ye uzanacak olan bu güç, Osmanlı Devleti'ni Hicaz'daki hâkimiyetini savunmak zorunda bırakacaktı.", kaynak:"suudiler", duygu:["🏛"], yer_id:"Dir'iye (Necid)" },
{ t:"1746-09-04", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Kerden Antlaşması — Osmanlı-İran savaşlarının sonu", gun:"4 Eylül 1746", yer:"Kerden, Kazvin yakınları", kisiler:"I. Mahmud, Nâdir Şah, Nazif Mustafa Efendi", d:"Dört yıl süren son savaşın ardından imzalanan antlaşmayla 1639 Kasr-ı Şîrin sınırı aynen yenilendi; iki taraf da toprak kazancı elde edemedi. Nâdir Şah'ın Ca'ferîliğin beşinci mezhep olarak tanınması yönündeki ısrarlı talebi karşılıksız kaldı, buna karşılık İran hacılarının serbestçe hac yapmasına ve karşılıklı elçi teatisine karar verildi. İki asrı aşan Osmanlı-İran savaşları böylece fiilen kapandı; bu sınır bugüne kadar büyük ölçüde korunmuştur.", kaynak:"osmanlilar", duygu:["🤝"], yer_kon:[36.2797,50.0049] },
{ t:"1754-12-13", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"I. Mahmud'un ölümü ve III. Osman'ın cülûsu", gun:"13 Aralık 1754", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Mahmud, III. Osman", d:"Yirmi dört yıllık saltanatında Belgrad Antlaşması'yla kaybedilen toprakları geri alan ve Humbaracı Ocağı ıslahatını destekleyen I. Mahmud, cuma selâmlığından dönerken vefat etti. Yerine, elli sekiz yaşına kadar kafes hayatı yaşamış olan kardeşi III. Osman geçti. Kısa ve tedirgin bir saltanat başladı; üç yıl içinde altı sadrazam değiştiren III. Osman döneminde devlet işlerinde belirgin bir durgunluk hâkim oldu.", kaynak:"osman-iii", vefat_id:"mahmud1", duygu:["🏛"] },
{ t:"1757-10-30", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"III. Osman'ın ölümü ve III. Mustafa'nın cülûsu", gun:"30 Ekim 1757", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Osman, III. Mustafa, Koca Râgıb Paşa", d:"Üç yıllık saltanatın ardından III. Osman'ın vefatıyla tahta, ıslahat fikirlerine açık ve devlet işlerine yakın ilgi gösteren III. Mustafa çıktı. Yeni padişah, sadrazam Koca Râgıb Paşa'nın tecrübesine dayanarak maliyeyi düzeltmeye ve orduyu yenilemeye çalıştı; Baron de Tott'un sürat topçuları bu dönemde kuruldu. Ancak 1768'de girilen Rus savaşı, on yedi yıllık saltanatın bütün kazanımlarını gölgede bırakacaktı.", kaynak:"mustafa-iii", vefat_id:"osman3", duygu:["🏛"] },
{ t:"1768-10-08", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"Rusya'ya savaş ilanı — Balta olayı ve 1768-1774 savaşının başlaması", gun:"Ekim 1768", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Mustafa, Silâhdar Hamza Paşa, II. Katerina", d:"Lehistan'daki Bar Konfederasyonu'nu kovalayan Rus ve Kazak birliklerinin Osmanlı sınırındaki Balta kasabasını basıp yakması üzerine Divan savaş kararı aldı, Rus elçisi Yedikule'ye hapsedildi. Ciddi bir askerî hazırlık yapılmadan ve altı ay önceden ilân edilerek girilen savaş, daha başından kötü gitti. Altı yıl sürecek bu mücadele Çeşme baskını, Kartal bozgunu ve Kırım'ın işgaliyle Osmanlı tarihinin en ağır yenilgi silsilelerinden birine dönüşecekti.", kaynak:"mustafa-iii", duygu:["⚔️"] },
{ t:"1769-09-19", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Hotin Kalesi'nin Ruslara kaybı", gun:"Eylül 1769", yer:"Hotin, Besarabya", kisiler:"Moldovancı Ali Paşa, Prens Golitsın", d:"Prens Golitsın kumandasındaki Rus ordusunun iki denemesi püskürtülmüşken, Kamaniçe ile Hotin arasında sadrazamın uğradığı bozgun üzerine ordu geri çekildi ve muhafızlar kaleyi boşalttı. Tuna'nın kuzeyindeki en güçlü Osmanlı istihkâmının direnişsiz elden çıkması, Eflak ve Boğdan'ın kapılarını Ruslara açtı. İki prenslik aynı yıl işgal edildi; Hotin ancak 1774'te Küçük Kaynarca Antlaşması'yla geri alınabildi.", kaynak:"hotin", duygu:["😔"], yer_id:"Hotin" },
{ t:"1770-08-01", k:"savas", etiket:["savas","konu-askeri"], b:"Kartal (Kagul) Ovası Bozgunu", gun:"1 Ağustos 1770", yer:"Kartal ovası, Tuna boyu", kisiler:"İvazzâde Halil Paşa, Mareşal Rumyantsev", d:"Çeşme'de donanmanın yakılmasından üç hafta sonra, Tuna boyundaki ana Osmanlı ordusu Kartal ovasında Mareşal Rumyantsev'in sayıca çok daha küçük ama disiplinli birlikleri karşısında dağıldı. Ordugâh, ağırlıklar ve yüzlerce top düşman eline geçti; kaçan birlikler Tuna'yı geçerken büyük kayıp verdi. Aynı yaz içinde hem donanmanın hem kara ordusunun imhası, Kili, Akkirman, İsmail ve Bender'in birbiri ardına düşmesine ve Kırım'ın işgaline yol açtı.", kaynak:"mustafa-iii", duygu:["⚔️","😔"], yer_kon:[45.8,28.1833] },
{ t:"1771-07-01", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Kırım yarımadasının Rus işgali", gun:"1771", yer:"Kırım yarımadası", kisiler:"Prens Dolgorukov, Selim Giray III, Sâhib Giray", d:"Bir yıl önce Bucak'ı ele geçiren Rus orduları, Prens Dolgorukov kumandasında Or Kapı'yı aşarak Kırım yarımadasının tamamını istilâ etti. Han tahtından indirildi, Rus yanlısı Sâhib Giray başa geçirilerek hanlığın Osmanlı'dan koparılması yönünde ilk adım atıldı. Üç asırdır Osmanlı'nın kuzey kalkanı olan Kırım'ın elden çıkması, 1774'te bağımsızlık, 1783'te de doğrudan ilhak sürecinin başlangıcıydı.", kaynak:"kirim", duygu:["😔"], kapsam_genis:true, yer_id:"Bahçesaray" },
{ t:"1774-01-21", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"III. Mustafa'nın ölümü ve I. Abdülhamid'in cülûsu", gun:"21 Ocak 1774", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Mustafa, I. Abdülhamid", d:"Rus savaşının en buhranlı anında vefat eden III. Mustafa'nın yerine, kırk üç yılını sarayın kafesinde geçirmiş olan kardeşi I. Abdülhamid kırk dokuz yaşında tahta çıktı. Devletin en zor dönemlerinden birini devralan yeni padişah, aynı yıl imzalanacak Küçük Kaynarca Antlaşması'nın ağır şartlarıyla yüzleşmek zorunda kaldı. On beş yıllık saltanatı, Kırım'ın kaybı ve yeni bir Rus savaşıyla geçecek, 1789'da Özi'nin düşüş haberini okurken geçirdiği felçle son bulacaktı.", kaynak:"abdulhamid-i", vefat_id:"mustafa3", duygu:["🏛"] },
{ t:"1774-06-25", k:"savas", etiket:["savas","konu-askeri"], b:"Kozluca Bozgunu — Küçük Kaynarca'ya giden yenilgi", gun:"25 Haziran 1774", ic_not_gun:"17 Eyl 2026: t kaynak gününe alındı, bağlar birlikte taşındı (KOSU13-YAMA · YAMA-KOSU10-KALAN G6). ÖNCEKİ NOT — EK2 §4: TDV kucuk-kaynarca-antlasmasi Kozluca'yı 25 Haziran 1774 veriyor; t:1774-06-20 günü dayanaksızdı. t KORUNDU — ekokuma_antlasma2 '1774-06-20|Kozluca' bağı + savaslar.js; D147 ③ 1774-06-25 = 0 · öneri YAMA-KRON2. Akademik kaynakla (Jülyen/Gregoryen ayrımı dahil) bu oturumda ÖLÇÜLMEDİ · eski gun: Haziran 1774", yer:"Kozluca, Dobruca", kisiler:"Abdürrezzak Paşa, Suvorov, Kamenski", d:"Şumnu önlerinde toplanan Osmanlı kuvvetleri, Suvorov ve Kamenski'nin birleşik kollarına Kozluca'da yenildi ve ordunun büyük bölümü dağıldı. Bu bozgunla Balkanlar'da direnecek kuvvet kalmadı; Rus öncüleri Şumnu'yu kuşattı ve sadrazamın karargâhı tehdit altına girdi. Bir ay dolmadan Küçük Kaynarca'da masaya oturulması ve olağanüstü ağır şartların kabul edilmesi doğrudan bu yenilginin sonucudur.", kaynak:"kucuk-kaynarca-antlasmasi", duygu:["⚔️","😔"], yer_kon:[43.2833,27.6] },
{ t:"1775-05-07", k:"kayip", etiket:["toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"Bukovina'nın (Kuzey Boğdan) Avusturya'ya terki", gun:"1775", yer:"Bukovina, Kuzey Boğdan", kisiler:"I. Abdülhamid, Maria Theresia", d:"Küçük Kaynarca'nın yol açtığı zafiyetten yararlanan Avusturya, Boğdan ile Erdel arasındaki bağlantıyı sağlayan Bukovina bölgesini talep etti ve savaşa girmeden, tehdit ve rüşvetle bu toprağı elde etti. Hotin'in güneybatısındaki bu verimli ve stratejik bölgenin kaybı, Boğdan voyvodalığını fiilen ikiye böldü. Tek bir kurşun atılmadan yaşanan bu terk, Osmanlı Devleti'nin artık caydırıcılığını yitirdiğinin en açık göstergelerinden biri sayıldı.", kaynak:"hotin", duygu:["😔"], kapsam_genis:true, yer_id:"İstanbul" },
{ t:"1776-04-16", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Basra'nın İran işgaline uğraması", gun:"16 Nisan 1776", yer:"Basra", yer_id:"Basra", kisiler:"Sâdık Han, Kerim Han Zend, Süleyman Ağa", d:"Zend hükümdarı Kerim Han'ın kardeşi Sâdık Han, bir yıl süren kuşatmanın ardından Basra'yı ele geçirdi ve Osmanlı Devleti Basra körfezindeki en önemli limanını kaybetti. İşgal Hint ticaret yolunu, hurma ve inci gelirlerini ve Irak'ın güney savunmasını doğrudan sarstı. Şehir ancak 1779'da Kerim Han'ın ölümüyle İran'da çıkan taht kavgaları sırasında geri alınabildi.", kaynak:"basra", duygu:["😔"] },
{ t:"1779-03-10", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Aynalıkavak Tenkihnâmesi — Kırım üzerine geçici uzlaşma", gun:"10 Mart 1779", yer:"Aynalıkavak Kasrı, İstanbul", kisiler:"I. Abdülhamid, Halil Hamid Paşa, Prens Repnin", d:"Kırım hanlığının başına kimin geçeceği yüzünden savaşın eşiğine gelen iki devlet, Fransa'nın arabuluculuğuyla Aynalıkavak Kasrı'nda bir açıklama metni imzaladı. Rusya Kırım'dan askerini çekmeyi, Osmanlı Devleti ise Rus yanlısı Şâhin Giray'ın hanlığını tanımayı kabul etti; padişahın Kırım üzerindeki dinî halifelik hakkı teyit edildi. Dört yıl sürecek bu kırılgan denge, 1783'te Rusya'nın yarımadayı doğrudan ilhak etmesiyle tamamen çökecekti.", kaynak:"kirim", duygu:["🤝"], yer_id:"İstanbul" },
{ t:"1787-08-16", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"Rusya'ya savaş ilanı — 1787-1792 Osmanlı-Rus Savaşı başladı", gun:"16 Ağustos 1787 (2 Zilkade 1201)", ic_not_gun:"0035/H-0090 (PAKET-A3, 13 Eylül 2026): eski gün 17 Ağustos kaynaksızdı. TDV yas-antlasmasi ilanı '2 Zilkade 1201 (16 Ağustos 1787)' diye veriyor. TDV abdulhamid-i ise 19 Ağustos 1787'yi sadrazamın savaş kararını padişaha arz ettiği gün olarak anıyor — iki TDV maddesi arasında 3 günlük ayrışma, özel madde (antlaşma) esas alındı, çelişki bildirildi. Başlığa savaşın adı eklendi (Emre: savaş başlangıcı haberlerinde savaşın ismi de verilmeli).", yer:"İstanbul", yer_id:"İstanbul", kisiler:"I. Abdülhamid, Koca Yûsuf Paşa, II. Katerina", d:"II. Katerina'nın gösterişli Kırım seyahati ve Gürcistan'ı himayesine alması üzerine Divan, ilhakı geri döndürmek amacıyla savaş kararı aldı ve Rus elçisi tekrar Yedikule'ye kapatıldı. Ancak ordu hazır değildi, hazine boştu ve müttefik arayışı sonuçsuz kalmıştı. Beş yıl sürecek savaş, Özi'nin katliamla düşüşü, İsmail'in kaybı ve Yaş Antlaşması'nın ağır şartlarıyla sonuçlanacaktı.", kaynak:"abdulhamid-i", duygu:["⚔️","😔"] },
{ t:"1788-02-09", k:"savas", etiket:["savas","ittifak","konu-askeri","konu-diplomasi"], b:"Avusturya'nın savaşa girmesi — iki cepheli mücadele", gun:"9 Şubat 1788", yer:"Viyana / Belgrad cephesi", kisiler:"II. Josef, Koca Yûsuf Paşa, I. Abdülhamid", d:"Rusya ile 1781'de yaptığı gizli ittifak gereği Avusturya imparatoru II. Josef, Osmanlı Devleti'ne savaş ilân ederek Belgrad ve Bosna yönünde harekete geçti. Osmanlı ordusu bir anda kuzeyde Rusya, batıda Avusturya olmak üzere iki cephede birden savaşmak zorunda kaldı. Lazarethane, Muhâdiye ve Şebeş'te Avusturyalılara karşı kazanılan zaferlere rağmen, 1789'da Belgrad'ın kaybıyla batı cephesi de çökecekti.", kaynak:"abdulhamid-i", duygu:["⚔️"], yer_id:"Viyana" },
{ t:"1790-01-31", k:"antlasma", etiket:["ittifak","antlasma","diplomasi","konu-diplomasi"], b:"Osmanlı-Prusya İttifakı", gun:"31 Ocak 1790", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Selim, Koca Yûsuf Paşa, Heinrich von Diez", d:"Tahta çıkar çıkmaz Avrupa'da müttefik arayan III. Selim, Prusya ile karşılıklı yardım öngören bir ittifak antlaşması imzaladı; Prusya Rusya ve Avusturya'ya savaş açmayı, Osmanlı Devleti de Kırım geri alınmadan barış yapmamayı taahhüt etti. Bu, Osmanlı tarihinde bir Avrupa devletiyle imzalanan ilk gerçek karşılıklı ittifak metniydi ve klasik 'küffârla ittifak olmaz' anlayışının terk edildiğini gösteriyordu. Prusya savaşa girmedi, ancak Avusturya'yı barışa zorlayarak Ziştovi Antlaşması'nın önünü açtı.", kaynak:"selim-iii", duygu:["🤝"] },
{ t:"1790-12-22", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"İsmail Kalesi'nin düşüşü ve katliamı", gun:"22 Aralık 1790", yer:"İsmail, Tuna deltası", kisiler:"Aydoslu Mehmed Paşa, General Suvorov", d:"Tuna deltasının en güçlü istihkâmı sayılan İsmail Kalesi, General Suvorov'un düzenlediği kanlı bir genel hücumla bir günde ele geçirildi; garnizon ve şehir halkı büyük ölçüde kılıçtan geçirildi. Avrupa'da geniş yankı uyandıran bu katliam, Osmanlı kamuoyunda derin bir şok yarattı ve Tuna savunma hattının bel kemiğini kırdı. Kale, bir yıl sonra Yaş Antlaşması'yla geri alınacak, ancak savaşın kaderi çoktan belirlenmiş olacaktı.", kaynak:"osmanlilar", duygu:["😢","😔","😠"], yer_id:"İsmail" },
{ t:"1791-08-04", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Ziştovi Antlaşması — Avusturya cephesinin kapanması", gun:"4 Ağustos 1791", yer:"Ziştovi, Tuna boyu", kisiler:"III. Selim, II. Leopold, Prusya arabuluculuğu", d:"Prusya'nın baskısı ve Fransız İhtilâli'nin Avusturya'yı batıda meşgul etmesi sayesinde, iki devlet savaş öncesi sınırlar esas alınarak barışa vardı. Avusturya işgal ettiği Belgrad dahil bütün yerleri geri verdi; Osmanlı Devleti yalnızca Hırvatistan sınırında küçük düzeltmeler kabul etti. Batı cephesinin bu şartlarla kapanması, Osmanlı Devleti'nin bütün gücünü Rusya'ya karşı toplamasını sağladı ve Yaş Antlaşması'ndaki kaybı sınırladı.", kaynak:"zistovi-antlasmasi", duygu:["🤝"], yer_kon:[43.617,25.35] },
{ t:"1792-01-10", k:"antlasma", etiket:["antlasma","toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"Yaş Antlaşması — Kırım'ın kesin kaybı ve Turla sınırı", gun:"10 Ocak 1792", yer:"Yaş (Iaşi), Boğdan", kisiler:"III. Selim, Prens Potemkin, Bezborodko", d:"Beş yıllık savaşın sonunda imzalanan antlaşmayla Turla (Dinyester) nehri sınır kabul edildi; nehrin sol yakası Rusya'ya, sağ yakası Osmanlı'ya kaldı ve Özi ile çevresi kesin olarak elden çıktı. Osmanlı Devleti Kırım'ı geri alma ümidini tamamen bıraktı ve 1783 ilhakını hukuken tanıdı; Eflak ile Boğdan iki yıllık vergi muafiyetiyle iade edildi. On iki milyon kuruşluk savaş tazminatı yükümlülüğü de kabul edilerek Karadeniz'in kuzeyi kalıcı biçimde Rusya'ya terk edilmiş oldu. Aynı tarihte katılan öteki yerler: İsmail.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"yas-antlasmasi", duygu:["🤝","😔"], yer_id:"Hacıbey (Odessa)" },
{ t:"1795-03-01", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"Pazvandoğlu Osman'ın Vidin'de fiilî hükümdarlığı", gun:"1795", yer:"Vidin, Tuna boyu", kisiler:"Pazvandoğlu Osman, III. Selim, Küçük Hüseyin Paşa", d:"Nizâm-ı Cedîd düzenlemelerine karşı ayaklanan Pazvandoğlu Osman, Vidin valisini kaçırtarak şehri ele geçirdi ve Tuna boyunca derin hendeklerle tahkim etti. 1797'de gücünün zirvesinde seksen bine yakın kuvvet toplayarak Niğbolu, Ziştovi, Rusçuk, Sofya ve Niş'i denetimine aldı; kendisini âsi değil ıslahatçı olarak takdim etti. Bâbıâli'nin 1798-1799'da aylarca süren kuşatması sonuçsuz kaldı ve o 1807'deki ölümüne kadar Kuzey Bulgaristan'da yarı bağımsız hüküm sürdü.", kaynak:"pazvandoglu-osman", duygu:["✊"], yer_id:"Vidin" },
{ t:"1795-09-01", kesinlik:"ay", k:"bilim", etiket:["bilim","siyaset","konu-siyasi","konu-bilim"], b:"Mühendishâne-i Berrî-i Hümâyun'un açılışı", gun:"Safer 1210 / Eylül 1795", yer:"Hasköy, İstanbul", kisiler:"III. Selim, Hüseyin Rıfkı Tamânî, Mustafa Reşid", d:"Nizâm-ı Cedîd ordusuna topçu, istihkâm ve haritacı subay yetiştirmek üzere Hasköy'de kara mühendishânesi açıldı; 1773'te kurulan Bahriye Mühendishânesi'nin kara ordusundaki karşılığıydı. Programda cebir, hendese, mekanik, istihkâm ve balistik okutuldu, Avrupa dillerinden matematik ve topçuluk kitapları tercüme edildi. Türkiye'de modern mühendislik eğitiminin kökü sayılan bu okul, günümüz İstanbul Teknik Üniversitesi'nin başlangıcı kabul edilir.", kaynak:"muhendishane-i-berri-i-humayun — TDV gövdesi birebir: 'Mühendis yetiştirmek üzere 1795 yılında açılan mektep.' · '5 Zilhicce 1207'de (14 Temmuz 1793) başlanmış ve Safer 1210'da (Eylül 1795) tamamlanmıştır.' · '1210'da (1795) Hasköy'de açılmıştır.' ⇒ kaynak HAZİRAN DEMİYOR; eski t:\"1795-06-15\" kaynaksızdı (KRONO-EKSIK-0921, 21 Eylül 2026, 1.MURAT hükmü M-4911a)", ic_not_gun:"🔴 GÜN DÜZELTMESİ — 21 Eylül 2026, KRONO-EKSIK-0921, 1.MURAT hükmü M-4911(a). Eski kayıt t:\"1795-06-15\" (gün hassasiyeti) ama kendi gun: alanı yalnız \"1795\" diyordu — sahte kesinlik (D210). TDV muhendishane-i-berri-i-humayun gövdesi açılış için GÜN VERMEZ; verdiği en ince değer bina için Safer 1210 = Eylül 1795'tir. ⇒ t ayın 1'ine çekildi ve hassasiyet AÇIKLAYAN alandan okunsun diye kesinlik:\"ay\" yazıldı (D213: YYYY-MM-01 biçimi 'ayın 1'i' ile 'ay biliniyor'u kendi başına ayırt edemez). İnşaatın BAŞLANGICI ayrı maddedir (olaylar_ek14.js, t:\"1793-07-14\", 5 Zilhicce 1207). Taşımadan önce \"1795-06-15\" kalıbı bütün data/ · js/ · arac/ altında tarandı: 4 yer bulundu — bu kayıt, data/yer_yama.js anahtarı (birlikte güncellendi) ve iki YORUM satırı. EK OKUMA bağı YOKTU: ekokuma_kurum2.js kartları 1795-01-01'e bağlı, 1795-06-15'e değil.", duygu:["🔬"], yer_id:"İstanbul" },
{ t:"1798-09-09", kesinlik:"gun", k:"savas", etiket:["savas","ittifak","diplomasi","konu-askeri","konu-diplomasi"], b:"Fransa'ya savaş ilanı ve Rusya-İngiltere ile ittifak", gun:"9 Eylül 1798 (gün: Azmi Süslü, \"Osmanlı-Fransız Diplomatik İlişkileri, 1798-1807\", TTK Belleten XLVII/185, 1983)", ic_not_gun:"19 Eylül 2026 EKO-DENIZ-0069: eski t 1798-09-03, kaynak:'misir' — TDV misir gövdesinde bu gün BULUNAMADI. TDV yusuf-ziya-pasa: 'Fransa'nın Mısır'a saldırısı ve savaş ilânı üzerine (Eylül 1798)' (ay). Gün Belleten makalesinden: '9 Eylülde Fransa'ya resmen savaş ilân ederek, Fransız Maslahatgüzarı Rulfin'i Yedikule zindanlarına attırdı (12 Eylül)' — makale TDV fransa kaynakçasında. İttifaklar ayrı günlerdedir (TDV selim-iii/ingiltere/rusya: Ocak 1799); b/d ikisini birlikte anlatıyor.", yer:"İstanbul", yer_id:"İstanbul", kisiler:"III. Selim, Napolyon Bonapart, Rus ve İngiliz elçileri", d:"Napolyon'un Mısır'ı işgali üzerine Osmanlı Devleti, iki buçuk asırlık geleneksel Fransız dostluğunu bozarak Fransa'ya savaş ilân etti. Aynı süreçte tarihinde ilk defa Rusya ile ittifak yaptı ve Rus donanmasının Boğazlar'dan geçerek Akdeniz'e çıkmasına izin verdi; ardından İngiltere ile de ittifak imzalandı. Bu ittifaklar sayesinde İyon adaları Fransızlardan alındı, ancak Boğazlar'ın bir yabancı donanmaya açılması ileride ağır bedeli olan bir emsal oluşturdu.", kaynak:"yusuf-ziya-pasa", duygu:["⚔️"] },
{ t:"1799-05-20", k:"savas", etiket:["savas","konu-askeri"], b:"Akkâ Savunması — Napolyon'un püskürtülmesi", gun:"18 Mart – 20 Mayıs 1799", yer:"Akkâ (Filistin)", kisiler:"Cezzâr Ahmed Paşa, Napolyon Bonapart, Sidney Smith", d:"Mısır'dan Suriye'ye ilerleyen Napolyon, Akkâ'yı kuşattı ve iki ay boyunca arka arkaya hücumlar düzenledi; şehri Cezzâr Ahmed Paşa, İngiliz donanmasının desteği ve İstanbul'dan gönderilen Nizâm-ı Cedîd birlikleriyle savundu. Kuşatmayı kaldırıp Mısır'a çekilmek zorunda kalan Napolyon, doğuya uzanma hayalini bu surların önünde gömdü. Haber İstanbul'da büyük sevinçle karşılandı ve yeni kurulan talimli ordunun ilk ciddi sınavını geçtiğinin kanıtı sayıldı.", kaynak:"cezzar-ahmed-pasa", duygu:["⚔️"], yer_id:"Akkâ" },
{ t:"1801-04-01", k:"isyan", etiket:["isyan","diger","konu-isyan"], b:"Vehhâbîlerin Kerbelâ baskını", gun:"Nisan 1801 başları", yer:"Kerbelâ, Irak", kisiler:"Suûd b. Abdülazîz, Bağdat valisi Süleyman Paşa", d:"Necid'den kalkan Vehhâbî kuvvetleri Kerbelâ'ya girerek şehri yağmaladı, Hz. Hüseyin türbesini tahrip etti ve üç binden fazla kişiyi öldürdü. Osmanlı Devleti'nin Irak'taki kölemen valileri baskını önleyemedi; olay hem İran'da hem İstanbul'da büyük tepki uyandırdı. Bu saldırı, Suûdî hareketinin artık bir vaha emirliği olmaktan çıkıp Osmanlı'nın kutsal şehirlerini tehdit eden bölgesel bir güce dönüştüğünün ilanıydı.", kaynak:"kerbela", duygu:["✊","😔"], yer_id:"Kerbelâ" },
{ t:"1801-10-09", k:"fetih", etiket:["savas","toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Mısır'ın Fransızlardan tahliyesi", gun:"9 Ekim 1801", yer:"Kahire ve İskenderiye", kisiler:"Yûsuf Ziya Paşa, Sir Ralph Abercromby, General Menou", d:"Osmanlı ve İngiliz kuvvetlerinin karadan ve denizden ortak harekâtı sonucunda önce Kahire, ardından İskenderiye teslim alındı ve Fransız kuvvetleri gemilerle ülkelerine gönderildi. Üç yıl süren işgal sona ererken Mısır kâğıt üzerinde Osmanlı idaresine döndü, fakat kölemen beyleri ile Arnavut birlikleri arasındaki hâkimiyet mücadelesi ülkeyi kaosa sürükledi. Bu boşluk, birkaç yıl içinde Kavalalı Mehmed Ali'nin yükselişine zemin hazırlayacaktı.", kaynak:"misir", duygu:["🎉"], yer_id:"İskenderiye" },
{ t:"1802-06-25", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Paris Antlaşması — Fransa ile barışın yeniden kurulması", gun:"25 Haziran 1802", yer:"Paris", yer_id:"Paris", kisiler:"III. Selim, Napolyon Bonapart, Seyyid Ali Efendi", d:"Mısır'ın tahliyesinden sonra imzalanan antlaşmayla Osmanlı Devleti ile Fransa arasındaki savaş hali resmen sona erdi ve eski kapitülasyonlar yenilendi. Fransız ticaret gemilerinin Karadeniz'e girmesine izin verildi; buna karşılık Fransa Osmanlı toprak bütünlüğünü tanıdı. Barışın kurulması, III. Selim'in Rusya ve İngiltere yanında sıkışan dış politikasına yeniden manevra alanı kazandırdı.", kaynak:"misir", duygu:["🤝"] },
{ t:"1803-02-01", k:"kayip", etiket:["isyan","toprak-kayip","konu-askeri","konu-isyan"], b:"Vehhâbîlerin Tâif'i ele geçirmesi", gun:"Şubat 1803", yer:"Tâif, Hicaz", kisiler:"Suûd b. Abdülazîz, III. Selim", d:"Suûd b. Abdülazîz kumandasındaki Vehhâbî kuvvetleri Hicaz'a yönelik ilk hamlede Tâif'i kuşatıp yağmaladı; şehir kutsal topraklara açılan ilk kapı olarak düştü. Haremeyn'in hâmisi sıfatını taşıyan Osmanlı padişahı için bu, saltanatın meşruiyetini doğrudan sarsan bir darbeydi. İki buçuk ay sonra aynı ordu Mekke'ye yürüyecekti.", kaynak:"taif", duygu:["😔"], yer_id:"Tâif" },
{ t:"1803-04-30", k:"kayip", etiket:["isyan","toprak-kayip","konu-askeri","konu-isyan"], b:"Vehhâbîlerin Mekke'yi ilk kez ele geçirmesi", gun:"30 Nisan 1803", yer:"Mekke, Hicaz", kisiler:"Suûd b. Abdülazîz, Şerif Gālib, III. Selim", d:"Tâif'in düşmesinden iki buçuk ay sonra Vehhâbî kuvvetleri Mekke'ye girdi, türbeleri yıktı ve kendi anlayışlarına göre bir düzen kurdu; Şerif Gālib Cidde'ye çekilmek zorunda kaldı. Hac yollarının kapanması bütün İslâm dünyasında yankılandı ve İstanbul'u Mısır valisi Mehmed Ali'den askerî yardım istemeye mecbur bıraktı. Bu ilk hâkimiyet yalnız üç ay sürecekti.", kaynak:"mekke", duygu:["😔"], yer_id:"Mekke" },
{ t:"1803-08-06", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Şerif Gālib'in Mekke'yi geri alması", gun:"Ağustos 1803 başı (12 Temmuz'da başlayan yirmi beş günlük kuşatmanın sonunda)", ic_not_gun:"eski gun: Ağustos 1803 başı — TDV yalnız kuşatmanın başlangıcını (12 Temmuz) ve süresini (25 gün) veriyor, gün türetilmiştir", yer:"Mekke, Hicaz", kisiler:"Şerif Gālib", d:"Cidde'ye çekilmiş olan Şerif Gālib, topladığı kuvvetlerle Mekke'yi kuşattı ve yirmi beş günlük kuşatmanın ardından şehri Vehhâbîlerden geri aldı; Osmanlı adına hutbe yeniden okundu. Bu ikinci hâkimiyet de kalıcı olmayacak, Suûd kuvvetleri 1806'da şehri tekrar alacaktı.", kaynak:"mekke", duygu:["🎉"], yer_id:"Mekke" },
{ t:"1804-02-14", k:"isyan", etiket:["isyan","konu-isyan"], b:"Birinci Sırp İsyanı'nın başlaması", gun:"Şubat 1804", yer:"Semendire sancağı, Belgrad çevresi", kisiler:"Kara Yorgi (Karadjordje), âsi dayılar, III. Selim", d:"Belgrad'da yönetimi ele geçiren âsi yeniçeri dayılarının Sırp ileri gelenlerini toplu hâlde katletmesi üzerine Kara Yorgi önderliğinde silâhlı bir direniş başladı. Başlangıçta padişaha sadık kalarak yalnız dayılara karşı yürütülen hareket, kısa sürede özerklik ve bağımsızlık talep eden millî bir isyana dönüştü. Sırp kuvvetleri 1806'da Belgrad'ı ele geçirdi; bu ayaklanma, Balkanlar'da milliyetçi bağımsızlık hareketlerinin ilk halkası oldu.", kaynak:"sirbistan", duygu:["✊"], yer_id:"Semendire" },
{ t:"1805-06-01", k:"kayip", etiket:["isyan","toprak-kayip","konu-askeri","konu-isyan"], b:"Vehhâbîlerin Medine'yi işgali", gun:"Haziran 1805", yer:"Medine, Hicaz", kisiler:"Suûd b. Abdülazîz, III. Selim", d:"Mekke'nin ardından Medine de Vehhâbî kuvvetlerinin eline geçti; Ravza-i Mutahhara'nın hazinesi dağıtıldı ve şehirdeki kubbeli türbeler yıkıldı. Böylece iki kutsal şehir birden Osmanlı denetiminden çıktı ve Şam ile Mısır'dan gelen hac kafileleri yıllarca yola çıkamadı. Medine ancak yedi yıl sonra, 1812'de Mehmed Ali Paşa'nın oğlu Tosun Paşa kumandasındaki Mısır ordusu tarafından geri alınabildi.", kaynak:"medine", duygu:["😔"], yer_id:"Medine" },
{ t:"1806-12-22", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"Rusya ile savaşın başlaması (1806-1812 Osmanlı-Rus Savaşı) ve Boğazların kapatılması", gun:"22 Aralık 1806", ic_not_b:"0035/H-0090 (PAKET-A3, 13 Eylül 2026): başlığa savaşın adı eklendi. ⚠️ 22 Aralık günü ÖLÇÜLEMEDİ: TDV selim-iii yalnız '1806'da bu iki devletle savaş durumu' der, gün vermez; TDV hotin Rus işgalini 1806'ya koyar.", yer:"İstanbul ve Tuna cephesi", kisiler:"III. Selim, General Michelson, Sébastiani", d:"Napolyon'un Austerlitz zaferinden sonra Fransa'ya yakınlaşan III. Selim'in Eflak ve Boğdan voyvodalarını Rus baskısına rağmen azletmesi üzerine Rus orduları iki prensliği işgal etti ve savaş başladı. Osmanlı Devleti Boğazlar'ı Rus donanmasına kapattı; buna karşılık İngiltere de Rusya'nın yanında yer alarak İstanbul'a bir filo gönderdi. Altı yıl sürecek bu savaş, Kabakçı İsyanı ve III. Selim'in tahttan indirilmesiyle iç içe geçerek 1812 Bükreş Antlaşması'nda Besarabya'nın kaybıyla bitecekti.", kaynak:"selim-iii", duygu:["⚔️"], yer_id:"İstanbul" },
{ t:"1807-02-20", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"İngiliz donanmasının İstanbul önlerine gelmesi (Duckworth harekâtı)", gun:"20 Şubat 1807", yer:"İstanbul Boğazı ve Çanakkale", kisiler:"Amiral Duckworth, III. Selim, Sébastiani", d:"Osmanlı Devleti'ni Fransa ile bağını koparmaya zorlamak isteyen İngiltere, Amiral Duckworth kumandasındaki filoyu Çanakkale'den geçirerek İstanbul önlerine demirletti. Fransız elçisi Sébastiani'nin de yönlendirmesiyle İstanbul halkı seferber oldu, sahil bataryaları günler içinde takviye edildi ve şehir topa tutulamadan filo geri çekilmek zorunda kaldı; dönüşte Çanakkale'de ağır kayıp verdi. Başkentin bir yabancı donanma tarafından ilk defa bu kadar yakından tehdit edilmesi, Boğazlar meselesini Avrupa diplomasisinin merkezine yerleştirdi.", kaynak:"selim-iii", duygu:["⚔️"], yer_id:"İstanbul" },
{ t:"1809-01-05", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Kal'a-i Sultâniyye Antlaşması — İngiltere ile barış ve Boğazlar kaidesi", gun:"5 Ocak 1809", yer:"Kal'a-i Sultâniyye (Çanakkale)", kisiler:"II. Mahmud, Robert Adair, Mustafa Reşid", d:"Duckworth harekâtının başarısızlığından sonra İngiltere ile imzalanan antlaşmayla iki devlet arasındaki savaş sona erdi ve İngiliz tüccarının eski imtiyazları geri verildi. Metinde yer alan ve 'kadîm kaide' diye anılan hüküm, barış zamanında hiçbir yabancı savaş gemisinin Boğazlar'dan geçemeyeceğini kayıt altına aldı. Bu ilke, XIX. yüzyıl boyunca Boğazlar rejimini şekillendirecek bütün uluslararası düzenlemelerin hukukî dayanağı oldu.", kaynak:"osmanlilar", duygu:["🤝"], yer_id:"Çanakkale" },
{ t:"1811-10-25", k:"savas", etiket:["savas","konu-askeri"], b:"Slobozia Bozgunu — Tuna ordusunun kuşatılması", gun:"25 Ekim 1811", yer:"Slobozia, Rusçuk karşısı", kisiler:"Ahmed Paşa, Mareşal Kutuzov", d:"Rusçuk önünde Tuna'yı geçen Osmanlı ordusunun büyük bölümü, Kutuzov'un nehrin karşı yakasından yaptığı kuşatma manevrasıyla Slobozia'da sıkıştırıldı ve açlığa terk edildi. Binlerce asker teslim olmak zorunda kaldı; sadrazamın elindeki kuvvet fiilen eridi ve Bâbıâli bir ay sonra ateşkes istemek zorunda kaldı. Bu yenilgi, 1812 Bükreş Antlaşması'nda Besarabya'nın verilmesine razı olunmasının doğrudan sebebidir.", kaynak:"osmanlilar", duygu:["⚔️","😔"], yer_id:"Rusçuk" },
{ t:"1813-10-05", k:"fetih", etiket:["savas","toprak-kazanc","isyan","konu-askeri","konu-isyan"], b:"Belgrad'ın geri alınışı ve Birinci Sırp İsyanı'nın bastırılması", gun:"Ekim 1813", yer:"Belgrad ve Semendire sancağı", kisiler:"Hurşid Ahmed Paşa, Kara Yorgi, II. Mahmud", d:"Bükreş Antlaşması'yla Rus desteğinden mahrum kalan Sırp isyancıları, Bosna ve Rumeli'den gelen kuvvetlerin ortak harekâtı karşısında dayanamadı; Hurşid Ahmed Paşa Belgrad'a girdi ve dokuz yıllık ayaklanma tamamen bastırıldı. Kara Yorgi Avusturya'ya kaçtı, Semendire sancağı yeniden doğrudan Osmanlı idaresine bağlandı. Ancak uygulanan sert tedbirler iki yıl sonra Miloş Obrenoviç önderliğinde ikinci ve kalıcı bir isyanı tetikleyecekti.", kaynak:"sirbistan", duygu:["🎉"], yer_id:"Belgrad" },
{ t:"1815-04-23", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"İkinci Sırp İsyanı ve Miloš Obrenović'in başknezliği", gun:"1815", yer:"Semendire sancağı, Sırbistan", kisiler:"Miloš Obrenović, Marâşlı Ali Paşa, II. Mahmud", d:"Birinci isyanın bastırılmasının ardından uygulanan ağır tedbirlere karşı Miloš Obrenović önderliğinde yeni bir ayaklanma patlak verdi; bu defa Bâbıâli kuvvet yerine uzlaşmayı tercih etti. Yapılan anlaşmayla Miloš 'başknez' sıfatıyla tanındı, vergi toplama ve iç işlerini yürütme yetkisi Sırp knezlerine bırakıldı. Fiilî özerkliğin bu ilk çekirdeği, 1830 fermanı ve 1878 bağımsızlığına uzanan sürecin başlangıç noktası oldu.", kaynak:"sirbistan", duygu:["✊"], yer_id:"Semendire" },
{ t:"1821-02-22", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"Eflak İsyanı — Ypsilanti'nin Prut'u geçmesi ve Vladimirescu ayaklanması", gun:"Şubat 1821", yer:"Eflak (Bükreş ve Yaş)", kisiler:"Aleksandr Ypsilanti, Tudor Vladimirescu, II. Mahmud", d:"Rus ordusunda general olan Aleksandr Ypsilanti, Etniki Eterya adına Prut'u geçerek Eflak ve Boğdan'da genel bir Rum ayaklanması başlatmayı denedi; aynı günlerde Tudor Vladimirescu da yerli köylüleri harekete geçirdi. İki hareket birleşemedi: Vladimirescu, Ypsilanti'nin birlikte Türkler'e karşı savaşma çağrısına 'Ben Türkler'e değil Rumlar'a karşı ayaklandım' cevabını verdi ve kısa süre sonra Ypsilanti'nin adamlarınca öldürüldü. İsyan Osmanlı kuvvetlerince mayısta bastırıldı, ancak Fenerli voyvodalık düzeni sona erdi ve isyan ateşi Mora'ya sıçradı.", kaynak:"eflak", duygu:["✊"], odak_kimlik:["eflak","bogdan"] },
  // 🔴 KRONO-YER-0072 (H-0012, Emre: "haritada yer işaretlemesi yok bundan
  // dolayı imparatorluk görünümünde görünüyor"). H-0009 ile AYNI sınıf:
  // `kapsam_genis:true` yanlış beyandı — isyan iki voyvodalıkta geçiyor,
  // imparatorluk çapında değil. TDV `eflak` ve `bogdan` maddelerinde Prut'un
  // NEREDE geçildiği YOK (Boğdan: "Aleksandro İpsilanti'nin organize ettiği
  // Rum ihtilâl hareketi, Boğdan voyvodası ... tarafından destekleniyordu");
  // geçişin Yaş'a girişle sonuçlandığı TDV DIŞI kaynaktan (Britannica,
  // "Alexander Ypsilantis") okunuyor — tek nokta yazmak yerine maddenin
  // kendi `yer:` alanının söylediği iki voyvodalık odak kutusuna çevrildi.
  // Ölçüldü (1821-02-22): 15 yerleşim · kutu [22.31, 43.98, 28.36, 47.51].
{ t:"1824-06-01", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"İkinci Suûdî Devleti'nin Riyad'da kurulması", gun:"1824", yer:"Riyad, Necid", kisiler:"Türkî b. Abdullah, İbrâhim Paşa", d:"Dir'iye'nin 1818'de düşmesi ve ilk Suûdî Devleti'nin yıkılmasından altı yıl sonra, Türkî b. Abdullah Mısır garnizonlarını Necid'den çıkararak Riyad merkezli yeni bir Suûdî emirliği kurdu. Yeni yapı Hicaz'a uzanmaktan kaçınarak Necid'de kalmayı tercih etti ve Osmanlı-Mısır kuvvetleriyle doğrudan çatışmadan uzak durdu. Bu ikinci devlet, yüzyılın sonuna kadar sürecek ve bugünkü Suudi Arabistan'ın kuruluşuna giden zincirin ikinci halkasını oluşturacaktı. Aynı tarihte elden çıkan diğer yerleşimler: Dir'iye (Necid).", kaynak:"suudiler", duygu:["✊"], yer_id:"Riyad" },
{ t:"1826-10-07", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Akkirman Antlaşması — Sırbistan ve prensliklere tavizler", gun:"7 Ekim 1826", yer:"Akkirman (Belgorod-Dnestrovski)", kisiler:"II. Mahmud, Vorontsov, Ribeaupierre", d:"Yeniçeri Ocağı'nın kaldırılmasının hemen ardından ordusuz kalan Osmanlı Devleti, Rusya'nın ültimatomu karşısında ağır şartlı bir antlaşmayı kabul etmek zorunda kaldı. Sırbistan'a vaad edilen özerklik teyit edildi, Eflak ve Boğdan voyvodalarının Rus onayı olmadan azledilemeyeceği kabul edildi, Rus ticaret gemilerine Boğazlar'da tam serbestlik tanındı. Bâbıâli iki yıl sonra Yunan meselesi yüzünden antlaşmayı tanımadığını ilân edince, Rusya bunu savaş gerekçesi sayacaktı.", kaynak:"sirbistan", duygu:["🤝"], yer_id:"Akkirman" },
{ t:"1827-02-01", k:"siyaset", etiket:["siyaset","ekonomi","konu-siyasi","konu-ekonomi"], b:"Tımar sisteminin tasfiyesi", gun:"1827", yer:"Rumeli ve Anadolu (53 sancak)", kisiler:"II. Mahmud", d:"Yeniçeri Ocağı'nın kaldırılmasından bir yıl sonra, Rumeli ve Anadolu'daki elli üç sancakta bulunan yaklaşık 5.200 tımarlı sipahi, tımar gelirleriyle birlikte Asâkir-i Mansûre süvarisine dönüştürüldü. Böylece Osmanlı toprak, vergi ve ordu düzeninin dört asırlık omurgası olan tımar rejimi fiilen sona erdi. Boşalan tımarlar hazineye devredildi ve merkezî maaşlı ordu ile nakdî vergi sistemine geçişin önü açıldı.", kaynak:"timar", duygu:["🏛"], kapsam_genis:true, odak_yer:"İstanbul" },
  // 🔴 KRONO-YER-0072 · 0074/H-0004 — Emre: "harita noktası yok sanırım İstanbul
  // koymak lazım bunun odak noktasına". `yer_id:"İstanbul"` YAZILMADI: olay 53
  // sancakta oldu, İstanbul'da değil; `yer_id` "olay burada oldu" demektir.
  // TDV `timar` kararın NEREDE alındığını söylemiyor (arandı: "metinde yok"),
  // yalnız sonucu veriyor — AYNEN: "1827'de Rumeli ve Anadolu'daki elli üç
  // sancaktan 5200 kadar timarlı sipahi timar gelirleriyle birlikte Asâkir-i
  // Mansûre süvarisi haline getirildi." ⇒ İstanbul kaynaklı bir OLAY YERİ değil,
  // bir GÖSTERİM tercihidir ve `odak_yer` tam da bunu söyler.
  // `kapsam_genis:true` DURUYOR — olay gerçekten ülke çapında; iki alan çelişmiyor.
{ t:"1827-03-14", k:"bilim", etiket:["bilim","kultur","konu-bilim","konu-kultur"], b:"Tıphâne-i Âmire'nin kurulması — modern tıp eğitiminin başlangıcı", gun:"1827", yer:"Şehzadebaşı, İstanbul", kisiler:"II. Mahmud, Mustafa Behçet Efendi", d:"Yeni kurulan Asâkir-i Mansûre ordusuna hekim ve cerrah yetiştirmek üzere, hekimbaşı Mustafa Behçet Efendi'nin teklifiyle Şehzadebaşı'nda Tıphâne-i Âmire açıldı. Dersler Avrupa'daki müfredata göre düzenlendi ve öğretim başlangıçta Fransızca yapıldı; birkaç yıl sonra Cerrahhâne-i Âmire de kurularak iki kurum birleştirildi. Türkiye'de modern tıp öğretiminin başlangıcı sayılan bu okul, bugünkü İstanbul Tıp Fakültesi'nin kökeni kabul edilir.", kaynak:"osmanlilar", duygu:["🔬"], yer_id:"İstanbul" },
{ t:"1828-04-26", k:"savas", etiket:["savas","diplomasi","konu-askeri","konu-diplomasi"], b:"1828-1829 Osmanlı-Rus Savaşı'nın başlaması", gun:"26 Nisan 1828", yer:"Tuna ve Kafkas cepheleri", kisiler:"II. Mahmud, I. Nikola, Ağa Hüseyin Paşa", d:"Navarin'de donanmanın yakılması ve Bâbıâli'nin Akkirman Antlaşması'nı tanımadığını ilân etmesi üzerine Rusya iki cepheden birden savaş açtı. Yeniçeri Ocağı henüz kaldırılmış, yeni ordu ise kurulma aşamasında olduğu için Osmanlı savunması baştan zayıftı; Ruslar Tuna'yı geçerken doğuda Kars ve Ahıska'yı aldı. Bir yıl içinde Edirne'ye kadar ilerleyen Rus ordusu, 1829 Edirne Antlaşması'nın ağır şartlarını ve Yunanistan'ın bağımsızlığını dayatacaktı.", kaynak:"edirne-antlasmasi", duygu:["⚔️"], kapsam_genis:true, odak_yer:["Yaş","Anapa"] },
  // 🔴 KRONO-YER-0072 · 0074/H-0010 — Emre: "Osmanlı-Rus savaşının haritada
  // noktası yok". Bu madde H-0004'ten FARKLI bir sınıf: karar maddesi değil,
  // CEPHE maddesi — ve cephesi İKİ tane, o yüzden tek nokta yazılamaz.
  // TDV `edirne-antlasmasi`, AYNEN: "Rusya ise Bâbıâli'nin yayımladığı bildiriyi
  // bahane ederek savaş açmıştı (26 Nisan 1828)" — ilânın YERİNİ vermiyor; ve
  // ilk harekât için AYNEN: "Balkanlar'da ve Kafkaslar'da saldırıya geçen Ruslar
  // Boğdan'a girdikleri gibi Anapa Kalesi'ni de kuşattılar."
  // ⇒ İki cephenin iki çapası: Yaş (Boğdan'ın merkezi) ve Anapa (TDV'nin ismen
  // verdiği tek Kafkas hedefi). Kutu [26,8 · 44,2 · 37,6 · 47,5] — imparatorluk
  // kutusunun ([-2,4 · 10,5 · 49,3 · 47,9]) beşte biri kadar.
{ t:"1830-05-07", k:"antlasma", etiket:["antlasma","diplomasi","ekonomi","konu-diplomasi","konu-ekonomi"], b:"Amerika Birleşik Devletleri ile ilk antlaşma", gun:"7 Mayıs 1830", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Mahmud, Charles Rhind, David Offley", d:"Yıllarca süren temaslardan sonra imzalanan ticaret ve seyrisefain antlaşmasıyla ABD, Osmanlı ülkesinde en ziyade müsaadeye mazhar millet statüsü ve Boğazlar'dan ticarî geçiş hakkı elde etti. Metnin gizli bir maddesi Amerikan tersanecilerinin Osmanlı donanmasına gemi inşa etmesini öngörüyordu; nitekim Amerikalı ustalar İstanbul tersanesinde çalıştı. Bu antlaşma, Osmanlı Devleti'nin Avrupa dışındaki bir devletle kurduğu ilk kapsamlı ilişkinin belgesi oldu.", kaynak:"osmanlilar", duygu:["🤝"] },
{ t:"1831-09-14", k:"siyaset", etiket:["siyaset","isyan","konu-siyasi","konu-isyan"], b:"Bağdat'ta Kölemen idaresine son verilmesi", gun:"1831", yer:"Bağdat", yer_id:"Bağdat", kisiler:"Dâvud Paşa, Ali Rızâ Paşa, II. Mahmud", d:"Merkezîleşme siyaseti güden II. Mahmud, istediği parayı göndermeyen ve merkezden gelen görevliyi öldürten Bağdat valisi Dâvud Paşa'yı âsi ilân etti. Ali Rızâ Paşa kumandasındaki kuvvet doksan gün süren bir kuşatmanın ardından şehri ele geçirdi ve kölemenlerin neredeyse tamamı tasfiye edildi. Böylece 1704'ten beri süren yarı bağımsız Kölemen yönetimi sona erdi ve Irak yeniden doğrudan merkeze bağlandı.", kaynak:"bagdat", duygu:["🏛"] },
{ t:"1834-07-01", k:"bilim", etiket:["bilim","siyaset","konu-siyasi","konu-bilim","konu-egitim"], b:"Mekteb-i Harbiye'nin Maçka Kışlası'nda kurulması", gun:"1834", yer:"Maçka, İstanbul", kisiler:"II. Mahmud, Mehmed Nâmık Paşa", d:"Asâkir-i Mansûre-i Muhammediyye'ye Avrupa usulünde yetişmiş subay sağlamak için Maçka Kışlası'nda Mekteb-i Fünûn-ı Harbiyye açıldı. Öğrencilere matematik, harita, istihkâm ve yabancı dil okutuldu; kısa süre sonra Viyana ve Paris'e öğrenci gönderilerek kadro güçlendirildi. Bu okul, Osmanlı ordusunda mektepli subay geleneğinin ve dolayısıyla XIX. yüzyıl sonunda ortaya çıkacak yeni asker-aydın kuşağının doğduğu yer oldu.", kaynak:"osmanlilar", duygu:["🔬"], yer_id:"İstanbul" },
{ t:"1835-05-26", k:"siyaset", etiket:["siyaset","toprak-kazanc","konu-askeri","konu-siyasi","konu-hanedan"], b:"Trablusgarp'ın doğrudan merkeze bağlanması — Karamanlı hanedanının sonu", gun:"1835", yer:"Trablusgarp", kisiler:"II. Mahmud, Ali Karamanlı, Mustafa Necib Paşa", d:"Karamanlı ailesi içindeki taht kavgaları ve Fransa'nın 1830'da Cezayir'i işgal etmesinden sonra artan Avrupa baskısı üzerine, Bâbıâli Trablusgarp'a doğrudan müdahale etti. İstanbul'dan gönderilen donanma şehre girdi, son Karamanlı beyi azledilerek İstanbul'a getirildi ve eyalet merkezden atanan bir valiye teslim edildi. 124 yıllık hanedan dönemi sona ererken, Kuzey Afrika'da Osmanlı Devleti'nin doğrudan yönettiği son toprak parçası pekiştirilmiş oldu.", statu_dogrudan:["Trablus","Misrata","Bingazi","Derne","Murzuk (Fizan)"], kaynak:"trablusgarp", duygu:["🏛"], yer_id:"Trablus" },
{ t:"1838-02-28", k:"siyaset", etiket:["siyaset","ekonomi","konu-siyasi","konu-burokrasi","konu-ekonomi"], b:"Defterdarlığın kaldırılıp Maliye Nezâreti'nin kurulması", gun:"28 Şubat 1838", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Mahmud, Nâfiz Efendi", d:"Klasik Osmanlı malî düzeninin başı olan defterdarlık makamı ilga edilerek, Avrupa tarzında bir bakanlık olan Maliye Nezâreti kuruldu ve dağınık hazineler tek elde toplandı. Aynı yıl Bâbıâli'nin diğer birimleri de nezâret adı altında yeniden düzenlenerek modern bir bakanlar kurulu yapısına geçildi. Bu düzenleme, bir yıl sonra ilân edilecek Tanzimat Fermanı'nın idarî altyapısını hazırlayan en önemli adımlardan biriydi.", kaynak:"maliye-nezareti", duygu:["🏛"] },
{ t:"1839-01-19", k:"kayip", etiket:["toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"İngilizlerin Aden'e yerleşmesi", gun:"1839", yer:"Aden, Güney Yemen", kisiler:"Kaptan Haines, Lehic Sultanı Ahmed b. Abdülkerîm", d:"İngiltere, 1802'de Lehic sultanı Ahmed b. Abdülkerîm ile imzaladığı ticaret ve dostluk anlaşmasına dayanarak Aden limanına asker çıkardı ve şehri denetimine aldı. Kızıldeniz'in ağzını tutan bu liman, Hindistan yolunun kömür ikmal üssü olarak İngiliz imparatorluk stratejisinin kilit noktasına dönüştü. Osmanlı Devleti'nin Yemen üzerindeki iddiası kâğıt üzerinde sürse de, güney sahilindeki fiilî hâkimiyeti bu tarihten sonra bir daha geri gelmedi.", kaynak:"aden", duygu:["😔"], yer_id:"Aden" },

// ---------- D) TANZİMAT'TAN CUMHURİYET'E (1839-1923) ----------
{ t:"1849-01-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"],
  b:"Tihâme sahiline dönüş: Hudeyde, Zebîd ve Moha'nın alınması",
  gun:"1849", yer:"Hudeyde, Zebîd, Moha (Tihâme, Yemen)",
  kisiler:"Tevfik Paşa, Mekke şerifi",
  d:"Mısır ordusunun 1840'ta çekilmesiyle sahipsiz kalan Yemen sahiline, Mekke şerifinin nezareti altında Tevfik Paşa kumandasındaki kuvvetler çıkarak Hudeyde, Zebîd ve Moha limanlarını Osmanlı idaresine bağladı. San'a'ya kadar ilerlenmek istendiyse de halkın direnişi yüzünden Hudeyde'ye dönüldü; böylece yaylalar Zeydî imamlarında kaldı ve Osmanlı hâkimiyeti yirmi üç yıl boyunca yalnız Tihâme şeridinde sürdü. İç Yemen ancak 1872'de Ahmed Muhtar Paşa'nın seferiyle geri alınacaktı.", kaynak:"hudeyde", duygu:["🎉"], yer_id:"Hudeyde" },
{ t:"1849-08-16", k:"siyaset", etiket:["diplomasi","siyaset","konu-siyasi","konu-diplomasi"], b:"Macar mültecileri meselesi: Kossuth ve arkadaşlarının Osmanlı'ya sığınması", gun:"1849", yer:"Vidin, Şumnu, Kütahya", kisiler:"Lajos Kossuth, Abdülmecid, Mustafa Reşid Paşa", d:"1848-1849 Macar ihtilâlinin Rus-Avusturya müdahalesiyle bastırılması üzerine Lajos Kossuth ve binlerce Macar-Leh mülteci Osmanlı topraklarına sığındı. Avusturya ve Rusya mültecilerin iadesini sert biçimde istedi; Bâbıâli, İngiltere ve Fransa'nın desteğiyle iadeyi reddetti ve grubu Kütahya'ya yerleştirdi. Kossuth'un çevresi burada yaklaşık on sekiz ay kaldı, yüzlerce mülteci Müslüman olup Osmanlı hizmetine girdi. Olay Tanzimat Osmanlısının Avrupa kamuoyundaki itibarını yükselten nadir diplomatik zaferlerden biri sayıldı.", kaynak:"macaristan", duygu:["🏛"], yer_id:"Vidin" },
{ t:"1849-05-01", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Baltalimanı Sözleşmesi: Eflak ve Boğdan'da ortak Osmanlı-Rus himayesi", gun:"1 Mayıs 1849", yer:"Baltalimanı, İstanbul", kisiler:"Fuad Efendi, Vladimir Titov", d:"1848 ihtilâllerinin Eflak ve Boğdan'a sıçraması üzerine Osmanlı ve Rus kuvvetleri prenslikleri birlikte işgal etmişti. Baltalimanı'nda imzalanan sözleşmeyle voyvodaların seçimle değil padişah tarafından yedi yıllığına tayin edilmesi ve iki devletin bölgede ortak denetim kurması kararlaştırıldı. Anlaşma Osmanlı'nın kâğıt üzerindeki hükümranlığını korurken Rusya'ya fiilî bir ortaklık hakkı tanıdı ve Tuna prensliklerinin Osmanlı'dan kopuşunu hızlandırdı.", kaynak:"eflak", duygu:["🤝"], yer_id:"İstanbul" },
{ t:"1851-02-11", k:"bilim", etiket:["bilim","kultur","islahat","konu-bilim","konu-kultur","konu-islahat"], b:"Encümen-i Dâniş'in kuruluşu: İstanbul'da ilk Osmanlı akademisi", gun:"11 Şubat 1851", yer:"İstanbul (Dârülmaârif, Divanyolu)", kisiler:"Abdülmecid, Mustafa Reşid Paşa, Ahmed Cevdet Paşa", d:"Meclis-i Maârif-i Umûmiyye kararıyla kurulan Encümen-i Dâniş, Türkçe ilim ve ders kitapları hazırlamak üzere teşkil edilmiş ilk Osmanlı bilim akademisidir. 18 Temmuz 1851'de Dârülmaârif binasında törenle açıldı; yerli ve yabancı üyeleri arasında Ahmed Cevdet Paşa da vardı. Kısa ömürlü olmakla birlikte Cevdet Paşa'nın Târih'i ve Kavâid-i Osmâniyye gibi eserleri bu kurumun ürünü oldu ve Türkçenin ilim dili hâline gelmesinde köşe taşı sayıldı.", kaynak:"encumen-i-danis", duygu:["🔬"], yer_id:"İstanbul" },
{ t:"1853-11-11", k:"savas", etiket:["savas","konu-askeri"], b:"Oltenitsa Zaferi: Tuna cephesinde ilk Osmanlı başarısı", gun:"11 Kasım 1853", yer:"Oltenitsa, Eflak (Tuna boyu)", kisiler:"Ömer Lütfi Paşa", d:"Kırım Savaşı'nın açılış safhasında Serdâr-ı Ekrem Ömer Lütfi Paşa, Tuna'yı geçerek Oltenitsa'da Rus kuvvetlerini ağır kayıplarla püskürttü. Zafer, savaşın hemen başında Rus ilerleyişini durdurarak Osmanlı ordusunun Tanzimat sonrası eğitimle kazandığı gücü Avrupa'ya gösterdi. Bu başarı İngiltere ve Fransa'nın Osmanlı yanında savaşa girme kararını kolaylaştıran psikolojik zemini hazırladı.", kaynak:"osmanlilar", duygu:["⚔️"], yer_kon:[44.09,26.64] },
{ t:"1854-03-12", k:"antlasma", etiket:["ittifak","diplomasi","savas","konu-askeri","konu-diplomasi"], b:"İstanbul'da İngiltere ve Fransa ile ittifak antlaşması", gun:"12 Mart 1854", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Abdülmecid, Lord Stratford Canning, Baraguey d'Hilliers", d:"Kırım Savaşı'nda Rusya'ya karşı Osmanlı Devleti ile İngiltere ve Fransa arasında imzalanan ittifak antlaşması, üç devletin ortak harekât yürütmesini ve müttefiklerin savaş bitmeden ayrı barış yapmamasını hükme bağladı. Böylece Osmanlı Devleti tarihinde ilk kez büyük Avrupa devletleriyle eşit taraf sıfatıyla askerî bir ittifaka girdi. Bu antlaşma, iki yıl sonra Paris'te Osmanlı'nın Avrupa devletler sistemine resmen kabulünün de hukukî zeminini oluşturdu.", kaynak:"osmanlilar", duygu:["🤝"] },
{ t:"1855-08-16", k:"siyaset", etiket:["siyaset","diger","islahat","konu-siyasi","konu-islahat"], b:"İstanbul Şehremaneti'nin kurulması: ilk modern belediye teşkilatı", gun:"16 Ağustos 1855", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Abdülmecid, Salih Paşa", d:"Kırım Savaşı sırasında İstanbul'a yığılan müttefik askerleri ve artan nüfusun doğurduğu altyapı krizi, kadılık merkezli klasik şehir idaresinin yetersizliğini açığa çıkardı. Avrupa örneklerine göre kurulan Şehremaneti ile temizlik, narh, çarşı denetimi ve imar işleri tek elde toplandı; ertesi yıl Beyoğlu-Galata'da Altıncı Daire-i Belediye pilot bölge olarak teşkil edildi. Bu adım Osmanlı'da modern belediyeciliğin başlangıcı kabul edilir.", kaynak:"sehremaneti", duygu:["🏛"] },
{ t:"1856-03-30", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Paris Antlaşması: Kırım Savaşı'nın sonu ve Osmanlı'nın Avrupa devletler sistemine kabulü", gun:"30 Mart 1856", yer:"Paris, İsmail, Kahul, Bolgrad, Kili (Güney Besarabya)", yer_id:"İsmail", kisiler:"Âlî Paşa, III. Napolyon, Lord Clarendon", d:"Kırım Savaşı'nı bitiren Paris Antlaşması ile Osmanlı Devleti Avrupa devletler hukukunun eşit üyesi ilan edildi ve toprak bütünlüğü büyük devletlerin ortak garantisine alındı. Karadeniz tarafsızlaştırıldı, Rusya'nın Küçük Kaynarca'dan beri elde ettiği Ortodoks tebaa üzerindeki himaye iddiası geçersiz kılındı, Besarabya'nın güneyi (Kili, Kahul, İsmail ve Bolgrad kazaları) Boğdan'a verildi. Ancak aynı antlaşma Islahat Fermanı'nı uluslararası bir taahhüt hâline getirerek iç işlere müdahalenin de kapısını araladı.", kaynak:"paris-antlasmasi · kili — AYNEN: «Kırım Harbi sonunda imzalanan Paris Antlaşması ile (1856) Rusya, Besarabya’nın Kili dahil Kahul (Cahul, Kahulu), İsmâil ve Bolgrad kazalarından mürekkep kısmını Osmanlı hâkimiyeti altında olmak şartıyla Boğdan beyliğine terketti.» (YIL; gün paris-antlasmasi künyesinden: 30 Mart 1856)", duygu:["🤝"] },
{ t:"1856-06-07", k:"kultur", etiket:["kultur","siyaset","konu-siyasi","konu-kultur","konu-imar"], b:"Dolmabahçe Sarayı'nın açılışı: idare merkezinin Topkapı'dan taşınması", gun:"7 Haziran 1856", yer:"İstanbul, Dolmabahçe", kisiler:"Abdülmecid, Garabet Balyan, Nikoğos Balyan", d:"Abdülmecid'in 1842'de Balyan ailesine sipariş ettiği saray, on dört yıllık inşaatın ardından açıldı ve devletin idare merkezi dört asırlık Topkapı'dan Boğaz kıyısına taşındı. Avrupaî üslûbu, kristal merdiveni ve Muayede Salonu ile saray, Tanzimat'ın Batılılaşma iddiasının taştan ifadesi oldu. Muazzam maliyeti ise Osmanlı maliyesinin dış borçlanma sarmalına girdiği yılların en çok eleştirilen kalemlerinden biri hâline geldi.", kaynak:"dolmabahce-sarayi", duygu:["🎨"], yer_id:"İstanbul" },
{ t:"1859-01-24", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Eflak ve Boğdan'ın Cuza yönetiminde birleşmesi: Romanya'nın doğuşu", gun:"24 Ocak 1859", yer:"Bükreş ve Yaş (Eflak-Boğdan)", kisiler:"Alexandru Ioan Cuza", d:"Paris Antlaşması sonrası düzenlenen seçimlerde iki prenslik de Albay Alexandru Ioan Cuza'yı voyvoda seçerek fiilî birleşmeyi gerçekleştirdi. Bâbıâli ve Avusturya buna karşı çıktıysa da Fransa'nın desteklediği oldubitti kabul edilmek zorunda kalındı. Kâğıt üzerinde Osmanlı'ya bağlı kalan bu birlik 1862'de Romanya adını alacak, 1877'de tek taraflı bağımsızlığını ilan edecekti; Tuna boyundaki Osmanlı hâkimiyetinin çözülüşünde dönüm noktasıdır.", kaynak:"eflak", duygu:["😔"], yer_id:"Bükreş" },
{ t:"1859-09-14", k:"isyan", etiket:["isyan","siyaset","darbe-askeri","konu-siyasi","konu-isyan","konu-darbe"], b:"Kuleli Vak'ası: İstanbul'da Abdülmecid'e karşı ilk darbe girişimi", gun:"14 Eylül 1859", yer:"İstanbul (Kılıç Ali Paşa Camii, Kuleli Kışlası)", kisiler:"Abdülmecid, Şeyh Ahmed, Hüseyin Dâim Paşa", d:"Tanzimat siyasetine ve Islahat Fermanı'nın gayrimüslimlere tanıdığı eşitliğe tepki duyan asker-sivil karışımı gizli bir cemiyet, padişahı tahttan indirmeyi planlarken Kılıç Ali Paşa Camii'ndeki toplantı hâlinde basıldı. Sanıklar Kuleli Kışlası'nda yargılandığı için olay bu adla anıldı; ölüm cezaları sürgüne çevrildi. Osmanlı tarihinde ideolojik gerekçeyle kurulmuş bir örgütün giriştiği ilk saray darbesi teşebbüsü olarak kabul edilir.", kaynak:"kuleli-vakasi", duygu:["✊"], yer_id:"İstanbul" },
{ t:"1860-05-30", k:"isyan", etiket:["isyan","diger","konu-isyan"], b:"Cebel-i Lübnan'da Dürzî-Mârûnî iç savaşı ve Şam olayları", odak_yer:["Sayda","Şam"], gun:"Mayıs 1860", yer:"Cebel-i Lübnan, Şam", kisiler:"Fuad Paşa, Abdülkādir el-Cezâirî", d:"Mayıs 1860'ta Sayda yakınlarında iki Dürzî'nin öldürülmesiyle patlayan çatışmalar, dağdaki en kanlı Dürzî-Mârûnî iç savaşına dönüştü ve Temmuz'da Şam'a sıçrayarak binlerce Hıristiyan'ın ölümüyle sonuçlandı. Fransa'nın asker çıkarması üzerine Bâbıâli, Fuad Paşa'yı olağanüstü yetkiyle bölgeye gönderdi; sert bir tenkil hareketi yürütüldü. Olaylar Avrupa müdahalesine gerekçe oluşturdu ve Lübnan'ın özel statüye kavuşmasının doğrudan sebebi oldu.", kaynak:"lubnan", duygu:["✊"], kapsam_genis:true },
{ t:"1860-10-22", k:"kultur", etiket:["kultur","konu-kultur"], b:"Tercümân-ı Ahvâl'in yayına başlaması: İstanbul'da ilk özel Türkçe gazete", gun:"22 Ekim 1860", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Agâh Efendi, İbrâhim Şinâsi", d:"Agâh Efendi'nin çıkardığı ve Şinâsi'nin yazı işlerini üstlendiği Tercümân-ı Ahvâl, devlet desteği almadan yayımlanan ilk Türkçe gazetedir. İlk sayısındaki mukaddimede halkın kendi işleri hakkında söz söyleme hakkı savunulmuş, gazete Şinâsi'nin Şair Evlenmesi'ni tefrika ederek modern Türk edebiyatının da kapısını aralamıştır. Osmanlı'da kamuoyu kavramının ve muhalif basının doğuşu bu tarihe dayandırılır.", kaynak:"tercuman-i-ahval", duygu:["🎨"] },
{ t:"1861-06-09", k:"siyaset", etiket:["siyaset","diplomasi","islahat","konu-siyasi","konu-diplomasi","konu-islahat","konu-hukuk"], b:"Cebel-i Lübnan Nizamnâmesi: Lübnan'a imtiyazlı mutasarrıflık statüsü", gun:"9 Haziran 1861", yer:"Cebel-i Lübnan", kisiler:"Fuad Paşa, Dâvud Paşa", d:"1860 katliamlarının ardından büyük devletlerin baskısıyla hazırlanan nizamnâme, Cebel-i Lübnan'ı doğrudan Bâbıâli'ye bağlı, mezhepler arası dengeye göre kurulan bir idare meclisiyle yönetilen imtiyazlı mutasarrıflık hâline getirdi. Mutasarrıfın Osmanlı tebaası bir Katolik Hıristiyan olması ve tayininin büyük devletlerin onayına sunulması şart koşuldu; ilk mutasarrıf Dâvud Paşa oldu. Bu düzen 1915'e kadar sürecek ve modern Lübnan devletinin çekirdeğini oluşturacaktı.", kaynak:"lubnan", duygu:["🏛","😔"], kapsam_genis:true },
{ t:"1861-06-25", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"Abdülmecid'in vefatı ve Sultan Abdülaziz'in cülûsu", gun:"25 Haziran 1861", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Abdülmecid, Abdülaziz, Âlî Paşa, Fuad Paşa", d:"Yirmi iki yıllık saltanatında Tanzimat ve Islahat fermanlarına imza atan Abdülmecid'in vereme yenik düşmesi üzerine kardeşi Abdülaziz tahta çıktı. Yeni padişah ilk yıllarda tasarruf tedbirleriyle ve sade yaşayışıyla umut verdi; donanmayı dünyanın sayılı güçlerinden biri hâline getirdi. Ancak saltanatının sonunda ağır dış borç, 1875 iflası ve Balkan isyanları birikerek 1876'daki hal' hareketine zemin hazırlayacaktı.", kaynak:"abdulaziz", vefat_id:"abdulmecid", duygu:["🏛"] },
{ t:"1862-02-21", k:"kayip", etiket:["siyaset","konu-askeri","konu-siyasi"], b:"Birleşik prensliklerin Romanya adını alması", gun:"21 Şubat 1862", yer:"Bükreş", yer_id:"Bükreş", kisiler:"Alexandru Ioan Cuza", d:"1859'da Cuza'nın çifte seçilmesiyle fiilen birleşen Eflak ve Boğdan, 1862'de meclislerini ve hükümetlerini Bükreş'te tek çatı altında toplayarak resmen Romanya adını aldı. Osmanlı Devleti hukuken metbû sıfatını ve yıllık vergiyi korusa da prenslik üzerindeki denetimini fiilen kaybetti. Tuna'nın kuzeyindeki dört asırlık Osmanlı nüfuzunun sona erişi bu tarihle simgelenir.", kaynak:"romanya", duygu:["😔"] },
{ t:"1865-01-01", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Sevâkin, Masavva ve Dahlak'ın Mısır'a bağlanması", gun:"1865", yer:"Sevâkin, Masavva, Dahlak (Habeş kıyısı)", kisiler:"Hidiv İsmâil Paşa", d:"1846'da Sultan Abdülmecid tarafından Mısır Hidivi Mehmed Ali Paşa'ya Sevâkin ile birlikte sâlyâne (gelir tahsisi) olarak verilmiş olan Masavva, Hidiv İsmâil Paşa zamanında Dahlak ve Sevâkin ile birlikte Mısır emlâkine dahil edilerek kaymakamlık statüsünde teşkilâtlandırıldı. Böylece Kızıldeniz'in Afrika kıyısındaki bu üç liman, hukuken Osmanlı toprağı kalmakla birlikte idareten doğrudan Bâbıâli'den Kahire'ye geçti — komşusu Mısır ve Sudan'la aynı tâbi katmana girdi.", statu_vasal:["Sevâkin","Masavva","Dahlak"], kaynak:"masavva", duygu:["😔"], yer_id:"Sevâkin" },
{ t:"1866-08-21", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Girit İsyanı'nın başlaması (1866-1869)", gun:"1866", yer:"Girit", yer_id:"Girit (Resmo)", kisiler:"Abdülaziz, Ömer Lütfi Paşa, Âlî Paşa", d:"Yunanistan'ın açık desteğiyle adada patlak veren geniş çaplı ayaklanma, Girit Rumlarının enosis (Yunanistan'a katılma) talebini ilk kez uluslararası bir mesele hâline getirdi. Üç yıl süren çetin dağ savaşı Osmanlı ordusuna ağır kayıplar verdirdi, Avrupa kamuoyunda büyük yankı uyandırdı. İsyan ancak 1868'de Âlî Paşa'nın adaya gidip geniş imtiyazlar tanıyan nizamnâmeyi yürürlüğe koymasıyla sönümlenebildi.", kaynak:"girit", duygu:["✊"] },
{ t:"1867-04-18", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Belgrad ve Sırbistan kalelerindeki son Osmanlı garnizonlarının çekilmesi", gun:"18 Nisan 1867", yer:"Belgrad, Semendire, Böğürdelen, Fethülislâm", kisiler:"Abdülaziz, Mihailo Obrenović, Âlî Paşa", d:"Büyük devletlerin baskısı ve Prens Mihailo'nun ısrarlı talebi üzerine Bâbıâli, Sırbistan'da elinde kalan son askerî üsleri boşaltmayı kabul etti; 18 Nisan 1867'de Belgrad Kalesi'ndeki Osmanlı sancağı indirilerek anahtarlar prense teslim edildi. Böylece 1521'den beri süren fiilî Osmanlı askerî varlığı sona erdi ve Sırbistan'ın bağımsızlığa giden yolunda son büyük engel kalktı. Padişahın metbûluğu yalnız sembolik bir bayrak ve vergi meselesine indirgendi.", statu_vasal:["Semendire","Belgrad","Böğürdelen (Šabac)"], kaynak:"sirbistan", duygu:["😔"], yer_id:"Belgrad" },
{ t:"1867-06-08", k:"siyaset", etiket:["siyaset","diger","konu-siyasi"], b:"Mısır valilerine hidiv unvanının verilmesi", gun:"8 Haziran 1867", yer:"Kahire, İstanbul", kisiler:"Abdülaziz, İsmâil Paşa", d:"Kavalalı hanedanının üçüncü kuşağından İsmâil Paşa'nın yoğun lobisi ve İstanbul'a akıttığı paralar sonucunda Mısır valisine, diğer valilerden üstün olduğunu vurgulayan hidiv unvanı verildi. Aynı yıllarda veraset usulü de babadan oğula geçecek biçimde değiştirildi ve Mısır'a dış borçlanma, madalya verme, konsolosluk bulundurma gibi hükümranlık nitelikli yetkiler tanındı. Bu adımlar Mısır'ın Osmanlı'dan hukuken kopuşunu hızlandıran zincirin ilk halkasıdır.", kaynak:"hidiv", duygu:["🏛"], yer_id:"Kahire" },
{ t:"1868-01-04", k:"siyaset", etiket:["siyaset","isyan","islahat","konu-siyasi","konu-isyan","konu-islahat","konu-hukuk"], b:"Girit Nizamnâmesi: adaya geniş idarî imtiyazlar", odak_yer:["Hanya","Kandiye (Girit)"], gun:"4 Ocak 1868", yer:"Girit (Hanya, Kandiye)", kisiler:"Abdülaziz, Âlî Paşa", d:"Üç yıllık isyanı sona erdirmek için Sadrazam Âlî Paşa bizzat adaya geçti ve padişahın onayıyla yayımlanan nizamnâmeyle Giritlilere karma idare meclisleri, mahallî mahkemeler, Rumca'nın resmî muamelelerde kullanılması ve vergi kolaylıkları tanındı. Bu düzenleme adada Osmanlı hâkimiyetini otuz yıl daha ayakta tuttu. Ancak Hıristiyan nüfusa tanınan ayrıcalıklar Müslüman Giritlilerin konumunu zayıflattı ve 1896-1898 krizinin tohumlarını attı.", kaynak:"girit", duygu:["🏛"], kapsam_genis:true },
{ t:"1868-05-10", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"Şûrâ-yı Devlet'in açılışı: Osmanlı Danıştayı'nın kuruluşu", gun:"10 Mayıs 1868", yer:"İstanbul (Bâbıâli)", kisiler:"Abdülaziz, Âlî Paşa, Midhat Paşa", d:"5 Mart 1868 tarihli iradeyle Meclis-i Ahkâm-ı Adliyye ikiye ayrılarak idarî-teşriî işler Şûrâ-yı Devlet'e, yargı işleri Dîvân-ı Ahkâm-ı Adliyye'ye bırakıldı; kurum Bâbıâli'de törenle açıldı ve ilk başkanlığına Midhat Paşa getirildi. Kanun tasarılarını hazırlamak, idarî uyuşmazlıkları çözmek ve memur yargılamalarını yürütmekle görevlendirildi. Müslim-gayrimüslim karma üye yapısıyla Osmanlı'da kuvvetler ayrılığı fikrinin ilk kurumsal uygulaması sayılır.", kaynak:"sura-yi-devlet", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1869-11-17", k:"kesif", etiket:["ekonomi","bilim","diplomasi","konu-diplomasi","konu-bilim","konu-ekonomi","konu-ulastirma","konu-kesif"], b:"Süveyş Kanalı'nın açılışı: Mısır üzerinden Hint yolunun kısalması", gun:"17 Kasım 1869", yer:"Süveyş, Port Said, İsmâiliye (Mısır)", kisiler:"Ferdinand de Lesseps, Hidiv İsmâil Paşa, İmparatoriçe Eugénie", d:"1859'da başlayan inşaat on yıl sürdü ve Akdeniz'i Kızıldeniz'e bağlayan 163 kilometrelik kanal görkemli bir törenle hizmete girdi. Avrupa'yı Hindistan'a bağlayan yol binlerce mil kısalınca Mısır bir anda dünya ticaretinin kilit noktası hâline geldi. Bu jeostratejik değer, kanalın açılışından on üç yıl sonra İngiltere'nin Mısır'ı işgal etmesinin başlıca sebebi olacak; kanalın Mısır'a yüklediği borç ise hidivliği iflasa sürükleyecekti.", kaynak:"suveys", duygu:["🧭"], yer_id:"Süveyş" },
{ t:"1870-03-11", k:"siyaset", etiket:["siyaset","diger","konu-siyasi","konu-din"], b:"Bulgar Eksarhlığı'nın kurulması: Bulgar kilisesinin Fener'den ayrılması", gun:"11 Mart 1870", yer:"İstanbul, Tuna vilâyeti", kisiler:"Abdülaziz, Âlî Paşa", d:"Padişah fermanıyla Rum Patrikhanesi'nden ayrı, müstakil bir Bulgar kilisesi (eksarhlık) kuruldu ve hangi kazaların eksarhlığa bağlanacağı halk oylamasına bırakıldı. Bâbıâli bu adımı Rum nüfuzunu kırmak için attıysa da sonuç tersine işledi: kilise, Bulgar millî kimliğinin ve Makedonya üzerindeki Bulgar iddiasının örgütlü merkezine dönüştü. Balkanlar'daki Bulgar-Rum-Sırp rekabetinin ve 1876 isyanlarının kurumsal zemini böylece atılmış oldu.", kaynak:"bulgaristan", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1871-04-20", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Midhat Paşa'nın Necid seferi: Lahsâ'da Osmanlı hâkimiyetinin yeniden kurulması", gun:"20 Nisan 1871", yer:"Lahsâ (Ahsâ), Necid, Basra", kisiler:"Midhat Paşa, Nâfiz Paşa, Abdullah b. Faysal", d:"Bağdat valisi Midhat Paşa, Suûdî ailesi içindeki taht kavgasından yararlanarak Basra Körfezi'nin batı kıyısına asker sevk etti ve Lahsâ bölgesini Necid sancağı adıyla Basra vilâyetine bağladı. Abdullah b. Faysal mutasarrıf tayin edilerek Osmanlı hâkimiyeti kâğıt üzerinde tesis edildi. Sefer, körfezde İngiliz nüfuzunun yayılmasını durdurma amacı taşıyordu ve aynı yıl Katar'ın da Osmanlı denetimine girmesine yol açtı.", kaynak:"lahsa", duygu:["🎉"], yer_id:"Lahsa" },
{ t:"1871-09-20", k:"fetih", etiket:["toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Katar'da Osmanlı kontrolünün kurulması", gun:"Sonbahar 1871", yer:"Katar (Bidâ/Doha)", kisiler:"Şeyh Kāsım b. Muhammed b. Sânî, Midhat Paşa", d:"İngiliz baskısı altındaki Şeyh Kāsım b. Sânî'nin daveti üzerine Osmanlı kuvvetleri Katar yarımadasına çıktı ve 1871 sonbaharında bölgede Osmanlı kontrolü sağlandı. Katar, Necid sancağına bağlı bir kaza olarak teşkilatlandırıldı ve şeyh kaymakam tayin edildi. Bu hamle, Midhat Paşa'nın körfezde İngiltere'ye karşı yürüttüğü ileri siyasetin en somut kazanımı oldu; Osmanlı bayrağı yarımadada 1913'e kadar dalgalandı.", kaynak:"katar", duygu:["🎉"], yer_id:"Doha (Katar)" },
{ t:"1871-09-07", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-kisiler","konu-burokrasi","konu-islahat"], b:"Sadrazam Âlî Paşa'nın vefatı: Tanzimat kadrosunun sonu", gun:"7 Eylül 1871", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Mehmed Emin Âlî Paşa, Abdülaziz, Mahmud Nedim Paşa", d:"Fuad Paşa'nın 1869'daki ölümünün ardından Tanzimat siyasetini tek başına omuzlayan Âlî Paşa'nın vefatıyla, devletin dış siyasetini otuz yıl yöneten usta diplomat kuşağı tükendi. Yerine gelen Mahmud Nedim Paşa'nın Rus yanlısı ve keyfî idaresi, Abdülaziz'in şahsî yönetimini pekiştirdi. Âlî Paşa'nın ölümünden sonraki beş yıl içinde maliye iflas etti, Balkanlar ayaklandı ve saltanat değişikliği kaçınılmaz hâle geldi.", kaynak:"ali-pasa-mehmed-emin", duygu:["🏛"] },
{ t:"1872-04-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"San'a'nın alınışı: Yemen'de Osmanlı otoritesinin yeniden kurulması", gun:"1872", yer:"San'a, Yemen", kisiler:"Ahmed Muhtar Paşa", d:"Süveyş Kanalı'nın açılmasıyla Kızıldeniz'in stratejik değeri artınca Bâbıâli Yemen'e Ahmed Muhtar Paşa kumandasında fırka-i ihtiyâtiyye ordusunu sevk etti. San'a'nın alınmasıyla iki yüzyıldır fiilen kaybedilmiş olan iç Yemen'de devlet otoritesi yeniden tesis edildi ve bölge vilâyet hâline getirildi. Ancak Zeydî imamlarla mücadele hiç bitmedi; 1891, 1898 ve 1904 isyanları Osmanlı'nın en pahalı ve en uzun süren iç cephesini oluşturdu. Aynı tarihte katılan öteki yerler: Sana, Taiz.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"yemen", duygu:["🎉"], yer_id:"Sana" },
{ t:"1875-10-06", k:"siyaset", etiket:["ekonomi","siyaset","konu-siyasi","konu-ekonomi"], b:"Osmanlı maliyesinin iflası: dış borç ödemelerinin yarıya indirilmesi", gun:"1875", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Abdülaziz, Mahmud Nedim Paşa", d:"1854'ten beri üst üste alınan istikrazlar, Kırım Savaşı masrafları, saray inşaatları ve 1873-74 Anadolu kıtlığı bütçe açığını beş milyon lirayı aşan bir uçuruma çevirdi. Mahmud Nedim Paşa hükümeti, borç faiz ve anapara ödemelerinin beş yıl süreyle yarıya indirileceğini ilan ederek fiilen moratoryum ilan etti. Avrupa borsalarında büyük tepki uyandıran bu karar, altı yıl sonra Muharrem Kararnâmesi ve Düyûn-ı Umûmiyye İdaresi'nin kurulmasıyla sonuçlanacak süreci başlattı.", kaynak:"duyun-i-umumiyye", duygu:["🏛"] },
{ t:"1875-06-19", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Hersek İsyanı'nın başlaması: Şark Meselesi'nin yeniden alevlenmesi", gun:"19 Haziran 1875", yer:"Hersek (Nevesinje, Mostar)", kisiler:"Abdülaziz, Server Paşa", d:"Ağır vergiler ve âyan baskısı yüzünden Nevesinje çevresindeki Hıristiyan köylülerin ayaklanması kısa sürede tüm Hersek'e yayıldı ve Sırbistan ile Karadağ'dan gelen gönüllülerle beslendi. Avusturya ve Rusya'nın reform dayatmalarına yol açan isyan, ertesi yıl Bulgar ayaklanmalarını ve Sırp-Karadağ savaş ilanlarını tetikledi. Böylece 93 Harbi'ne ve Berlin Antlaşması'yla Balkanlar'ın kaybına götüren büyük zincirin ilk halkası kırıldı.", kaynak:"bosna-hersek", duygu:["✊"], yer_id:"Mostar" },
{ t:"1876-08-31", k:"siyaset", etiket:["siyaset","darbe-siyasi","konu-siyasi","konu-darbe","konu-hanedan"], b:"V. Murad'ın hal'i ve II. Abdülhamid'in cülûsu", gun:"31 Ağustos 1876", yer:"İstanbul", yer_id:"İstanbul", kisiler:"V. Murad, II. Abdülhamid, Midhat Paşa", d:"Abdülaziz'in tahttan indirilmesinden sonra tahta çıkan V. Murad, amcasının ölümü ve Çerkes Hasan Vak'ası'nın sarstığı ruh sağlığı sebebiyle görev yapamaz hâle geldi; doksan üç günlük saltanatının ancak yedi gününde muhakemesi yerindeydi. Şeyhülislâm fetvasıyla hal'edilerek yerine kardeşi II. Abdülhamid getirildi. Yeni padişah tahta, Midhat Paşa'ya meşrutiyeti ilan edeceği sözünü vererek çıktı; otuz üç yıl sürecek bir devir başlıyordu.", kaynak:"murad-v", duygu:["🏛"] },
{ t:"1876-12-23", k:"diger", etiket:["diplomasi","siyaset","islahat","konu-siyasi","konu-diplomasi","konu-islahat"], b:"Tersane Konferansı: büyük devletlerin Balkan reform dayatması", gun:"23 Aralık 1876", yer:"İstanbul (Haliç Tersanesi)", kisiler:"II. Abdülhamid, Midhat Paşa, Lord Salisbury, Kont İgnatyev", d:"Balkan krizini çözmek üzere büyük devletlerin İstanbul'da topladığı konferans, Bulgaristan'ın iki özerk vilâyete ayrılmasını ve Bosna-Hersek'e uluslararası denetimli reform uygulanmasını istedi. Bâbıâli, konferansın açıldığı gün top atışlarıyla Kanûn-ı Esâsî'nin ilanını duyurarak dayatmaları anayasal reformla karşılamaya çalıştı. Delegeler bunu oyalama sayıp 20 Ocak 1877'de dağıldı; dört ay sonra Rusya savaş ilan etti.", kaynak:"tersane-konferansi", duygu:["📌"], yer_id:"İstanbul" },
{ t:"1877-03-19", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"İlk Meclis-i Meb'ûsan'ın Dolmabahçe'de açılışı", gun:"19 Mart 1877", yer:"İstanbul (Dolmabahçe Sarayı, Muayede Salonu)", kisiler:"II. Abdülhamid, Ahmed Vefik Paşa, Midhat Paşa", d:"Kanûn-ı Esâsî uyarınca seçilen 115 mebus, 19 Mart 1877'de Dolmabahçe Sarayı'nın Muayede Salonu'nda yapılan törenle ilk kez toplandı; böylece Osmanlı tarihinde temsilî meclis dönemi başladı. Müslüman ve gayrimüslim mebuslar hükümeti sert biçimde sorguladı, savaşın yönetimini ve nâzırların sorumluluğunu tartıştı. Bu cesur muhalefet, meclisin ömrünü kısaltan başlıca sebep olacaktı.", kaynak:"meclis-i-mebusan", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1877-07-19", k:"savas", etiket:["savas","konu-askeri"], b:"Plevne savunmasının başlaması: Gazi Osman Paşa'nın direnişi", gun:"19 Temmuz 1877", ic_not_gun:"A2 §4b: TDV gazi-osman-pasa: Plevne'ye 7 Temmuz 1877'de ulaştı, I. Plevne 8 Temmuz, II. Plevne 18 Temmuz. Üç günde de madde/kronoloji_balkan ile tam 12 gün fark (19 · 20-21 · 30 Temmuz) = XIX. yy Jülyen/Rumî-Gregoryen farkı; TDV tarihlerinin Rumî/Jülyen olduğu akademik kaynakla ÖLÇÜLMEDİ. t korundu (ekokuma_savas '1877-07-19|Plevne savunmasının' bağı)", yer:"Plevne, Bulgaristan", kisiler:"Gazi Osman Paşa, Çar II. Aleksandr", d:"93 Harbi'nde Tuna'yı geçen Rus ordusunun İstanbul yolunu kesmek üzere Vidin'den Plevne'ye yürüyen Osman Paşa, kasabayı tabya ve siperlerle tahkim ederek beş aylık efsanevî bir savunma başlattı. Üst üste üç büyük Rus-Romen taarruzu ağır kayıplarla püskürtüldü ve Çar II. Aleksandr'ın bizzat idare ettiği ordu kuşatmaya mecbur kaldı. Plevne, Osmanlı ordusunun 19. yüzyıldaki en parlak savunma başarısı olarak tarihe geçti.", ic_not_d:"eski kaynak: plevne", kaynak:"gazi-osman-pasa · plevne-muharebeleri", duygu:["⚔️"], yer_id:"Plevne" },
{ t:"1877-12-10", k:"kayip", etiket:["savas","toprak-kayip","konu-askeri"], b:"Plevne'nin düşüşü: Tuna cephesinin çöküşü", gun:"10 Aralık 1877", yer:"Plevne, Bulgaristan", kisiler:"Gazi Osman Paşa, Çar II. Aleksandr", d:"Beş aylık kuşatmada erzakı tükenen Osman Paşa, Vid nehri üzerinden huruç harekâtına girişti; yaralanıp esir düşünce şehir teslim oldu. Rus kumandanları esir aldıkları paşayı kılıcını iade ederek selamladı ve Osman Paşa'ya 'Gazi' unvanı verildi. Plevne'nin düşüşüyle Rus ordusunun önü açıldı; iki ay içinde Sofya, Filibe ve Edirne düştü, Rus öncüleri Yeşilköy'e ulaştı.", kaynak:"plevne", duygu:["😔"], yer_id:"Plevne" },
{ t:"1878-01-04", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Sofya'nın Rus kuvvetlerince işgali", gun:"3 Ocak 1878", ic_not_gun:"eski gun: 3 Ocak 1878 (TDV) — kayıttaki tarih 4 Ocak, bir gün fark", yer:"Sofya", yer_id:"Sofya", kisiler:"General Gurko, II. Abdülhamid", d:"Plevne'nin düşüşünden sonra Balkanlar'ı aşan Rus ordusu, savunmasız kalan Sofya'ya girdi. Şehir bir daha Osmanlı idaresine dönmeyecek, 1878 sonunda özerk Bulgaristan Prensliği'nin, 1879'da fiilen başşehri olacaktı. Haritada Sofya bu tarihten itibaren Osmanlı doğrudan idaresinden çıkıp geçici Rus işgaline, ardından özerk Bulgar yönetimine geçer.", statu_vasal:["Sofya"], kaynak:"sofya", duygu:["😔"] },
{ t:"1878-01-31", k:"antlasma", etiket:["antlasma","savas","konu-askeri","konu-diplomasi"], b:"Edirne Mütarekesi: 93 Harbi'nde silahların susması", gun:"31 Ocak 1878", yer:"Edirne", yer_id:"Edirne", kisiler:"Namık Paşa, Server Paşa, Grandük Nikolay", d:"Sofya, Filibe ve Edirne'nin peş peşe düşmesi ve Rus ordusunun Marmara kıyılarına dayanması üzerine Bâbıâli mütareke istemek zorunda kaldı. Edirne'de imzalanan ateşkes, Bulgaristan'a özerklik, Karadağ-Sırbistan-Romanya'nın bağımsızlığı ve ağır savaş tazminatı gibi ön barış şartlarını Osmanlı'ya kabul ettirdi. Bu şartlar bir ay sonra Ayastefanos'ta antlaşma metnine dönüşecekti.", kaynak:"ayastefanos-antlasmasi", duygu:["🤝"] },
{ t:"1878-02-13", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"II. Abdülhamid'in Meclis-i Meb'ûsan'ı süresiz tatil etmesi", gun:"13 Şubat 1878", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Abdülhamid, Astarcılar Kethüdâsı Ahmed Efendi", d:"Savaşın felaketle sonuçlanmasından hükümeti ve sarayı sorumlu tutan mebusların sert eleştirileri üzerine II. Abdülhamid, Kanûn-ı Esâsî'nin kendisine tanıdığı yetkiye dayanarak meclisi süresiz tatil etti. Yaklaşık on bir ay çalışan ilk Osmanlı parlamentosu böylece kapandı ve otuz yıl sürecek istibdat devri başladı. Meclis ancak 1908 İhtilâli'nden sonra yeniden toplanabilecekti.", kaynak:"meclis-i-mebusan", duygu:["🏛"] },
{ t:"1878-03-03", k:"antlasma", etiket:["antlasma","konu-diplomasi"], b:"Ayastefanos Antlaşması: Büyük Bulgaristan tasarısı", gun:"3 Mart 1878", yer:"Ayastefanos (Yeşilköy), İstanbul", kisiler:"Safvet Paşa, Sadullah Bey, Kont İgnatyev", d:"93 Harbi'ni bitiren Ayastefanos Antlaşması, Ege'ye kadar uzanan ve Makedonya'yı içine alan devasa bir özerk Bulgaristan kuruyor; Sırbistan, Karadağ ve Romanya'nın bağımsızlığını tanıyor; Kars, Ardahan, Batum ve Doğubayazıt'ı Rusya'ya bırakıyor, ayrıca ödenmesi imkânsız bir savaş tazminatı yüklüyordu. Rusya'yı Akdeniz'e indiren bu metin İngiltere ve Avusturya'nın şiddetli tepkisini çekti. Uygulanmadan dört ay içinde Berlin Kongresi'yle yeniden düzenlendi; yine de Osmanlı Rumelisi'nin sonunu ilan eden belge olarak kaldı.", kaynak:"ayastefanos-antlasmasi", duygu:["🤝"], yer_id:"Kars" },
{ t:"1878-07-29", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Bosna-Hersek ve Yenipazar'ın Avusturya-Macaristan tarafından işgali", gun:"29 Temmuz 1878", yer:"Saraybosna, Mostar, Yenipazar", kisiler:"Josip Filipović, Hacı Loyo, II. Abdülhamid", d:"Berlin Antlaşması'nın verdiği yetkiye dayanarak Avusturya-Macaristan orduları Bosna'ya girdi; Osmanlı hükümeti direnmemeyi kabul etmesine rağmen Saraybosna ve Mostar'daki yerli Müslüman-Ortodoks halk silaha sarılarak üç ay boyunca çetin bir mukavemet gösterdi. İşgal ancak 20 Ekim 1878'de tamamlanabildi. Padişahın hukukî hükümranlığı 1908'e kadar kâğıt üzerinde sürdü, ancak dört asırlık Osmanlı Bosnası fiilen elden çıktı ve büyük bir Müslüman göç dalgası başladı. Aynı tarihte elden çıkan diğer yerleşimler: Banaluka.", kaynak:"bosna-hersek", duygu:["😔"], yer_id:"Saraybosna" },
{ t:"1881-12-20", k:"siyaset", etiket:["ekonomi","siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-ekonomi"], b:"Muharrem Kararnâmesi ve Düyûn-ı Umûmiyye İdaresi'nin kuruluşu", gun:"20 Aralık 1881", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Abdülhamid, Server Paşa", d:"1875 iflasından sonra alacaklı devletlerin temsilcileriyle yürütülen görüşmeler, 28 Muharrem 1299 (20 Aralık 1881) tarihli kararnâmeyle sonuçlandı: borç anaparası yarıdan fazla indirildi, buna karşılık tuz, tütün, ipek, damga ve balık resimleri gibi en verimli gelir kalemleri doğrudan alacaklıların yönettiği Düyûn-ı Umûmiyye İdaresi'ne devredildi. Binlerce memur çalıştıran bu idare, devlet içinde ayrı bir maliye teşkilatına dönüştü. Osmanlı malî bağımsızlığının fiilen sona erdiği tarih kabul edilir.", kaynak:"duyun-i-umumiyye", duygu:["🏛"] },
{ t:"1884-02-01", k:"diger", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"Sevâkin — Mehdî'ye düşmeyen tek liman", gun:"Şubat 1884", yer:"Sevâkin, Habeş kıyısı", kisiler:"Muhammed Ahmed el-Mehdî, General Gerald Graham", d:"1884 Şubatından itibaren Sevâkin dışındaki bütün doğu Sudan bölgeleri Muhammed Ahmed el-Mehdî'nin hâkimiyetine geçerken, liman General Graham kumandasındaki üç taburluk İngiliz kuvvetinin askerî korumasıyla ayakta kaldı. Bu, fiilî ile hukukî durumun ayrıştığı bir dönemin başlangıcıydı: kıyı fiilen İngiliz askerî denetiminde olsa da idarî bağı 1885'te Mısır'dan alınıp doğrudan Yemen vilâyetine, yani Bâbıâli'ye bağlanacaktı — o düzen 1888'de Fransa'nın Zeylâ'yı işgaliyle sona erene kadar sürdü.", kaynak:"muhammed-ahmed-el-mehdi", duygu:["📌"], yer_id:"Sevâkin" },
{ t:"1884-05-08", k:"siyaset", etiket:["siyaset","suikast","konu-siyasi","konu-kisiler"], b:"Midhat Paşa'nın Tâif zindanında öldürülmesi", gun:"7-8 Mayıs 1884 gecesi", yer:"Tâif, Hicaz", kisiler:"Midhat Paşa, II. Abdülhamid", d:"Kanûn-ı Esâsî'nin mimarı ve I. Meşrutiyet'in sembol ismi Midhat Paşa, Abdülaziz'in ölümüyle ilgili Yıldız Mahkemesi'nde suçlu bulunup idam cezası sürgüne çevrilerek Tâif'e gönderilmişti. TDV kaydına göre 7-8 Mayıs 1884 gecesi hücresinde boğularak öldürüldü, resmî sebep 'şîrpençe' hastalığı olarak açıklandı. Ölümü, II. Abdülhamid devrinde anayasal muhalefetin tasfiyesinin simgesi hâline geldi.", kaynak:"midhat-pasa", duygu:["🏛"], yer_id:"Tâif" },
{ t:"1888-09-24", k:"diger", etiket:["ekonomi","diplomasi","islahat","konu-diplomasi","konu-ekonomi","konu-islahat","konu-ulastirma"], b:"Haydarpaşa-Ankara demiryolu imtiyazının Almanlara verilmesi", gun:"24 Eylül 1888", yer:"İstanbul, Haydarpaşa-İzmit-Ankara hattı", kisiler:"II. Abdülhamid, Alfred von Kaulla, Deutsche Bank", d:"Padişah iradesiyle Haydarpaşa-Ankara hattının yapım ve işletme imtiyazı, Deutsche Bank'ı temsil eden bankacı Alfred von Kaulla'ya verildi ve Anadolu Demiryolu Şirketi kuruldu. Bu imtiyaz, Osmanlı ulaşım ve dış siyasetinde İngiliz-Fransız tekelini kırıp Alman nüfuzunu yerleştiren dönüm noktası oldu. On bir yıl sonra aynı şirkete verilecek Bağdat hattı imtiyazıyla birlikte 'Berlin-Bağdat' hayali doğacak, bu da I. Dünya Savaşı öncesi büyük güç rekabetinin ana eksenlerinden biri hâline gelecekti.", kaynak:"bagdat-demiryolu", duygu:["📌"], yer_id:"İstanbul" },
{ t:"1889-06-02", k:"siyaset", etiket:["siyaset","konu-siyasi"], b:"İttihâd-ı Osmânî Cemiyeti'nin İstanbul'da kuruluşu", gun:"2 Haziran 1889", yer:"İstanbul (Mekteb-i Tıbbiyye-i Şâhâne)", kisiler:"İbrâhim Temo, Abdullah Cevdet, İshak Sükûtî, Mehmed Reşid", d:"Askerî Tıbbiye'nin dört öğrencisi, istibdat idaresine karşı gizli bir örgüt olarak İttihâd-ı Osmânî Cemiyeti'ni kurdu; bu yapı kısa sürede Jön Türk hareketinin bütün muhalif unsurlarını çatısı altında toplayacak olan İttihat ve Terakkî Cemiyeti'ne dönüştü. Hücre esasına dayanan örgütlenme Avrupa'daki sürgünlerle ve Selanik'teki subaylarla birleşti. 1908'de II. Meşrutiyet'i ilan ettirecek, 1913'ten sonra devleti tek başına yönetecek kadro bu küçük öğrenci hücresinden çıktı.", kaynak:"ittihat-ve-terakki-cemiyeti", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1896-08-26", k:"isyan", etiket:["isyan","siyaset","konu-siyasi","konu-isyan"], b:"Osmanlı Bankası Baskını: Taşnak eylemcilerinin Galata eylemi", gun:"26 Ağustos 1896", yer:"İstanbul, Galata", kisiler:"II. Abdülhamid, Babken Siuni, Armen Garo", d:"Ermeni Taşnaksutyun örgütünün silahlı bir grubu, Avrupa'nın dikkatini Ermeni meselesine çekmek amacıyla Galata'daki Osmanlı Bankası genel merkezini basıp rehin aldı ve binayı havaya uçurmakla tehdit etti. Kriz, büyükelçilerin araya girmesiyle eylemcilerin bir gemiyle ülkeden çıkarılması karşılığında sona erdi. Baskını izleyen günlerde İstanbul'da yaşanan kanlı olaylar, Ermeni meselesinin uluslararası bir müdahale kaldıracına dönüşmesinde belirleyici oldu.", kaynak:"abdulhamid-ii", duygu:["✊"], yer_id:"İstanbul" },
{ t:"1897-04-17", k:"savas", etiket:["savas","konu-askeri"], b:"1897 Osmanlı-Yunan Savaşı'nın başlaması: Teselya cephesi", gun:"17 Nisan 1897", yer:"Teselya, Epir, Girit", kisiler:"II. Abdülhamid, Edhem Paşa, Prens Konstantin", d:"Yunanistan'ın Girit'e donanma ve asker çıkarması ile Rumeli sınırındaki çete saldırıları üzerine Osmanlı Devleti savaş ilan etti. Alman ıslahat heyetinin eğittiği Osmanlı ordusu Teselya'da hızla ilerleyerek bir ay içinde Yenişehir, Çatalca ve Dömeke'yi aldı; Yunan ordusu dağıldı. Büyük devletlerin araya girmesiyle kazanılan topraklar iade edildi, ancak savaş II. Abdülhamid devrinin tek kesin askerî zaferi olarak kaldı ve Girit'in fiilî kaybını önleyemedi.", kaynak:"yunanistan", duygu:["⚔️"], yer_id:"Yenişehir (Larissa)" },
{ t:"1899-11-27", k:"diger", etiket:["ekonomi","diplomasi","konu-diplomasi","konu-ekonomi"], b:"Konya-Bağdat hattı imtiyazının Almanlara verilmesi", gun:"1899", yer:"Konya-Halep-Musul-Bağdat hattı", kisiler:"II. Abdülhamid, Deutsche Bank, Kayzer II. Wilhelm", d:"Kayzer II. Wilhelm'in 1898'deki İstanbul ve Şam ziyaretinin ardından Anadolu Demiryolu Şirketi'ne Konya'dan Bağdat ve Basra'ya uzanacak hattın ön imtiyazı verildi. Bağdat Demiryolu projesi, Osmanlı için Arap vilâyetleri üzerindeki merkezî denetimi güçlendirme, Almanya için ise Basra Körfezi'ne ulaşma anlamına geliyordu. İngiltere ve Rusya'nın şiddetle karşı çıktığı bu proje, I. Dünya Savaşı'na giden emperyalist rekabetin en tartışmalı dosyalarından biri oldu.", kaynak:"bagdat-demiryolu", duygu:["📌"], kapsam_genis:true, yer_id:"İstanbul" },
{ t:"1900-09-01", k:"diger", etiket:["ekonomi","kultur","islahat","imar","konu-ekonomi","konu-kultur","konu-imar","konu-islahat","konu-ulastirma"], b:"Hicaz Demiryolu inşaatının Şam'da başlaması", gun:"1 Eylül 1900", yer:"Şam, Maan, Medine", kisiler:"II. Abdülhamid, Meissner Paşa, Ahmed İzzet Paşa", d:"II. Abdülhamid'in 2 Mayıs 1900 tarihli iradesiyle emrettiği hat, 1 Eylül 1900'de Şam'da yapılan resmî törenle inşaata başlandı. Tamamen İslâm dünyasından toplanan bağışlar ve Osmanlı mühendis-askerlerinin emeğiyle yapılan proje, hacıların Şam-Medine yolculuğunu kırk günden beş güne indirdi. Hem hilâfetin manevî otoritesini pekiştiren bir prestij eseri hem de Hicaz üzerindeki askerî denetimi güçlendiren stratejik bir yatırımdı.", kaynak:"hicaz-demiryolu", duygu:["📌"], yer_id:"Şam" },
{ t:"1903-10-02", k:"siyaset", etiket:["diplomasi","siyaset","islahat","konu-siyasi","konu-diplomasi","konu-islahat"], b:"Mürzsteg Programı: Makedonya'da uluslararası reform denetimi", odak_yer:["Selanik","Manastır"], gun:"Ekim 1903", yer:"Makedonya (Selanik, Manastır, Kosova vilâyetleri)", kisiler:"II. Abdülhamid, Çar II. Nikolay, İmparator Franz Joseph, Hüseyin Hilmi Paşa", d:"İlinden ayaklanmasının ardından Rus ve Avusturya imparatorları Mürzsteg'de buluşarak Makedonya için yeni bir reform paketi hazırladı. Program, Osmanlı umumi müfettişinin yanına iki yabancı sivil ajanın yerleştirilmesini, jandarmanın Avrupalı subaylarca yeniden düzenlenmesini ve idarî sınırların milliyet esasına göre değiştirilmesini öngörüyordu. Bâbıâli egemenlik haklarının zedelendiği gerekçesiyle direndiyse de ortak baskı karşısında kabul etmek zorunda kaldı; program, genç subaylar arasında İttihatçı örgütlenmeyi hızlandıran temel etkenlerden biri oldu.", kaynak:"makedonya", duygu:["🏛"], kapsam_genis:true },
// Bu madde 31 Tem 2026'da AÇIK KIRILMA kapatmak için eklendi: veride San'a
// 1905-04-01'de Osmanlı'dan çıkıyordu ama o günün maddesi yoktu — haritada
// sebepsiz renk değişimi. İçerik yeni araştırma değil; aşağıdaki 1905-09-01
// maddesinin ("1904'te başlayan ayaklanma Nisan 1905'te San'a'nın düşmesiyle
// sonuçlandı") zaten kaynaklı olan ilk yarısının kendi gününe ayrılmasıdır.
// Aynı `kaynak:"yemen"` kaydına dayanır; kayıp ve geri alış artık iki ayrı gün.
{ t:"1905-04-01", k:"kayip", etiket:["isyan","toprak-kayip","konu-askeri","konu-isyan"], b:"San'a'nın İmam Yahyâ'ya kaybı", gun:"Nisan 1905", yer:"San'a, Yemen", kisiler:"İmam Yahyâ Hamîdüddin, Ali Rızâ Paşa", d:"Zeydî İmam Yahyâ Hamîdüddin'in 1904'te başlattığı ayaklanma, Nisan 1905'te San'a'nın kuşatma sonunda düşmesiyle sonuçlandı; şehir Osmanlı idaresinden çıktı ve kuşatma boyunca açlıkla salgın baş gösterdi. Yemen'in dağlık coğrafyası, ikmal hatlarının uzunluğu ve Zeydî imamlığın yerel meşruiyeti, buradaki Osmanlı hâkimiyetini kuruluşundan beri kırılgan kılıyordu. Şehir beş ay sonra ağır kayıplar pahasına geri alınacak, ancak Yemen sorunu 1918'e kadar kapanmayacaktı.", kaynak:"yemen", duygu:["😔"], yer_id:"Sana" },
{ t:"1905-07-21", k:"siyaset", etiket:["siyaset","isyan","suikast","konu-siyasi","konu-kisiler","konu-isyan"], b:"Yıldız Suikastı: II. Abdülhamid'e bombalı saldırı", gun:"21 Temmuz 1905", yer:"İstanbul, Yıldız Hamidiye Camii", kisiler:"II. Abdülhamid, Edward Joris, Taşnaksutyun", d:"Taşnaksutyun örgütü, cuma selâmlığından çıkan padişahın arabasına saatli bombalı bir landonun patlatılmasıyla suikast düzenledi; Abdülhamid'in şeyhülislâmla konuşarak birkaç dakika gecikmesi hayatını kurtardı. Patlamada yirmi altı kişi öldü, elliden fazla kişi yaralandı. Olay padişahın güvenlik saplantısını ve hafiye teşkilatına dayalı istibdat idaresini daha da sertleştirdi; Tevfik Fikret'in 'Bir Lahza-i Taahhur' şiirine de konu oldu.", kaynak:"abdulhamid-ii", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1905-09-01", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"San'a'nın geri alınması: İmam Yahyâ isyanının bastırılması", gun:"Nisan-1 Eylül 1905", yer:"San'a, Yemen", kisiler:"İmam Yahyâ Hamîdüddin, Ahmed Feyzi Paşa, Ali Rızâ Paşa", d:"1904'te Zeydî İmam Yahyâ önderliğinde başlayan ayaklanma Nisan 1905'te San'a'nın düşmesiyle sonuçlandı ve şehirde açlık ve salgın baş gösterdi. Ali Rızâ Paşa ve Ahmed Feyzi Paşa kumandasındaki takviye orduları, 15 Temmuz - 1 Eylül 1905 tarihleri arasında yürüttükleri ve Taiz'deki kuvvetlerin de desteklediği harekâtla ağır kayıplar pahasına şehri geri aldı ve isyan bastırıldı. Yemen harekâtı Osmanlı ordusuna on binlerce kayıp ve muazzam bir malî yük getirdi; Rumeli'deki subaylar arasında 'Yemen'e sürgün' korkusu İttihatçı örgütlenmeyi besleyen şikâyetlerin başında geliyordu.", kaynak:"yemen", duygu:["✊","😔"], yer_id:"Sana" },
{ t:"1908-12-17", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-islahat"], b:"II. Meşrutiyet'in ilk Meclis-i Meb'ûsan'ının toplanması", gun:"17 Aralık 1908", yer:"İstanbul", yer_id:"İstanbul", kisiler:"II. Abdülhamid, Ahmed Rızâ Bey", d:"Otuz yıllık aradan sonra yapılan iki dereceli seçimlerle oluşan meclis, 17 Aralık 1908'de padişahın nutkuyla açıldı ve başkanlığına Jön Türk hareketinin lideri Ahmed Rızâ Bey seçildi. Türk, Arap, Arnavut, Rum, Ermeni ve Yahudi mebuslardan oluşan meclis Osmanlıcılık idealinin son büyük denemesiydi. Ancak Bulgaristan'ın bağımsızlığı, Bosna'nın ilhakı ve Girit'in Yunanistan'a katılma ilanı, meclis daha açılmadan bu iyimserliği gölgelemişti.", kaynak:"meclis-i-mebusan", duygu:["🏛"] },
{ t:"1909-04-27", k:"siyaset", etiket:["siyaset","isyan","darbe-askeri","konu-siyasi","konu-isyan","konu-darbe","konu-hanedan"], b:"Hareket Ordusu ve II. Abdülhamid'in hal'i: V. Mehmed Reşad'ın cülûsu", gun:"27 Nisan 1909", yer:"İstanbul (Yeşilköy, Yıldız Sarayı)", kisiler:"II. Abdülhamid, Mahmud Şevket Paşa, Hüseyin Hüsnü Paşa, V. Mehmed Reşad", d:"31 Mart Vak'ası üzerine Selanik'ten yola çıkan Hareket Ordusu 22-23 Nisan gecesi dört koldan İstanbul'a girdi ve 24 Nisan'da Yıldız Sarayı teslim oldu. Meclis-i Umûmî-i Millî 27 Nisan'da II. Abdülhamid'in hal'ine karar verdi; padişah Selanik'e gönderildi, yerine kardeşi V. Mehmed Reşad tahta çıkarıldı. Otuz üç yıllık şahsî idare böylece sona erdi, ancak yerini padişahın sembolleştiği ve İttihat ve Terakkî'nin ordu desteğiyle yönettiği yeni bir dönem aldı.", kaynak:"hareket-ordusu", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1910-04-01", k:"isyan", etiket:["isyan","savas","konu-askeri","konu-isyan"], b:"Arnavutluk İsyanı: Kosova ve İşkodra'da silahlı direniş", odak_yer:["İşkodra","Priştine","Üsküp"], gun:"1910", yer:"Kosova, İşkodra, Priştine, Üsküp", kisiler:"Mahmud Şevket Paşa, Turhan Paşa, İsmâil Kemal", d:"İttihatçı hükümetin merkeziyetçi vergi politikası, silah toplama kampanyası ve Latin alfabesi tartışması, o güne kadar devlete en sadık unsurlardan sayılan Arnavut aşiretlerini ayaklandırdı. Mahmud Şevket Paşa kumandasındaki ordu isyanı sert biçimde bastırdıysa da huzursuzluk 1911 ve 1912'de yeniden alevlendi. Bu isyanlar Osmanlı ordusunu Balkan Savaşı arifesinde yıprattığı gibi Arnavut millî hareketinin de doğuşunu hızlandırdı.", kaynak:"arnavutluk", duygu:["✊"], kapsam_genis:true },
{ t:"1912-10-18", k:"kayip", etiket:["antlasma","toprak-kayip","konu-askeri","konu-diplomasi"], b:"Uşi Antlaşması: Trablusgarp ve Bingazi'nin İtalya'ya terki", gun:"18 Ekim 1912 (15 Ekim tarihli belge muhtariyet iradesidir — TDV trablusgarp-savasi)", yer:"Uşi (Ouchy), Lozan / Trablusgarp, Bingazi", kisiler:"Mehmed Nâbi Bey, Rumbeyoğlu Fahreddin Bey, Giuseppe Volpi", d:"Balkan devletlerinin savaş hazırlığı karşısında iki cepheli çatışmayı göze alamayan Bâbıâli, İsviçre'nin Uşi kasabasında İtalya ile gizli barış imzalayarak Trablusgarp ve Bingazi'yi terk etti. Osmanlı Devleti Afrika'daki son toprağını böylece kaybetti; buna karşılık İtalya'nın işgal ettiği Rodos ve On İki Ada'nın iadesi vaat edildiyse de bu vaat hiç yerine getirilmedi. Antlaşma imzalandığında Balkan Savaşı çoktan başlamıştı.", kaynak:"trablusgarp", duygu:["😔"], yer_id:"Trablus" },
{ t:"1913-06-11", k:"siyaset", etiket:["siyaset","suikast","konu-siyasi","konu-kisiler","konu-burokrasi"], b:"Sadrazam Mahmud Şevket Paşa'nın İstanbul'da suikastle öldürülmesi", gun:"11 Haziran 1913", yer:"İstanbul, Çarşıkapı", kisiler:"Mahmud Şevket Paşa, Talat Bey, Enver Bey", d:"Bâb-ı Âli Baskını'ndan sonra sadrazamlığa getirilen Mahmud Şevket Paşa, Harbiye Nezâreti'ne giderken Çarşıkapı yakınında arabasına açılan ateşle öldürüldü. İttihat ve Terakkî suikastı muhalefetin üzerine yıkarak geniş bir tevkif ve idam dalgası başlattı, Hürriyet ve İtilâf Fırkası fiilen tasfiye edildi. Bu olayla birlikte İttihatçıların Enver-Talat-Cemal üçlüsüne dayanan tek parti diktatörlüğü kesin biçimde kuruldu.", kaynak:"mahmud-sevket-pasa", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1913-06-29", k:"savas", etiket:["savas","toprak-kazanc","konu-askeri"], b:"II. Balkan Savaşı'nın başlaması: müttefiklerin paylaşım kavgası", odak_yer:["Edirne"], gun:"29 Haziran 1913", yer:"Makedonya, Trakya", kisiler:"Enver Bey, Çar Ferdinand", d:"Londra Antlaşması ile Osmanlı'dan aldıkları toprakları paylaşamayan Balkan müttefikleri birbirine düştü; Bulgaristan'ın Sırp ve Yunan mevzilerine saldırmasıyla ikinci savaş başladı. Romanya ve Karadağ da Bulgaristan'a karşı cepheye girince Bulgar ordusu çöktü. Osmanlı Devleti bu fırsatı değerlendirerek Londra Antlaşması'nın çizdiği Midye-Enez hattını aştı ve Doğu Trakya'yı Edirne ile birlikte geri aldı.", kaynak:"osmanlilar", duygu:["⚔️"], kapsam_genis:true, ic_not_gun:"KAYNAK ÇELİŞKİSİ BEYANI — 23 Eylül 2026. TDV `balkan-savasi` AYNEN: 'Bulgaristan 23 Haziran 1913'te Sırbistan, Karadağ ve Yunanistan'a karşı savaşa başladı.' Britannica 'Balkan Wars' ise savaşı 29-30 Haziran 1913 gecesine, Kral Ferdinand'ın saldırı emrine bağlar ve olay kutusunda 'June 29, 1913 - August 10, 1913' yazar. İki kaynak AYNI soruya (savaş hangi gün başladı) farklı gün veriyor; 23 Haziran'a karşılık gelen ayrı bir olay arandı, bulunamadı (TDV balkan-savasi tam gövde · TDV bulgaristan · TDV bukres-antlasmasi 302 · Britannica tam gövde). Gün 1913-06-29'da BIRAKILDI — mekanizmasıyla birlikte verilen tarih tercih edildi; TDV'nin günü SİLİNMEDİ, burada kayıtlıdır." },
{ t:"1913-09-29", k:"antlasma", etiket:["antlasma","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"İstanbul Antlaşması: Bulgaristan ile barış ve Edirne'nin tescili", gun:"29 Eylül 1913", yer:"İstanbul / Edirne, Kırklareli, Dimetoka", kisiler:"Talat Bey, Halil Bey, General Savov", d:"II. Balkan Savaşı'nın ardından Osmanlı Devleti ile Bulgaristan arasında imzalanan antlaşma, Meriç nehrini sınır kabul ederek Edirne, Kırklareli, Dimetoka ve Doğu Trakya'nın Osmanlı'da kalmasını hukuken tescil etti. Kavala ve Dedeağaç Bulgaristan'da bırakıldı, iki ülke arasında karşılıklı nüfus mübadelesi ve Bulgaristan'daki Müslümanların hakları düzenlendi. Balkan felaketinden geri alınabilen tek toprak parçasının garantisi bu metindir. Aynı tarihte katılan öteki yerler: Gümülcine.", ic_not_d:"eski ifade: Aynı tarihte haritaya katılan diğer yerleşimler:", kaynak:"bulgaristan", duygu:["🤝"], yer_id:"Edirne" },
{ t:"1913-11-14", k:"antlasma", etiket:["antlasma","toprak-kayip","konu-askeri","konu-diplomasi"], b:"Atina Antlaşması: Yunanistan ile barış ve Selanik-Yanya'nın devri", gun:"14 Kasım 1913", yer:"Atina / Selanik, Yanya, Girit, Ege adaları", kisiler:"Galib Kemâlî Bey, Elefterios Venizelos", d:"Osmanlı Devleti ile Yunanistan arasında imzalanan antlaşma, Balkan Savaşı'nda kaybedilen Selanik, Yanya ve Güney Makedonya'nın Yunanistan'a geçişini resmen tanıdı ve Girit üzerindeki Osmanlı haklarından vazgeçildi. Yunanistan'da kalan Müslümanların din ve mülkiyet hakları, vakıfların statüsü ve müftülerin tayini ayrıntılı biçimde düzenlendi. Ege adalarının statüsü ise çözümsüz bırakılarak iki devlet arasında sürekli gerilim kaynağı olarak kaldı.", kaynak:"yunanistan", duygu:["🤝"], yer_id:"Selanik" },
{ t:"1914-08-02", k:"antlasma", etiket:["ittifak","diplomasi","savas","konu-askeri","konu-diplomasi"], b:"İstanbul'da Osmanlı-Alman gizli ittifak antlaşmasının imzalanması", gun:"2 Ağustos 1914", yer:"İstanbul (Yeniköy)", kisiler:"Said Halim Paşa, Enver Paşa, Talat Bey, Hans von Wangenheim", d:"Avrupa'da savaş patlar patlamaz, Sadrazam Said Halim Paşa'nın konağında Osmanlı Devleti ile Almanya arasında gizli bir ittifak antlaşması imzalandı; metin Rusya'nın Almanya'ya karşı savaşa girmesi hâlinde Osmanlı'nın da Almanya yanında yer almasını öngörüyordu. Antlaşma kabineden bile gizlendi, sadece dört kişi tarafından bilinmekteydi. Üç ay sonra Karadeniz baskınıyla Osmanlı Devleti fiilen savaşa sürüklenecek, imparatorluğun kaderi bu belgeyle bağlanacaktı.", kaynak:"birinci-dunya-savasi", duygu:["🤝"], yer_id:"İstanbul" },
{ t:"1914-09-09", k:"siyaset", etiket:["ekonomi","siyaset","diplomasi","konu-siyasi","konu-diplomasi","konu-ekonomi"], b:"Kapitülasyonların tek taraflı olarak kaldırılması", gun:"9 Eylül 1914", yer:"İstanbul", yer_id:"İstanbul", kisiler:"Said Halim Paşa, Talat Bey", d:"Osmanlı hükümeti, Avrupa'nın savaşla meşgul olduğu bir anda, yabancılara adlî, malî ve gümrük ayrıcalıkları tanıyan kapitülasyonları 1 Ekim 1914'ten itibaren tek taraflı olarak kaldırdığını ilan etti. Dört asırlık bu imtiyaz düzeninin sona erdirilmesi ülke içinde büyük bir bağımsızlık coşkusuyla karşılandı ve İstanbul'da kutlamalar yapıldı. Müttefik Almanya dahil bütün devletler kararı protesto etti; kapitülasyonlar ancak 1923'te Lozan'da kesin olarak tarihe karışacaktı.", kaynak:"kapitulasyon", duygu:["🏛"] },
{ t:"1914-10-29", k:"savas", etiket:["savas","konu-askeri"], b:"Karadeniz Baskını: Osmanlı donanmasının Rus limanlarını bombalaması", odak_yer:["Hacıbey (Odessa)"], gun:"29 Ekim 1914", yer:"Odessa, Sivastopol, Novorossiysk (Karadeniz)", kisiler:"Enver Paşa, Amiral Souchon", d:"Almanya'dan kaçıp Osmanlı donanmasına 'satın alınmış' gibi katılan Goeben ve Breslau (Yavuz ve Midilli), Amiral Souchon kumandasında Karadeniz'e açılarak Rus limanlarını topa tuttu ve gemileri batırdı. Enver Paşa'nın kabineden gizli verdiği bu emir, tarafsızlığı fiilen bitirdi. Bir hafta içinde Rusya, İngiltere ve Fransa savaş ilan etti ve Osmanlı Devleti geri dönüşü olmayan biçimde I. Dünya Savaşı'na girmiş oldu.", kaynak:"birinci-dunya-savasi", duygu:["⚔️"], kapsam_genis:true },
{ t:"1914-11-14", k:"siyaset", etiket:["siyaset","savas","konu-askeri","konu-siyasi","konu-din","konu-imar"], b:"Cihâd-ı Ekber ilanı: Fatih Camii'nde cihad fetvasının okunması", gun:"14 Kasım 1914", yer:"İstanbul (Fatih Camii)", kisiler:"V. Mehmed Reşad, Şeyhülislâm Ürgüplü Hayri Efendi", d:"Şeyhülislâm Ürgüplü Hayri Efendi'nin verdiği beş fetva, halife-padişah adına Fatih Camii'nde okunarak bütün Müslümanlar İtilâf devletlerine karşı cihada çağrıldı. Almanya'nın büyük umut bağladığı bu hamle, İngiliz ve Fransız sömürgelerindeki Müslümanları ayaklandırmayı hedefliyordu. Beklenen genel kalkışma gerçekleşmedi; aksine iki yıl sonra Mekke Emîri Şerif Hüseyin'in İngiliz desteğiyle isyan etmesi, hilâfetin siyasî nüfuzunun sınırlarını acı biçimde gösterdi.", kaynak:"birinci-dunya-savasi", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1914-12-18", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Mısır'ın İngiliz himayesine alınarak sultanlık ilan edilmesi", gun:"18 Aralık 1914", yer:"Kahire, Mısır", kisiler:"Abbas Hilmi Paşa, Hüseyin Kâmil, Lord Kitchener", d:"Osmanlı Devleti'nin savaşa girmesi üzerine İngiltere, 1882'den beri fiilen işgal altında tuttuğu Mısır'ı resmen himayesine aldığını ilan etti; Osmanlı'ya bağlılığı sürdüren Hidiv Abbas Hilmi Paşa azledilerek yerine Hüseyin Kâmil 'sultan' unvanıyla getirildi. Böylece 1517'den beri süren hukukî Osmanlı hükümranlığı tek taraflı biçimde sona erdirildi. Bâbıâli kararı tanımadı ve iki ay sonra Kanal Harekâtı'yla Mısır'ı geri almaya girişti.", kaynak:"misir", duygu:["😔"], yer_id:"Kahire" },
{ t:"1914-12-22", k:"savas", etiket:["savas","toprak-kayip","konu-askeri"], b:"Sarıkamış Harekâtı: Kafkas cephesinde felaket", gun:"22 Aralık 1914 - 4 Ocak 1915", yer:"Sarıkamış, Allahuekber dağları, Kars", kisiler:"Enver Paşa, Hafız Hakkı Paşa, Hasan İzzet Paşa", d:"Enver Paşa, 1878'de kaybedilen Kars-Ardahan-Batum'u geri almak ve Kafkasya'daki Türkleri ayaklandırmak amacıyla III. Ordu'yu kışın Allahuekber dağları üzerinden Rus kuvvetlerini kuşatacak bir manevraya sürdü. Yetersiz kışlık donanım, tükenen ikmal ve eksi otuz dereceyi bulan tipi yüzünden ordu daha muharebeye girmeden eridi; on binlerce asker donarak öldü. Harekât Osmanlı'nın savaştaki en ağır felaketlerinden biri oldu ve doğu cephesini iki yıl boyunca savunmasız bıraktı.", kaynak:"sarikamis-harekati", duygu:["⚔️"], yer_id:"Sarıkamış" },
{ t:"1915-01-14", k:"savas", etiket:["savas","konu-askeri","konu-ulastirma"], b:"Birinci Kanal Harekâtı: Süveyş'e Sina çölü üzerinden taarruz", gun:"14 Ocak - 15 Şubat 1915", yer:"Sina çölü, Süveyş Kanalı, Filistin", kisiler:"Cemal Paşa, Kress von Kressenstein", d:"IV. Ordu kumandanı Cemal Paşa, Mısır'ı İngiliz işgalinden kurtarmak ve Süveyş Kanalı'nı ulaşıma kapatmak amacıyla Sina çölünü aşan bir taarruz düzenledi. Osmanlı birlikleri kanalın doğu yakasına ulaşıp bir kısmı karşıya geçmeyi başardıysa da İngiliz üstünlüğü ve beklenen Mısır halk ayaklanmasının gerçekleşmemesi üzerine geri çekildi. Harekât hedefine ulaşamadı, ancak İngiltere'yi Mısır'da büyük kuvvet bulundurmaya mecbur bırakarak dolaylı bir stratejik etki yarattı.", kaynak:"birinci-dunya-savasi", duygu:["⚔️"], yer_id:"Süveyş" },
{ t:"1915-05-27", k:"siyaset", etiket:["siyaset","diger","konu-siyasi","konu-demografi","konu-hukuk"], b:"Sevk ve İskân (Tehcir) Kanunu'nun çıkarılması", odak_yer:["İstanbul"], gun:"27 Mayıs 1915", yer:"Doğu Anadolu, Suriye, Musul", kisiler:"Talat Paşa, V. Mehmed Reşad", d:"Van isyanı ve Rus ilerleyişinin ardından hükümet, cephe gerisinde güvenliği bozduğu değerlendirilen nüfusun ordu kumandanlarınca başka bölgelere nakledilmesine izin veren geçici kanunu çıkardı ve padişah 27 Mayıs 1915'te tasdik etti. Uygulama sonucunda Anadolu'nun doğu ve güney vilâyetlerindeki Ermeni nüfusun büyük kısmı Suriye ve Musul yönüne sevk edildi; sevkiyat sırasında hastalık, açlık ve saldırılar sebebiyle çok büyük can kaybı yaşandı. Karar, Osmanlı'nın son yıllarının en ağır ve bugün de en tartışmalı meselesi olarak kalmıştır.", kaynak:"tehcir", duygu:["😢","🏛","😠"], kapsam_genis:true },
{ t:"1918-02-10", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-imar"], b:"II. Abdülhamid'in Beylerbeyi Sarayı'nda vefatı", gun:"10 Şubat 1918", yer:"İstanbul, Beylerbeyi Sarayı", kisiler:"II. Abdülhamid", d:"1909'da tahttan indirilip önce Selanik'e, Balkan Savaşı'nda şehrin kaybedilmesi üzerine İstanbul'a getirilen ve Beylerbeyi Sarayı'nda göz hapsinde tutulan II. Abdülhamid vefat etti. Otuz üç yıllık saltanatı boyunca devleti savaşlardan uzak tutarak zaman kazanmaya çalışmış, ancak istibdat idaresiyle de anılmıştı. Cenazesi büyük bir kalabalıkla Divanyolu'ndaki I. Mahmud Türbesi'ne defnedildi; ölümü, kurduğu düzenin çoktan tasfiye edildiği bir savaş yılına denk geldi.", kaynak:"abdulhamid-ii", vefat_id:"abdulhamid2", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1918-03-03", k:"antlasma", etiket:["antlasma","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Brest-Litovsk Antlaşması: Kars, Ardahan ve Batum'un geri alınması", gun:"3 Mart 1918", yer:"Brest-Litovsk / Kars, Ardahan, Batum", kisiler:"Talat Paşa, Ahmed Nesimî Bey, Lev Troçki", d:"Bolşevik ihtilâlinden sonra savaştan çekilen Rusya ile İttifak devletleri arasında imzalanan antlaşma, Doğu cephesini kapattı ve Osmanlı Devleti'ne 1878 Berlin Antlaşması'yla kaybettiği Kars, Ardahan ve Batum'u (Elviye-i Selâse) geri kazandırdı. Bu, Osmanlı tarihinde kırk yıl aradan sonra elde edilen tek toprak kazancıydı. Ancak Mondros Mütarekesi'nden sonra bölge yeniden elden çıkacak, kesin çözüm 1921 Kars Antlaşması'yla gelecekti.", kaynak:"birinci-dunya-savasi", duygu:["🤝"], yer_id:"Kars" },
{ t:"1918-07-03", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-kisiler","konu-hanedan"], b:"V. Mehmed Reşad'ın vefatı ve VI. Mehmed Vahdeddin'in cülûsu", gun:"3 Temmuz 1918", yer:"İstanbul", yer_id:"İstanbul", kisiler:"V. Mehmed Reşad, VI. Mehmed Vahdeddin, Talat Paşa", d:"Dokuz yıllık saltanatı Trablusgarp, Balkan ve Dünya savaşlarıyla geçen V. Mehmed Reşad, savaşın en kritik döneminde vefat etti ve yerine kardeşi Vahdeddin VI. Mehmed adıyla tahta çıktı. Yeni padişah, İttihatçı kadronun vesayetinden kurtulmaya çalıştı; dört ay sonra mütareke imzalandığında imparatorluğun tasfiyesini yönetmek zorunda kalacaktı. Osmanlı hanedanının otuz altıncı ve son padişahıydı.", kaynak:"mehmed-vi", vefat_id:"mehmed5", duygu:["🏛"] },
{ t:"1918-11-13", k:"kayip", etiket:["savas","siyaset","konu-askeri","konu-siyasi"], b:"İtilâf donanmasının İstanbul önlerine gelişi ve şehrin fiilî işgali", gun:"13 Kasım 1918", yer:"İstanbul, Boğaziçi", kisiler:"VI. Mehmed Vahdeddin, Ahmed Tevfik Paşa, Amiral Calthorpe", d:"Mondros Mütarekesi'nin ardından İngiliz, Fransız, İtalyan ve Yunan gemilerinden oluşan altmışı aşkın parçalık müttefik donanması Dolmabahçe önlerine demirledi ve İstanbul fiilen işgal altına girdi. Dört yüz altmış beş yıl sonra payitaht ilk kez yabancı askerlerin denetimine geçmişti. Aynı gün Mustafa Kemal Paşa'nın Haydarpaşa'ya inip manzarayı görünce söylediği rivayet edilen 'Geldikleri gibi giderler' sözü, Millî Mücadele'nin sembol cümlelerinden biri olacaktı.", kaynak:"milli-mucadele", duygu:["😔"], yer_id:"İstanbul" },
{ t:"1919-07-23", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-idari","konu-diplomasi"], b:"Erzurum Kongresi: Doğu vilâyetlerinin millî direniş kararı", gun:"23 Temmuz - 7 Ağustos 1919", yer:"Erzurum", yer_id:"Erzurum", kisiler:"Mustafa Kemal Paşa, Kâzım Karabekir, Hüseyin Rauf Bey", d:"Şarkî Anadolu Müdafaa-i Hukuk Cemiyeti'nin topladığı kongre, İngiliz baskısıyla ertelendikten sonra elli altı delegeyle açıldı ve başkanlığına askerlikten istifa etmiş olan Mustafa Kemal Paşa seçildi. Kongre, millî sınırlar içinde vatanın bir bütün olduğunu, manda ve himayenin kabul edilemeyeceğini, hükümetin dağılması hâlinde milletin kendi mukadderatını eline alacağını ilan etti. Bu kararlar altı ay sonra Misâk-ı Millî metninin çekirdeğini oluşturacaktı.", kaynak:"erzurum-kongresi", duygu:["🏛"] },
{ t:"1919-09-04", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-diplomasi"], b:"Sivas Kongresi: millî direnişin tek çatı altında birleşmesi", gun:"4-11 Eylül 1919", yer:"Sivas (Sivas Sultânîsi)", kisiler:"Mustafa Kemal Paşa, Rauf Bey, Bekir Sami Bey", d:"4 Eylül 1919'da Sivas Sultânîsi'nde çalışmalarına başlayan kongre, ülkenin dört bir yanındaki müdafaa-i hukuk cemiyetlerini Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adı altında birleştirdi ve bir Heyet-i Temsîliyye seçti. Amerikan mandası teklifi uzun tartışmalardan sonra reddedildi. 11 Eylül'de yayımlanan beyannâme ile Millî Mücadele tek merkezli, meşru bir siyasî hareket hâline geldi ve İstanbul hükümetiyle açık bir güç mücadelesi başladı.", kaynak:"sivas-kongresi", duygu:["🏛"], yer_id:"Sivas" },
{ t:"1919-10-22", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi"], b:"Amasya Protokolü: İstanbul hükümetiyle Heyet-i Temsîliyye görüşmesi", gun:"22 Ekim 1919", yer:"Amasya", yer_id:"Amasya", kisiler:"Mustafa Kemal Paşa, Bahriye Nâzırı Salih Paşa", d:"Damat Ferid'in düşüp Ali Rızâ Paşa hükümetinin kurulmasından sonra Bahriye Nâzırı Salih Paşa, Heyet-i Temsîliyye ile görüşmek üzere Amasya'ya gönderildi. Varılan protokollerle İstanbul hükümeti, Anadolu hareketinin varlığını fiilen tanıdı; Meclis-i Meb'ûsan'ın toplanması, seçimlerin serbest yapılması ve millî sınırların korunması kabul edildi. Bu, Millî Mücadele'nin İstanbul karşısında elde ettiği ilk resmî siyasî kazanımdır.", kaynak:"milli-mucadele", duygu:["🏛"] },
{ t:"1920-01-28", k:"siyaset", etiket:["siyaset","diplomasi","konu-siyasi","konu-diplomasi"], b:"Misâk-ı Millî'nin son Osmanlı Meclisi'nde kabulü", gun:"28 Ocak 1920", yer:"İstanbul (Meclis-i Meb'ûsan)", kisiler:"Mustafa Kemal Paşa, Rauf Bey, Şeref Bey", d:"Son Osmanlı Meclis-i Meb'ûsan'ında 121 mebusun imzaladığı Ahd-i Millî metni, Mondros hattı içinde kalan ve Müslüman-Türk çoğunluğun yaşadığı toprakların bölünmez bütünlüğünü, Arap vilâyetleri ve Batı Trakya'da halk oylamasını, kapitülasyonların kaldırılmasını ve tam siyasî-malî bağımsızlığı şart koşuyordu. Metin 17 Şubat 1920'de oy birliğiyle kabul edilip dünyaya ilan edildi. Bu bildiri Millî Mücadele'nin siyasî programı olduğu kadar Lozan'da savunulacak sınırların da haritasıydı; İtilâf devletlerinin 16 Mart'ta İstanbul'u resmen işgal etmesinin doğrudan sebebi oldu.", kaynak:"misak-i-milli", duygu:["🏛"], yer_id:"İstanbul" },
{ t:"1920-12-03", k:"antlasma", etiket:["antlasma","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Gümrü Antlaşması: TBMM hükümetinin ilk uluslararası antlaşması", gun:"3 Aralık 1920", yer:"Gümrü (Aleksandropol), Kars, Sarıkamış", kisiler:"Kâzım Karabekir, Ahmed Muhtar Bey", d:"Kâzım Karabekir kumandasındaki Doğu cephesi ordusunun Sarıkamış ve Kars'ı geri alması üzerine Ermenistan barış istedi ve Gümrü'de imzalanan antlaşmayla Sevr'i tanımadığını, doğudaki toprak taleplerinden vazgeçtiğini kabul etti. Ankara hükümetinin imzaladığı bu ilk antlaşma, Sevr'i fiilen reddeden ilk uluslararası belge oldu ve TBMM'ye hukukî tanınma yolunu açtı. Doğu sınırı böylece güvence altına alınarak Batı cephesine kuvvet kaydırılması mümkün hâle geldi.", kaynak:"milli-mucadele", duygu:["🤝"], yer_id:"Gümrü (Aleksandropol)" },
{ t:"1921-01-10", k:"savas", etiket:["savas","konu-askeri"], b:"Birinci İnönü Muharebesi: düzenli ordunun ilk zaferi", gun:"10 Ocak 1921", yer:"İnönü, Eskişehir", kisiler:"İsmet Bey (İnönü), Mustafa Kemal Paşa", d:"Yeni kurulan düzenli ordu, Bursa istikametinden ilerleyen Yunan kuvvetlerini İnönü mevzilerinde durdurarak geri çekilmeye mecbur bıraktı. Askerî bakımdan sınırlı ölçekte olan bu başarı, siyasî sonuçları itibariyle çok büyüktü: Ankara hükümeti Londra Konferansı'na davet edildi, Sovyet Rusya ile Moskova Antlaşması'nın yolu açıldı ve Teşkilât-ı Esâsiyye Kanunu kabul edildi. İç kamuoyunda düzenli orduya duyulan güven de bu zaferle pekişti.", kaynak:"milli-mucadele", duygu:["⚔️"], yer_id:"Eskişehir" },
{ t:"1921-04-01", k:"savas", etiket:["savas","konu-askeri"], b:"İkinci İnönü Muharebesi: Yunan taarruzunun ikinci kez kırılması", gun:"1 Nisan 1921", yer:"İnönü, Eskişehir, Kütahya", kisiler:"İsmet Paşa, Refet Paşa, Mustafa Kemal Paşa", d:"Londra Konferansı'ndan sonuç alamayan Yunan ordusu Bursa ve Uşak yönlerinden yeni bir taarruza geçti, ancak yine İnönü sırtlarında durduruldu ve geri çekilmek zorunda kaldı. Mustafa Kemal Paşa'nın İsmet Paşa'ya çektiği 'Siz orada yalnız düşmanı değil, milletin makûs talihini de yendiniz' telgrafı bu zaferin ardından yazıldı. Muharebe, Millî Mücadele'nin uluslararası itibarını yükseltti ve İtalya'nın Anadolu'dan çekilme sürecini hızlandırdı.", kaynak:"milli-mucadele", duygu:["⚔️"], yer_id:"Eskişehir" },
{ t:"1921-10-20", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kazanc","konu-askeri","konu-diplomasi"], b:"Ankara İtilâfnâmesi: Fransa ile barış ve güney cephesinin kapanması", gun:"20 Ekim 1921", yer:"Ankara / Adana, Antep, Maraş, Urfa", kisiler:"Yusuf Kemal Bey, Henry Franklin-Bouillon", d:"Sakarya zaferinin ardından Fransa ile Ankara'da imzalanan itilâfnâme ile güney cephesindeki savaş sona erdi; Fransız kuvvetleri Adana, Antep, Maraş ve Urfa dahil Çukurova ve Güneydoğu'yu boşaltarak Suriye sınırına çekildi. İtilâf devletlerinden biri böylece Ankara hükümetini fiilen tanımış oldu ve Sevr cephesinde ilk çatlak açıldı. Boşaltılan bölgelerden devralınan silahlar ve serbest kalan birlikler Büyük Taarruz'un hazırlığında kritik rol oynadı.", kaynak:"milli-mucadele", duygu:["🤝"], yer_id:"Adana" },
{ t:"1922-10-11", k:"antlasma", etiket:["antlasma","diplomasi","konu-diplomasi"], b:"Mudanya Mütarekesi: İstanbul ve Boğazlar'ın savaşsız devri", gun:"11 Ekim 1922", yer:"Mudanya, Bursa / İstanbul, Doğu Trakya", kisiler:"İsmet Paşa, General Harington, Mustafa Kemal Paşa", d:"Büyük Taarruz'un ardından Türk ordusunun Çanakkale ve İzmit'te İngiliz kuvvetleriyle karşı karşıya gelmesi üzerine Mudanya'da toplanan konferans, on bir günlük çetin pazarlıktan sonra mütarekeyle sonuçlandı. Doğu Trakya'nın Meriç'e kadar on beş gün içinde Yunanistan tarafından boşaltılarak Türk idaresine devri, İstanbul ve Boğazlar'ın da barış antlaşmasıyla teslimi kabul edildi. Böylece Millî Mücadele'nin silahlı safhası tek kurşun atılmadan kazanılmış bir diplomatik zaferle kapandı ve Lozan'ın kapısı açıldı.", kaynak:"mudanya-mutarekesi", duygu:["🤝"], yer_id:"Edirne" },
{ t:"1922-11-17", k:"siyaset", etiket:["siyaset","konu-siyasi","konu-din","konu-kisiler"], b:"VI. Mehmed Vahdeddin'in İstanbul'dan ayrılışı ve Abdülmecid Efendi'nin halife seçilmesi", gun:"17-19 Kasım 1922", yer:"İstanbul, Dolmabahçe", kisiler:"VI. Mehmed Vahdeddin, Abdülmecid Efendi, Refet Paşa", d:"Saltanatın kaldırılmasından sonra konumu tartışmalı hâle gelen son padişah VI. Mehmed Vahdeddin, 17 Kasım 1922 Cuma sabahı İngiliz zırhlısı Malaya ile İstanbul'dan ayrılarak Malta'ya gitti. TBMM iki gün sonra, 19 Kasım'da Abdülmecid Efendi'yi siyasî yetkisi bulunmayan bir halife olarak seçti. Altı yüz yirmi üç yıllık Osmanlı hanedan hükümdarlığı böylece fiilen sona erdi; hilâfet ise on beş ay daha sembolik olarak sürecekti. Malta ve ardından İtalya'ya geçen Vahdeddin, San Remo'daki Villa Nobel'e yerleşti; bir müslüman ülkesine kabul edilmek için yaptığı başvurulardan sonuç alamadı ve 16 Mayıs 1926'da orada, hiçbir zaman saltanat ve hilâfet haklarından feragat etmediğini yineleyerek öldü.", kaynak:"mehmed-vi", duygu:["🏛","😔"], vefat_id:"mehmed6", yer_id:"İstanbul" },

// ---- 0e. Kanunî devrinin "sessiz" toprak değişimleri (1534-1559) ----
// Denetim, bu yirmi beş yılda haritada renk değiştirip kronolojide karşılığı olmayan
// on dokuz kırılma buldu. Maddesi olmayan fetih, zaman çubuğunda kendisine en yakın
// alakasız maddenin üstünde beliriyordu: Basra ve Yemen "İstanbul Antlaşması"nda,
// Lahsa "Trablusgarp'ın fethi"nde, Sahra kaleleri "Temeşvar'ın fethi"nde, Şehrizor
// "Pîrî Reis'in idamı"nda, Bicâye ile İbrim "Amasya Antlaşması"nda, Habeş sahili ise
// "Süleymaniye Külliyesi"nde ortaya çıkıyordu. Aşağıdaki maddeler bu bağı düzeltir.
{ t:"1534-06-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Kars'ın alınması ve kuzeydoğu sınırının açılması", gun:"Haziran 1534", yer:"Kars", yer_id:"Kars", kisiler:"Makbul İbrahim Paşa", d:"Irakeyn Seferi'nin öncü kolu Erzurum'dan doğuya yönelirken, Gürcü atabegliğinin elinde bulunan ve Timur'dan beri harap yatan Kars kalesi direnişle karşılaşmadan teslim alındı. Şehir, Aras yayı ile Çıldır arasındaki geçidi tuttuğu için İran'a açılan kuzey kapısının anahtarı sayılıyordu. Bu kazanç, otuz yıl sonra kurulacak Kars beylerbeyiliğinin ve Kafkas hattının ilk halkası oldu.", kaynak:"kars", duygu:["🎉"] },
{ t:"1534-07-13", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Tebriz'e ilk giriş — Irakeyn Seferi'nin açılışı", gun:"13 Temmuz 1534", yer:"Tebriz, Azerbaycan", yer_id:"Tebriz", kisiler:"Makbul İbrahim Paşa, Şah Tahmasb", d:"Serdar-ı ekrem sıfatıyla önden hareket eden İbrahim Paşa, Şah Tahmasb'ın meydan savaşından kaçınıp içerilere çekilmesi üzerine Safevî başkenti Tebriz'e direnişle karşılaşmadan girdi. Kanunî de eylülde şehre ulaştı; ancak kışın bastırması ve ikmal hattının çok uzaması yüzünden ordu Bağdat istikametine yöneldi ve Tebriz uzun süre elde tutulamadı. Çaldıran'dan sonra ikinci kez alınan şehir, Osmanlı'nın doğuda ele geçirmenin kolay, elde tutmanın zor olduğunu öğrendiği yer oldu.", kaynak:"irakeyn-seferi", duygu:["🎉"] },
{ t:"1538-08-03", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Aden'in zaptı ve Yemen sahilinin ilhakı", gun:"3 Ağustos 1538", yer:"Aden, Moha, Kemeran, Ferasan", yer_id:"Aden", kisiler:"Hadım Süleyman Paşa", d:"Hint seferi için Süveyş'ten kalkan donanma, Kızıldeniz'i güvene almadan okyanusa çıkılamayacağı için önce Yemen kıyısına yöneldi. Hadım Süleyman Paşa 3 Ağustos 1538'de Aden limanına girdi; Portekizliler'e temayül eden Tâhirî hâkimi Âmir b. Dâvud kaptan kapısına getirtilip idam edildi ve şehre 500 kişilik muhafız bırakıldı. Aynı sefer sırasında Moha ile boğaza hâkim Kemeran ve Ferasan adaları da teslim alındı ve Yemen beylerbeyiliğinin temeli atıldı. Böylece Osmanlı Devleti ilk kez Bâbülmendep'in kuzey kıyısının tamamına sahip oldu; Sana ve iç bölgeler ise dokuz yıl daha beklemek zorunda kalacaktı.", statu_dogrudan:["Aden"], kaynak:"yemen", duygu:["🎉"] },
{ t:"1540-11-01", k:"fetih", etiket:["toprak-kazanc","antlasma","konu-askeri","konu-diplomasi"], b:"Anabolu'nun (Nauplion) antlaşmayla devralınması", gun:"Kasım 1540", yer:"Anabolu, Mora", yer_id:"Mora (Tripoliçe)", kisiler:"Kanunî Sultan Süleyman, Yunus Bey", d:"Preveze'den sonra üç yıl süren Venedik savaşı, cumhuriyetin Mora'daki son iki kalesini bırakmayı kabul etmesiyle sona erdi. Kuşatmayla alınamayan Anabolu ile Benefşe, üç yüz bin duka savaş tazminatının yanında masa başında Osmanlı'ya devredildi. Mora yarımadası böylece tek bir Venedik ayak izi kalmayacak şekilde bütünleşti.", kaynak:"anabolu", duygu:["🎉"] },
{ t:"1543-07-21", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Valpo, Şikloş ve Peçuy'un fethi", gun:"21 Temmuz 1543", yer:"Peçuy (Pécs), Güney Macaristan", yer_id:"Peçuy", kisiler:"Kanunî Sultan Süleyman", d:"Budin'in ilhakından iki yıl sonra çıkılan Macaristan seferinin ilk hedefi, yeni eyaletin Drava ile Tuna arasındaki güney kanadını güvene almaktı. Valpo ve Şikloş kaleleri alındıktan sonra Baranya'nın merkezi Peçuy teslim oldu. Şehir, Osmanlı Macaristanı'nın en kalabalık ve en fazla imar gören merkezi hâline gelecek, tarihçi İbrahim Peçuylu adını buradan alacaktı.", kaynak:"pecuy", duygu:["🎉"] },
{ t:"1544-09-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Budin'in kuzey ve batı savunma kuşağı: Vaç, Hatvan ve Şimontorna", gun:"1544", yer:"Vaç, Hatvan, Novigrad, Şimontorna", yer_id:"Hatvan", kisiler:"Yahyapaşazâde Mehmed Paşa", d:"Estergon ve İstolni Belgrad alındıktan sonra Budin beylerbeyi, başkenti çevreleyen kale halkasını tamamlamak üzere padişah seferi olmaksızın harekete geçti. Tuna dirseğindeki Vaç, Alföld'ün kapısı Hatvan ve Sió hattındaki Şimontorna tek tek teslim alındı. Bu sessiz yılın kazanımları, Budin'i bir uç şehri olmaktan çıkarıp yüz kırk yıl dayanacak bir eyalet merkezine dönüştürdü.", kaynak:"budin", duygu:["🎉"] },
{ t:"1546-01-01", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Basra'nın ilhakı ve Basra Körfezi'ne çıkış", gun:"1546", yer:"Basra, Şattülarab", yer_id:"Basra", kisiler:"Ayas Paşa, Râşid b. Mugâmis", d:"Bağdat'ın fethinden sonra Osmanlı hâkimiyetini kâğıt üzerinde tanıyan Müşa'şa' ve Muntafık emirlerinin bağlılığı fiilî hâle getirildi ve Basra doğrudan idareye alınarak eyalet merkezi yapıldı. Şattülarab'ın ağzındaki bu liman, Portekiz'in Hürmüz'den kontrol ettiği körfeze Osmanlı'nın açıldığı tek kapıydı. Kısa süre sonra kurulan Basra tersanesi, Hint Okyanusu'na yönelik bütün harekâtların üssü olacaktı.", kaynak:"basra", duygu:["🎉"] },
{ t:"1547-02-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Taiz'in fethi", gun:"Şubat 1547", yer:"Taiz, Yemen", yer_id:"Taiz", kisiler:"Özdemir Paşa", d:"Dokuz yıl önce sahil şeridiyle yetinilen Yemen'de, Zeydî imamların dağlık iç bölgede giderek güçlenmesi üzerine Özdemir Paşa kuvvetleri yaylaya çıkarak Taiz'i zaptetti.", kaynak:"taiz", duygu:["🎉"] },
{ t:"1547-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Sana ve Yemen içlerinin fethi", gun:"1547", yer:"Sana", yer_id:"Sana", kisiler:"Özdemir Paşa, Ferhad Paşa", d:"Taiz'in ardından Sana da alınarak ülkenin tamamı beylerbeyiliğe bağlandı. Ancak sarp coğrafya ve mezhep farkı yüzünden bu hâkimiyet hiçbir zaman rahat olmadı; Yemen, Osmanlı için sürekli asker yutan bir cephe hâline geldi.", kaynak:"yemen", duygu:["🎉"] },
{ t:"1548-07-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"İkinci İran Seferi ve Tebriz'in yeniden alınması", gun:"27 Temmuz 1548", yer:"Tebriz, Azerbaycan", yer_id:"Tebriz", kisiler:"Kanunî Sultan Süleyman, Şah Tahmasb, Elkas Mirza", d:"Şah Tahmasb'a isyan edip İstanbul'a sığınan kardeşi Elkas Mirza'nın teşvikiyle çıkılan seferde ordu ikinci kez Tebriz'e girdi. Safevîler yine meydan savaşına girmeyip toprağı yakarak çekildiği için şehirde yalnız birkaç hafta kalınabildi. Sefer, Tebriz'in elde tutulamayacağını kesinleştirdi ve Osmanlı stratejisini kalıcı bir sınır hattı kurmaya, yani Van'ı tahkim etmeye yöneltti.", kaynak:"tebriz", duygu:["🎉"] },
{ t:"1548-08-24", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Van'ın fethi ve doğu sınırının sabitlenmesi", gun:"24 Ağustos 1548", yer:"Van, Doğu Anadolu", kisiler:"Kanunî Sultan Süleyman", d:"Tebriz'den dönerken kuşatılan Van kalesi, gölün doğu kıyısındaki kayalık üzerinde yükselen konumuyla bölgenin tartışmasız kilidiydi ve kısa bir muhasaradan sonra teslim oldu. Şehir hemen beylerbeyilik merkezi yapıldı; Erciş, Adilcevaz ve Hakkâri sancakları buraya bağlandı. Tebriz'in aksine Van elde tutuldu ve dört yüz yıl boyunca Osmanlı'nın doğudaki en ileri kalıcı mevzii olarak kaldı.", kaynak:"van", duygu:["🎉"], yer_id:"Van" },
{ t:"1550-01-01", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Lahsa ve Katîf'in ilhakı — Körfez'in Arabistan kıyısı", gun:"1550", yer:"Lahsa, Katîf, Basra Körfezi", yer_id:"Lahsa", kisiler:"Kubad Paşa", d:"Basra'nın alınmasından sonra körfezin batı kıyısında Portekiz'in ileri karakolu hâline gelmiş olan Katîf ele geçirildi ve iç kesimdeki Lahsa vahaları ile birlikte yeni bir beylerbeyilik kuruldu. Bahreyn'e ve Hürmüz'e yönelik harekâtların çıkış noktası burasıydı. Osmanlı Devleti böylece Arabistan yarımadasının hem Kızıldeniz hem Basra Körfezi kıyılarında aynı anda söz sahibi oldu.", kaynak:"lahsa", duygu:["🎉"] },
{ t:"1551-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Ardahan ve Çıldır havzasının alınması", gun:"1551", yer:"Ardahan, Çıldır, Şavşat, Posof, Hanak, Artvin, Hopa, Sarp, Borçka, Ahılkelek (Akhalkalaki)", yer_id:"Ardahan", kisiler:"İskender Paşa", d:"Erzurum beylerbeyi, Safevîlerle süren savaş sırasında Gürcü atabeglerinin Kür yayındaki topraklarına yönelerek Ardahan'ı ve Çıldır çevresini Osmanlı idaresine bağladı. Kars-Ardahan hattı böylece bütünleşti ve kuzeydoğuda Gürcistan'a açılan yaylalar denetim altına alındı. Bölgenin kesin idari düzeni, yirmi yedi yıl sonra kurulacak Çıldır eyaletiyle tamamlanacaktı.", kaynak:"kars", duygu:["🎉"] },
// DENETİM AÇIK (28 Ağu 2026) — SİLİNDİ (1552-01-01): mükerrer:
// olaylar_ek17.js'teki "Cezayir Ocaklığı'nın Sahra'ya doğru genişlemesi" kaydı
// AYNI seferi anlatıyor (aynı gün · aynı kişi · aynı `kaynak:"tilimsan"` slug'ı).
// Kalan kayıt bu kaydın taşıdığı üç yerin (Tilimsan · Biskra · Tuggurt) hepsini
// İÇERİYOR ve 14 yere çıkarıyor; "İspanya'nın Vehran'dan beslediği Zeyyânî
// hânedanı" ve "Sahra kervan yollarının kuzey ucu" nüansları da orada mevcut.
// ⚠️ Tek fark `k:` alanıydı — burada "fetih", orada "vassal". Kalan kayıt ikisini
// de anlatıyor (Tilimsan FETH, Tuggurt-Vargla HARACA bağlanır); TDV'nin ayrımı
// budur, dolayısıyla "vassal" daha dar değil daha DOĞRU.
{ t:"1550-01-01", kesinlik:"yil", k:"kayip", etiket:["toprak-kayip","siyaset","konu-askeri","konu-siyasi"], b:"Şehrizor'un elden çıkışı — Erdelân beyi Sührâb Safevîlere meyletti", gun:"1550", yer:"Şehrizor, Halepçe (Zalm Kalesi), Kürdistan", yer_id:"Şehrizor", kisiler:"Bige Bey, Sührâb Bey",
  d:"Irakeyn Seferi sırasında (1535) Osmanlı idaresini tanımış olan Şehrizor yöresi, Zalm Kalesi'nde oturan Erdelân emîri Bige Bey'in yönetimindeydi. Bige Bey'in 1550'de ölümü üzerine Zalm Kalesi'ni ele geçirip beyliğe hâkim olan kardeşi Sührâb, Safevîler'e yönelerek Osmanlı'ya itaatten ayrıldı; Şehrizor yöresi böylece Osmanlı nüfuzundan çıktı. Bölge ancak Nahçıvan seferi sırasında, 1554'te Zalm Kalesi'nin kuşatılıp alınmasıyla geri kazanıldı.",
  ic_not_t:"TDV sehrizor: 'Osmanlı hâkimiyetini kabul eden Bige Bey'in 1550'de ölümünün ardından Zalm Kalesi'ni ele geçirip beyliğe hâkim olan kardeşi Sührâb, Safevîler'e meyledip Osmanlılar'a itaatten ayrıldı' — YIL verir, ay/gün vermez ⇒ 1550-01-01 + kesinlik:yil. Harita kırılması Şehrizor d:1535-01-01→1550-01-01 · Halepçe d:…→1550-01-01 (yerlesimler.js). Geri alınış: olaylar_ek8.js 1554-08-22. 0081/H-0035 · UYGULA-OLAYLAR-0930",
  kaynak:"sehrizor", duygu:["😔"] },
{ t:"1552-09-04", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Solnok'un fethi ve Eğri kuşatmasının başarısızlığı", gun:"4 Eylül – 17 Ekim 1552", yer:"Solnok, Eğri — Macaristan", yer_id:"Solnok (Szolnok)", kisiler:"Kara Ahmed Paşa, Hadım Ali Paşa, İstvan Dobo", d:"Temeşvar'ın alınmasından sonra birleşen iki Osmanlı ordusu, Tisa üzerindeki Solnok'u paralı muhafızların kaleyi terk etmesiyle neredeyse çatışmasız ele geçirdi. Ardından kuşatılan Eğri kalesi ise İstvan Dobo kumandasındaki iki bin kişilik garnizonun otuz sekiz günlük direnişi karşısında alınamadı ve ordu kış bastırınca çekildi. Aynı seferde bir kale kolayca düşerken diğerinin dayanması, Macaristan'da sınırın artık Osmanlı lehine kendiliğinden ilerlemediğini gösteren ilk açık işaretti.", kaynak:"egri", duygu:["🎉"] },
// 🔴 KALDIRILDI — H-0017 · KITA 14 · 13 Eylül 2026 · paket 0044 ②
//    Burada "1554-01-01 Şehrizor'un ilhakı ve eyalet kurulması" maddesi vardı. Aynı fethin
//    olaylar_ek8.js'te 1554-08-22 günlü, TDV'ye birebir dayanan ikinci maddesi var ve haritanın
//    değişim günü de 1554-08-22 (Şehrizor · Halepçe kayıtları). Emre iki madde gördü ve harita
//    ikinciden sonra değişiyordu. ÖLÇÜLDÜ: bu madde çıkınca ±30 gün penceresinde açık kalan kırılma 0.
//    Metni ayrıca anakronikti: 1554'te "merkezi Gülanber olan eyalet" dedi — TDV `sehrizor`
//    Gülanber'in "970 Zilkadesinde (Temmuz 1563)" yapıldığını, 1554'te bölgenin "sancak haline
//    getirilerek Murad Bey'e verildiğini" yazıyor; "Amasya Antlaşması'nda tescil" cümlesi TDV'de GEÇMİYOR.
//    Kaynaklı bağlamı (Nahçıvan seferi · Osman Paşa · sancak) ek8 maddesine taşındı.
{ t:"1555-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"İbrim ve Nübye sınırının güneye taşınması", gun:"XVI. yüzyıl ortası", ic_not_gun:"0035/H-0065 (PAKET-A3, 13 Eylül 2026): t:1555-01-01 KAYNAKTA YOK — TDV sudan olayı yalnız 'XVI. yüzyılın ortalarında' diye Özdemir Paşa'ya bağlar. Madde silinmedi, t değiştirilmedi (değişirse Değişmez 2 kovası oynar); yıl borcu kayda geçti. Harita bu maddede kıpırdamıyor çünkü atlas İbrim'i 1517-04-13'ten Osmanlı gösteriyor — yerleşim tarafı B, denetim/YAMA-A3-0913.json.", yer:"İbrim (Kasr İbrim), Yukarı Mısır", yer_id:"İbrim", kisiler:"Özdemir Paşa", d:"Mısır beylerbeyiliğinin güney sınırı, Nil üzerinde kayalık bir burun üstünde yükselen İbrim kalesinin alınmasıyla ikinci çağlayanın ötesine taşındı. Kale, Nübye'den gelen akınlara karşı bir set olduğu kadar Sennar'a giden altın ve köle yolunun da denetim noktasıydı. Buraya yerleştirilen Bosnalı muhafız birliği o kadar kalıcı oldu ki torunları üç yüz yıl sonra hâlâ kalede bulunuyordu. Kaynaklar İbrim'in Osmanlı idaresine giriş zamanında iki ayrı anlatı verir: TDV'nin Sudan maddesi Aşağı Nûbe'nin Osmanlı Mısırı'na katılmasını XVI. yüzyıl ortasında Özdemir Paşa'nın harekâtına bağlarken, Nûbe maddesi Halfa vadisine kadar olan bölgenin ve İbrim'deki idarî teşkilâtın 1517 fethinin hemen ardından kurulduğunu yazar. İbrim sancağı 26 Temmuz 1573'te Habeş eyaletine bağlandı.", kaynak:"sudan · nube · habes-eyaleti", duygu:["🎉"] },
{ t:"1555-09-27", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Bicâye'nin (Bougie) İspanyollardan alınması", gun:"27 Eylül 1555", yer:"Bicâye, Cezayir", yer_id:"Bicâye", kisiler:"Sâlih Reis", d:"Kırk üç yıldır İspanya'nın elinde bulunan ve Cezayir ile Konstantin arasındaki kıyıyı ikiye bölen Bicâye, karadan ve denizden kuşatıldıktan sonra teslim oldu. Kalenin düşmesiyle Cezayir ocağının sahili Vehran'a kadar kesintisiz hâle geldi. İspanya'da bu kayıp öyle büyük bir infial uyandırdı ki kaleyi teslim eden kumandan Alonso de Peralta memleketinde idam edildi.", kaynak:"cezayir", duygu:["🎉"] },
// DENETİM AÇIK (28 Ağu 2026) — SİLİNDİ (1557-01-01): mükerrer:
// olaylar_ek17.js'teki "Habeş Eyaleti'nin kuruluşu" kaydı AYNI kuruluşu
// anlatıyor (aynı gün · aynı kişi · aynı `kaynak:"habes-eyaleti"` slug'ı).
// Kalan kayıt buradaki üç yeri (Sevâkin · Masavva · Dahlak) İÇERİYOR ve 13'e
// çıkarıyor; ayrıca TDV'nin iki ayrı tarihini de veriyor (5 Temmuz 1555 resmî
// kuruluş, 2 Nisan 1557 Masavva'nın alınışı) — buradaki kayıt ikisini tek
// "1557" altında topluyordu.
// ⚠️ Burada kaybolan tek nüans "Portekiz'in Habeşistan üzerinden Kızıldeniz'e
// sızmasını önlemek" gerekçesiydi; kalan kaydın `d:` metnine EKLENDİ.
{ t:"1559-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri","konu-idari"], b:"Zeyla'nın Habeş Eyaleti'ne katılması", gun:"1559", yer:"Zeyla, Aden Körfezi", yer_id:"Zeyla", kisiler:"Özdemir Paşa", d:"Habeş eyaletinin güney ucunda, Aden Körfezi'nin Afrika kıyısındaki Zeyla limanı Osmanlı idaresine bağlandı. Adal Sultanlığı'nın denize açılan kapısı olan bu şehir, Bâbülmendep'in dışına çıkan gemiler için son ikmal noktasıydı. Zeyla'nın katılmasıyla Osmanlı Devleti'nin Afrika'daki sınırı en güney noktasına ulaştı.", kaynak:"habes-eyaleti", duygu:["🎉"] },

// ---- 0d. Nokta yokluğundan haritada sahte sahiplenilen adaların maddeleri ----
// Bu üç madde, ada denetiminde ortaya çıkan boşlukların kronolojideki karşılığıdır:
// adaların doğru tarihte el değiştirdiği artık haritada da görünüyor.
{ t:"1521-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Nikarya (İkarya) adasının Osmanlı idaresine girmesi", gun:"1521", yer:"Nikarya, Doğu Ege", yer_id:"Nikarya (İkarya)", kisiler:"Kanunî Sultan Süleyman", d:"Sisam ile Sakız arasındaki Nikarya, 1481'den 1521'e kadar Rodos Saint Jean Şövalyeleri'nin idaresindeydi; adadaki ilk Osmanlı dönemi 1522'de başladı ve 1822'ye kadar sürdü. Bu dönemde vergilerin toplanıp ödenmesinden kaymakam sorumluydu; öteki Ege adalarında olduğu gibi yerel ihtiyarlar meclisi (demogerontia) da varlığını sürdürdü ve zaman zaman Osmanlı idaresiyle çatıştı.", ic_not_d:"⚠️ TARİH HAKKINDA: dayanak kaynak Şövalye idaresinin 1521'e kadar sürdüğünü ve ilk Osmanlı döneminin 1522'de başladığını yazıyor; atlasın haritası geçişi 1521 başına koyuyor — fark kayıt için ayrıca bildirildi. ⚠️ KAYNAK HAKKINDA: TDV'nin sisam, cezayir-i-bahr-i-sefid ve rodos maddeleri adayı anmıyor.", kaynak:"bulunamadı — TDV bu taneciği kapsamıyor (sisam · cezayir-i-bahr-i-sefid · rodos: 200, üçü de Nikarya'yı anmıyor; nikarya · ikarya · ahikerya · sakiz: 302; önceki kaynak sakiz-adasi adayı kapsamıyordu). Dayanak: Ιστορία Βορείου Αιγαίου / History of the Northern Aegean (Kuzey Ege Bölge Yönetimi projesi), 'Ikaria before the Greek Revolution of 1821' — 'From 1481 to 1521, it came under the rule of the Knights Hospitaller of Rhodes.' · 'The first period of Ottoman rule lasted from 1522 to 1822.' · kaymakam ve demogerontia cümlesi aynı sayfadan. Sayfa kaynakçasında: Stamatiadis, Ikariaka (Mnemon 6, 1893) · Melas 1998 · Kontaxopoulou 2012. Tek kaynak — ikinci bağımsız kaynakla eşleşmedi. Önceki metnin '1362'den beri Cenevizli Arangio' ve 'Cezâyir-i Bahr-i Sefîd eyaletine bağlandı' ifadeleri kaynaksız olduğu için çıkarıldı (H: KITA 14, 13 Eylül 2026).", duygu:["🎉"] },
{ t:"1538-08-01", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Barbaros'un Kuzey Ege seferi: İskiros ve Kuzey Sporadlar'ın alınması", gun:"1538 yazı", yer:"İskiros, İskiathos, İskopelos – Kuzey Ege", yer_id:"İskiathos", kisiler:"Barbaros Hayreddin Paşa", d:"Preveze'ye giden yolda donanma, İstanbul'un fethinden sonra Venedik'e sığınmış olan Kuzey Ege adalarını tek tek teslim aldı. Eğriboz'un kuzeyindeki İskiros ile Selanik körfezinin ağzını tutan İskiathos, İskopelos ve Alonisos böylece Osmanlı idaresine girdi. Bu adalar, Eğriboz 1470'te alınmış olmasına rağmen altmış sekiz yıl daha Venedik elinde kalmış olan son Kuzey Ege boşluğunu kapattı.", kaynak:"barbaros-hayreddin-pasa", duygu:["🎉"] },
{ t:"1482-01-01", k:"kayip", etiket:["toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"Zaklise'nin (Zakynthos) yıllık haraç karşılığı Venedik'e bırakılması", gun:"1482", yer:"Zaklise, İyon Denizi", yer_id:"Zaklise (Zakynthos)", kisiler:"II. Bayezid", d:"Fatih devrinin sonunda Tocco ailesinden alınan İyon adalarından Zaklise, Cem Sultan meselesiyle uğraşan yeni padişahın Batı'da sükûnet arayışı içinde Venedik'e bırakıldı. Ada, Osmanlı hükümdarlığını tanıyan ve yıllık beş yüz duka haraç ödeyen bir Venedik idaresine devredildi. Böylece İyon Denizi'nde Osmanlı doğrudan idaresi yalnız Ayamavra'da kaldı.", kaynak:"venedik", duygu:["😔"] },
{ t:"1500-12-24", k:"kayip", etiket:["toprak-kayip","savas","konu-askeri"], b:"Kefalonya ve İthaki'nin kaybı", gun:"24 Aralık 1500", yer:"Kefalonya, İyon Denizi", yer_id:"Kefalonya", kisiler:"II. Bayezid, Gonzalo de Córdoba", d:"Modon ve Koron'un alınmasıyla sarsılan Venedik, İspanya ile birleşerek karşı taarruza geçti ve 1479'dan beri Osmanlı elinde bulunan Kefalonya'yı kuşattı. Kırk yedi günlük direnişin ardından kale düştü, ada İthaki ile birlikte Venedik'e geçti ve üç yüz yıl boyunca Osmanlı idaresine dönmedi. Bu kayıp, Mora'da kazanılanın İyon'da geri verildiği bir denge yarattı.", kaynak:"venedik", duygu:["😔"] },
{ t:"1537-10-01", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Barbaros'un Ege seferi: Venedik'in doğrudan yönettiği adaların alınması", gun:"Ekim 1537", yer:"Egina, Astipalya, Batnoz, Karpatos, Kaşot", yer_id:"Karpatos", kisiler:"Barbaros Hayreddin Paşa", d:"Korfu kuşatmasından dönen donanma, Venedik'e savaş açılmış olmasından yararlanarak Ege'de dukalığa değil doğrudan Venedik'e bağlı adaları tek tek teslim aldı. Egina şiddetli bir direnişin ardından zaptedildi, Querini ailesinin elindeki Astipalya ile Karpatos ve Kaşot teslim oldu, manastır idaresindeki Batnoz da Osmanlı himayesini kabul etti. Nakşa Dukalığı ise haraca bağlanarak yerinde bırakıldı; onun ilhakı 1566'yı bekleyecekti.", statu_dogrudan:["Batnoz (Patmos)"], kaynak:"barbaros-hayreddin-pasa", duygu:["🎉"] },
{ t:"1715-06-05", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"İstendil (Tinos): Venedik'in Ege'deki son adasının teslimi", gun:"5 Haziran 1715", yer:"İstendil (Tinos), Kiklad Adaları", kisiler:"Damad Ali Paşa, Canum Hoca", d:"Mora seferine çıkan donanma, yol üzerinde Venedik'in Ege'de elinde kalan tek adası olan İstendil'in önüne demirledi. Nakşa Dukalığı 1566'da düştüğü hâlde Latin nüfusu sayesinde yüz elli yıl daha Venedik bayrağı taşımış olan ada, kısa bir kuşatmanın ardından kan dökülmeden teslim oldu. Böylece Ege Denizi'nde Venedik'in son ayak izi silindi ve deniz bütünüyle bir Osmanlı iç denizi hâline geldi.", kaynak:"venedik", duygu:["🎉"], yer_id:"İstendil (Tinos)" },

// ---- 0f. Kalan sessiz toprak değişimlerinin maddeleri ----
// İki yönlü senkron denetiminin son turu: haritada renk değiştirip kronolojide
// karşılığı olmayan otuz üç kırılmanın tamamı burada maddeleşti. Bunlar olmadan
// Şirvan'ın fethi "Çıldır Zaferi"nde, Pasarofça'nın toprak kayıpları hiçbir
// maddede, Kafkasya seferleri de alakasız komşu maddelerin üstünde beliriyordu.
{ t:"1427-01-01", k:"kayip", etiket:["toprak-kayip","diplomasi","konu-askeri","konu-diplomasi"], b:"Belgrad'ın Macaristan'a bırakılması — Tata Antlaşması", gun:"1427", yer:"Belgrad", yer_id:"Belgrad", kisiler:"II. Murad, Sigismund, Stefan Lazareviç", d:"Sırp despotu Stefan Lazareviç'in ölümü üzerine, Macar kralı Sigismund ile varisi Georg Brankoviç arasında yapılan Tata Antlaşması gereği Belgrad kalesi Macaristan'a devredildi. Tuna ile Sava'nın birleştiği noktada duran kale, o güne kadar Sırp despotluğunun elindeydi ve Osmanlı için Orta Avrupa'ya açılan kapının kilidiydi. Bu devir, Belgrad'ı yüz yıl boyunca Osmanlı ilerleyişinin önündeki en sert engel hâline getirdi: 1440 ve 1456 kuşatmaları başarısız olacak, kale ancak 1521'de düşecekti.", kaynak:"belgrad", duygu:["😔"] },
{ t:"1523-01-05", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Şövalyelerin çekilişi: Bodrum, İstanköy ve Onikiada'nın devri", gun:"5 Ocak 1523", yer:"Bodrum, İstanköy, Kelemez, İleryoz", yer_id:"Bodrum", kisiler:"Kanunî Sultan Süleyman, Philippe de Villiers de L'Isle-Adam", d:"Rodos'un teslim şartları gereği Saint Jean şövalyeleri yalnız ada merkezini değil, iki yüz yıldır ellerinde tuttukları bütün mevzileri boşalttı. Anadolu kıyısındaki Bodrum (Saint Pierre) kalesi ile İstanköy, Kelemez ve İleryoz adaları böylece çatışmasız Osmanlı idaresine geçti. Rodos'un düşüşünden iki hafta sonra tamamlanan bu devirle Ege'nin güneydoğu köşesinde Latin varlığı tamamen sona erdi.", kaynak:"rodos", duygu:["🎉"] },
{ t:"1513-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Sin (Sinj) Kalesi'nin fethi", gun:"1513 (gün belirsiz)", yer:"Sin (Sinj), Dalmaçya", yer_id:"Sin (Sinj)", kisiler:"", d:"Bosna sınırındaki Osmanlı akıncı kuvvetleri, Dalmaçya içlerine uzanan Sin (Sinj) Kalesi'ni Macar Krallığı'ndan aldı. Bu, dokuz yıl sonra Gazi Hüsrev Bey'in Knin ve çevresini fethiyle genişleyecek Dalmaçya sınır hattının erken bir halkasıydı; kale 1686'da Venedik'e kaybedilecekti.", kaynak:"dalmacya", duygu:["🎉"] },
{ t:"1522-01-01", k:"fetih", etiket:["toprak-kazanc","siyaset"], b:"Dulkadir ülkesinin ilhakı — Maraş merkezli Dulkadır eyaleti", gun:"1522", yer:"Maraş, Elbistan, Göksun, Gürün, Zamantı (Pınarbaşı), Darende", yer_id:"Maraş", kisiler:"Kanûnî Sultan Süleyman, Şehsuvaroğlu Ali Bey, Ferhad Paşa", d:"1515 Turnadağ bozgunundan sonra Osmanlı'ya tâbi bir beylik olarak süren Dulkadır ülkesi, Şehsuvaroğlu Ali Bey'in Artukova'da çocuklarıyla birlikte katledilmesinin ardından doğrudan Osmanlı topraklarına katıldı ve Maraş merkez olmak üzere bir eyalet haline getirildi. Beyliğin Bozok bölgesi ayrı bir sancak olarak Osmanlı idaresine bağlandı. Böylece Maraş, Elbistan, Göksun, Gürün, Zamantı ve Darende'nin yaklaşık iki yüzyıllık Dulkadırlı dönemi kapandı; Memlük sınırındaki tampon beylik tamamen ortadan kalktı.", kaynak:"dulkadirogullari", ic_not_d:"🔴 HASSASİYET: GÜN YOK. TDV dulkadirogullari Ali Bey'in katlini 1522, TDV dulkadir-eyaleti ise 1521 der; ikincisi beylerbeyiliğin hangi tarihte teşkil edildiğinin kesin olarak bilinmediğini, Kanûnî devrinin başlarında kurulduğunun tahmin edildiğini yazar. 1522-01-01 bir ölçüm değil pencere işaretidir (D210). Yerleşim tarafı: 6 kaydın d: dönemi bu güne çekildi — TARIH-SUPHE-0920.", duygu:["🎉"] },
{ t:"1522-05-29", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Knin'in fethi", gun:"1522", ic_not_gun:"1522 (TDV yalnız yılı veriyor)", yer:"Knin, Dalmaçya", yer_id:"Knin", kisiler:"Gazi Hüsrev Bey", d:"Bosna sancakbeyi Gazi Hüsrev Bey'in 927-928 (1521-1522) yıllarındaki akınlarıyla Knin, Skradin ve Ostrovica başta olmak üzere bir dizi Venedik kalesi Osmanlı idaresine geçti; sınır ikinci dağ sırasının ötesine itildi. Bu fetih zinciri on beş yıl sonra Klis'in alınmasıyla tamamlanacak Dalmaçya sancağının temelini attı.", kaynak:"gazi-husrev-bey", duygu:["🎉"] },
{ t:"1528-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Kuzey Bosna'nın ilhakı: Yayça ve Banaluka", gun:"1528", yer:"Banaluka, Yayça — Bosna", yer_id:"Banaluka", kisiler:"Gazi Hüsrev Bey", d:"Mohaç'tan sonra Macar savunma hattı çökünce, Bosna sancakbeyi Gazi Hüsrev Bey Vrbas vadisine yürüyerek Macar krallığının elinde kalan son Bosna kalelerini aldı. Yayça'nın ve Banaluka'nın düşmesiyle Bosna eyaleti kuzeyde Sava nehrine dayandı ve Hırvatistan cephesi doğdu. Banaluka kısa sürede eyaletin ikinci merkezi hâline geldi.", fethedilen:["Yayça (Jajce)","Banaluka"], kaynak:"banaluka", duygu:["🎉"] },
{ t:"1543-01-01", k:"fetih", etiket:["toprak-kazanc"], b:"Segedin'in Osmanlı idaresine girmesi ve Segedin livâsının teşkili", gun:"1543 başları", yer:"Segedin (Szeged), Tuna-Tisza arası", yer_id:"Segedin (Szeged)", kisiler:"Küçük Bâlî Paşa, Derviş Bey", d:"Budin'de Osmanlı idaresinin 1541'de tam olarak kurulmasının ardından Segedin ileri gelenleri I. Ferdinand'ın hâkimiyetini benimseyip silâhlı savunmaya hazırlandılar. Budin Beylerbeyi Küçük Bâlî Paşa 1543 başlarında şehrin yöneticilerini yanına çağırtıp ihanet gerekçesiyle idam ettirdi, ardından şehri ele geçirmek üzere birlik gönderdi. Bu sırada Segedin livâsı teşkil edilerek ilk sancak beyliğine Bâlî Paşa'nın oğlu Derviş Bey tayin edildi; livâ başlangıçta Tuna-Tisza arasına uzanıyordu.", kaynak:"segedin", ic_not_d:"🔴 HASSASİYET: GÜN YOK — TDV segedin yalnız 1543 başları der. Atlasın eski 1543-08-10 günü, o güne düşen Estergon-İstolni Belgrad maddesinden devralınmış bir komşu günüydü; TDV Segedin ile Estergon seferi arasında bağ KURMUYOR ve gövdesinde 1542 hiç geçmiyor. Yerleşim tarafı: Segedin kaydının s:/d: ucu 1543-01-01'e çekildi — TARIH-SUPHE-0920.", duygu:["🎉"] },
{ t:"1566-04-14", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Sakız'ın Cenevizlilerden alınışı", gun:"14 Nisan 1566", yer:"Sakız, İpsara", yer_id:"Sakız", kisiler:"Piyâle Paşa, Giustiniani ailesi", d:"İki yüz yıldır Ceneviz'in Giustiniani ailesine ait bir ticaret kolonisi olarak yönetilen ve Osmanlı'ya haraç ödeyen Sakız, haracını aksatması ve düşman gemilerine liman vermesi gerekçesiyle Piyâle Paşa tarafından tek kurşun atılmadan teslim alındı. Sakız ve İpsara ile birlikte Ege'nin doğu kıyısındaki son Ceneviz varlığı da tasfiye edildi. Sakızlıların mastik üretimi ve imtiyazları korunarak ada Cezâyir-i Bahr-i Sefîd eyaletine bağlandı.", kaynak:"sakiz-adasi", duygu:["🎉"] },
{ t:"1566-04-15", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Nakşa Dukalığı'nın ilhakı — Kiklad Adaları'nın tamamı", gun:"15 Nisan 1566", yer:"Nakşa, Paros, Değirmenlik, Andros, Sire, Mikonos ve Kikladlar", yer_id:"Nakşa", kisiler:"Piyâle Paşa, Giacomo IV Crispo, Yasef Nasi", d:"1207'den beri süren ve 1537'den beri Osmanlı'ya haraç ödeyen Latin Nakşa Dukalığı, son dukası Giacomo Crispo'nun halkını ezmesi üzerine gelen şikâyetler gerekçe gösterilerek lağvedildi. Nakşa, Paros, Değirmenlik, Andros, Sire, Mikonos, Nio, Yamurgi ve çevrelerindeki bütün Kiklad adaları tek bir kararla doğrudan Osmanlı idaresine alındı. Kanunî adaların yönetimini bir süre Yasef Nasi'ye verdi; üç buçuk asırlık Latin hâkimiyeti böylece Ege'nin ortasında sona erdi.", kaynak:"venedik", duygu:["🎉"] },
{ t:"1570-07-23", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Kıbrıs çıkarması: Limasol ve Baf'ın alınışı", gun:"23 Temmuz 1570", yer:"Limasol, Baf — Kıbrıs", yer_id:"Limasol", kisiler:"Lala Mustafa Paşa, Piyâle Paşa, Müezzinzâde Ali Paşa", d:"Tuzla'ya çıkarılan ordu, Lefkoşa üzerine yürümeden önce adanın güney ve batı kıyısını güvene aldı. Venedik'in savunmasını Lefkoşa ile Magosa'ya yığmış olması sayesinde Limasol ve Baf ciddi bir direniş göstermeden teslim oldu. Böylece donanmanın ikmal hattı kurulmuş, adanın kuşatmaya dayanacak iki kalesi yalnız bırakılmış oldu.", kaynak:"kibris", duygu:["🎉"] },
{ t:"1570-09-17", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Girne'nin teslimi — Kıbrıs'ın kuzey kıyısı", gun:"17 Eylül 1570", yer:"Girne, Kıbrıs", kisiler:"Lala Mustafa Paşa", d:"Lefkoşa'nın 9 Eylül'de kılıçtan geçirilerek düşmesi Kıbrıs'ın kuzeyindeki direnci kırdı. Beşparmak dağlarının ardındaki Girne kalesi, başkentin âkıbetini öğrenince sekiz gün sonra şartlı teslim oldu ve garnizonu adadan çıkmasına izin verilerek gönderildi. Adada Venedik bayrağı yalnız Magosa'da kaldı; o da on bir ay daha dayanacaktı.", kaynak:"kibris", duygu:["🎉","😔"], yer_id:"Girne (Kyrenia)" },
{ t:"1578-11-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Şirvan'ın fethi: Şamahı'nın alınışı", gun:"Kasım 1578", yer:"Şamahı, Şirvan", yer_id:"Şamahı", kisiler:"Özdemiroğlu Osman Paşa, Lala Mustafa Paşa", d:"Çıldır Zaferi'nden sonra Kafkasya'ya açılan ordu, Safevîlerin Hazar kıyısındaki en zengin eyaleti olan Şirvan'a girdi ve merkez şehir Şamahı'yı aldı. Özdemiroğlu Osman Paşa buraya beylerbeyi tayin edilerek İpek Yolu'nun kuzey kolu Osmanlı denetimine sokuldu. Şirvan, on iki yıl sürecek doğu savaşının en çok el değiştiren ve en pahalıya mal olan cephesi hâline gelecekti.", kaynak:"sirvan", duygu:["🎉"] },
{ t:"1578-10-05", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Derbend halkının Lala Mustafa Paşa'ya bağlılık arzı — Demirkapı Osmanlı idaresinde", gun:"5 Ekim 1578", yer:"Ereş (Şirvan) · Derbend, Dağıstan", yer_id:"Derbend", kisiler:"Lala Mustafa Paşa, Özdemiroğlu Osman Paşa", d:"Şirvan seferi sırasında Derbend halkından yedi kişilik bir heyet Ereş'te bulunan Serdar Lala Mustafa Paşa'nın yanına giderek bağlılık arzetti. Kafkas duvarı ile Hazar denizi arasındaki dar geçidi kapatan Derbend (Demirkapı), kuzeyden gelen kara yollarının mecburi geçidi olarak Şirvan'ın elde tutulmasında kilit rol oynadı. Osmanlı hâkimiyeti burada 1607'ye kadar sürdü.", ic_not_d:"17 Eyl 2026 (KOSU13-YAMA · YAMA-KOSU10-KALAN G6-HALKA-DERBEND): madde 1583-01-01'den kaynak gününe taşındı; eski metin Meşaleler Savaşı (1583) sonrasını anlatıyordu.", kaynak:"derbend--dagistan · sirvan", duygu:["🎉"] },
{ t:"1583-09-13", k:"fetih", etiket:["toprak-kazanc","konu-askeri","konu-imar"], b:"Revan'ın (Erivan) fethi ve kale inşası", gun:"Eylül 1583 ortaları (fetih günü kaynakta yok; 13 Eylül 1583 Revan üzerine yürüyüş emri)", yer:"Revan, Aras vadisi", yer_id:"Revan", kisiler:"Ferhad Paşa", d:"Kars'ta Revan'a gidip orada bir kale yapma emri alan Ferhad Paşa Revan üzerine yürüdü ve şehir 991 Ramazanı başlarında (Eylül 1583 ortaları) Osmanlı denetimine alındı. Aras vadisinin kuzey kapısını tutan Revan'da yeni ve büyük bir kale inşa edildi; şehir beylerbeyilik merkezi yapıldı. Kars ile Tebriz arasındaki ordu yolunun ortasında duran Revan, doğu cephesinin lojistik omurgasıydı. Kale o kadar sağlam yapıldı ki sonraki iki yüz yıl boyunca Osmanlı-İran savaşlarının değişmez hedefi oldu.", ic_not_d:"Tarih: 13 Eylül 1583 bir EMİR günüdür, fetih günü DEĞİL — fetih günü kaynakta yok (1.MURAT kararı ③, KITA 29 M-3760). t: 1583-06-01 idi; KITA 29 Ferhat Paşa yamasının Revan ve Eçmiyadzin d: başlangıcıyla birebir aynı güne alındı, madde ile yama BİRLİKTE inmeli. Pencere ölçümü: eski gün 1583-06-01 başka maddeyle kapalı kalıyor; 1583-09-13'te bugün kırılma yok.", kaynak:"revan — TDV revan birebir: 'Revan 991 Ramazanı başlarında (Eylül 1583 ortaları) Osmanlılar tarafından kontrol altına alındı. Şehri ele geçiren Ferhad Paşa, burada hemen Zengi çayının doğu kıyısında…' · yürüyüş emri günü: Davut Adlığ, Dicle Üniversitesi Sosyal Bilimler Enstitüsü Dergisi 42 (2026), BOA A.DVNSMHM.d 51-322 (13 Eylül 1583) — makaleyi KITA 29 okudu (denetim/OLCUM-KITA29-FERHATPASA-0913.md), KITA 14 okumadı.", duygu:["🎉"] },
{ t:"1583-08-01", k:"fetih", etiket:["toprak-kazanc","denizcilik","konu-askeri"], b:"Bakü'nün alınışı — Hazar kıyısına çıkış", gun:"1583", yer:"Bakü, Hazar denizi", yer_id:"Bakü", kisiler:"Özdemiroğlu Osman Paşa", d:"Şirvan harekâtının son halkası olarak Hazar denizinin batı kıyısındaki Bakü limanı alındı. Şehrin çevresindeki neft kuyuları o dönemde bile bilinen bir gelir kaynağıydı ve liman, Hazar üzerinden gelen İran ipeğinin çıkış noktasıydı. Osmanlı Devleti böylece tarihinde ilk ve tek kez Hazar denizine kıyı sahibi oldu.", kaynak:"sirvan", duygu:["🎉"] },
{ t:"1588-09-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Karabağ ve Gence'nin ilhakı", gun:"1 Eylül 1588 (9 Şevval 996)", yer:"Gence, Karabağ", yer_id:"Gence", kisiler:"Ferhad Paşa", d:"On yıllık doğu savaşının son kazancı olarak Ferhad Paşa 1588'de Gence üzerine yürüdü ve 1 Eylül'de şehre girdi; Kür ile Aras arasındaki Karabağ bölgesi ve merkezi Gence Osmanlı idaresine alındı. Böylece Şirvan, Revan ve Karabağ birleşerek Kafkasya'da kesintisiz bir Osmanlı hattı oluştu. 1590'da imzalanan Ferhad Paşa Antlaşması bu sınırı tescil edecek, ancak kazanç yalnız yirmi yıl elde tutulabilecekti.", ic_not_d:"Tarih düzeltmesi (KITA 14, 13 Eylül 2026): t: 1588-01-01 (yıl kodu) idi; iki bağımsız TDV maddesi aynı günü veriyor → 1588-09-01. KITA 29 Ferhat Paşa yamasının Gence ve Berde d: başlangıcıyla birebir aynı gün; madde ile yama BİRLİKTE inmeli. Pencere ölçümü: eski gün 1588-01-01 başka maddeyle kapalı kalıyor; 1588-09-01'de bugün kırılma yok. Metindeki 'Ertesi yıl imzalanan' ifadesi yanlıştı (antlaşma 1590) — düzeltildi.", kaynak:"gence + murad-iii + safeviler — TDV murad-iii birebir: 'Ferhad Paşa’nın 996’da (1588) Gence’ye yönelik harekâtı ve 9 Şevval’de (1 Eylül) şehre girişi…' · TDV safeviler birebir: 'Çok geçmeden Gence, Osmanlılar’ın eline geçti (1 Eylül 1588). 998’de (1590) İstanbul’da imzalanan Ferhad Paşa antlaşmasıyla…'", duygu:["🎉"] },
{ t:"1646-11-13", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Resmo'nun fethi — Girit'in ikiye bölünmesi", gun:"13 Kasım 1646", yer:"Resmo (Rethymno), Girit", kisiler:"Hüseyin Paşa (Deli)", d:"Hanya'nın alınmasından bir yıl sonra adanın orta kesimindeki Resmo kalesi de düştü ve Girit'in batı yarısı bütünüyle Osmanlı idaresine girdi. Venedik'in elinde yalnız başkent Kandiye ile doğu ucu kaldı; ada yirmi üç yıl boyunca ikiye bölünmüş hâlde yaşadı. Resmo'nun alınması Kandiye kuşatmasını başlatan adım oldu — tarihin en uzun kuşatması burada başladı.", kaynak:"girit", duygu:["🎉"], yer_id:"Girit (Resmo)" },
{ t:"1688-04-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Atina'nın geri alınışı — Venedik'in çekilişi", gun:"Nisan 1688", yer:"Atina", yer_id:"Atina", kisiler:"Francesco Morosini", d:"1687 Eylül'ünde Akropolis'i bombalayıp Parthenon'u havaya uçuran Morosini, kışı Atina'da geçirdikten sonra şehirde tutunamayacağını anladı. Veba salgını, ikmal güçlüğü ve Osmanlı kuvvetlerinin toparlanması üzerine Venedik garnizonu şehri boşaltarak Mora'ya çekildi. Atina böylece savaşılmadan yeniden Osmanlı idaresine döndü, ancak Parthenon'un uğradığı yıkım geri alınamadı.", kaynak:"atina", duygu:["🎉","😔"] },
{ t:"1715-07-20", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Anabolu'nun fethi — Mora'nın kilit kalesi", gun:"20 Temmuz 1715", yer:"Anabolu (Nauplion), Mora", kisiler:"Damad Ali Paşa", d:"Venedik'in Mora'daki başkenti ve en güçlü istihkâmı olan Anabolu, Palamidi tabyasının dokuz günlük bombardımandan sonra ele geçirilmesiyle düştü. Kalenin bu kadar çabuk alınması yarımadanın geri kalanındaki direnci kırdı. Karlofça'da kaybedilen Mora'nın geri alınışı fiilen burada tamamlandı.", kaynak:"mora", duygu:["🎉"], yer_id:"Anabolu (Nauplion)" },
{ t:"1715-08-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Modon'un teslimi", gun:"Ağustos 1715", yer:"Modon (Methoni), Mora", kisiler:"Damad Ali Paşa, Canum Hoca", d:"Anabolu'nun düşmesinden sonra Mora'nın güneybatı ucundaki Modon kalesi, karadan ordu denizden donanma tarafından kuşatıldı ve kısa sürede teslim oldu. Venedik'in Doğu Akdeniz seferlerinde iki yüz yıl boyunca kullandığı bu liman, gemilerin su ve erzak aldığı zorunlu uğrak noktasıydı. Kaybı Venedik donanmasının Ege'deki hareket kabiliyetini bitirdi.", kaynak:"modon", duygu:["🎉"], yer_id:"Modon" },
{ t:"1715-08-16", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Koron'un teslimi — Mora seferinin tamamlanması", gun:"16 Ağustos 1715", yer:"Koron (Koroni), Mora", kisiler:"Damad Ali Paşa", d:"Mesenya körfezinin ağzını tutan Koron kalesinin teslim olmasıyla Mora yarımadasında Venedik idaresi tamamen sona erdi. Karlofça'da kaybedilen yarımada, seferin açılmasından yalnız üç ay sonra bütünüyle geri alınmış oldu. Aynı seferin devamında, 1715 Eylülünde İyon denizindeki Ayamavra (Lefkada) adası da Venedik'ten alındı. Bu hız Venedik'i Avusturya'yı savaşa sokmaya zorladı ve üç yıl sonra Pasarofça'ya giden yol açıldı.", fethedilen:["Ayamavra (Lefkada)"], kaynak:"koron", duygu:["🎉"], yer_id:"Koron" },
{ t:"1715-09-07", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Çuha Adası'nın (Kythira) alınışı", gun:"Eylül 1715", yer:"Çuha Adası (Cerigo), Mora'nın güneyi", kisiler:"Canum Hoca", d:"Mora'nın güney ucundaki Çuha Adası, yarımadanın tamamlanmasının ardından donanma tarafından teslim alındı. İyon denizi ile Ege arasındaki geçişi gözetleyen ada, Venedik'in bu suları denetlemekte kullandığı ileri karakoldu. Ancak elde tutulan tek Osmanlı adası olarak kalmadı: üç yıl sonra Pasarofça'da Venedik'e geri verildi.", kaynak:"mora", duygu:["🎉"], yer_id:"Çuha Adası (Kythira)" },
{ t:"1718-07-21", k:"antlasma", etiket:["antlasma","diplomasi","toprak-kayip","ekonomi","konu-askeri","konu-diplomasi","konu-ekonomi"], b:"Pasarofça Antlaşması — Mora kazanıldı, Belgrad ve Banat kaybedildi", gun:"21 Temmuz 1718", yer:"Pasarofça (Požarevac), Sırbistan", kisiler:"III. Ahmed, Nevşehirli Damad İbrahim Paşa, Silâhdar İbrahim Efendi, Yirmisekiz Çelebi Mehmed Efendi", d:"Venedik'ten Mora geri alınmıştı, fakat savaşa giren Avusturya Petrovaradin ve Belgrad'da kazandığı zaferlerle masaya üstün geldi. İngiltere ile Hollanda'nın arabuluculuğunda imzalanan antlaşma Mora'yı Osmanlı'da bıraktı, buna karşılık Belgrad ile birlikte Kuzey Sırbistan, Banat ve Küçük Eflak Avusturya'ya terk edildi; Venedik ise İyon kıyısındaki Preveze ve Çuha gibi mevzilerini korudu. Aynı gün imzalanan ticaret ahidnâmesiyle Avusturya mallarından alınan gümrük yüzde beşten üçe indirildi. Antlaşma, Osmanlı Devleti'nin Orta Avrupa'daki geri çekilişini tescil ederken açtığı yirmi yedi yıllık barış Lâle Devri'nin (1718-1730) zeminini kurdu: Nevşehirli Damad İbrahim Paşa'nın yönetiminde ilk Osmanlı matbaası (1727, İbrahim Müteferrika), tercüme heyetleri, çiçek aşısı gözlemleri ve yeni bir saray-kültür hayatı bu barış yıllarının ürünüdür.", kaynak:"pasarofca-antlasmasi", duygu:["🤝"], yer_id:"Semendire" },
{ t:"1723-08-01", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"1723 İran Seferi: Şirvan ve Gürcistan'a giriş", gun:"1723", yer:"Şamahı, Tiflis", kisiler:"III. Ahmed, Nevşehirli Damad İbrahim Paşa", d:"Safevî Devleti'nin Afgan istilâsıyla çökmesi üzerine, Rusya'nın Hazar kıyılarına inmesini önlemek gerekçesiyle doğuya sefer açıldı. Erzurum ordusu Gürcistan üzerinden Tiflis'e, Şirvan kolu ise Şamahı'ya girerek yüz otuz yıl önce kaybedilen toprakları geri aldı. Bu sefer, Osmanlı'nın Kafkasya'daki son büyük ilerleyişi oldu.", kaynak:"sirvan", duygu:["🎉"], yer_id:"Şamahı" },
{ t:"1723-10-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Kirmanşah'ın alınışı — Zağros kapısı", gun:"Ekim 1723", yer:"Kirmanşah, Batı İran", kisiler:"Bağdat Valisi Hasan Paşa", d:"Bağdat ordusu Zağros geçitlerini aşarak İran'ın batı kapısı sayılan Kirmanşah'ı ele geçirdi. Şehir, Bağdat'tan İsfahan'a giden kervan ve ordu yolunun üzerindeydi ve alınması Irak eyaletinin doğu güvenliğini sağlıyordu. Bu ilerleyiş, dağılan Safevî ülkesinde Osmanlı ile Rusya arasında paylaşım yarışını başlattı.", kaynak:"bagdat", duygu:["🎉"], yer_id:"Kirmanşah" },
{ t:"1724-08-31", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Hemedan'ın fethi", gun:"31 Ağustos 1724", yer:"Hemedan, Batı İran", kisiler:"Bağdat Valisi Hasan Paşa", d:"Kirmanşah'tan doğuya yürüyen ordu, İran platosunun batı eşiğindeki Hemedan'ı uzun bir kuşatmadan sonra aldı. Şehir, Osmanlı ordularının Irakeyn Seferi'nden beri ulaşabildiği en doğudaki nokta olan İsfahan yolunun son büyük durağıydı. Aynı yıl Rusya ile imzalanan İstanbul Mukavelenâmesi, dağılan İran'ın Osmanlı ile Rusya arasında paylaşımını kâğıda döktü.", kaynak:"bagdat", duygu:["🎉"], yer_id:"Hemedan" },
{ t:"1724-10-03", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Revan'ın yeniden fethi", gun:"3 Ekim 1724 (gün: Bilgili 2016, BOA MD 132)", yer:"Revan (Erivan)", kisiler:"Köprülüzâde Abdullah Paşa", d:"Doksan gün süren çetin bir kuşatmanın ardından Aras vadisinin kilit kalesi Revan yeniden Osmanlı idaresine girdi. 1583'te inşa edilip 1604'te kaybedilen kale, bu kez daha güçlü bir garnizonla tahkim edildi. Kuşatmanın uzunluğu, Osmanlı ordusunun artık kolay ilerlemediğinin göstergesiydi. Karpi (Üçkilise), Şerür, Makû ve Şüregel nahiyeleri de Revan eyaletine bağlandı.", kaynak:"revan · Bilgili 2016 (Ermeni Araştırmaları 53) s.107", duygu:["🎉"], yer_id:"Revan" },
{ t:"1724-08-11", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Nahçıvan'ın alınışı", gun:"11 Ağustos 1724 (gün: Aktepe 1970 s.53-58, Yörük-Valiyev 2016; Bilgili 2016 fethi 'Nisan 1723'ten biraz önce'ye koyar)", yer:"Nahçıvan, Ordubad, Aras vadisi", kisiler:"Bayezid beyi Mahmud Paşa, Eleşkird beyi Halil Bey", d:"Aras boyunca ilerleyen Osmanlı kuvvetleri Nahçıvan ile Ordubad'ı aldı; Culfa da Nahçıvan livasına katıldı. Şehir, İran'ın kuzeybatı kapısı olarak yeni kurulan Revan eyaletine bağlandı. Böylece Osmanlı sınırı Kanunî devrindeki en doğu çizgisine yeniden ulaştı.", kaynak:"nahcivan · Yörük & Valiyev 2016 (SUTAD 40) s.20 · Bilgili 2016 s.117 (BOA TD 905)", duygu:["🎉"], yer_id:"Nahçıvan" },
{ t:"1725-09-12", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Gence'nin fethi — Kafkasya seferinin sonu", gun:"12 Eylül 1725", yer:"Gence, Karabağ", kisiler:"Köprülüzâde Abdullah Paşa", d:"Kafkasya harekâtının son hedefi olan Gence, Kür ile Aras arasındaki Karabağ'ın merkezi olarak teslim alındı. Şirvan, Revan, Nahçıvan ve Gence hattının tamamlanmasıyla Osmanlı Devleti Kafkasya'da 1590'daki genişliğine ulaştı. Ancak bu kazanç kısa ömürlü oldu: Nâdir Şah'ın yükselişi on yıl içinde bütün bölgeyi geri alacaktı.", kaynak:"nahcivan", duygu:["🎉"], yer_id:"Gence" },
{ t:"1781-01-01", k:"diger", etiket:["toprak-kazanc","savas","konu-askeri","konu-imar"], b:"Anapa Kalesi'nin inşası — Kafkas savunma hattı", gun:"1781", yer:"Anapa, Kuban havzası", kisiler:"I. Abdülhamid, Ferah Ali Paşa", d:"Küçük Kaynarca ile Kırım elden çıkınca Kafkasya'daki Osmanlı nüfuzunu korumak için Kuban ırmağının ağzında yeni bir kale inşasına girişildi. Ceneviz kolonisi kalıntıları üzerine kurulan Anapa, çarşısı, hamamları ve iki yüz elliyi aşan dükkânıyla kısa sürede Çerkes kabileleriyle bağlantıyı sağlayan bir şehir hâline geldi. Kale, Rusya'nın Kafkasya'ya inişine karşı kırk sekiz yıl boyunca Osmanlı'nın en ileri karakolu olarak kaldı.", kaynak:"anapa", duygu:["📌"], yer_id:"Anapa" },
{ t:"1792-02-12", k:"fetih", etiket:["toprak-kazanc","diplomasi","konu-askeri","konu-diplomasi"], b:"Vehrân'ın (Oran) İspanyollarca boşaltılması ve Cezayir'e devri", gun:"12 Şubat 1792", yer:"Vehrân (Oran), Batı Cezayir", kisiler:"Cezayir Ocağı, IV. Carlos", d:"1790 depreminde kale ve şehir büyük ölçüde yıkılınca, üç asırdır sürdürdüğü masraflı garnizonu artık taşıyamayan İspanya, Cezayir ocağıyla anlaşarak Vehrân'ı ve Mersalkebîr'i savaşsız devretti. Böylece Kuzey Afrika kıyısındaki son Avrupa mevzisi de tasfiye edildi. Osmanlı Cezayiri, Fransız işgaline kadar geçecek otuz sekiz yıl boyunca kıyının tamamına hâkim kaldı.", kaynak:"vehran", duygu:["🎉"], yer_id:"Oran" },
{ t:"1798-10-23", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Preveze'nin Fransızlardan alınışı — Nikopolis Muharebesi", gun:"23 Ekim 1798", yer:"Preveze, Epir", kisiler:"Tepedelenli Ali Paşa", d:"Venedik Cumhuriyeti 1797'de yıkılınca İyon adaları ve karadaki Preveze, Parga, Vonitsa Fransa'nın eline geçti. Yanya valisi Tepedelenli Ali Paşa, Fransa'nın Mısır'ı işgali üzerine açılan savaştan yararlanarak Preveze üzerine yürüdü ve şehrin dışındaki Nikopolis harabelerinde Fransız garnizonunu ağır bir yenilgiye uğrattı. Böylece Pasarofça'da Venedik'te bırakılan bu liman, seksen yıl sonra Osmanlı idaresine girdi.", kaynak:"yanya", duygu:["🎉"], yer_id:"Preveze" },
{ t:"1871-01-01", k:"fetih", etiket:["toprak-kazanc","konu-askeri"], b:"Asîr'in doğrudan idareye alınması", gun:"1871", yer:"Ebha (Asir), Güneybatı Arabistan", kisiler:"Redif Paşa", d:"Süveyş Kanalı'nın açılmasıyla Kızıldeniz'in stratejik değeri artınca, Yemen'e giden kara yolunun ortasındaki Asîr dağlarının denetimsiz bırakılamayacağı görüldü. Yemen seferine çıkan Redif Paşa'nın kuvvetleri Ebha'ya girerek bölgeyi doğrudan Osmanlı idaresine bağladı ve Asîr sancağı kuruldu. Dağlık coğrafya ve İdrîsî nüfuzu yüzünden bu hâkimiyet hiçbir zaman tam oturmadı.", kaynak:"yemen", duygu:["🎉"], yer_id:"Ebha (Asir)" },
{ t:"1913-11-01", k:"fetih", etiket:["toprak-kazanc","antlasma","konu-askeri","konu-diplomasi"], b:"Bozcaada ve İmroz'un geri alınışı — Atina Antlaşması", gun:"Kasım 1913", yer:"Bozcaada, İmroz", kisiler:"Talat Bey", d:"Balkan Savaşı'nda Yunanistan'ın işgal ettiği Kuzey Ege adalarından Boğaz'ın ağzını tutan Bozcaada ile İmroz, Atina Antlaşması görüşmelerinde Çanakkale'nin savunması için vazgeçilmez sayıldı ve Osmanlı'ya iade edildi. Diğer adalar Yunanistan'da kaldı. Bu iki ada, İmparatorluğun Ege'de elinde tuttuğu son topraklar oldu ve Lozan'da da Türkiye'ye bırakıldı.", kaynak:"bozcaada", duygu:["🎉"], yer_id:"Bozcaada" },
{ t:"1918-04-14", k:"fetih", etiket:["toprak-kazanc","savas","konu-askeri"], b:"Batum'un geri alınışı", gun:"14 Nisan 1918", yer:"Batum, Acara", kisiler:"Vehib Paşa, Kâzım Karabekir", d:"Brest-Litovsk Antlaşması'yla Rusya'nın savaştan çekilmesi üzerine doğuya ilerleyen Osmanlı ordusu, 1878'de kaybedilen Batum limanını kırk yıl sonra geri aldı. Karadeniz'in doğu ucundaki bu liman, Bakü petrolünün deniz çıkışıydı. Kazanç yalnız yedi ay sürdü; Mondros Mütarekesi'nden sonra bölge boşaltılacaktı.", kaynak:"birinci-dunya-savasi", duygu:["🎉"], yer_id:"Batum" },
{ t:"1918-05-25", k:"fetih", etiket:["toprak-kazanc","antlasma","konu-askeri","konu-diplomasi"], b:"Elviye-i Selâse: Kars ve Ardahan'ın geri alınışı", gun:"25 Mayıs 1918", yer:"Kars, Ardahan", kisiler:"Kâzım Karabekir, Vehib Paşa", d:"Brest-Litovsk'ta 1878 Berlin Antlaşması'yla kaybedilen üç sancağın — Kars, Ardahan ve Batum — iadesi kararlaştırılmış, bölgede yapılan halk oylamasının ardından Osmanlı idaresi fiilen kuruldu. 'Elviye-i Selâse' adıyla anılan bu topraklar, Doksanüç Harbi'nden beri süren kaybın telâfisi sayıldı. Mütarekeden sonra yeniden elden çıkacak, kesin olarak ancak 1921 Kars Antlaşması'yla Türkiye'ye bağlanacaklardı.", kaynak:"kars", duygu:["🎉"], yer_id:"Kars" }

